(window.__KSHC_DATA=window.__KSHC_DATA||{})["learning"]={"packs":[{"id":"hiculture-learning-core","schemaVersion":1,"version":"1.0.0","generatedAt":"2026-07-27T12:00:00Z","questions":[{"id":"science-evolution-selection-001","category":"science","conceptID":"science.evolution-variation","conceptTitle":"Natural selection","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"A bacterial population contains heritable variation in antibiotic resistance before treatment begins. After repeated treatment, resistant bacteria become more common. Which explanation best matches natural selection?","choices":[{"id":"a","text":"Exposure induced resistance in the surviving cells, which then passed that acquired trait to offspring.","rationale":"This is inheritance of acquired characteristics. The stem says resistance variation existed before treatment; selection explains its spread without traits arising because they were needed."},{"id":"b","text":"The antibiotic raised the mutation rate, generating the resistance mutations that then spread.","rationale":"The stem states resistance variation was present before treatment, so drug-generated mutations are not needed to explain the change; selection sorts existing variants."},{"id":"c","text":"Individual bacteria grew tolerant through repeated exposure, much as people build drug tolerance.","rationale":"Physiological acclimation within individuals is not a heritable change in variant frequencies, which is what natural selection explains."},{"id":"d","text":"Bacteria that already carried heritable resistance survived treatment and left more descendants.","rationale":"Correct. Selection acts on variation that existed before treatment: resistant variants survived and reproduced more, so their frequency rose."}],"correctChoiceID":"d","explanation":"Selection sorts heritable variation already present or newly arising without regard to need. Resistant variants reproduce disproportionately under antibiotic pressure.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"openstax-biology-2e","title":"Biology 2e","publisher":"OpenStax","url":"https://openstax.org/details/books/biology-2e","accessedAt":"2026-07-27T12:00:00Z","license":"CC BY 4.0","usage":"openLicense","evidenceLocator":"Evolution and the Origin of Species"}],"tags":["evolution","antibiotic-resistance"],"generatedAt":"2026-07-27T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"editorial-v1","reviewStatus":"verified"},{"id":"science-cell-surface-area-001","category":"science","conceptID":"science.models-systems","conceptTitle":"Surface-area-to-volume constraints","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"Two spherical cells have the same membrane properties, but one has twice the diameter of the other. What is the most important transport consequence for the larger cell?","choices":[{"id":"a","text":"Its surface-area-to-volume ratio falls to one-quarter, because its volume grows eightfold.","rationale":"Volume does grow eightfold, but area also grows fourfold, so the ratio falls to 4/8 = 1/2, not 1/4."},{"id":"b","text":"Its surface-area-to-volume ratio is halved, so exchange per unit volume is less efficient.","rationale":"Correct. Area scales by 2² = 4 and volume by 2³ = 8, so the ratio falls to 4/8 = 1/2 (for a sphere it equals 6/d)."},{"id":"c","text":"Its membrane area quadruples, so its exchange capacity keeps pace with its larger volume.","rationale":"Area quadruples while volume grows eightfold, so exchange capacity per unit of metabolically active volume falls."},{"id":"d","text":"Its ratio is unchanged, since area and volume both increase when the diameter doubles.","rationale":"Both increase, but at different powers of length (squared versus cubed), so the ratio changes."}],"correctChoiceID":"b","explanation":"Doubling diameter multiplies surface area by four but volume by eight. The larger cell therefore has less membrane area per unit of metabolically active volume.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"openstax-biology-2e","title":"Biology 2e","publisher":"OpenStax","url":"https://openstax.org/details/books/biology-2e","accessedAt":"2026-07-27T12:00:00Z","license":"CC BY 4.0","usage":"openLicense","evidenceLocator":"Cell Structure"}],"tags":["cell-biology","scaling"],"generatedAt":"2026-07-27T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"editorial-v1","reviewStatus":"verified"},{"id":"science-experimental-design-essay-001","category":"science","conceptID":"science.causality-experimental-design","conceptTitle":"Experimental design","type":"essay","dimension":"synthesis","difficulty":"advanced","prompt":"Design a study to test whether a new study routine improves long-term retention rather than merely same-day performance. Explain the comparison groups, assignment method, outcome measures, timing, and the limits of the causal claim.","choices":[],"explanation":"Coaching should test whether the design separates treatment effects from selection, expectancy, and short-lived practice effects.","rubric":[{"id":"design","title":"Identification strategy","description":"Defines a controlled comparison and a defensible assignment strategy.","weight":0.4,"coachingQuestions":["What alternative explanation does random assignment address?"]},{"id":"measurement","title":"Measurement","description":"Uses delayed, comparable retention outcomes and an appropriate timeline.","weight":0.35,"coachingQuestions":["How will you distinguish retention from immediate fluency?"]},{"id":"limits","title":"Limits","description":"States threats to validity and the population to which results may generalize.","weight":0.25,"coachingQuestions":["Which conclusion would the design still not justify?"]}],"coachingPrompts":["Name the treatment and control conditions precisely.","Identify at least two plausible confounders.","Separate internal validity from generalizability."],"modelOutline":["Question and hypothesis","Randomized comparison","Delayed assessment","Analysis and uncertainty","Boundary of inference"],"sources":[{"id":"roediger-karpicke-2006","title":"Test-Enhanced Learning: Taking Memory Tests Improves Long-Term Retention","publisher":"PubMed, U.S. National Library of Medicine","url":"https://pubmed.ncbi.nlm.nih.gov/16507066/","publishedAt":"2006-03-01T12:00:00Z","accessedAt":"2026-07-27T12:00:00Z","usage":"linkOnly","evidenceLocator":"Abstract and lawful full-text links"},{"id":"cepeda-2008","title":"Spacing Effects in Learning: A Temporal Ridgeline of Optimal Retention","publisher":"PubMed, U.S. National Library of Medicine","url":"https://pubmed.ncbi.nlm.nih.gov/19076480/","publishedAt":"2008-11-01T12:00:00Z","accessedAt":"2026-07-27T12:00:00Z","usage":"linkOnly","evidenceLocator":"Abstract and lawful full-text links"},{"id":"openstax-biology-2e","title":"Biology 2e","publisher":"OpenStax","url":"https://openstax.org/details/books/biology-2e","accessedAt":"2026-07-27T12:00:00Z","license":"CC BY 4.0","usage":"openLicense","evidenceLocator":"The Process of Science"}],"tags":["experimental-design","causal-inference"],"generatedAt":"2026-07-27T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"editorial-v1","reviewStatus":"verified"},{"id":"biotechnology-crispr-targeting-001","category":"biotechnology","conceptID":"biotechnology.genome-editing","conceptTitle":"CRISPR targeting","type":"multipleChoice","dimension":"recognition","difficulty":"college","prompt":"In a typical CRISPR-Cas9 editing system, what gives the complex most of its sequence specificity?","choices":[{"id":"a","text":"Cas9's own DNA-binding domain, which reads the target gene's sequence directly.","rationale":"Cas9 protein recognizes only the short PAM. Protein-based sequence reading is how zinc-finger nucleases and TALENs target DNA, not CRISPR-Cas9."},{"id":"b","text":"Base pairing between the guide RNA's spacer and the target DNA, next to a compatible PAM.","rationale":"Correct. The roughly 20-nucleotide spacer supplies sequence matching; Cas9 also requires an adjacent PAM, which is short and contributes little specificity on its own."},{"id":"c","text":"The PAM sequence, which is unique to the target gene and marks where Cas9 must cut.","rationale":"PAMs such as NGG are only a few bases long and occur very frequently in a genome; they are required but supply little specificity."},{"id":"d","text":"The repair template supplied with Cas9, which pairs with the target to choose the cut site.","rationale":"A donor template guides homology-directed repair after a cut; it does not determine where Cas9 binds or cuts."}],"correctChoiceID":"b","explanation":"A designed guide RNA pairs with complementary target DNA, while Cas9 recognition also depends on a nearby PAM. Off-target activity remains possible when similar sequences satisfy these constraints.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"nhgri-genome-editing","title":"What Is Genome Editing?","publisher":"National Human Genome Research Institute","url":"https://www.genome.gov/about-genomics/policy-issues/what-is-Genome-Editing","accessedAt":"2026-07-27T12:00:00Z","usage":"linkOnly","evidenceLocator":"CRISPR overview"}],"tags":["crispr","gene-editing"],"generatedAt":"2026-07-27T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"editorial-v1","reviewStatus":"verified"},{"id":"biotechnology-somatic-germline-001","category":"biotechnology","conceptID":"biotechnology.bioethics-governance","conceptTitle":"Somatic and germline editing","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"A therapy edits blood-forming stem cells removed from an adult, then returns those cells to the same patient. Which description is most accurate?","choices":[{"id":"a","text":"Somatic editing, because blood-forming stem cells do not give rise to eggs or sperm.","rationale":"Correct. The edited cells are non-reproductive cells of an existing patient, so the change is not designed to pass to offspring."},{"id":"b","text":"Germline editing, because the edited stem cells self-renew for the patient's whole lifetime.","rationale":"Self-renewal and persistence do not make a cell part of the reproductive germline."},{"id":"c","text":"Germline editing, because the cells were edited outside the body before being returned.","rationale":"In vivo versus ex vivo describes how editing is delivered, not whether the target is somatic or germline."},{"id":"d","text":"Somatic editing, but the change will be inherited because the cells re-enter circulation.","rationale":"The classification is right, but circulating blood cells do not reach the germline, so the edit is not transmitted to children."}],"correctChoiceID":"a","explanation":"Editing a patient's blood-forming cells is somatic even though those cells persist and divide. Germline editing targets eggs, sperm, embryos, or their precursors in a way that may transmit changes to descendants.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"nih-genome-editing","title":"Somatic Cell Genome Editing","publisher":"National Center for Advancing Translational Sciences","url":"https://ncats.nih.gov/research/research-activities/gene-targeted-therapies/scge-somatic-cell-gene-editing","accessedAt":"2026-07-27T12:00:00Z","usage":"linkOnly","evidenceLocator":"Non-reproductive somatic-cell editing"}],"tags":["somatic-editing","germline-editing","ethics"],"generatedAt":"2026-07-27T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"editorial-v1","reviewStatus":"verified"},{"id":"biotechnology-trial-ethics-essay-001","category":"biotechnology","conceptID":"biotechnology.clinical-regulatory-evidence","conceptTitle":"Gene-therapy trial reasoning","type":"essay","dimension":"synthesis","difficulty":"advanced","prompt":"A proposed first-in-human gene-editing treatment may help a severe disease but carries uncertain off-target and long-term risks. Build an argument for the evidence and safeguards that should be required before and during a small clinical trial.","choices":[],"explanation":"A strong response connects biological uncertainty to consent, monitoring, enrollment, stopping rules, and fair interpretation of early results.","rubric":[{"id":"evidence","title":"Preclinical evidence","description":"Explains what mechanism, specificity, and model evidence should establish.","weight":0.4,"coachingQuestions":["Which uncertainty must be reduced before exposing a person?"]},{"id":"safeguards","title":"Participant safeguards","description":"Addresses consent, eligibility, monitoring, stopping rules, and long-term follow-up.","weight":0.35,"coachingQuestions":["How should unknown risk be communicated without therapeutic misconception?"]},{"id":"inference","title":"Responsible inference","description":"Distinguishes safety, biological activity, and efficacy claims.","weight":0.25,"coachingQuestions":["What can a small uncontrolled trial actually show?"]}],"coachingPrompts":["Separate scientific validity from social value.","Explain why long-term follow-up matters.","State what result would halt escalation."],"modelOutline":["Disease need and alternatives","Preclinical threshold","Consent and selection","Monitoring and stopping","Limits of early evidence"],"sources":[{"id":"fda-gene-therapy-guidance","title":"Human Gene Therapy Products Incorporating Human Genome Editing","publisher":"U.S. Food and Drug Administration","url":"https://www.fda.gov/regulatory-information/search-fda-guidance-documents/human-gene-therapy-products-incorporating-human-genome-editing","accessedAt":"2026-07-27T12:00:00Z","usage":"linkOnly","evidenceLocator":"FDA guidance page and linked document"}],"tags":["clinical-trials","bioethics","risk"],"generatedAt":"2026-07-27T12:00:00Z","validUntil":"2027-07-27T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"editorial-v1","reviewStatus":"verified"},{"id":"space-transit-method-001","category":"space","conceptID":"space.observation-instrumentation","conceptTitle":"Transit photometry","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"A star's otherwise steady brightness drops by nearly the same small fraction for a few hours at regular intervals, with each dip having a similar shape. What is the strongest initial interpretation?","choices":[{"id":"a","text":"Starspots rotating into view, since spot coverage repeats with the star's rotation period.","rationale":"Spots produce broad, continuous modulation that evolves as spots change, not brief identical dips from an otherwise steady baseline."},{"id":"b","text":"A pulsating star whose radius shrinks and expands on a regular cycle.","rationale":"Pulsation varies brightness continuously through the whole cycle rather than producing short dips separated by steady stretches."},{"id":"c","text":"An orbiting body that periodically passes in front of the star along our line of sight.","rationale":"Correct. Brief, repeatable, same-shaped dips at a fixed period are the signature transit surveys look for, subject to confirmation."},{"id":"d","text":"The star's Doppler wobble as an unseen planet tugs it toward and away from us.","rationale":"A reflex wobble shifts spectral lines (the radial-velocity method); it does not dim the star's brightness."}],"correctChoiceID":"c","explanation":"Regular dips can indicate a transit, but stellar activity or blended systems can mimic one. Follow-up observations test the candidate and estimate other properties.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"nasa-exoplanet-methods","title":"How We Find and Characterize Exoplanets","publisher":"NASA Science","url":"https://science.nasa.gov/exoplanets/how-we-find-and-characterize/","accessedAt":"2026-07-27T12:00:00Z","usage":"linkOnly","evidenceLocator":"Transit method"}],"tags":["exoplanets","transits"],"generatedAt":"2026-07-27T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"editorial-v1","reviewStatus":"verified"},{"id":"space-redshift-spectrum-001","category":"space","conceptID":"space.cosmology-evidence","conceptTitle":"Spectral redshift","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"An astronomer recognizes a familiar pattern of absorption lines in a galaxy, but every line appears at a proportionally longer wavelength than in a laboratory spectrum. What does the pattern most directly measure?","choices":[{"id":"a","text":"The galaxy's temperature, since cooler gas shifts its spectral lines toward the red.","rationale":"Temperature changes the continuum shape and which lines are strong, not the wavelengths of the atomic transitions."},{"id":"b","text":"Interstellar reddening by dust, which moves the galaxy's lines to longer wavelengths.","rationale":"Dust reddening dims blue light more than red, changing the continuum slope, but it does not shift line wavelengths."},{"id":"c","text":"The galaxy's distance, read directly in megaparsecs from the size of the line shift.","rationale":"Converting redshift to distance needs a cosmological model and calibration and is affected by peculiar motion; the shift itself measures redshift."},{"id":"d","text":"The galaxy's redshift: a proportional shift of its spectrum relative to the lab.","rationale":"Correct. A recognizable line pattern displaced by a common factor to longer wavelengths is exactly what redshift quantifies."}],"correctChoiceID":"d","explanation":"Matching line patterns identify atomic transitions; their systematic wavelength shift defines redshift. Interpreting its cause and converting it to distance requires additional context.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"openstax-astronomy-2e","title":"Astronomy 2e","publisher":"OpenStax","url":"https://openstax.org/details/books/astronomy-2e","accessedAt":"2026-07-27T12:00:00Z","license":"CC BY 4.0","usage":"openLicense","evidenceLocator":"Spectroscopy and redshift"}],"tags":["spectroscopy","redshift"],"generatedAt":"2026-07-27T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"editorial-v1","reviewStatus":"verified"},{"id":"space-exoplanet-atmosphere-essay-001","category":"space","conceptID":"space.planetary-systems","conceptTitle":"Interpreting exoplanet spectra","type":"essay","dimension":"synthesis","difficulty":"advanced","prompt":"A team reports water vapor in an exoplanet atmosphere from a transmission spectrum. Explain what observations and checks would make the claim persuasive, and why the finding would not by itself establish habitability or life.","choices":[],"explanation":"Coaching should reward a chain from measurement through alternative explanations to a calibrated conclusion.","rubric":[{"id":"measurement","title":"Measurement chain","description":"Explains transit spectroscopy, uncertainty, repeated observations, and instrument calibration.","weight":0.4,"coachingQuestions":["Which signal is divided or compared to isolate atmospheric absorption?"]},{"id":"alternatives","title":"Alternative explanations","description":"Considers stellar contamination, clouds, retrieval assumptions, and independent confirmation.","weight":0.35,"coachingQuestions":["What non-planetary effect could mimic a spectral feature?"]},{"id":"claim","title":"Claim discipline","description":"Separates molecule detection from habitability and biosignature claims.","weight":0.25,"coachingQuestions":["What additional context is needed before discussing life?"]}],"coachingPrompts":["Trace the claim from photons to molecule.","Name at least two confounders.","State the narrowest justified conclusion."],"modelOutline":["Observation design","Spectral retrieval","Cross-checks","Planetary context","Limits on habitability inference"],"sources":[{"id":"nasa-exoplanet-methods","title":"How We Find and Characterize Exoplanets","publisher":"NASA Science","url":"https://science.nasa.gov/exoplanets/how-we-find-and-characterize/","accessedAt":"2026-07-27T12:00:00Z","usage":"linkOnly","evidenceLocator":"Atmospheric characterization"}],"tags":["exoplanets","spectroscopy","evidence"],"generatedAt":"2026-07-27T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"editorial-v1","reviewStatus":"verified"},{"id":"philosophy-valid-sound-001","category":"philosophy","conceptID":"philosophy.argument-validity","conceptTitle":"Validity and soundness","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"Consider this argument: 'All fish are mammals. All whales are fish. Therefore, all whales are mammals.' Which evaluation of it is correct?","choices":[{"id":"a","text":"It is valid but unsound: the form holds, yet both premises are false.","rationale":"Correct. The form (all A are B; all C are A; so all C are B) guarantees the conclusion if the premises are true, so it is valid; because the premises are in fact false, it is not sound."},{"id":"b","text":"It is invalid, because a true conclusion cannot follow from false premises.","rationale":"Validity is about form, not the actual truth of the parts. False premises can validly lead to a true conclusion, as they do here; they just give no good reason to accept it."},{"id":"c","text":"It is sound, because its form is valid and its conclusion is in fact true.","rationale":"Soundness requires a valid form plus premises that are all true. A true conclusion does not make up for false premises."},{"id":"d","text":"It is invalid, because validity requires every premise to be actually true.","rationale":"That confuses validity with soundness. Validity asks only whether true premises would guarantee the conclusion; a valid argument can have false premises."}],"correctChoiceID":"a","explanation":"Validity asks whether true premises would guarantee the conclusion, and this argument has a valid form: all A are B; all C are A; so all C are B. Soundness is validity plus premises that are in fact true. Both premises here are false, so the argument is valid but unsound, even though its conclusion happens to be true. A true conclusion never shows by itself that an argument is valid or sound.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"iep-validity","title":"Validity and Soundness","publisher":"Internet Encyclopedia of Philosophy","url":"https://iep.utm.edu/val-snd/","accessedAt":"2026-07-27T12:00:00Z","usage":"linkOnly","evidenceLocator":"Validity and soundness distinctions"}],"tags":["logic","validity"],"generatedAt":"2026-07-27T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"editorial-v1","reviewStatus":"verified"},{"id":"philosophy-deontology-consequence-001","category":"philosophy","conceptID":"philosophy.ethics-frameworks","conceptTitle":"Deontology and consequentialism","type":"multipleChoice","dimension":"recognition","difficulty":"college","prompt":"Which claim most clearly distinguishes a deontological theory from a purely consequentialist one?","choices":[{"id":"a","text":"Deontologists judge acts by intended consequences; consequentialists, by actual ones.","rationale":"Intended versus actual consequences is a debate within consequentialism; deontology is not defined by appeal to intended outcomes."},{"id":"b","text":"Deontologists follow moral rules, while consequentialists never rely on rules at all.","rationale":"Rule consequentialism relies on rules justified by their outcomes; the difference lies in what grounds rightness, not whether rules are used."},{"id":"c","text":"Deontologists treat consequences as irrelevant; consequentialists treat them as relevant.","rationale":"Many deontologists count consequences (for example, a duty of beneficence); they deny only that outcomes alone settle what is right."},{"id":"d","text":"Some acts are wrong even when performing them would produce the best overall outcome.","rationale":"Correct. Deontology gives duties or constraints independent weight, so rightness is not reducible to outcomes."}],"correctChoiceID":"d","explanation":"Deontology assigns foundational importance to duties, permissions, or constraints. Consequentialism makes the value of outcomes foundational to the rightness of acts.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"sep-deontology","title":"Deontological Ethics","publisher":"Stanford Encyclopedia of Philosophy","url":"https://plato.stanford.edu/entries/ethics-deontological/","accessedAt":"2026-07-27T12:00:00Z","usage":"linkOnly","evidenceLocator":"Deontological theories"},{"id":"sep-consequentialism","title":"Consequentialism","publisher":"Stanford Encyclopedia of Philosophy","url":"https://plato.stanford.edu/entries/consequentialism/","accessedAt":"2026-07-27T12:00:00Z","usage":"linkOnly","evidenceLocator":"General definition"}],"tags":["ethics","deontology","consequentialism"],"generatedAt":"2026-07-27T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"editorial-v1","reviewStatus":"verified"},{"id":"philosophy-public-policy-essay-001","category":"philosophy","conceptID":"philosophy.political-legitimacy","conceptTitle":"Ethical argument in public policy","type":"essay","dimension":"synthesis","difficulty":"advanced","prompt":"A city can reduce serious traffic injuries by deploying automatic cameras, but doing so expands routine surveillance. Analyze the policy through one consequentialist lens and one rights- or duty-based lens, then defend a policy with safeguards.","choices":[],"explanation":"The response should reconstruct competing moral reasons before reaching a qualified judgment rather than merely naming theories.","rubric":[{"id":"frameworks","title":"Accurate frameworks","description":"Uses each ethical framework as an argument, not a label.","weight":0.4,"coachingQuestions":["What makes an action right within each framework?"]},{"id":"conflict","title":"Tradeoff analysis","description":"Identifies empirical assumptions and genuine conflicts among safety, privacy, equality, and accountability.","weight":0.35,"coachingQuestions":["Which factual uncertainty could reverse your conclusion?"]},{"id":"judgment","title":"Defended judgment","description":"Offers a coherent policy and safeguards responsive to objections.","weight":0.25,"coachingQuestions":["Which safeguard follows from your moral analysis?"]}],"coachingPrompts":["State each framework's decision rule.","Separate empirical predictions from moral premises.","Answer the strongest objection to your recommendation."],"modelOutline":["Moral stakes","Consequentialist analysis","Duty or rights analysis","Policy design","Objection and response"],"sources":[{"id":"sep-deontology","title":"Deontological Ethics","publisher":"Stanford Encyclopedia of Philosophy","url":"https://plato.stanford.edu/entries/ethics-deontological/","accessedAt":"2026-07-27T12:00:00Z","usage":"linkOnly","evidenceLocator":"Deontological theories"},{"id":"sep-consequentialism","title":"Consequentialism","publisher":"Stanford Encyclopedia of Philosophy","url":"https://plato.stanford.edu/entries/consequentialism/","accessedAt":"2026-07-27T12:00:00Z","usage":"linkOnly","evidenceLocator":"Consequentialist structure"}],"tags":["applied-ethics","privacy","policy"],"generatedAt":"2026-07-27T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"editorial-v1","reviewStatus":"verified"},{"id":"history-primary-source-context-001","category":"history","conceptID":"history.primary-source-criticism","conceptTitle":"Contextualizing primary sources","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"A wartime propaganda poster is being used to study public opinion. Which first step best avoids treating it as a transparent record of what everyone believed?","choices":[{"id":"a","text":"Count how many copies were printed, since circulation shows how many people agreed.","rationale":"Print runs measure distribution, not agreement; a widely posted message can be ignored or resented."},{"id":"b","text":"Establish who made it, for what audience and purpose, and how widely it circulated.","rationale":"Correct. Sourcing and contextualization define what the poster can evidence, such as official messaging, rather than what everyone believed."},{"id":"c","text":"Check whether its factual claims were accurate, since accurate posters mirrored opinion.","rationale":"Accuracy of claims says nothing about whether audiences accepted them, and it skips the sourcing step."},{"id":"d","text":"Analyze its imagery and slogans closely, since persuasive design reveals what viewers felt.","rationale":"Close reading reveals the producer's strategy and assumptions, not audience reception; without sourcing it still treats the poster as a mirror of opinion."}],"correctChoiceID":"b","explanation":"A source can illuminate official messaging, persuasive strategies, or assumptions without measuring public belief. Provenance, purpose, audience, and corroboration define its evidentiary reach.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"loc-primary-sources","title":"Getting Started with Primary Sources","publisher":"Library of Congress","url":"https://www.loc.gov/programs/teachers/getting-started-with-primary-sources/","accessedAt":"2026-07-27T12:00:00Z","usage":"linkOnly","evidenceLocator":"Observe, reflect, question"}],"tags":["historiography","primary-sources"],"generatedAt":"2026-07-27T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"editorial-v1","reviewStatus":"verified"},{"id":"history-corroboration-001","category":"history","conceptID":"history.comparison-context","conceptTitle":"Corroboration","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"Two eyewitness accounts of the same protest disagree about crowd size and who initiated violence. What is the strongest historical response?","choices":[{"id":"a","text":"Weigh each witness's vantage and motives, then test both against independent evidence.","rationale":"Correct. Disagreement becomes evidence to investigate through sourcing and corroboration with independent records and material evidence."},{"id":"b","text":"Prefer the account written closer to the event, since memory degrades quickly over time.","rationale":"Timing is one useful factor, but a contemporaneous account can still be partisan or limited in vantage; it does not settle the dispute alone."},{"id":"c","text":"Prefer the witness with no stake in the outcome, and treat that account as settled.","rationale":"A disinterested witness may be more credible, but a single account still needs testing against vantage point and independent evidence."},{"id":"d","text":"Report only what the accounts agree on and treat the disputed points as unknowable.","rationale":"Agreement is useful, but disputed points can often be tested against other records; declaring them unknowable abandons inquiry."}],"correctChoiceID":"a","explanation":"Corroboration evaluates how independent evidence converges or diverges while accounting for source position. It can support a bounded conclusion without pretending uncertainty disappeared.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"archives-document-analysis","title":"Document Analysis","publisher":"U.S. National Archives","url":"https://www.archives.gov/education/lessons/worksheets","accessedAt":"2026-07-27T12:00:00Z","usage":"linkOnly","evidenceLocator":"Primary source analysis worksheets"}],"tags":["corroboration","evidence"],"generatedAt":"2026-07-27T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"editorial-v1","reviewStatus":"verified"},{"id":"history-archive-argument-essay-001","category":"history","conceptID":"history.historiography-interpretation","conceptTitle":"Building a historical argument","type":"essay","dimension":"synthesis","difficulty":"advanced","prompt":"You have a government report, three private letters, a newspaper editorial, and later oral histories about a forced migration. Explain how you would use this uneven archive to make a defensible claim without erasing uncertainty or treating every source as equivalent.","choices":[],"explanation":"Coaching should emphasize provenance, comparison, silence in the archive, and claims calibrated to evidence.","rubric":[{"id":"sourcing","title":"Source criticism","description":"Evaluates purpose, audience, position, timing, and preservation for each source type.","weight":0.4,"coachingQuestions":["Whose perspective was easiest for the archive to preserve?"]},{"id":"corroboration","title":"Corroboration strategy","description":"Explains how sources will be compared rather than simply accumulated.","weight":0.35,"coachingQuestions":["Where can independent evidence test a disputed claim?"]},{"id":"calibration","title":"Calibrated conclusion","description":"Distinguishes strong findings, plausible inferences, and unresolved questions.","weight":0.25,"coachingQuestions":["Which sentence in your conclusion needs a qualifier?"]}],"coachingPrompts":["Create a provenance note for each source type.","Identify one archival silence.","Match the strength of each claim to the evidence."],"modelOutline":["Research question","Archive and its biases","Comparison method","Claim with counterevidence","Uncertainty and next evidence"],"sources":[{"id":"loc-primary-sources","title":"Getting Started with Primary Sources","publisher":"Library of Congress","url":"https://www.loc.gov/programs/teachers/getting-started-with-primary-sources/","accessedAt":"2026-07-27T12:00:00Z","usage":"linkOnly","evidenceLocator":"Primary-source inquiry"}],"tags":["archives","historiography","argument"],"generatedAt":"2026-07-27T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"editorial-v1","reviewStatus":"verified"},{"id":"people-curie-nobel-001","category":"people","conceptID":"people.leadership-institutions","conceptTitle":"Marie Curie and scientific institutions","type":"multipleChoice","dimension":"recall","difficulty":"college","prompt":"What makes Marie Curie's Nobel record historically distinctive?","choices":[{"id":"a","text":"She is the only person to have won two Nobel Prizes in the same science.","rationale":"Her prizes were in different fields. Two prizes in one science describes laureates such as John Bardeen (Physics) or Frederick Sanger (Chemistry)."},{"id":"b","text":"She won the Physics Prize alone, then shared the Chemistry Prize with Pierre Curie.","rationale":"This reverses the record: she shared the 1903 Physics Prize, while the 1911 Chemistry Prize was hers alone, awarded after Pierre's death in 1906."},{"id":"c","text":"She won Nobel Prizes in two different sciences, Physics and Chemistry.","rationale":"Correct. She shared the 1903 Physics Prize and received the 1911 Chemistry Prize, and remains the only laureate honored in two different sciences."},{"id":"d","text":"She shared both prizes with Pierre Curie for discovering radium and polonium.","rationale":"Pierre Curie died in 1906; only the 1903 Physics Prize was shared with him (and Henri Becquerel)."}],"correctChoiceID":"c","explanation":"Curie shared the 1903 Physics Prize for work on radiation and received the 1911 Chemistry Prize for work involving radium and polonium. The record also reveals changing access to scientific recognition.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"nobel-curie","title":"Marie Curie – Biographical","publisher":"Nobel Prize Outreach","url":"https://www.nobelprize.org/prizes/physics/1903/marie-curie/biographical/","accessedAt":"2026-07-27T12:00:00Z","usage":"linkOnly","evidenceLocator":"Prize biography"}],"tags":["marie-curie","science-history"],"generatedAt":"2026-07-27T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"editorial-v1","reviewStatus":"verified"},{"id":"people-dubois-double-consciousness-001","category":"people","conceptID":"people.identity-context","conceptTitle":"W. E. B. Du Bois","type":"multipleChoice","dimension":"recognition","difficulty":"college","prompt":"In the work of W. E. B. Du Bois, what problem does the idea of 'double consciousness' illuminate?","choices":[{"id":"a","text":"Seeing oneself through one's own eyes and through the contempt of a racist society.","rationale":"Correct. Du Bois describes a divided self-perception: measuring one's soul by the tape of a world that looks on in contempt."},{"id":"b","text":"The color line: the worldwide division of peoples by race in the twentieth century.","rationale":"The color line is Du Bois's term for the structural problem of the century; double consciousness names the inner experience of living under it."},{"id":"c","text":"The talented tenth: an educated Black elite responsible for leading racial uplift.","rationale":"That is a different Du Bois idea about leadership and education, not the divided self-perception of double consciousness."},{"id":"d","text":"Accommodation: accepting segregation for now in exchange for economic progress.","rationale":"That describes Booker T. Washington's strategy, which Du Bois criticized in the same book."}],"correctChoiceID":"a","explanation":"Du Bois used the concept to describe a self experienced through one's own consciousness and through the devaluing gaze of a racist society. It links individual identity to social structure.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"gutenberg-souls-black-folk","title":"The Souls of Black Folk","publisher":"Project Gutenberg","url":"https://www.gutenberg.org/ebooks/408","accessedAt":"2026-07-27T12:00:00Z","usage":"publicDomain","evidenceLocator":"Chapter I, Of Our Spiritual Strivings"},{"id":"loc-dubois-resource","title":"W. E. B. Du Bois: A Resource Guide","publisher":"Library of Congress","url":"https://guides.loc.gov/web-dubois","accessedAt":"2026-07-27T12:00:00Z","usage":"linkOnly","evidenceLocator":"Works and contextual resources"}],"tags":["du-bois","sociology","identity"],"generatedAt":"2026-07-27T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"editorial-v1","reviewStatus":"verified"},{"id":"people-biography-context-essay-001","category":"people","conceptID":"people.biography-evidence","conceptTitle":"Biography and historical agency","type":"essay","dimension":"synthesis","difficulty":"advanced","prompt":"Choose a major intellectual, artist, scientist, or political organizer. Explain one achievement without reducing it either to lone genius or to impersonal historical forces. Show how personal choices, collaborators, institutions, and constraints interacted.","choices":[],"explanation":"Coaching should produce a causal biography that retains agency while making systems and collaborators visible.","rubric":[{"id":"evidence","title":"Biographical evidence","description":"Uses reliable evidence for the achievement, choices, and relevant relationships.","weight":0.4,"coachingQuestions":["Which source supports your claim about motive rather than merely action?"]},{"id":"context","title":"Context and collaboration","description":"Explains institutions, collaborators, resources, and constraints causally.","weight":0.35,"coachingQuestions":["Who or what made the achievement possible?"]},{"id":"balance","title":"Balanced agency","description":"Avoids both hero worship and a biography in which the person makes no consequential choices.","weight":0.25,"coachingQuestions":["Where did this person have a meaningful choice?"]}],"coachingPrompts":["Distinguish evidence of action from speculation about motive.","Name overlooked collaborators.","Explain one counterfactual carefully."],"modelOutline":["Achievement and thesis","Personal decisions","Networks and institutions","Constraints","Balanced assessment"],"sources":[{"id":"smithsonian-learning-lab","title":"Smithsonian Learning Lab","publisher":"Smithsonian Institution","url":"https://learninglab.si.edu/","accessedAt":"2026-07-27T12:00:00Z","usage":"linkOnly","evidenceLocator":"Primary-source collections and object records"}],"tags":["biography","agency","institutions"],"generatedAt":"2026-07-27T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"editorial-v1","reviewStatus":"verified"},{"id":"law-burdens-of-proof-001","category":"law","conceptID":"law.procedure-remedies","conceptTitle":"Civil and criminal burdens","type":"multipleChoice","dimension":"recognition","difficulty":"college","prompt":"Which statement best captures a common difference between ordinary civil litigation and criminal prosecution in the United States?","choices":[{"id":"a","text":"Civil: clear and convincing evidence; criminal: guilt beyond a reasonable doubt.","rationale":"Clear and convincing evidence is an intermediate standard used for certain civil issues, such as fraud in many jurisdictions, not the ordinary civil default."},{"id":"b","text":"Civil: preponderance of the evidence; criminal: guilt beyond a reasonable doubt.","rationale":"Correct. These are the usual baseline burdens, although particular issues and proceedings can use other standards."},{"id":"c","text":"Civil: preponderance of the evidence; criminal: clear and convincing proof of guilt.","rationale":"Criminal conviction requires proof beyond a reasonable doubt, a higher standard than clear and convincing evidence."},{"id":"d","text":"Civil: probable cause, as for a warrant; criminal: guilt beyond a reasonable doubt.","rationale":"Probable cause governs arrests, searches, and charging decisions, not the plaintiff's burden to win a civil judgment."}],"correctChoiceID":"b","explanation":"The different burdens reflect different stakes and error costs. Specific proceedings and issues may use other standards, so the statement is a general legal-literacy baseline rather than case advice.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"uscourts-civil-cases","title":"Civil Cases","publisher":"Administrative Office of the U.S. Courts","url":"https://www.uscourts.gov/about-federal-courts/types-cases/civil-cases","accessedAt":"2026-07-27T12:00:00Z","usage":"linkOnly","evidenceLocator":"Civil standard of proof"},{"id":"uscourts-criminal-cases","title":"Criminal Cases","publisher":"Administrative Office of the U.S. Courts","url":"https://www.uscourts.gov/about-federal-courts/types-cases/criminal-cases","accessedAt":"2026-07-27T12:00:00Z","usage":"linkOnly","evidenceLocator":"Government burden"}],"tags":["legal-literacy","procedure","burden-of-proof"],"generatedAt":"2026-07-27T12:00:00Z","validUntil":"2027-07-27T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"legal-editorial-v1","reviewStatus":"verified"},{"id":"law-precedent-statute-001","category":"law","conceptID":"law.authority-hierarchy","conceptTitle":"Statutes and precedent","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"A legislature enacts a statute, and later appellate courts decide disputes about ambiguous language in that statute. Which description is most accurate?","choices":[{"id":"a","text":"The statute remains law, but each judicial reading binds only the parties to that case.","rationale":"Binding only the parties describes the judgment's preclusive effect; published appellate interpretations also serve as precedent for lower courts."},{"id":"b","text":"The courts' readings replace the statute, which then has no independent legal force.","rationale":"Interpretation applies the enacted text rather than erasing it, and the legislature can still amend the statute."},{"id":"c","text":"The statute remains law, and appellate readings of it bind lower courts in that jurisdiction.","rationale":"Correct. Enacted text stays in force, and under stare decisis an appellate interpretation binds courts below it in the same hierarchy."},{"id":"d","text":"Appellate readings bind every court nationwide, since they interpret enacted law.","rationale":"Binding force depends on jurisdiction and hierarchy; for example, one federal circuit does not bind another, and a state court does not bind other states."}],"correctChoiceID":"c","explanation":"Legislatures enact statutes and courts resolve concrete disputes about their meaning. Whether a decision binds another court depends on jurisdiction, hierarchy, later cases, and any later statutory change.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"uscourts-court-role","title":"Court Role and Structure","publisher":"Administrative Office of the U.S. Courts","url":"https://www.uscourts.gov/about-federal-courts/court-role-and-structure","accessedAt":"2026-07-27T12:00:00Z","usage":"linkOnly","evidenceLocator":"Judicial interpretation and appellate structure"}],"tags":["legal-literacy","precedent","statutes"],"generatedAt":"2026-07-27T12:00:00Z","validUntil":"2027-07-27T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"legal-editorial-v1","reviewStatus":"verified"},{"id":"law-judicial-review-essay-001","category":"law","conceptID":"law.rights-government-power","conceptTitle":"Judicial review","type":"essay","dimension":"synthesis","difficulty":"advanced","prompt":"Explain judicial review to an educated reader who assumes courts can invalidate any policy they dislike. Describe its constitutional setting, the role of a concrete case, interpretive disagreement, precedent, and institutional limits.","choices":[],"explanation":"This is general civic education, not legal advice. Coaching should distinguish legal authority from policy preference without pretending constitutional interpretation is mechanical.","rubric":[{"id":"doctrine","title":"Legal framework","description":"Accurately explains review in the context of cases, constitutional supremacy, and court authority.","weight":0.4,"coachingQuestions":["Why does the existence of a concrete dispute matter?"]},{"id":"reasoning","title":"Interpretation and precedent","description":"Explains that legal reasoning uses text, structure, history, precedent, and contested methods.","weight":0.35,"coachingQuestions":["How can judges disagree while still giving legal reasons?"]},{"id":"limits","title":"Institutional limits","description":"Addresses jurisdiction, remedies, compliance, later cases, and constitutional amendment or legislation where applicable.","weight":0.25,"coachingQuestions":["What can a court judgment not accomplish by itself?"]}],"coachingPrompts":["Define judicial review before evaluating it.","Use one historical example as illustration, not as the whole rule.","State at least two institutional limits."],"modelOutline":["Constitutional setting","Case-or-controversy context","Interpretive reasoning","Precedent and hierarchy","Limits and democratic tension"],"sources":[{"id":"congress-constitution-judicial-review","title":"Judicial Review","publisher":"Congressional Research Service, Constitution Annotated","url":"https://constitution.congress.gov/browse/essay/artIII-S1-2-1/ALDE_00013513/","accessedAt":"2026-07-27T12:00:00Z","usage":"linkOnly","evidenceLocator":"Judicial review essay and linked authorities"}],"tags":["legal-literacy","judicial-review","civics"],"generatedAt":"2026-07-27T12:00:00Z","validUntil":"2027-07-27T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"legal-editorial-v1","reviewStatus":"verified"},{"id":"investing-diversification-001","category":"investing","conceptID":"investing.diversification-correlation","conceptTitle":"Diversification","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"An investor replaces a single-company stock position with a broad portfolio spanning many firms and industries. Which risk is most directly reduced?","choices":[{"id":"a","text":"Firm-specific risk, since one company's lawsuit or failed product matters less.","rationale":"Correct. Diversification is most effective against idiosyncratic risk that is not shared across holdings."},{"id":"b","text":"Market risk, since owning many firms spreads exposure across the whole economy.","rationale":"Market-wide (systematic) risk affects most holdings together, so spreading across many firms cannot remove it."},{"id":"c","text":"Interest-rate risk, since a broad stock portfolio offsets rising and falling rates.","rationale":"A broad equity portfolio remains exposed to rate changes that affect valuations across the market."},{"id":"d","text":"Inflation risk, since different industries' prices rise at different rates.","rationale":"Broad inflation affects real returns across the whole market; holding many stocks does not neutralize it."}],"correctChoiceID":"a","explanation":"Diversification reduces dependence on one issuer or narrow sector. It manages risk but does not guarantee profit or protect against every market loss.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"sec-diversification","title":"Diversification","publisher":"U.S. Securities and Exchange Commission, Investor.gov","url":"https://www.investor.gov/introduction-investing/investing-basics/glossary/diversification","accessedAt":"2026-07-27T12:00:00Z","usage":"linkOnly","evidenceLocator":"Investor glossary"}],"tags":["portfolio","risk","diversification"],"generatedAt":"2026-07-27T12:00:00Z","validUntil":"2027-07-27T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"finance-editorial-v1","reviewStatus":"verified"},{"id":"investing-bond-rates-001","category":"investing","conceptID":"investing.valuation-cash-flows","conceptTitle":"Interest rates and bond prices","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"Market interest rates rise after an investor buys a conventional fixed-rate bond. All else equal, what generally happens to the bond's resale price?","choices":[{"id":"a","text":"It rises, because the bond's yield to maturity moves up with market rates.","rationale":"The yield rises precisely because the price falls; price and yield move in opposite directions."},{"id":"b","text":"It stays near par, because a fixed coupon locks in the bond's market value.","rationale":"Fixed cash flows have a lower present value when discount rates rise; par is assured only at maturity, absent default."},{"id":"c","text":"It falls, because new bonds now offer higher coupons for the same price.","rationale":"Correct. The older bond's fixed payments must trade at a discount to offer a competitive yield."},{"id":"d","text":"It falls only if the issuer's credit rating is also downgraded.","rationale":"A rate change alone moves the price; credit risk is a separate influence."}],"correctChoiceID":"c","explanation":"Bond prices and prevailing rates generally move in opposite directions. Longer maturities and lower coupons commonly produce greater sensitivity, though actual pricing also reflects credit and liquidity.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"sec-bonds","title":"Bonds or Fixed Income Products","publisher":"U.S. Securities and Exchange Commission, Investor.gov","url":"https://www.investor.gov/introduction-investing/investing-basics/investment-products/bonds-or-fixed-income-products","accessedAt":"2026-07-27T12:00:00Z","usage":"linkOnly","evidenceLocator":"Interest-rate risk"}],"tags":["bonds","interest-rates","risk"],"generatedAt":"2026-07-27T12:00:00Z","validUntil":"2027-07-27T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"finance-editorial-v1","reviewStatus":"verified"},{"id":"investing-fund-comparison-essay-001","category":"investing","conceptID":"investing.fees-taxes-compounding","conceptTitle":"Comparing investment funds","type":"essay","dimension":"synthesis","difficulty":"advanced","prompt":"Two diversified funds pursue similar markets, but differ in fees, turnover, benchmark, tax consequences, and tracking. Build a decision framework for comparing them for a long-term goal without predicting which will outperform.","choices":[],"explanation":"This is education, not personalized investment advice. Coaching should favor a transparent decision process over a return forecast.","rubric":[{"id":"goal","title":"Goal and constraints","description":"Defines horizon, risk capacity, liquidity, account type, and relevant benchmark.","weight":0.4,"coachingQuestions":["Which constraint could make a lower-fee fund unsuitable?"]},{"id":"cost-risk","title":"Cost and risk comparison","description":"Analyzes total fees, turnover, concentration, tracking, and tax effects.","weight":0.35,"coachingQuestions":["Which costs compound even when performance is similar?"]},{"id":"uncertainty","title":"Uncertainty discipline","description":"Avoids treating past performance or a single metric as a forecast.","weight":0.25,"coachingQuestions":["What do you still not know after reading historical returns?"]}],"coachingPrompts":["Separate controllable costs from uncertain returns.","State the benchmark and why it fits.","Identify missing information before deciding."],"modelOutline":["Investor objective","Exposure and benchmark","Costs and taxes","Risk and implementation","Decision rule and uncertainty"],"sources":[{"id":"sec-fees","title":"Understanding Fees","publisher":"U.S. Securities and Exchange Commission, Investor.gov","url":"https://www.investor.gov/introduction-investing/getting-started/understanding-fees","accessedAt":"2026-07-27T12:00:00Z","usage":"linkOnly","evidenceLocator":"Fee effects and comparison resources"}],"tags":["funds","fees","decision-making"],"generatedAt":"2026-07-27T12:00:00Z","validUntil":"2027-07-27T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"finance-editorial-v1","reviewStatus":"verified"},{"id":"business-profit-cash-flow-001","category":"business","conceptID":"business.unit-economics","conceptTitle":"Profit and cash flow","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"A growing company reports accounting profit but cannot pay suppliers on time because customers have not yet paid large invoices. What does this illustrate?","choices":[{"id":"a","text":"The company booked revenue too early and should restate its profit downward.","rationale":"Accrual accounting generally recognizes revenue when earned, before cash is collected; nothing in the stem indicates improper recognition."},{"id":"b","text":"The firm is insolvent, because its liabilities must now exceed its assets.","rationale":"This is a liquidity problem, not insolvency; the unpaid invoices are receivables, which are assets."},{"id":"c","text":"The firm has a margin problem, so raising prices would solve the supplier delays.","rationale":"The firm is profitable; the bottleneck is the timing of collections and working capital, not margins."},{"id":"d","text":"Profit and cash flow can diverge in timing, so a profitable firm can run short of cash.","rationale":"Correct. Accrual revenue can be recognized before customers pay, so receivables can grow faster than cash arrives."}],"correctChoiceID":"d","explanation":"Income statements and cash-flow statements answer different questions. Rapid growth can increase receivables and working-capital needs faster than cash arrives.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"sba-finances","title":"Manage Your Finances","publisher":"U.S. Small Business Administration","url":"https://www.sba.gov/business-guide/manage-your-business/manage-your-finances","accessedAt":"2026-07-27T12:00:00Z","usage":"linkOnly","evidenceLocator":"Cash-flow projection and financial management"}],"tags":["cash-flow","working-capital"],"generatedAt":"2026-07-27T12:00:00Z","validUntil":"2027-07-27T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"business-editorial-v1","reviewStatus":"verified"},{"id":"business-customer-segment-001","category":"business","conceptID":"business.market-research","conceptTitle":"Customer discovery","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"A team asks ten friends whether they 'like' an app idea and treats nine positive answers as proof of market demand. What is the most important flaw?","choices":[{"id":"a","text":"Friends are a biased sample, and saying they like an idea isn't evidence they'd adopt or pay.","rationale":"Correct. The test suffers from selection and courtesy bias and measures stated liking rather than behavior or commitment."},{"id":"b","text":"Ten answers are too few; polling 500 friends and followers would establish demand.","rationale":"A larger sample from the same friendly pool, asked the same hypothetical question, keeps both the selection and the courtesy bias."},{"id":"c","text":"The question was too vague; asking friends to rate the idea from 1 to 10 would fix it.","rationale":"A finer rating scale still measures acquaintances' stated opinions, not adoption or willingness to pay."},{"id":"d","text":"The team should first launch the full app, since only real sales can validate demand.","rationale":"Cheaper behavioral tests, such as pre-orders, pilots, or sign-ups from target customers, can validate demand before a full launch."}],"correctChoiceID":"a","explanation":"The team measured agreeable reactions among acquaintances, not demand in a defined segment. Better evidence tests the problem, alternatives, behavior, and meaningful commitments.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"openstax-entrepreneurship","title":"Entrepreneurship","publisher":"OpenStax","url":"https://openstax.org/details/books/entrepreneurship","accessedAt":"2026-07-27T12:00:00Z","license":"CC BY 4.0","usage":"openLicense","evidenceLocator":"Identifying entrepreneurial opportunity and market research"}],"tags":["customer-discovery","market-research"],"generatedAt":"2026-07-27T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"business-editorial-v1","reviewStatus":"verified"},{"id":"business-launch-experiment-essay-001","category":"business","conceptID":"business.value-proposition","conceptTitle":"Testing a business hypothesis","type":"essay","dimension":"synthesis","difficulty":"advanced","prompt":"A team believes independent restaurants will pay for a tool that reduces food waste. Design a low-cost validation sequence that tests the problem, buyer, value proposition, and willingness to pay before a full product build.","choices":[],"explanation":"Coaching should turn broad enthusiasm into falsifiable hypotheses, behavioral evidence, and explicit decision thresholds.","rubric":[{"id":"hypotheses","title":"Testable hypotheses","description":"Separates problem, customer, buyer, value, and pricing assumptions.","weight":0.4,"coachingQuestions":["Which assumption would kill the idea if false?"]},{"id":"experiments","title":"Evidence sequence","description":"Uses progressively costlier interviews, prototypes, and commitment tests with relevant participants.","weight":0.35,"coachingQuestions":["What behavior is stronger evidence than stated interest?"]},{"id":"decisions","title":"Decision rules","description":"Defines success, failure, iteration, and ethical handling of customer data.","weight":0.25,"coachingQuestions":["What result would make the team stop or change segments?"]}],"coachingPrompts":["Write each assumption as a falsifiable sentence.","Name the buyer separately from the user.","Set a threshold before collecting results."],"modelOutline":["Risk map","Problem interviews","Prototype test","Payment or commitment test","Go, revise, or stop criteria"],"sources":[{"id":"openstax-entrepreneurship","title":"Entrepreneurship","publisher":"OpenStax","url":"https://openstax.org/details/books/entrepreneurship","accessedAt":"2026-07-27T12:00:00Z","license":"CC BY 4.0","usage":"openLicense","evidenceLocator":"Opportunity recognition and business-model development"}],"tags":["experimentation","entrepreneurship","validation"],"generatedAt":"2026-07-27T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"business-editorial-v1","reviewStatus":"verified"},{"id":"recipe-emulsion-001","category":"recipe","conceptID":"recipe.ingredient-function","conceptTitle":"Emulsion stability","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"Why can mustard or egg yolk help a vinaigrette remain mixed longer than oil and vinegar shaken alone?","choices":[{"id":"a","text":"They dissolve the oil into the vinegar, forming a single uniform solution.","rationale":"An emulsion is a dispersion of droplets, not a solution; the oil remains a separate phase."},{"id":"b","text":"They make the oil and vinegar equal in density, so gravity stops separating them.","rationale":"The density difference remains; the emulsifier works at the interface rather than by matching densities."},{"id":"c","text":"Their acidity breaks the oil into smaller molecules that can mix with water.","rationale":"Droplets are made smaller mechanically by whisking; acid does not break the oil into water-soluble molecules."},{"id":"d","text":"Their amphiphilic molecules coat oil droplets, slowing them from merging again.","rationale":"Correct. Emulsifiers adsorb at the oil-water interface and slow droplet coalescence and separation."}],"correctChoiceID":"d","explanation":"Mechanical mixing creates droplets, and emulsifiers stabilize their interfaces. Droplet size, viscosity, temperature, and formulation also affect how quickly the emulsion separates.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"harvard-science-cooking","title":"Science and Cooking","publisher":"Harvard John A. Paulson School of Engineering and Applied Sciences","url":"https://sciencecooking.seas.harvard.edu/","accessedAt":"2026-07-27T12:00:00Z","usage":"linkOnly","evidenceLocator":"Course materials on food structure"}],"tags":["food-science","emulsion"],"generatedAt":"2026-07-27T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"culinary-editorial-v1","reviewStatus":"verified"},{"id":"recipe-browning-001","category":"recipe","conceptID":"recipe.heat-transfer","conceptTitle":"Maillard browning","type":"multipleChoice","dimension":"recognition","difficulty":"college","prompt":"Which description best distinguishes Maillard browning from caramelization?","choices":[{"id":"a","text":"Maillard browning is enzymatic, as when a cut apple browns; caramelization is non-enzymatic.","rationale":"Cut-apple browning is enzymatic (polyphenol oxidase). Maillard and caramelization are both non-enzymatic."},{"id":"b","text":"Maillard browning needs fat to get hot enough; caramelization occurs at lower heat.","rationale":"Maillard reactions do not require fat, and caramelization generally needs higher temperatures than Maillard browning."},{"id":"c","text":"Maillard browning is the browning of meats; caramelization is that of plant foods.","rationale":"Food type is not the distinction: bread crust and roasted coffee brown largely by Maillard chemistry, and meats lack much free sugar to caramelize."},{"id":"d","text":"Maillard needs amino groups and reducing sugars; caramelization, only sugar and heat.","rationale":"Correct. The presence of amino compounds is the central reactant distinction, though real foods can host both processes."}],"correctChoiceID":"d","explanation":"Maillard pathways begin with carbonyl-amino reactions and generate many flavor and color compounds. Caramelization transforms sugars through heat without requiring amino compounds.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"acs-maillard","title":"The Maillard Reaction Turns 100","publisher":"Chemical & Engineering News, American Chemical Society","url":"https://cen.acs.org/articles/90/i40/Maillard-Reaction-Turns-100.html","accessedAt":"2026-11-10T12:00:00Z","usage":"linkOnly","evidenceLocator":"Reaction overview"}],"tags":["food-chemistry","browning"],"generatedAt":"2026-07-27T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"culinary-editorial-v1","reviewStatus":"verified"},{"id":"recipe-debug-bread-essay-001","category":"recipe","conceptID":"recipe.sensory-analysis","conceptTitle":"Diagnosing a recipe","type":"essay","dimension":"synthesis","difficulty":"advanced","prompt":"A lean yeast bread is consistently dense. Design a controlled troubleshooting plan covering fermentation, dough development, hydration, shaping, and oven conditions. Change variables in a way that lets the baker learn from each batch.","choices":[],"explanation":"Coaching should connect mechanisms to observable tests and avoid changing every variable at once.","rubric":[{"id":"mechanisms","title":"Mechanistic hypotheses","description":"Links possible failure modes to gas production, retention, dough structure, and heat.","weight":0.4,"coachingQuestions":["Is the problem too little gas or failure to retain it?"]},{"id":"tests","title":"Controlled tests","description":"Prioritizes measurable one-variable comparisons with repeatable records.","weight":0.35,"coachingQuestions":["Which single change gives the most diagnostic next batch?"]},{"id":"safety-quality","title":"Quality and safety","description":"Uses sensible temperature, time, and handling observations without unsafe tasting or storage.","weight":0.25,"coachingQuestions":["What objective endpoint will you record?"]}],"coachingPrompts":["Write three competing hypotheses.","Choose the cheapest discriminating test.","Record ingredient mass, dough temperature, time, and result."],"modelOutline":["Observed failure","Ranked hypotheses","Controlled batch plan","Measurements","Interpretation and next iteration"],"sources":[{"id":"harvard-science-cooking","title":"Science and Cooking","publisher":"Harvard John A. Paulson School of Engineering and Applied Sciences","url":"https://sciencecooking.seas.harvard.edu/","accessedAt":"2026-07-27T12:00:00Z","usage":"linkOnly","evidenceLocator":"Course approach to culinary experimentation"}],"tags":["bread","experimentation","food-science"],"generatedAt":"2026-07-27T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"culinary-editorial-v1","reviewStatus":"verified"},{"id":"obscure-antikythera-001","category":"obscure","conceptID":"obscure.material-culture","conceptTitle":"Antikythera mechanism","type":"multipleChoice","dimension":"recognition","difficulty":"college","prompt":"Why is the Antikythera mechanism especially important to histories of technology?","choices":[{"id":"a","text":"It is the earliest known navigational instrument, used aboard ship to fix the vessel's position.","rationale":"It was found in a shipwreck, but it was an astronomical and calendrical calculator, not a navigation instrument."},{"id":"b","text":"Its bronze gearing computed celestial cycles, unmatched by other surviving ancient devices.","rationale":"Correct. The fragments preserve geared calculation of celestial and calendrical cycles unmatched in surviving technology for many centuries."},{"id":"c","text":"It is the oldest known mechanical clock, using an escapement to keep time.","rationale":"It was hand-cranked and had no escapement; escapement clocks appear in medieval Europe."},{"id":"d","text":"It shows Greek astronomers used a Sun-centered model of planetary motion.","rationale":"Reconstructions show an Earth-centered display of celestial cycles; it is not evidence of heliocentric astronomy."}],"correctChoiceID":"b","explanation":"The corroded fragments preserve a dense arrangement of gears used to represent celestial cycles and calendars. Reconstruction depends on archaeology, imaging, inscriptions, and mechanical modeling.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"nature-antikythera","title":"A Model of the Cosmos in the Ancient Greek Antikythera Mechanism","publisher":"Scientific Reports","url":"https://www.nature.com/articles/s41598-021-84310-w","accessedAt":"2026-07-27T12:00:00Z","license":"CC BY 4.0","usage":"openLicense","evidenceLocator":"Abstract, evidence, and reconstruction"}],"tags":["archaeology","technology","astronomy"],"generatedAt":"2026-07-27T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"editorial-v1","reviewStatus":"verified"},{"id":"obscure-quipu-001","category":"obscure","conceptID":"obscure.language-meaning","conceptTitle":"Quipu information systems","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"What does responsible interpretation of Inka quipu require?","choices":[{"id":"a","text":"Decoding them as a knotted alphabet, since the Inka recorded spoken language this way.","rationale":"Quipu are not an alphabetic script; whether some encode language-like information remains an open research question."},{"id":"b","text":"Reading them as numerical tallies only, since their decimal knot system is fully decoded.","rationale":"The positional decimal system is well understood, but some quipu may record nonnumerical information that is not yet deciphered."},{"id":"c","text":"Combining knot type, position, color, and cord structure with context, flagging what's undeciphered.","rationale":"Correct. Quipu encode information through several interacting material features, and not all uses are deciphered."},{"id":"d","text":"Relying chiefly on Spanish colonial transcriptions, since those record what each quipu said.","rationale":"Colonial records are valuable but partial and shaped by colonial purposes, and they rarely match surviving quipu one to one."}],"correctChoiceID":"c","explanation":"Quipu challenge narrow assumptions about what records look like. Their interpretation combines material analysis, mathematical structure, context, oral knowledge, and written sources produced under colonial conditions.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"nmai-quipu","title":"The Great Inka Road: Quipu","publisher":"Smithsonian National Museum of the American Indian","url":"https://americanindian.si.edu/nk360/inka-water/quipu/quipu","accessedAt":"2026-07-27T12:00:00Z","usage":"linkOnly","evidenceLocator":"Quipu structure and use"}],"tags":["inka","information-systems","material-culture"],"generatedAt":"2026-07-27T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"editorial-v1","reviewStatus":"verified"},{"id":"obscure-object-interpretation-essay-001","category":"obscure","conceptID":"obscure.material-culture","conceptTitle":"Reasoning from material culture","type":"essay","dimension":"synthesis","difficulty":"advanced","prompt":"Archaeologists recover an unfamiliar object with repeated wear marks, residues, and a patterned find context, but no explanatory text. Build a cautious interpretation that uses those clues while distinguishing observation, inference, analogy, and speculation.","choices":[],"explanation":"Coaching should reward multiple hypotheses and testable predictions instead of a confident story built from resemblance alone.","rubric":[{"id":"observations","title":"Evidence inventory","description":"Separates measured features and context from interpretive claims.","weight":0.4,"coachingQuestions":["Which statement is directly observed rather than inferred?"]},{"id":"hypotheses","title":"Competing hypotheses","description":"Develops alternatives and tests them against wear, residue, distribution, and experimental comparison.","weight":0.35,"coachingQuestions":["What evidence would distinguish ritual from everyday use?"]},{"id":"calibration","title":"Calibrated conclusion","description":"States confidence, analogy limits, and the next useful analysis.","weight":0.25,"coachingQuestions":["Where does analogy become speculation?"]}],"coachingPrompts":["List observations without purpose words.","Offer at least three functions.","Predict a finding that would weaken your preferred explanation."],"modelOutline":["Object and context","Observed traces","Alternative functions","Tests and comparisons","Provisional conclusion"],"sources":[{"id":"smithsonian-anthropology","title":"Department of Anthropology Collections","publisher":"Smithsonian National Museum of Natural History","url":"https://naturalhistory.si.edu/research/anthropology/collections-overview","accessedAt":"2026-07-27T12:00:00Z","usage":"linkOnly","evidenceLocator":"Material collections and research context"}],"tags":["archaeology","inference","objects"],"generatedAt":"2026-07-27T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"editorial-v1","reviewStatus":"verified"},{"id":"literature-free-indirect-discourse-001","category":"literature","conceptID":"literature.narrative-voice","conceptTitle":"Free indirect discourse","type":"multipleChoice","dimension":"recognition","difficulty":"advanced","prompt":"Which feature most strongly suggests free indirect discourse in a third-person narrative?","choices":[{"id":"a","text":"The narrator reports thoughts with a tag, as in 'she thought that he was late again.'","rationale":"A tagged report of thought is ordinary indirect discourse; free indirect discourse drops the reporting clause."},{"id":"b","text":"A first-person narrator directly addresses the reader to reveal private thoughts.","rationale":"Free indirect discourse is a third-person technique; direct address by a first-person narrator is something else."},{"id":"c","text":"Third-person narration slips into a character's own idiom and judgments without 'she thought.'","rationale":"Correct. Free indirect style keeps third-person grammar while borrowing the character's voice without a reporting clause."},{"id":"d","text":"Unpunctuated, associative prose renders a character's raw flow of thought.","rationale":"That describes stream-of-consciousness writing; free indirect discourse often uses conventional syntax and punctuation."}],"correctChoiceID":"c","explanation":"Free indirect discourse can preserve third-person narration and past tense while borrowing a character's exclamations, judgments, or deictic viewpoint. The ambiguity enables irony and intimacy.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"cambridge-narrative","title":"The Cambridge Introduction to Narrative","publisher":"Cambridge University Press","url":"https://www.cambridge.org/core/books/cambridge-introduction-to-narrative/145624F5459B315F67D3D54DF22650F8","accessedAt":"2026-07-27T12:00:00Z","usage":"linkOnly","evidenceLocator":"Publisher page; consult linked text through lawful access"}],"tags":["narratology","voice"],"generatedAt":"2026-07-27T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"literature-editorial-v1","reviewStatus":"verified"},{"id":"literature-dramatic-irony-001","category":"literature","conceptID":"literature.form-genre","conceptTitle":"Dramatic irony","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"An audience knows that a trusted adviser has betrayed the protagonist, while the protagonist praises that adviser and follows the advice. What device chiefly shapes the scene?","choices":[{"id":"a","text":"Dramatic irony, because the audience knows a crucial fact the protagonist does not.","rationale":"Correct. The knowledge gap between audience and character changes the force of the protagonist's words and choices."},{"id":"b","text":"Situational irony, because events turn out contrary to what the protagonist expects.","rationale":"Situational irony concerns outcomes that defy expectations; the scene is defined by the audience's present knowledge gap."},{"id":"c","text":"Verbal irony, because the protagonist's praise means the opposite of what it says.","rationale":"Verbal irony requires a speaker to intend a contrary meaning; the protagonist's praise is sincere."},{"id":"d","text":"Foreshadowing, because the scene hints at a betrayal that will be revealed later.","rationale":"The audience already knows of the betrayal; foreshadowing hints at events not yet disclosed."}],"correctChoiceID":"a","explanation":"Dramatic irony gives the audience information withheld from a character. The gap can generate tension, pity, humor, or a critical view of the character's judgment.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"britannica-dramatic-irony","title":"Dramatic Irony","publisher":"Encyclopaedia Britannica","url":"https://www.britannica.com/art/dramatic-irony","accessedAt":"2026-07-27T12:00:00Z","usage":"linkOnly","evidenceLocator":"Definition and examples"}],"tags":["irony","drama","narrative"],"generatedAt":"2026-07-27T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"literature-editorial-v1","reviewStatus":"verified"},{"id":"literature-narrator-analysis-essay-001","category":"literature","conceptID":"literature.close-reading","conceptTitle":"Close reading narrative voice","type":"essay","dimension":"synthesis","difficulty":"advanced","prompt":"Using a lawfully available public-domain story or novel, make an argument about how narrative voice shapes the reader's judgment of one character. Link diction, distance, selection of detail, and irony to your claim.","choices":[],"explanation":"Coaching should anchor every interpretive move in a cited passage while avoiding a plot-summary essay.","rubric":[{"id":"thesis","title":"Interpretive thesis","description":"Makes a specific, contestable claim about voice and reader judgment.","weight":0.4,"coachingQuestions":["Could a reasonable reader disagree with this thesis?"]},{"id":"close-reading","title":"Close reading","description":"Analyzes diction, syntax, perspective, distance, and patterns in short passages.","weight":0.35,"coachingQuestions":["Which exact word creates the effect you name?"]},{"id":"structure","title":"Reasoning and structure","description":"Connects evidence to the thesis and addresses an alternative reading.","weight":0.25,"coachingQuestions":["What would the strongest alternative interpretation say?"]}],"coachingPrompts":["Choose two short passages from a public-domain edition.","Underline words that belong to narrator, character, or both.","Replace plot summary with analysis of form."],"modelOutline":["Text and thesis","Voice feature one","Voice feature two","Counter-reading","Implication"],"sources":[{"id":"project-gutenberg","title":"Project Gutenberg","publisher":"Project Gutenberg Literary Archive Foundation","url":"https://www.gutenberg.org/","accessedAt":"2026-07-27T12:00:00Z","usage":"publicDomain","evidenceLocator":"Select a title whose U.S. public-domain status is stated on its ebook page"}],"tags":["close-reading","narrative-voice","public-domain"],"generatedAt":"2026-07-27T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"literature-editorial-v1","reviewStatus":"verified"},{"id":"art-linear-perspective-001","category":"art","conceptID":"art.formal-analysis","conceptTitle":"Linear perspective","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"In a painting of a room viewed straight on, the receding edges of the floor tiles, the ceiling beams, and the tops of the side walls all meet, when extended, at a single point that is level with a seated figure's head. What does this convergence most directly tell a viewer about the picture's construction?","choices":[{"id":"a","text":"It uses two-point perspective, with a second vanishing point hidden outside the frame.","rationale":"Two-point perspective is for forms seen corner-on, where two sets of receding lines go to two separate points. Here the room is seen straight on and every receding line meets at one point."},{"id":"b","text":"That point is the vanishing point, and its height marks the horizon line, or eye level.","rationale":"Correct. In one-point perspective the lines running straight into depth (orthogonals) converge at a single vanishing point, which lies on the horizon line, the viewer's implied eye level."},{"id":"c","text":"The horizon line runs where the floor meets the back wall, well below that meeting point.","rationale":"The horizon line passes through the vanishing point at eye level. The line where the floor meets the back wall lies below eye level and is not the horizon."},{"id":"d","text":"The room is drawn in parallel projection, so its depth lines only appear to converge.","rationale":"In parallel (oblique or axonometric) projection, receding lines stay parallel and never meet. Lines that converge on a point are the defining sign of linear perspective."}],"correctChoiceID":"b","explanation":"In one-point perspective, lines that run straight into depth (orthogonals) converge at a single vanishing point, while lines parallel to the picture surface stay parallel. The vanishing point lies on the horizon line, which corresponds to the viewer's eye level, so finding where the orthogonals meet also shows the eye level the painter assumed. Two-point perspective has two such points, and parallel projection has none.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"smarthistory-one-point-perspective","title":"How one-point linear perspective works","publisher":"Smarthistory","url":"https://smarthistory.org/how-one-point-linear-perspective-works/","accessedAt":"2026-11-10T12:00:00Z","usage":"linkOnly","evidenceLocator":"Vanishing point, horizon line, and orthogonals"}],"tags":["renaissance","perspective"],"generatedAt":"2026-07-27T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"art-editorial-v1","reviewStatus":"verified"},{"id":"art-provenance-001","category":"art","conceptID":"art.provenance-ethics","conceptTitle":"Provenance research","type":"multipleChoice","dimension":"application","difficulty":"advanced","prompt":"A museum discovers a gap in an artwork's ownership history between 1933 and 1945 in Europe. What is the most responsible next step?","choices":[{"id":"a","text":"Keep the gap confidential, and notify claimants only if research proves looting.","rationale":"Secrecy defeats the purpose of disclosure; standards favor publishing provenance information, including gaps, so claims can surface."},{"id":"b","text":"Research archival, dealer, and restitution records, and publish the gap and findings.","rationale":"Correct. Museum standards call for systematic research and public disclosure of Nazi-era provenance gaps so that potential claimants can come forward."},{"id":"c","text":"Return the work to heirs of its last pre-1933 owner, since the gap implies a loss.","rationale":"A gap is a risk signal, not proof of loss, and the right claimant cannot be identified without research."},{"id":"d","text":"Rely on the seller's warranty of title, since the museum acquired it in good faith.","rationale":"Good-faith acquisition and a seller's warranty do not resolve the historical ownership question or the museum's ethical duties."}],"correctChoiceID":"b","explanation":"Provenance is an evidence chain, often with uncertainty. High-risk historical periods demand persistent research, claimant-sensitive practice, and transparent documentation.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"aam-nazi-era-provenance","title":"Standards Regarding the Unlawful Appropriation of Objects During the Nazi Era","publisher":"American Alliance of Museums","url":"https://www.aam-us.org/programs/ethics-standards-and-professional-practices/unlawful-appropriation-of-objects-during-the-nazi-era/","accessedAt":"2026-07-27T12:00:00Z","usage":"linkOnly","evidenceLocator":"Museum standards and transparency"}],"tags":["provenance","museum-ethics"],"generatedAt":"2026-07-27T12:00:00Z","validUntil":"2027-07-27T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"art-editorial-v1","reviewStatus":"verified"},{"id":"art-formal-contextual-essay-001","category":"art","conceptID":"art.reception-interpretation","conceptTitle":"Formal and contextual analysis","type":"essay","dimension":"synthesis","difficulty":"advanced","prompt":"Choose one work from an open-access museum collection. Make an argument that connects two formal features to the work's function or historical setting, while distinguishing visual evidence from contextual evidence.","choices":[],"explanation":"Coaching should move from careful description to interpretation, then test that interpretation against museum documentation.","rubric":[{"id":"looking","title":"Formal analysis","description":"Uses precise observations about composition, material, scale, color, space, or technique.","weight":0.4,"coachingQuestions":["What can a reader verify by looking at the image?"]},{"id":"context","title":"Contextual evidence","description":"Uses reliable object records and scholarship to explain function or setting.","weight":0.35,"coachingQuestions":["Which contextual claim needs a citation?"]},{"id":"argument","title":"Integrated argument","description":"Connects form and context without claiming that style mechanically proves intention.","weight":0.25,"coachingQuestions":["Does your conclusion overstate what form alone can establish?"]}],"coachingPrompts":["Describe before interpreting.","Cite the object record and one scholarly source.","Name one plausible alternative reading."],"modelOutline":["Object identification","Formal feature one","Formal feature two","Context and function","Qualified interpretation"],"sources":[{"id":"met-open-access","title":"Open Access at The Met","publisher":"The Metropolitan Museum of Art","url":"https://www.metmuseum.org/policies/image-resources","accessedAt":"2026-07-27T12:00:00Z","usage":"linkOnly","evidenceLocator":"Open-access policy and collection links"}],"tags":["formal-analysis","museum","context"],"generatedAt":"2026-07-27T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"art-editorial-v1","reviewStatus":"verified"},{"id":"architecture-flying-buttress-001","category":"architecture","conceptID":"architecture.structure-loads","conceptTitle":"Gothic structural systems","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"What structural role does a flying buttress chiefly serve in a large Gothic church?","choices":[{"id":"a","text":"It carries the vaults' outward thrust across to an external pier.","rationale":"Correct. The flyer, working in compression, transfers lateral vault thrust over the aisle to a pier and down to the ground."},{"id":"b","text":"It carries the roof's weight to the ground, relieving the walls of vertical load.","rationale":"Its main job is resisting lateral thrust; most vertical load still travels down through the walls and piers."},{"id":"c","text":"It works in tension, pulling the walls outward against the vault's inward pull.","rationale":"Masonry flyers work in compression, and vault thrust pushes outward; the flyer pushes back inward."},{"id":"d","text":"It lets the walls be thicker, adding mass so they can resist the vault's thrust.","rationale":"This reverses the effect: buttressing lets walls be thinner and more open, unlike massive Romanesque walls."}],"correctChoiceID":"a","explanation":"Vaults push laterally as well as downward. Flying buttresses channel part of that thrust to exterior supports, helping walls rise higher and contain larger openings.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"smarthistory-gothic","title":"Gothic Architecture: An Introduction","publisher":"Smarthistory","url":"https://smarthistory.org/gothic-architecture-an-introduction/","accessedAt":"2026-07-27T12:00:00Z","license":"CC BY-NC-SA","usage":"openLicense","evidenceLocator":"Structural innovations"}],"tags":["gothic","structure"],"generatedAt":"2026-07-27T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"architecture-editorial-v1","reviewStatus":"verified"},{"id":"architecture-curtain-wall-001","category":"architecture","conceptID":"architecture.materials-construction","conceptTitle":"Structural frame and curtain wall","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"In a typical framed high-rise, why can an exterior curtain wall contain broad areas of glass?","choices":[{"id":"a","text":"The glass is tempered, making it strong enough to carry the floors above it.","rationale":"Tempering improves breakage resistance, but curtain-wall glass does not carry floor loads."},{"id":"b","text":"The frame carries the gravity loads, so the wall is a non-load-bearing skin.","rationale":"Correct. Separating structure from enclosure lets the envelope be light, though it must still resist wind and other environmental loads."},{"id":"c","text":"The building's core resists wind, so the wall itself faces no lateral pressure.","rationale":"The curtain wall still receives wind pressure and must transfer it through anchors to the frame."},{"id":"d","text":"Slender masonry piers between the panes carry the floors down to the foundation.","rationale":"That describes a load-bearing wall with openings, which limits how much of the facade can be glass."}],"correctChoiceID":"b","explanation":"A structural frame can carry floors and major gravity loads while an attached curtain wall encloses the building. The wall still must manage wind, movement, water, air, heat, and safety interfaces.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"wbdg-envelope","title":"Building Envelope Design Guide","publisher":"Whole Building Design Guide, National Institute of Building Sciences","url":"https://www.wbdg.org/guides-specifications/building-envelope-design-guide","accessedAt":"2026-07-27T12:00:00Z","usage":"linkOnly","evidenceLocator":"Envelope systems and performance"}],"tags":["high-rise","curtain-wall","building-envelope"],"generatedAt":"2026-07-27T12:00:00Z","validUntil":"2027-07-27T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"architecture-editorial-v1","reviewStatus":"verified"},{"id":"architecture-climate-response-essay-001","category":"architecture","conceptID":"architecture.climate-passive-design","conceptTitle":"Climate-responsive architecture","type":"essay","dimension":"synthesis","difficulty":"advanced","prompt":"Compare how a small public library should respond to a hot-arid climate and a hot-humid climate. Reason from heat, solar gain, airflow, water, materials, and occupancy rather than applying a universal style.","choices":[],"explanation":"Coaching should connect each design move to a climate mechanism and acknowledge site-specific tradeoffs.","rubric":[{"id":"mechanisms","title":"Climate mechanisms","description":"Accurately distinguishes solar, diurnal, humidity, ventilation, and moisture conditions.","weight":0.4,"coachingQuestions":["When is thermal mass helpful, and when can it retain unwanted heat?"]},{"id":"strategies","title":"Integrated strategies","description":"Connects orientation, shade, envelope, mass, airflow, and systems to the two climates.","weight":0.35,"coachingQuestions":["Which strategy changes between dry and humid conditions?"]},{"id":"tradeoffs","title":"Tradeoffs and evidence","description":"Addresses comfort, durability, water, maintenance, and the need for local climate data.","weight":0.25,"coachingQuestions":["What local data would you request before design?"]}],"coachingPrompts":["Draw a heat-flow story for each climate.","Explain every feature with a 'because.'","Identify one strategy that could backfire."],"modelOutline":["Climate assumptions","Hot-arid response","Hot-humid response","Shared program needs","Tradeoffs and validation"],"sources":[{"id":"doe-climate-design","title":"Consumer Guide to Passive Solar Home Design","publisher":"U.S. Department of Energy","url":"https://www.energy.gov/sites/default/files/2021-08/ES-Passive%20Solar%20design_081321.pdf","accessedAt":"2026-07-27T12:00:00Z","usage":"linkOnly","evidenceLocator":"Official PDF on climate and passive-design principles"}],"tags":["climate","passive-design","building-science"],"generatedAt":"2026-07-27T12:00:00Z","validUntil":"2027-07-27T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"architecture-editorial-v1","reviewStatus":"verified"},{"id":"design-affordance-signifier-001","category":"design","conceptID":"design.human-centered-research","conceptTitle":"Affordances and signifiers","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"A flat digital control can be activated, but users repeatedly miss it because nothing indicates that it is interactive. What is the most direct design problem?","choices":[{"id":"a","text":"The control lacks an affordance, since nothing on a flat screen can be pressed.","rationale":"The control can be activated, so the affordance exists; what is missing is a perceivable cue to it."},{"id":"b","text":"The control lacks feedback, so users can't tell whether their tap succeeded.","rationale":"Feedback follows an action; here users never find the control in the first place."},{"id":"c","text":"The control breaks natural mapping between its position and its effect.","rationale":"Mapping concerns how controls relate to their effects; the problem described is discoverability."},{"id":"d","text":"The control lacks a signifier showing that it can be clicked or tapped.","rationale":"Correct. The action exists, but the interface fails to communicate where and how to interact."}],"correctChoiceID":"d","explanation":"A signifier is a perceivable cue to an action. Designers should distinguish what interaction is possible from what the interface communicates to a user.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"interaction-design-signifiers","title":"What are Affordances?","publisher":"Interaction Design Foundation","url":"https://ixdf.org/literature/topics/affordances","accessedAt":"2026-11-10T12:00:00Z","usage":"linkOnly","evidenceLocator":"Affordance and signifier distinction"}],"tags":["interaction-design","signifiers"],"generatedAt":"2026-07-27T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"design-editorial-v1","reviewStatus":"verified"},{"id":"design-keyboard-focus-001","category":"design","conceptID":"design.accessibility-inclusion","conceptTitle":"Keyboard and focus accessibility","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"A web dialog opens, but keyboard focus remains behind it and the Tab key can move through obscured page controls. Which improvement most directly addresses the barrier?","choices":[{"id":"a","text":"Set aria-modal on the dialog, which by itself keeps keyboard focus inside it.","rationale":"aria-modal tells assistive technology that outside content is inert, but it does not move or contain keyboard focus."},{"id":"b","text":"Give the dialog a tabindex so it joins the page's normal tab sequence.","rationale":"Adding the dialog to the tab order neither moves focus into it nor stops Tab from reaching obscured controls."},{"id":"c","text":"Move focus into the dialog, keep Tab inside, close on Escape, and restore focus.","rationale":"Correct. This follows the modal dialog pattern for keyboard users: focus moves in, stays contained, and returns to the trigger."},{"id":"d","text":"Add a stronger focus outline so users can see where focus sits behind the dialog.","rationale":"Visible focus helps orientation, but focus would still be in the wrong context behind the modal."}],"correctChoiceID":"c","explanation":"A modal interaction needs programmatic focus management and complete keyboard operation. Visible focus and a predictable return point help users understand where they are.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"w3c-aria-dialog","title":"Dialog (Modal) Pattern","publisher":"World Wide Web Consortium","url":"https://www.w3.org/WAI/ARIA/apg/patterns/dialog-modal/","accessedAt":"2026-07-27T12:00:00Z","usage":"linkOnly","evidenceLocator":"Keyboard interaction and focus management"}],"tags":["accessibility","keyboard","focus"],"generatedAt":"2026-07-27T12:00:00Z","validUntil":"2027-07-27T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"design-editorial-v1","reviewStatus":"verified"},{"id":"design-public-form-essay-001","category":"design","conceptID":"design.systems-service-design","conceptTitle":"Inclusive form design","type":"essay","dimension":"synthesis","difficulty":"advanced","prompt":"Redesign a high-stakes public-benefits application that currently uses dense jargon, loses work on timeout, and is difficult with keyboard or screen reader. Explain the research, information architecture, interaction, accessibility, privacy, and evaluation plan.","choices":[],"explanation":"Coaching should integrate usability, accessibility, institutional constraints, and dignity rather than treating inclusion as a final checklist.","rubric":[{"id":"problem","title":"Problem framing and research","description":"Identifies affected users, high-risk moments, service constraints, and ethical research methods.","weight":0.4,"coachingQuestions":["Whose failure would the current analytics hide?"]},{"id":"solution","title":"Inclusive interaction design","description":"Addresses language, chunking, save-and-resume, errors, keyboard, screen reader, and support channels.","weight":0.35,"coachingQuestions":["How will a user recover from interruption or error?"]},{"id":"evaluation","title":"Evaluation and accountability","description":"Defines accessible testing, outcome measures, privacy limits, and operational ownership.","weight":0.25,"coachingQuestions":["Which metric could improve while the service remains inequitable?"]}],"coachingPrompts":["Map the full service, not only the screen.","Test with people who use assistive technology.","Define safe recovery and human support."],"modelOutline":["Current harm","Research plan","Content and flow","Accessibility and privacy","Testing and governance"],"sources":[{"id":"wcag-22","title":"Web Content Accessibility Guidelines (WCAG) 2.2","publisher":"World Wide Web Consortium","url":"https://www.w3.org/TR/WCAG22/","accessedAt":"2026-07-27T12:00:00Z","usage":"linkOnly","evidenceLocator":"Normative success criteria"},{"id":"govuk-service-standard","title":"Service Standard","publisher":"UK Government Digital Service","url":"https://www.gov.uk/service-manual/service-standard","accessedAt":"2026-07-27T12:00:00Z","usage":"linkOnly","evidenceLocator":"User needs, accessibility, privacy, and measurement"}],"tags":["service-design","accessibility","public-interest"],"generatedAt":"2026-07-27T12:00:00Z","validUntil":"2027-07-27T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"design-editorial-v1","reviewStatus":"verified"}]},{"id":"hiculture-learning-focus-v2","schemaVersion":1,"version":"2.0.0","generatedAt":"2026-07-28T08:00:00Z","questions":[{"id":"science-depth-v2-energy-balance-001","category":"science","conceptID":"science.energy-matter","conceptTitle":"Energy and matter","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"A calorimeter contains 2.00 kg of water in a 0.50 kg copper vessel. Electrical work of 150 kJ enters while both warm from 20.0 °C to 35.0 °C. Using specific heat capacities of 4.18 kJ kg⁻¹ K⁻¹ for water and 0.385 kJ kg⁻¹ K⁻¹ for copper, which energy balance is best if there is no phase change?","choices":[{"id":"a","text":"About 125 kJ is stored, all of it in the water; the vessel's share is negligible, so 25 kJ was lost.","rationale":"Water stores about 125 kJ, but the copper adds about 2.9 kJ; omitting a measured component misstates both the stored energy and the residual."},{"id":"b","text":"About 157 kJ is stored, slightly more than the input, so the electrical meter must be under-reading.","rationale":"This applies water's specific heat to the copper vessel. With copper's 0.385 kJ kg⁻¹ K⁻¹, the vessel stores only about 2.9 kJ."},{"id":"c","text":"About 128 kJ is stored in the water and vessel; the other ~22 kJ crossed the boundary or went elsewhere.","rationale":"Correct. [2.00(4.18) + 0.50(0.385)](15.0) ≈ 128 kJ, leaving about 22 kJ that left as heat or entered an omitted component."},{"id":"d","text":"All 150 kJ is stored, since in a closed calorimeter the electrical work must all become internal energy.","rationale":"The measured temperature rise accounts for only about 128 kJ; real calorimeters exchange heat with surroundings, and the balance must follow the data."}],"correctChoiceID":"c","explanation":"For the stated system, ΔU ≈ (mwater cwater + mcopper ccopper)ΔT = 128.3 kJ. Relative to the 150 kJ electrical input, about 21.7 kJ is not represented by those two sensible-energy terms. It may have left as heat or entered omitted hardware. The calculation depends on the system boundary, constant heat capacities, accurate measurements, and the no-phase-change assumption.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"nasa-science-education","title":"First Law: Internal Energy","publisher":"National Aeronautics and Space Administration","url":"https://www1.grc.nasa.gov/beginners-guide-to-aeronautics/first-law-internal-energy/","accessedAt":"2026-07-28T08:00:00Z","usage":"publicDomain","evidenceLocator":"Energy conservation, heat, work, internal energy, and the importance of a defined thermodynamic system"}],"tags":["energy-balance","calorimetry","system-boundary","conservation"],"generatedAt":"2026-07-28T08:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"science-depth-v2-uncertainty-propagation-001","category":"science","conceptID":"science.measurement-uncertainty","conceptTitle":"Measurement and uncertainty","type":"multipleChoice","dimension":"application","difficulty":"advanced","prompt":"A rectangle has independently measured length L = 2.00 ± 0.02 m and width W = 3.00 ± 0.03 m, where each ± value is a one-standard uncertainty. Using first-order propagation for A = LW, what is the combined standard uncertainty of the area?","choices":[{"id":"a","text":"About 0.085 m², adding the relative uncertainties in quadrature.","rationale":"Correct. sqrt[(0.02/2.00)² + (0.03/3.00)²] = 0.01414, and 0.01414 × 6.00 m² ≈ 0.085 m²."},{"id":"b","text":"About 0.120 m², adding the two 1% relative uncertainties linearly.","rationale":"Linear addition (2% of 6.00 m²) is a worst-case bound; independent standard uncertainties combine in quadrature."},{"id":"c","text":"About 0.050 m², adding the two absolute uncertainties directly.","rationale":"Absolute uncertainties in different inputs must be weighted by sensitivity (W and L) before combining, and they combine in quadrature."},{"id":"d","text":"About 0.036 m², adding the absolute uncertainties in quadrature.","rationale":"Quadrature is right, but sqrt(0.02² + 0.03²) ignores the sensitivity coefficients; each term must be multiplied by the other dimension."}],"correctChoiceID":"a","explanation":"For independent inputs and a first-order model, u(A)^2 = (W u(L))^2 + (L u(W))^2. This gives sqrt[(3.00×0.02)^2 + (2.00×0.03)^2] = 0.0849 m². The approximation assumes the input uncertainties are independent, sufficiently small, and adequately described by the stated model.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"nist-measurement-uncertainty","title":"NIST Uncertainty of Measurement","publisher":"National Institute of Standards and Technology","url":"https://physics.nist.gov/cuu/Uncertainty/","accessedAt":"2026-07-28T08:00:00Z","usage":"publicDomain","evidenceLocator":"Combined standard uncertainty and law of propagation of uncertainty"}],"tags":["uncertainty-propagation","quantitative-reasoning","independence"],"generatedAt":"2026-07-28T08:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"science-depth-v2-evolution-causal-001","category":"science","conceptID":"science.evolution-variation","conceptTitle":"Evolution and variation","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"Six isolated microbial populations begin with a resistance allele at frequency 0.10. After 20 generations with a drug, the allele reaches 0.85–0.92 in every population; six no-drug populations remain at 0.08–0.14. Which follow-up most directly tests whether the allele itself, rather than a linked variant, causes the fitness advantage?","choices":[{"id":"a","text":"Sequence the evolved genomes and confirm the allele rose in all six drug lines but in none of the controls.","rationale":"This restates the association. Variants linked to the allele on the same background would rise in parallel too."},{"id":"b","text":"Run a genome-wide association across the twelve populations to rank variants by their drug effect.","rationale":"With few populations and tight linkage, association still cannot separate the allele from hitchhiking variants; it remains correlational."},{"id":"c","text":"Extend the experiment with more populations and generations to see whether the allele reaches fixation.","rationale":"More replication strengthens evidence of selection on the region but still does not isolate the allele from linked variants."},{"id":"d","text":"Engineer the allele into and out of matched genetic backgrounds, then compare fitness with and without the drug.","rationale":"Correct. Changing only the candidate allele, with reciprocal and environmental controls, directly tests its contribution apart from linked variants."}],"correctChoiceID":"d","explanation":"Parallel allele-frequency change in drug-exposed populations, contrasted with controls, is evidence for repeatable selection on the allele or linked genomic region. Reciprocal editing in matched backgrounds followed by replicated competition under both environments tests the allele's causal contribution more directly. Even then, background interactions and laboratory conditions limit generalization to other populations or environments.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"nhgri-gwas-fact-sheet","title":"Genome-Wide Association Studies Fact Sheet","publisher":"National Human Genome Research Institute","url":"https://www.genome.gov/about-genomics/fact-sheets/Genome-Wide-Association-Studies-Fact-Sheet","accessedAt":"2026-07-28T08:00:00Z","usage":"publicDomain","evidenceLocator":"Associated variants may be tagging along with the actual causal variants, so follow-up work is needed to identify the causal change"},{"id":"nist-statistics-handbook","title":"Choosing an Experimental Design","publisher":"National Institute of Standards and Technology","url":"https://www.itl.nist.gov/div898/handbook/pri/section3/pri3.htm","accessedAt":"2026-07-28T08:00:00Z","usage":"publicDomain","evidenceLocator":"Factor selection, controls, randomization, and designs that isolate the effect of one factor"}],"tags":["selection","linked-variation","allele-replacement","experimental-evolution"],"generatedAt":"2026-07-28T08:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"science-depth-v2-factor-confounding-001","category":"science","conceptID":"science.causality-experimental-design","conceptTitle":"Causality and experiments","type":"multipleChoice","dimension":"application","difficulty":"advanced","prompt":"Plant cultures grown at 18 °C in week 1 yield 20% less biomass than cultures grown at 24 °C in week 2. A new nutrient lot was also introduced at the start of week 2. What is the strongest warranted interpretation?","choices":[{"id":"a","text":"Warmth likely caused it, since a 20% gain fits the growth responses known for this temperature range.","rationale":"Prior plausibility cannot separate factors that changed together; the nutrient lot or week could produce the same difference."},{"id":"b","text":"Temperature is confounded with nutrient lot and week, so this comparison cannot isolate the cause.","rationale":"Correct. Each temperature occurs with only one nutrient lot and one time period, so their effects are inseparable."},{"id":"c","text":"Temperature caused it if a t-test on replicate cultures within each week shows a significant difference.","rationale":"Replicates within a week share the same bundle of conditions; significance shows the bundles differ, not which factor caused it."},{"id":"d","text":"The nutrient lot caused it, because a change of supplies is the more common source of run-to-run drift.","rationale":"The design provides no basis for assigning the effect to the nutrient lot rather than temperature or time."}],"correctChoiceID":"b","explanation":"Temperature, nutrient lot, and calendar week changed together. The comparison supports a difference between two bundles of conditions, not an isolated temperature effect. A stronger design would cross temperature with nutrient lot, randomize units within runs, replicate across runs, and predefine how run effects will be analyzed.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"nist-statistics-handbook","title":"Choosing an Experimental Design","publisher":"National Institute of Standards and Technology","url":"https://www.itl.nist.gov/div898/handbook/pri/section3/pri3.htm","accessedAt":"2026-07-28T08:00:00Z","usage":"publicDomain","evidenceLocator":"Factor selection, randomization, blocking, factorial designs, and confounding"},{"id":"nih-rigor-reproducibility","title":"Enhancing Reproducibility through Rigor and Transparency","publisher":"National Institutes of Health","url":"https://www.grants.nih.gov/policy-and-compliance/policy-topics/reproducibility","accessedAt":"2026-07-28T08:00:00Z","usage":"publicDomain","evidenceLocator":"Unbiased and well-controlled design, analysis, interpretation, and reporting"}],"tags":["factorial-design","confounding","causal-inference"],"generatedAt":"2026-07-28T08:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"science-depth-v2-model-domain-001","category":"science","conceptID":"science.models-systems","conceptTitle":"Models and systems","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"A bacterial culture begins with 100 cells and doubles hourly. An unconstrained exponential model predicts 25,600 cells after 8 hours, but the measured count is about 6,000. Which response best uses the model scientifically?","choices":[{"id":"a","text":"Refit the doubling time to match the 6,000 count, then keep the exponential model for future predictions.","rationale":"A slower constant rate hides the likely slowdown and will mispredict other time points; the deviation calls for a different model form."},{"id":"b","text":"Treat the gap as a sign growth left the exponential regime, then test for limits such as nutrients or waste.","rationale":"Correct. A systematic deviation marks where the model's constant-rate assumption fails and motivates discriminating measurements."},{"id":"c","text":"Assume the count was mismeasured, since exponential growth of dividing cells is a well-established result.","rationale":"Checking measurement is reasonable, but discarding data to protect a model is unscientific; a fourfold gap is a substantive signal."},{"id":"d","text":"Reject the doubling model entirely, since a model that misses by fourfold has no remaining scientific value.","rationale":"The model likely fit early growth and still defines a useful baseline; its failure point is informative."}],"correctChoiceID":"b","explanation":"The exponential model assumes a constant per-capita growth rate and no limiting feedback. The discrepancy does not make the model useless: it identifies where those assumptions may fail. A better next step is to measure nutrients, waste products, viable counts, and time-resolved growth, then compare bounded alternatives such as logistic growth.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"nih-research-process","title":"Explaining How Research Works","publisher":"National Institutes of Health","url":"https://www.nih.gov/about-nih/science-health-public-trust/tools/explaining-how-research-works","accessedAt":"2026-07-28T08:00:00Z","usage":"publicDomain","evidenceLocator":"Scientific models, revision in response to new information, replication, and calibrated confidence"},{"id":"nist-statistics-handbook","title":"What Is Design of Experiments?","publisher":"National Institute of Standards and Technology","url":"https://itl.nist.gov/div898/handbook/pmd/section3/pmd31.htm","accessedAt":"2026-07-28T08:00:00Z","usage":"publicDomain","evidenceLocator":"Modeling objectives and defensible conclusions from designed data"}],"tags":["model-assumptions","exponential-growth","domain-of-validity"],"generatedAt":"2026-07-28T08:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"science-depth-v2-calorimetry-energy-balance-001","category":"science","conceptID":"science.energy-matter","conceptTitle":"Energy and matter","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"In an idealized coffee-cup calorimeter, a reaction raises the temperature of 150.0 g of water by 3.20 °C. Taking water's specific heat as 4.184 J g⁻¹ °C⁻¹ and neglecting the cup's heat capacity and heat loss, what is the reaction's heat for this run?","choices":[{"id":"a","text":"About +2.01 kJ: the water's temperature rose, so the reaction's heat is positive.","rationale":"The water gains heat because the reaction releases it; with the reaction as the system, q is negative."},{"id":"b","text":"About −0.002 kJ, since the 150.0 g of water must first be converted to 0.150 kg.","rationale":"The specific heat is given per gram, so mass must stay in grams; converting to kilograms makes the result 1000 times too small."},{"id":"c","text":"About −2.01 kJ: the water gains about 2.01 kJ, so the reaction releases that much.","rationale":"Correct. q_water = 150.0 × 4.184 × 3.20 ≈ 2008 J, and under the idealized balance q_reaction = −q_water."},{"id":"d","text":"About −2.19 kJ, after adding the roughly 0.18 kJ that the foam cup must have absorbed.","rationale":"The stem says to neglect the cup's heat capacity, and it gives no data from which such a correction could be computed."}],"correctChoiceID":"c","explanation":"The water absorbs about 2.008 kJ. Under the idealized assumptions, the reaction releases the same magnitude, so q_reaction ≈ −2.01 kJ. A real analysis would include calorimeter heat capacity, solution rather than pure-water properties, heat loss, reaction extent, and measurement uncertainty.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"nasa-science-education","title":"First Law — Internal Energy","publisher":"NASA Glenn Research Center","url":"https://www1.grc.nasa.gov/beginners-guide-to-aeronautics/first-law-internal-energy/","accessedAt":"2026-07-28T08:00:00Z","usage":"publicDomain","evidenceLocator":"System boundaries, heat transfer, work, internal energy, and conservation of energy"},{"id":"nist-measurement-uncertainty","title":"NIST Uncertainty of Measurement","publisher":"National Institute of Standards and Technology","url":"https://physics.nist.gov/cuu/Uncertainty/","accessedAt":"2026-07-28T08:00:00Z","usage":"publicDomain","evidenceLocator":"Measurement models, uncertainty components, and reporting assumptions"}],"tags":["calorimetry","energy-conservation","system-boundary"],"generatedAt":"2026-07-28T08:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"science-depth-v2-hardy-weinberg-001","category":"science","conceptID":"science.evolution-variation","conceptTitle":"Evolution and variation","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"In a large population assumed to meet Hardy-Weinberg conditions, 4% of individuals show a recessive phenotype caused by genotype aa. What heterozygote frequency is expected?","choices":[{"id":"a","text":"0.32, since q = 0.20 and p = 0.80, so 2pq = 0.32.","rationale":"Correct. q² = 0.04 gives q = 0.20 and p = 0.80, and heterozygotes occur at 2pq."},{"id":"b","text":"0.16, since q = 0.20 and p = 0.80, so pq = 0.16.","rationale":"This omits the factor of 2: heterozygotes arise two ways (Aa and aA), so the frequency is 2pq."},{"id":"c","text":"0.077, since p = 0.96 and q = 0.04, so 2pq ≈ 0.077.","rationale":"This treats the phenotype frequency as q; 0.04 is q², so q = 0.20."},{"id":"d","text":"0.20, since q = √0.04 and each carrier has one a allele.","rationale":"The square root gives q, the recessive-allele frequency, not the heterozygote genotype frequency."}],"correctChoiceID":"a","explanation":"If q² = 0.04, then q = 0.20 and p = 0.80, so 2pq = 0.32. This is a model-based expectation, not a direct count. Population structure, selection, migration, mutation, nonrandom mating, sampling error, or phenotype misclassification can make observed frequencies differ.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"national-academies-ncbi","title":"Population Genetics","publisher":"National Academies Press, hosted by NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK232608/","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Hardy-Weinberg genotype proportions, population structure, laboratory artifacts, and limits of equilibrium assumptions"}],"tags":["population-genetics","hardy-weinberg","model-assumptions"],"generatedAt":"2026-07-28T08:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"science-depth-v2-association-inference-001","category":"science","conceptID":"science.scientific-inference","conceptTitle":"Scientific inference","type":"multipleChoice","dimension":"application","difficulty":"advanced","prompt":"A one-time survey of 60 lakes finds a strong positive association between dissolved phosphorus and algal biomass. No lake was experimentally manipulated, and agricultural runoff may affect both variables. Which conclusion is best calibrated to the evidence?","choices":[{"id":"a","text":"With 60 lakes and a strong correlation, both chance and confounding can be ruled out.","rationale":"Sample size and strength can argue against chance, but they do not address confounding by a shared cause such as runoff."},{"id":"b","text":"Phosphorus likely drives the algae, because nutrient enrichment is the established mechanism.","rationale":"Prior mechanism makes the hypothesis plausible, but this survey cannot exclude runoff-related confounding; the question is what these data warrant."},{"id":"c","text":"Adjusting for runoff in a regression would turn the association into a causal estimate.","rationale":"Adjusting for one measured confounder does not remove unmeasured confounding, reverse pathways, or measurement problems."},{"id":"d","text":"The data show an association useful for prediction, but this design can't isolate a cause.","rationale":"Correct. A cross-sectional association can be real and informative while remaining open to confounding and reverse pathways."}],"correctChoiceID":"d","explanation":"The survey supports covariation under the sampled conditions. It does not by itself establish direction, rule out runoff-related confounding, or show that phosphorus is the only limiting factor. Stronger inference would combine temporal evidence, pre-specified covariates, interventions or natural experiments, mechanistic measures, and replication across settings.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"nih-research-process","title":"Explaining How Research Works","publisher":"National Institutes of Health","url":"https://www.nih.gov/about-nih/science-health-public-trust/tools/explaining-how-research-works","accessedAt":"2026-07-28T08:00:00Z","usage":"publicDomain","evidenceLocator":"Evidence, models, replication, differing methods and timeframes, and self-correction"},{"id":"epa-nutrient-pollution","title":"Basic Information on Nutrient Pollution","publisher":"U.S. Environmental Protection Agency","url":"https://www.epa.gov/nutrientpollution/basic-information-nutrient-pollution","accessedAt":"2026-07-28T08:00:00Z","usage":"publicDomain","evidenceLocator":"Nitrogen and phosphorus inputs, algal blooms, oxygen depletion, and multiple human sources"}],"tags":["association","causality","ecology","epistemic-limits"],"generatedAt":"2026-07-28T08:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"science-depth-v2-metrology-discrepancy-essay-001","category":"science","conceptID":"science.measurement-uncertainty","conceptTitle":"Measurement and uncertainty","type":"essay","dimension":"synthesis","difficulty":"advanced","prompt":"Two laboratories measure the same air-quality filter extracts. Lab A reports particulate mass concentrations about 8% higher than Lab B, while each lab reports within-lab repeatability better than 1%. Build an investigation that can determine whether the discrepancy comes from calibration, sample handling, the definition of the measurand, environmental conditions, or data reduction. Explain what evidence would justify combining the laboratories' results and what uncertainty would remain.","choices":[],"explanation":"Coaching should push the learner to define what is being measured, trace the measurement chain, distinguish repeatability from comparability, and design blinded interlaboratory checks without promising that one diagnostic step will reveal a unique cause.","rubric":[{"id":"measurand-chain","title":"Measurand and measurement chain","description":"Defines the quantity, units, sample preparation, calibration hierarchy, blank correction, and data-reduction steps precisely.","weight":0.3,"coachingQuestions":["Could the laboratories be implementing different operational definitions of the same label?","Where can material be gained, lost, or transformed before the reading?"]},{"id":"diagnostic-design","title":"Diagnostic comparison","description":"Proposes blinded shared samples, reference materials, crossed instruments or operators, blanks, spikes, and replicated conditions that separate plausible sources.","weight":0.3,"coachingQuestions":["Which comparison isolates calibration from sample preparation?","How will sample heterogeneity be separated from laboratory effects?"]},{"id":"uncertainty-analysis","title":"Uncertainty and compatibility","description":"Builds an uncertainty budget, addresses correlations, and states a criterion for assessing whether results are compatible.","weight":0.25,"coachingQuestions":["Which uncertainty components are shared rather than independent?","Would a correction reduce bias while increasing uncertainty?"]},{"id":"limits-reporting","title":"Limits and reporting","description":"States residual uncertainty, scope of generalization, and transparent reporting needed before pooling.","weight":0.15,"coachingQuestions":["What would remain unknown even if the mean offset disappears?","Which future samples might not be covered by the comparison?"]}],"coachingPrompts":["Separate precision, bias, traceability, and commutability.","Draw the full measurement chain before choosing statistical tests.","Name at least one diagnostic result that would falsify each leading explanation.","Avoid treating overlapping error bars as a complete compatibility test."],"modelOutline":["Define the common measurand, units, and complete measurement chain","List competing causes of the offset and the observation each predicts","Run blinded shared-sample, reference-material, and crossed-process comparisons","Build correlated uncertainty budgets and test result compatibility","State pooling criteria, any correction, residual uncertainty, and reporting limits"],"sources":[{"id":"nist-measurement-uncertainty","title":"NIST Uncertainty of Measurement","publisher":"National Institute of Standards and Technology","url":"https://physics.nist.gov/cuu/Uncertainty/","accessedAt":"2026-07-28T08:00:00Z","usage":"publicDomain","evidenceLocator":"Identifying uncertainty components, combining them, and reporting measurement results"},{"id":"nist-measurement-uncertainty-examples","title":"Five Examples of the Assessment and Expression of Measurement Uncertainty","publisher":"National Institute of Standards and Technology","url":"https://www.nist.gov/publications/five-examples-assessment-and-expression-measurement-uncertainty","accessedAt":"2026-07-28T08:00:00Z","usage":"publicDomain","evidenceLocator":"Worked approaches to identifying, combining, and communicating measurement uncertainty"}],"tags":["interlaboratory-comparison","uncertainty-budget","traceability","essay"],"generatedAt":"2026-07-28T08:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"science-depth-v2-field-causal-design-essay-001","category":"science","conceptID":"science.causality-experimental-design","conceptTitle":"Causality and experiments","type":"essay","dimension":"synthesis","difficulty":"advanced","prompt":"A conservation team wants to know whether reducing a pesticide near farms increases wild pollinator abundance, but it cannot randomly assign individual insects and has resources for 24 farm sites over two seasons. Design a defensible study. Address assignment or natural-experiment strategy, baseline measurement, blocking, spillovers, outcomes, analysis, and the exact causal claim the design could support.","choices":[],"explanation":"Coaching should reward a design that makes the treatment contrast identifiable at the farm or cluster level, measures pre-intervention trajectories, anticipates spatial interference, and distinguishes a local intervention effect from universal ecological claims.","rubric":[{"id":"identification","title":"Identification strategy","description":"Defines treatment at the feasible unit, comparison sites, randomization or a justified quasi-experiment, and the causal estimand.","weight":0.32,"coachingQuestions":["What unit can actually be assigned independently?","What assumption makes the comparison causal rather than descriptive?"]},{"id":"design-controls","title":"Baseline, blocking, and interference","description":"Uses baseline outcomes, blocks on major site factors, and addresses movement or spillover between sites.","weight":0.28,"coachingQuestions":["Which site characteristics should be balanced before assignment?","How could a treated farm affect a nearby control farm?"]},{"id":"measurement-analysis","title":"Measurement and analysis","description":"Defines repeated outcomes, sampling effort, blinding where possible, uncertainty, attrition handling, and pre-specified analysis.","weight":0.25,"coachingQuestions":["Will abundance, diversity, and visitation answer the same question?","How will repeated observations within farms be modeled?"]},{"id":"scope-limits","title":"Scope and limits","description":"States limits from seasons, geography, compliance, power, and ecological heterogeneity.","weight":0.15,"coachingQuestions":["To which farms and seasons could the result generalize?","What null result could still be consistent with a meaningful effect?"]}],"coachingPrompts":["Consider a cluster-randomized or matched-pair farm design before reaching for individual-level randomization.","Specify how pre-intervention measurements change the analysis.","Define a buffer or explicitly model spatial spillover.","State the treatment effect and target population in one sentence."],"modelOutline":["Define the treatment, outcomes, target population, and causal estimand","Use baseline data to match or block farms and justify assignment","Specify buffers, spillover measurement, compliance, and blinded outcomes","Predefine site-level analysis, uncertainty, missingness, and power logic","Bound the conclusion by season, geography, implementation, and ecological heterogeneity"],"sources":[{"id":"nist-statistics-handbook","title":"Randomized Block Designs","publisher":"National Institute of Standards and Technology","url":"https://www.itl.nist.gov/div898/handbook/pri/section3/pri332.htm","accessedAt":"2026-07-28T08:00:00Z","usage":"publicDomain","evidenceLocator":"Using blocks to account for controlled nuisance factors while randomizing remaining variation"},{"id":"nih-rigor-reproducibility","title":"Enhancing Reproducibility through Rigor and Transparency","publisher":"National Institutes of Health","url":"https://www.grants.nih.gov/policy-and-compliance/policy-topics/reproducibility","accessedAt":"2026-07-28T08:00:00Z","usage":"publicDomain","evidenceLocator":"Unbiased, well-controlled design, analysis, interpretation, and transparent reporting"}],"tags":["field-experiment","cluster-randomization","spillovers","causal-estimand","essay"],"generatedAt":"2026-07-28T08:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"science-depth-v2-ecosystem-model-essay-001","category":"science","conceptID":"science.models-systems","conceptTitle":"Models and systems","type":"essay","dimension":"synthesis","difficulty":"advanced","prompt":"A lake experiences recurring summer algal blooms and low dissolved oxygen. Construct a systems model that could compare interventions such as reducing external phosphorus, restoring wetlands, or aerating deep water. Define stocks, flows, feedbacks, time scales, calibration data, and at least two ways the model could mislead decision-makers.","choices":[],"explanation":"Coaching should focus on a transparent model boundary and linked mechanisms rather than a decorative causal diagram. A strong response distinguishes matter stocks from energy flow, includes delays and feedback, and treats model outputs as conditional projections.","rubric":[{"id":"system-structure","title":"System structure","description":"Defines a coherent boundary, stocks, flows, external drivers, and units for key state variables.","weight":0.28,"coachingQuestions":["Which quantities accumulate and which merely set a rate?","Where do phosphorus and oxygen enter or leave the modeled boundary?"]},{"id":"mechanisms-feedback","title":"Mechanisms and feedback","description":"Connects nutrients, primary production, decomposition, oxygen demand, sediment release, and seasonal mixing with plausible feedbacks and delays.","weight":0.3,"coachingQuestions":["Could low oxygen increase internal nutrient loading?","Which feedback operates faster than the management horizon?"]},{"id":"calibration-validation","title":"Calibration and validation","description":"Names time-resolved observations, parameter constraints, withheld tests, sensitivity analysis, and uncertainty checks.","weight":0.27,"coachingQuestions":["Which independent observation could falsify the model?","Which parameter uncertainty most affects intervention ranking?"]},{"id":"decision-limits","title":"Decision limits","description":"Identifies structural omissions, extrapolation risks, value judgments, and conditions under which rankings should not be trusted.","weight":0.15,"coachingQuestions":["What important mechanism lies outside the boundary?","How could equal model fit conceal different intervention predictions?"]}],"coachingPrompts":["Give every stock and flow a unit.","Separate external loading from recycling within the lake.","Describe one calibration test and one out-of-sample validation test.","Report intervention results as conditional ranges, not single promised outcomes."],"modelOutline":["Set the lake boundary, time horizon, stocks, flows, and units","Connect nutrient inputs, biomass, decomposition, oxygen, and feedback delays","Identify calibration data, independent validation data, and competing structures","Simulate interventions with sensitivity and uncertainty ranges","Report structural limits and conditions under which intervention rankings could reverse"],"sources":[{"id":"epa-nutrient-pollution","title":"Basic Information on Nutrient Pollution","publisher":"U.S. Environmental Protection Agency","url":"https://www.epa.gov/nutrientpollution/basic-information-nutrient-pollution","accessedAt":"2026-07-28T08:00:00Z","usage":"publicDomain","evidenceLocator":"Nutrient inputs, accelerated algal growth, water-quality effects, and oxygen depletion"},{"id":"nih-systems-science","title":"Best Practices for Systems Science Research","publisher":"National Institutes of Health, Office of Behavioral and Social Sciences Research","url":"https://obssr.od.nih.gov/sites/obssr/files/inline-files/best-practices-consensus-statement-FINAL-508.pdf","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Explicit system boundaries, timeframes, endogenous and exogenous components, data-informed assumptions, and validation"}],"tags":["systems-model","feedback","eutrophication","sensitivity-analysis","essay"],"generatedAt":"2026-07-28T08:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"science-depth-v2-replication-evidence-essay-001","category":"science","conceptID":"science.scientific-inference","conceptTitle":"Scientific inference","type":"essay","dimension":"synthesis","difficulty":"advanced","prompt":"An influential experiment reported a moderate effect, but three later laboratories obtained estimates near zero with wide uncertainty intervals. Evaluate the claim that the phenomenon has been disproved. Then design a coordinated replication that could distinguish an overestimated original effect from protocol sensitivity, population heterogeneity, measurement differences, and low statistical power.","choices":[],"explanation":"Coaching should reject both automatic defense of the original result and the idea that several individually imprecise null estimates logically prove no effect. The response should synthesize effect sizes, uncertainty, study comparability, and a prospective multi-laboratory design.","rubric":[{"id":"evidence-interpretation","title":"Interpretation of existing evidence","description":"Evaluates effect estimates and uncertainty rather than treating significance labels or publication order as decisive.","weight":0.28,"coachingQuestions":["Do the replication intervals exclude the original effect, a smaller effect, or neither?","How might selection or publication processes have inflated the first estimate?"]},{"id":"comparability-heterogeneity","title":"Comparability and heterogeneity","description":"Separates implementation drift, measurement non-equivalence, and real effect modification across settings.","weight":0.24,"coachingQuestions":["Which protocol elements must be harmonized?","Which differences should be preserved and modeled as possible moderators?"]},{"id":"replication-design","title":"Prospective replication design","description":"Specifies preregistration, adequate independent sampling, shared materials, randomization or blinding, site structure, and pooled analysis.","weight":0.32,"coachingQuestions":["What smallest effect is the collaboration designed to distinguish?","How will site-level variation enter the analysis?"]},{"id":"conclusion-limits","title":"Conclusion and limits","description":"States what different outcomes would imply and avoids equating absence of evidence with evidence of exact absence.","weight":0.16,"coachingQuestions":["What result would substantially lower confidence without proving an exact zero?","Which conclusion remains vulnerable to unmeasured protocol differences?"]}],"coachingPrompts":["Put the original and replication effect estimates on the same scale.","Distinguish a direct replication from a test of generalizability.","Predefine the smallest effect of substantive interest.","Explain how a hierarchical or site-aware analysis changes the inference."],"modelOutline":["Synthesize original and replication effect estimates with their uncertainty","Separate exact absence from low power, heterogeneity, and protocol sensitivity","Pre-register a coordinated multi-site protocol with planned variation checks","Justify sample size, smallest meaningful effect, and site-aware analysis","Map possible result patterns to calibrated conclusions and remaining limits"],"sources":[{"id":"nih-rigor-reproducibility","title":"Enhancing Reproducibility through Rigor and Transparency","publisher":"National Institutes of Health","url":"https://www.grants.nih.gov/policy-and-compliance/policy-topics/reproducibility","accessedAt":"2026-07-28T08:00:00Z","usage":"publicDomain","evidenceLocator":"Rigor, reproducibility, transparent design, analysis, interpretation, and reporting"},{"id":"nist-statistics-handbook","title":"What Is Experimental Design?","publisher":"National Institute of Standards and Technology","url":"https://itl.nist.gov/div898/handbook/pri/section1/pri11.htm","accessedAt":"2026-07-28T08:00:00Z","usage":"publicDomain","evidenceLocator":"Planning experiments for valid, objective conclusions and explicit process models"}],"tags":["replication","effect-size","heterogeneity","power","essay"],"generatedAt":"2026-07-28T08:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"biotechnology-depth-v2-expression-timecourse-001","category":"biotechnology","conceptID":"biotechnology.gene-expression","conceptTitle":"Gene expression","type":"multipleChoice","dimension":"application","difficulty":"advanced","prompt":"Six hours after a regulatory RNA treatment, target mRNA is 25% of control, but the measured target protein is unchanged. Which follow-up best tests whether this is a timing or post-transcriptional issue rather than evidence that the RNA result is meaningless?","choices":[{"id":"a","text":"Repeat the six-hour mRNA assay with more replicates to narrow its confidence interval.","rationale":"Greater precision about mRNA says nothing about when or whether protein abundance or function changes."},{"id":"b","text":"Measure protein at six hours with a second antibody to check whether the first one failed.","rationale":"Antibody validation is worthwhile, but a single time point cannot test the timing or turnover explanation."},{"id":"c","text":"Track mRNA, protein, and activity over a time course in replicates, controlling for turnover.","rationale":"Correct. RNA and protein have different synthesis and decay dynamics; a time course with orthogonal endpoints tests the chain without assuming immediate correspondence."},{"id":"d","text":"Check whether pre-mRNA also fell, which would show that transcription itself had been blocked.","rationale":"This probes how mRNA was reduced, not why the protein has not yet changed."}],"correctChoiceID":"c","explanation":"Gene expression is regulated across transcription, RNA processing and stability, translation, protein modification, and degradation. A six-hour mismatch can therefore be biologically plausible. The strongest follow-up measures the chain over time and uses independent samples and assay controls; even concordant changes would support, not by themselves prove, a single causal mechanism.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"nhgri-genomics-fact-sheets","title":"Transcriptome Fact Sheet","publisher":"National Human Genome Research Institute","url":"https://www.genome.gov/about-genomics/fact-sheets/Transcriptome-Fact-Sheet","accessedAt":"2026-07-28T08:00:00Z","usage":"publicDomain","evidenceLocator":"Transcripts, mRNA translation, tissue-specific expression, and limits of inferring function from transcript patterns"},{"id":"nist-metrology-biology","title":"Metrology in Biology","publisher":"National Institute of Standards and Technology","url":"https://www.nist.gov/bioscience/metrology-biology","accessedAt":"2026-07-28T08:00:00Z","usage":"publicDomain","evidenceLocator":"Reliable, reproducible biological measurements, reference materials, and method evaluation"}],"tags":["rna","protein","time-course","orthogonal-measurement"],"generatedAt":"2026-07-28T08:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"biotechnology-depth-v2-dpcr-poisson-001","category":"biotechnology","conceptID":"biotechnology.gene-expression","conceptTitle":"Gene expression","type":"multipleChoice","dimension":"application","difficulty":"advanced","prompt":"In a simplified digital-PCR run, 2,500 of 10,000 equal-volume partitions are positive. Assuming random Poisson loading, perfect classification, and no other correction, what is the estimated mean number of target molecules per partition?","choices":[{"id":"a","text":"About 0.250, the positive fraction.","rationale":"Some positive partitions hold more than one molecule, so the raw positive fraction underestimates mean occupancy."},{"id":"b","text":"About 0.288, from λ = −ln(0.75).","rationale":"Correct. The negative fraction estimates P(0) = e^−λ; with 75% negative partitions, λ = −ln(0.75) ≈ 0.288."},{"id":"c","text":"About 1.386, from λ = −ln(0.25).","rationale":"P(0) corresponds to the negative fraction, 0.75, not the positive fraction."},{"id":"d","text":"About 0.333, from positives ÷ negatives.","rationale":"The ratio of positives to negatives is the odds of a positive partition, not the Poisson mean."}],"correctChoiceID":"b","explanation":"Digital PCR infers occupancy from the fraction of partitions with no detected target. Here P(0) = 0.75, so λ ≈ 0.288 molecules per partition. Real concentration estimates also depend on partition volume, classification thresholds, assay efficiency, false positives or negatives, dead volume, and uncertainty in the partition model.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"nist-digital-pcr","title":"Digital PCR","publisher":"National Institute of Standards and Technology","url":"https://www.nist.gov/programs-projects/digital-pcr","accessedAt":"2026-07-28T08:00:00Z","usage":"publicDomain","evidenceLocator":"Partitioning nucleic acids, counting positive and negative reactions, and estimating copies per partition or volume"},{"id":"nist-digital-pcr-traceability","title":"Evaluating Droplet Digital PCR for the Quantification of Human Genomic DNA","publisher":"National Institute of Standards and Technology","url":"https://www.nist.gov/publications/evaluating-droplet-digital-pcr-quantification-human-genomic-dna-lifting-traceability","accessedAt":"2026-07-28T08:00:00Z","usage":"publicDomain","evidenceLocator":"Mean target copies per reaction container and traceability limits from partition volume and model assumptions"}],"tags":["digital-pcr","poisson","quantification","measurement-assumptions"],"generatedAt":"2026-07-28T08:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"biotechnology-depth-v2-crispr-causal-controls-001","category":"biotechnology","conceptID":"biotechnology.experimental-evidence","conceptTitle":"Biotechnology evidence","type":"multipleChoice","dimension":"application","difficulty":"advanced","prompt":"A CRISPR knockout made with one guide RNA reduces cell growth. Which added result would most strengthen the claim that loss of the intended gene, rather than a guide-specific artifact, caused the phenotype?","choices":[{"id":"a","text":"A second clone made with the same guide shows the same growth defect in repeat assays.","rationale":"A clone made with the same guide shares that guide's off-target profile, so it cannot separate on-target from guide-specific effects."},{"id":"b","text":"Sequencing confirms the intended frameshift, and the top predicted off-target sites are clean.","rationale":"This verifies the on-target edit, but predicted-site screening cannot exclude other guide-specific effects, and there is no rescue."},{"id":"c","text":"Independent guides reproduce it, edits are verified, and an edit-resistant cDNA rescues growth.","rationale":"Correct. Convergent independent perturbations plus specific rescue make a guide-specific artifact much less plausible."},{"id":"d","text":"A nontargeting control guide, delivered the same way, leaves growth unchanged in parallel cultures.","rationale":"This rules out general Cas9 or delivery toxicity, but not off-target effects specific to the original guide."}],"correctChoiceID":"c","explanation":"Independent guides reduce dependence on one reagent, molecular verification establishes the intended perturbation, and a well-designed rescue tests specificity. This package still has limits: rescue overexpression can create artifacts, guides may share off-target pathways, clonal selection can bias results, and findings may not generalize beyond the tested cells.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"nhgri-genome-editing","title":"What Is Genome Editing?","publisher":"National Human Genome Research Institute","url":"https://www.genome.gov/about-genomics/policy-issues/what-is-Genome-Editing","accessedAt":"2026-07-28T08:00:00Z","usage":"publicDomain","evidenceLocator":"Genome-editing mechanisms and the use of edited models to investigate gene function"},{"id":"nist-biomanufacturing","title":"Metrology in Biology","publisher":"National Institute of Standards and Technology","url":"https://www.nist.gov/bioscience/metrology-biology","accessedAt":"2026-07-28T08:00:00Z","usage":"publicDomain","evidenceLocator":"Reliable and reproducible biological measurement, validated methods, and reference materials"}],"tags":["crispr","causal-evidence","independent-guides","rescue"],"generatedAt":"2026-07-28T08:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"biotechnology-depth-v2-off-target-claims-001","category":"biotechnology","conceptID":"biotechnology.genome-editing","conceptTitle":"Genome editing","type":"multipleChoice","dimension":"application","difficulty":"advanced","prompt":"After editing patient-derived cells, a team sequences the intended site and the 20 off-target sites ranked highest by software. It detects the intended edit and no variant above a 1% allele-fraction threshold at those 20 sites. Which statement is most defensible?","choices":[{"id":"a","text":"The cells have no off-target edits, since the top-ranked sites are where off-targets occur.","rationale":"Software ranking is a design aid; empirical genome-wide methods find off-target sites that prediction misses."},{"id":"b","text":"No variant above 1% was found at the 20 assayed sites; a genome-wide claim needs broader assays.","rationale":"Correct. This reports what the test covered while preserving uncertainty about unassayed sites, low-frequency events, and structural variants."},{"id":"c","text":"The cells have no off-target edits above 1% anywhere, though rarer events may remain.","rationale":"The 1% threshold applies only to the 20 sites that were sequenced; unassayed sites could carry edits at any frequency."},{"id":"d","text":"No off-target edits occurred at the 20 sites, though sub-1% edits elsewhere may remain.","rationale":"The assay cannot exclude edits below 1% at the assayed sites either, or structural changes it was not designed to detect."}],"correctChoiceID":"b","explanation":"A negative result is conditional on assay scope and sensitivity. Targeted sequencing of predicted sites can support a bounded statement, not the universal claim 'no off-target effects.' Empirical genome-wide discovery, orthogonal confirmation, on-target structural analysis, relevant cell types, and stated limits of detection improve the evidence without making uncertainty disappear.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"pubmed-guide-seq","title":"GUIDE-seq Enables Genome-wide Profiling of Off-target Cleavage by CRISPR-Cas Nucleases","publisher":"PubMed, U.S. National Library of Medicine","url":"https://pubmed.ncbi.nlm.nih.gov/25513782/","publishedAt":"2014-12-16T00:00:00Z","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Peer-reviewed record describing empirical genome-wide off-target discovery"},{"id":"fda-genome-editing-guidance","title":"Human Gene Therapy Products Incorporating Human Genome Editing","publisher":"U.S. Food and Drug Administration","url":"https://www.fda.gov/regulatory-information/search-fda-guidance-documents/human-gene-therapy-products-incorporating-human-genome-editing","publishedAt":"2024-01-01T00:00:00Z","accessedAt":"2026-07-28T08:00:00Z","usage":"publicDomain","evidenceLocator":"Product design, manufacturing and testing, nonclinical safety, and clinical-trial considerations for somatic genome-editing products"}],"tags":["off-target","limit-of-detection","negative-result","genomic-safety"],"generatedAt":"2026-07-28T08:00:00Z","validUntil":"2027-07-28T08:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"biotechnology-depth-v2-sequencing-batch-design-001","category":"biotechnology","conceptID":"biotechnology.experimental-evidence","conceptTitle":"Biotechnology evidence","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"A single-cell RNA-sequencing study uses paired treated and control cells from three donors, but all treated libraries are prepared on Monday and all control libraries on Friday. It reports 1,200 differentially expressed genes. Which redesign most directly makes a treatment effect distinguishable from preparation-batch effects?","choices":[{"id":"a","text":"Split each donor's treated and control samples across randomized preparation batches and lanes.","rationale":"Correct. Treatment-control overlap within batches and donors breaks the complete confounding while keeping donor pairing."},{"id":"b","text":"Fit a batch covariate to the original data, since modeling can remove the Monday-Friday effect.","rationale":"When treatment perfectly predicts batch, no model can separate their effects from those data."},{"id":"c","text":"Prepare all libraries on one day, with treated and control samples run as separate batches.","rationale":"Running treatment groups as separate batches on the same day keeps treatment confounded with batch."},{"id":"d","text":"Add three more donors, again with treated libraries on Monday and controls on Friday.","rationale":"More donors add biological replication but preserve the complete treatment-by-day confounding."}],"correctChoiceID":"a","explanation":"The original design has complete treatment-by-preparation-day confounding: no comparison can tell whether treatment or batch produced the expression pattern. Balancing and randomizing paired samples across batches creates overlap, while donor pairing, independent donors, quality controls, and a pre-specified model protect the relevant biological comparison. Large cell counts do not substitute for independent biological replication.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"nih-rigor-reproducibility","title":"Enhancing Reproducibility through Rigor and Transparency","publisher":"National Institutes of Health","url":"https://www.grants.nih.gov/policy-and-compliance/policy-topics/reproducibility","accessedAt":"2026-07-28T08:00:00Z","usage":"publicDomain","evidenceLocator":"Scientific premise, rigorous design, relevant biological variables, authentication, and transparent reporting"},{"id":"nist-biomanufacturing","title":"Genomic Measurements","publisher":"National Institute of Standards and Technology","url":"https://www.nist.gov/mml/bbd/core-capabilities/genomic-measurements","accessedAt":"2026-07-28T08:00:00Z","usage":"publicDomain","evidenceLocator":"Reliable genomic measurement, reference materials, sequencing controls, and measurement assurance"}],"tags":["single-cell-rna-seq","batch-confounding","biological-replication","randomization"],"generatedAt":"2026-07-28T08:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"biotechnology-depth-v2-bioreactor-scaleup-001","category":"biotechnology","conceptID":"biotechnology.bioprocess-engineering","conceptTitle":"Bioprocess engineering","type":"multipleChoice","dimension":"application","difficulty":"advanced","prompt":"A microbial process performs well in a 2 L stirred tank. Engineers propose running a geometrically different 2,000 L tank at the same revolutions per minute. Which critique is strongest?","choices":[{"id":"a","text":"Equal rpm won't preserve oxygen transfer, mixing, or shear; scale on process criteria like kLa, then verify.","rationale":"Correct. No single rpm equivalence captures the interacting transport and biological constraints; relevant criteria plus empirical confirmation are needed."},{"id":"b","text":"Equal rpm is too aggressive; match impeller tip speed instead, which preserves mixing and oxygen transfer.","rationale":"Constant tip speed limits peak shear but generally lowers power per volume and kLa at scale; it does not preserve mixing or oxygen transfer."},{"id":"c","text":"Equal rpm works if power per volume is also matched, which keeps every transport property equal.","rationale":"In different geometries both cannot hold, and even constant power per volume changes tip speed, mixing time, and gas transfer."},{"id":"d","text":"Keep equal rpm but scale aeration with volume, which keeps the oxygen supply per liter equal.","rationale":"Equal gas flow per volume does not guarantee equal kLa or oxygen transfer, and it leaves the rpm problem unaddressed."}],"correctChoiceID":"a","explanation":"Scale changes geometry, energy dissipation, gas-liquid area, mixing time, oxygen and carbon-dioxide transfer, gradients, and shear exposure. A defensible strategy identifies critical process needs, selects scale criteria such as kLa or oxygen-transfer flux with appropriate tradeoffs, maps the operating region, and verifies product quality—not merely biomass or titer.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"pubmed-bioreactor-scaleup","title":"Bioreactor Scale-up and Oxygen Transfer Rate in Microbial Processes: An Overview","publisher":"PubMed, U.S. National Library of Medicine","url":"https://pubmed.ncbi.nlm.nih.gov/19041387/","publishedAt":"2008-11-12T00:00:00Z","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Peer-reviewed review of oxygen-transfer rate, kLa, hydrodynamics, oxygen uptake, and scale-up criteria"},{"id":"nist-biomanufacturing","title":"Biomanufacturing Program","publisher":"National Institute of Standards and Technology","url":"https://www.nist.gov/programs-projects/biomanufacturing-program","accessedAt":"2026-07-28T08:00:00Z","usage":"publicDomain","evidenceLocator":"Measurement and standards infrastructure for bioprocess understanding and control"}],"tags":["scale-up","oxygen-transfer","kLa","mixing","shear"],"generatedAt":"2026-07-28T08:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"biotechnology-depth-v2-secondary-use-governance-001","category":"biotechnology","conceptID":"biotechnology.bioethics-governance","conceptTitle":"Bioethics and governance","type":"multipleChoice","dimension":"application","difficulty":"advanced","prompt":"A university biobank obtained disease-specific consent ten years ago. A commercial partner now proposes using the coded genomes to build an ancestry-linked consumer risk tool and argues that no further review is needed because names were removed. Which response is most defensible?","choices":[{"id":"a","text":"Approve it, since coded genomes fall outside human-subjects concerns once names are removed.","rationale":"Coded genomic data retain re-identification and familial risks, and de-identification does not settle consent scope or group harms."},{"id":"b","text":"Approve it if the partner shares revenue with the biobank, since benefit-sharing satisfies participants.","rationale":"Payment to an institution is not participant consent and does not address the mismatch with disease-specific consent."},{"id":"c","text":"Reject it outright, since disease-specific consent can never permit any later secondary use.","rationale":"Secondary use can be permissible under appropriate consent and governance; a categorical ban ignores the actual framework."},{"id":"d","text":"Check the consent's scope, seek oversight and re-consent where required, and weigh privacy and group harms.","rationale":"Correct. Consent scope, privacy, commercial use, and group effects are distinct questions that coding alone does not resolve."}],"correctChoiceID":"d","explanation":"Removing names is a privacy control, not blanket authorization. A defensible decision examines what participants were told, whether the proposed commercial and ancestry-linked use fits that scope, applicable oversight and re-consent pathways, data-access safeguards, community perspectives, and distributive or group harms. Engagement does not replace individual consent, and no governance process can guarantee zero privacy or downstream misuse risk.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"nhgri-genomics-fact-sheets","title":"The Informed Consent Process","publisher":"National Human Genome Research Institute","url":"https://www.genome.gov/about-genomics/educational-resources/fact-sheets/the-informed-consent-process","accessedAt":"2026-07-28T08:00:00Z","usage":"publicDomain","evidenceLocator":"Consent information, voluntariness, documentation, new findings, and participant decision-making"},{"id":"who-genome-editing-governance","title":"Human Genome Editing: Recommendations","publisher":"World Health Organization","url":"https://www.who.int/publications/i/item/9789240030381","publishedAt":"2021-07-12T00:00:00Z","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Accountable governance, registries, international collaboration, equity, education, and public engagement"}],"tags":["secondary-use","informed-consent","genomic-privacy","community-engagement","equity"],"generatedAt":"2026-07-28T08:00:00Z","validUntil":"2027-07-28T08:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"biotechnology-depth-v2-absolute-risk-001","category":"biotechnology","conceptID":"biotechnology.clinical-regulatory-evidence","conceptTitle":"Clinical and regulatory evidence","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"In a randomized biotechnology trial, an adverse event occurs in 10% of the control group and 8% of the intervention group over the same follow-up. Before considering confidence intervals or harms, which description communicates the observed effect most completely?","choices":[{"id":"a","text":"A 2% relative reduction and a 20% absolute reduction in the number of events per 100 people.","rationale":"This swaps the measures: the relative reduction is 20% and the absolute difference is 2 percentage points."},{"id":"b","text":"A 20% reduction in risk, meaning 20 fewer events for every 100 people treated.","rationale":"Twenty percent is relative to the 10% baseline; the absolute difference is 2 events per 100, not 20."},{"id":"c","text":"A 2-point absolute reduction and a 25% relative reduction, so 50 must be treated.","rationale":"The absolute difference and number needed to treat (50) are right, but the relative reduction divides by the control rate: 2/10 = 20%, not 2/8."},{"id":"d","text":"A 20% relative and a 2-percentage-point absolute reduction: 2 fewer events per 100.","rationale":"Correct. 0.08/0.10 = 0.80 gives a 20% relative reduction; 0.10 − 0.08 = 0.02 is 2 fewer events per 100 over the period."}],"correctChoiceID":"d","explanation":"The relative risk is 0.08/0.10 = 0.80, so the relative reduction is 20%. The absolute risk difference is 0.10 − 0.08 = 0.02, or 2 percentage points. Interpretation also requires uncertainty intervals, sample size, adherence, outcome definition, competing harms, and whether the trial population and follow-up match the intended use.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"ahrq-risk-communication","title":"The SHARE Approach: Communicating Numbers to Your Patients","publisher":"Agency for Healthcare Research and Quality","url":"https://www.ahrq.gov/sites/default/files/wysiwyg/sdm/share-approach/share-communicating-numbers.pdf","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"PDF guidance to present absolute risks with common denominators and timeframes rather than relative figures alone"}],"tags":["absolute-risk","relative-risk","risk-communication","clinical-evidence"],"generatedAt":"2026-07-28T08:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"biotechnology-depth-v2-editing-validation-essay-001","category":"biotechnology","conceptID":"biotechnology.genome-editing","conceptTitle":"Genome editing","type":"essay","dimension":"synthesis","difficulty":"advanced","prompt":"A company reports that its ex vivo editing process produces the intended sequence in 92% of cells and finds no variants at 20 software-predicted off-target sites. Design an evidence package that could support a carefully bounded claim about editing specificity and cell function. Address on-target heterogeneity, unintended edits, assay sensitivity, biological replication, functional testing, and what the data still could not prove.","choices":[],"explanation":"Coaching should turn the headline percentage into a testable evidence chain. The response should examine the full distribution of outcomes, use orthogonal methods, connect molecular changes to function, and avoid converting nondetection into proof of absence or safety.","rubric":[{"id":"on-target-characterization","title":"On-target characterization","description":"Distinguishes intended alleles from indels, partial edits, mosaic mixtures, large rearrangements, and copy-number or structural changes.","weight":0.26,"coachingQuestions":["What exactly is included in the reported 92%?","Could a cell counted as edited contain an additional on-target alteration?"]},{"id":"off-target-strategy","title":"Off-target strategy","description":"Combines hypothesis-driven sites with empirical genome-wide discovery, orthogonal confirmation, relevant cell context, and stated detection limits.","weight":0.28,"coachingQuestions":["Which events would the targeted panel be unable to discover?","How will low-frequency or structural events be detected and confirmed?"]},{"id":"functional-rigor","title":"Functional and experimental rigor","description":"Uses independent donors or lots, process controls, viability and phenotype measures, functional potency, and transparent analysis.","weight":0.28,"coachingQuestions":["Does the intended sequence restore the relevant function?","Which result could reveal selection for a rare abnormal clone?"]},{"id":"claim-boundary","title":"Claim boundary","description":"States population, assay, threshold, timeframe, and unresolved uncertainty without claiming universal precision or clinical safety.","weight":0.18,"coachingQuestions":["How would you phrase a negative result without saying no off-target edits exist?","Which clinical conclusion lies beyond this laboratory package?"]}],"coachingPrompts":["Decompose the 92% headline into mutually exclusive editing outcomes.","Pair a genome-wide discovery method with targeted orthogonal confirmation.","State limits of detection before interpreting nondetection.","Separate molecular specificity, cellular function, product consistency, and clinical safety."],"modelOutline":["Decompose intended and unintended on-target outcomes rather than using one edit percentage","Pair empirical genome-wide discovery with targeted orthogonal confirmation","Quantify assay sensitivity, biological replication, and relevant cell-context limits","Connect molecular findings to viability, phenotype, potency, and clonal behavior","Write a bounded specificity claim that does not imply universal absence or clinical safety"],"sources":[{"id":"fda-genome-editing-guidance","title":"Human Gene Therapy Products Incorporating Human Genome Editing","publisher":"U.S. Food and Drug Administration","url":"https://www.fda.gov/regulatory-information/search-fda-guidance-documents/human-gene-therapy-products-incorporating-human-genome-editing","publishedAt":"2024-01-01T00:00:00Z","accessedAt":"2026-07-28T08:00:00Z","usage":"publicDomain","evidenceLocator":"Product design, manufacturing and testing, nonclinical safety assessment, and clinical-trial design for somatic genome editing"},{"id":"pubmed-guide-seq","title":"GUIDE-seq Enables Genome-wide Profiling of Off-target Cleavage by CRISPR-Cas Nucleases","publisher":"PubMed, U.S. National Library of Medicine","url":"https://pubmed.ncbi.nlm.nih.gov/25513782/","publishedAt":"2014-12-16T00:00:00Z","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Peer-reviewed empirical method for genome-wide off-target cleavage discovery"},{"id":"nist-biomanufacturing","title":"Genomic Measurements","publisher":"National Institute of Standards and Technology","url":"https://www.nist.gov/mml/bbd/core-capabilities/genomic-measurements","accessedAt":"2026-07-28T08:00:00Z","usage":"publicDomain","evidenceLocator":"Reference materials and methods for sequencing, genome editing, and reliable genomic measurement"}],"tags":["genome-editing","validation","off-target","functional-evidence","essay"],"generatedAt":"2026-07-28T08:00:00Z","validUntil":"2027-07-28T08:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"biotechnology-depth-v2-process-comparability-essay-001","category":"biotechnology","conceptID":"biotechnology.bioprocess-engineering","conceptTitle":"Bioprocess engineering","type":"essay","dimension":"synthesis","difficulty":"advanced","prompt":"A biologic process will move from a 10 L pilot reactor to a 1,000 L production reactor and replace one purification resin. Titer remains similar in three engineering runs. Build a comparability strategy that could test whether the pre-change and post-change products are meaningfully comparable. Include process characterization, critical quality attributes, functional potency, impurity and stability testing, sampling, acceptance logic, and conditions that could require nonclinical or clinical evidence.","choices":[],"explanation":"Coaching should prevent the learner from treating similar titer as product equivalence. A strong response links changed process steps to plausible product risks, uses side-by-side analytical and functional evidence, and escalates evidence when the methods cannot resolve clinically meaningful differences.","rubric":[{"id":"risk-map","title":"Process and risk map","description":"Connects scale and resin changes to mixing, mass transfer, hold times, impurities, product variants, and stability risks.","weight":0.24,"coachingQuestions":["Which quality attributes could change even if titer does not?","Which sampling points isolate reactor effects from purification effects?"]},{"id":"analytical-functional","title":"Analytical and functional matrix","description":"Defines identity, structure, purity, impurities, potency, safety-related tests, and sensitive orthogonal methods.","weight":0.31,"coachingQuestions":["Which assay reflects the proposed mechanism of action?","Could two assays agree while missing a clinically relevant variant?"]},{"id":"design-acceptance","title":"Study design and acceptance logic","description":"Uses representative independent lots, reference standards, side-by-side testing, variability estimates, pre-specified criteria, and stability follow-up.","weight":0.27,"coachingQuestions":["Are three engineering runs representative of routine variability?","How were acceptance ranges justified before observing the results?"]},{"id":"escalation-limits","title":"Escalation and limits","description":"Explains when analytical uncertainty or meaningful differences require further nonclinical, pharmacologic, or clinical evidence.","weight":0.18,"coachingQuestions":["What unresolved difference would change safety or efficacy confidence?","When is an additional clinical study informative rather than automatic?"]}],"coachingPrompts":["Treat titer as one process output, not a proxy for every quality attribute.","Map each manufacturing change to a plausible failure mode.","Use old and new product side by side when feasible.","State how assay sensitivity determines the next evidentiary step."],"modelOutline":["Map each scale and resin change to plausible process and product risks","Select sensitive identity, structure, impurity, potency, and stability attributes","Design representative side-by-side lot testing with standards and pre-specified criteria","Interpret similarity against process variability and analytical uncertainty","Define differences that trigger investigation or additional nonclinical or clinical evidence"],"sources":[{"id":"fda-biologics-comparability","title":"Demonstration of Comparability of Human Biological Products","publisher":"U.S. Food and Drug Administration","url":"https://www.fda.gov/regulatory-information/search-fda-guidance-documents/demonstration-comparability-human-biological-products-including-therapeutic-biotechnology-derived","publishedAt":"1996-04-01T00:00:00Z","accessedAt":"2026-07-28T08:00:00Z","usage":"publicDomain","evidenceLocator":"Side-by-side chemical, physical, biological, pharmacologic, and potentially clinical comparability evidence"},{"id":"fda-gene-therapy-cmc","title":"Chemistry, Manufacturing, and Control Information for Human Gene Therapy INDs","publisher":"U.S. Food and Drug Administration","url":"https://www.fda.gov/regulatory-information/search-fda-guidance-documents/chemistry-manufacturing-and-control-cmc-information-human-gene-therapy-investigational-new-drug","publishedAt":"2020-01-01T00:00:00Z","accessedAt":"2026-07-28T08:00:00Z","usage":"publicDomain","evidenceLocator":"Safety, identity, quality, purity, strength, and potency information for investigational products"},{"id":"pubmed-bioreactor-scaleup","title":"Bioreactor Scale-up and Oxygen Transfer Rate in Microbial Processes: An Overview","publisher":"PubMed, U.S. National Library of Medicine","url":"https://pubmed.ncbi.nlm.nih.gov/19041387/","publishedAt":"2008-11-12T00:00:00Z","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Peer-reviewed scale-up analysis of oxygen transfer, hydrodynamics, and biological demand"}],"tags":["comparability","scale-up","critical-quality-attributes","potency","essay"],"generatedAt":"2026-07-28T08:00:00Z","validUntil":"2027-07-28T08:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"biotechnology-depth-v2-early-trial-inference-essay-001","category":"biotechnology","conceptID":"biotechnology.clinical-regulatory-evidence","conceptTitle":"Clinical and regulatory evidence","type":"essay","dimension":"synthesis","difficulty":"advanced","prompt":"A first-in-human, single-arm gene-editing study enrolls 12 participants with severe disease. Eight show the intended biomarker change, four report functional improvement, and two experience serious adverse events that may be treatment-related. Evaluate what can and cannot be inferred, then design the next study and long-term follow-up needed to learn about dose, safety, biological activity, and efficacy without overstating early results.","choices":[],"explanation":"Coaching should keep safety, biological activity, functional outcomes, and comparative efficacy distinct. The answer should account for selection, natural history, measurement variability, small-sample uncertainty, delayed harms, and ethical dose escalation.","rubric":[{"id":"current-inference","title":"Current evidence","description":"Separates feasibility, exposure, target engagement, functional change, safety signals, and efficacy while acknowledging the missing comparator and wide uncertainty.","weight":0.28,"coachingQuestions":["Does biomarker change establish patient benefit?","What alternative explanations exist for the functional improvements?"]},{"id":"next-design","title":"Next-study design","description":"Proposes justified eligibility, comparison, dose-escalation, endpoints, sample size logic, blinding where feasible, and analysis.","weight":0.3,"coachingQuestions":["Which endpoint is clinically meaningful and when should it be measured?","How will dose decisions respond to both activity and toxicity?"]},{"id":"safety-followup","title":"Safety and long-term follow-up","description":"Defines stopping rules, attribution review, genomic or clonal monitoring where relevant, delayed-event surveillance, and participant retention.","weight":0.27,"coachingQuestions":["What result would pause enrollment or dose escalation?","Which plausible adverse event may appear only after the active trial?"]},{"id":"communication-ethics","title":"Communication and ethics","description":"Uses calibrated language, distinguishes research from therapy, and addresses consent under serious disease and limited alternatives.","weight":0.15,"coachingQuestions":["How will uncertainty be explained without erasing hope or creating therapeutic misconception?","Which claim would be inappropriate in a public announcement?"]}],"coachingPrompts":["Create separate columns for safety, biological activity, and efficacy.","Use exact denominators and uncertainty rather than a success percentage alone.","Define prospective stopping and dose-escalation rules.","Connect each long-term measurement to a plausible delayed risk."],"modelOutline":["Separate feasibility, target engagement, biological activity, safety, and efficacy","Explain limits from the single arm, small sample, selection, and outcome variability","Design dose escalation, comparison, endpoints, stopping rules, and analysis","Create risk-based long-term surveillance for delayed and clonal events","State claims appropriate for participants, regulators, and public communication"],"sources":[{"id":"fda-genome-editing-guidance","title":"Human Gene Therapy Products Incorporating Human Genome Editing","publisher":"U.S. Food and Drug Administration","url":"https://www.fda.gov/regulatory-information/search-fda-guidance-documents/human-gene-therapy-products-incorporating-human-genome-editing","publishedAt":"2024-01-01T00:00:00Z","accessedAt":"2026-07-28T08:00:00Z","usage":"publicDomain","evidenceLocator":"Nonclinical safety, clinical-trial design, and quality evidence for somatic genome-editing products"},{"id":"fda-gene-therapy-long-term-follow-up","title":"Long Term Follow-up After Administration of Human Gene Therapy Products","publisher":"U.S. Food and Drug Administration","url":"https://www.fda.gov/regulatory-information/search-fda-guidance-documents/long-term-follow-after-administration-human-gene-therapy-products","publishedAt":"2020-01-01T00:00:00Z","accessedAt":"2026-07-28T08:00:00Z","usage":"publicDomain","evidenceLocator":"Risk-based extended observation for delayed adverse events after long-acting gene-therapy exposure"}],"tags":["early-phase-trial","efficacy","safety","long-term-follow-up","essay"],"generatedAt":"2026-07-28T08:00:00Z","validUntil":"2027-07-28T08:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"biotechnology-depth-v2-governance-consent-essay-001","category":"biotechnology","conceptID":"biotechnology.bioethics-governance","conceptTitle":"Bioethics and governance","type":"essay","dimension":"synthesis","difficulty":"advanced","prompt":"A nonprofit proposes an international trial of an ex vivo somatic genome-editing therapy for a rare disease. Participants' cells would be edited outside the body and returned to them; genomic and long-term outcome data would be shared across borders. Build a governance plan addressing consent, privacy and future data use, independent oversight, registries, equitable selection and access, community engagement, conflicts of interest, and response to uncertain or delayed harms. Distinguish somatic treatment from heritable editing and identify what ethics cannot resolve without better technical evidence.","choices":[],"explanation":"Coaching should integrate scientific uncertainty with governance rather than substituting slogans for either. The response should treat consent as an ongoing process, distinguish research participation from guaranteed benefit, and confront cross-border enforcement and access limits.","rubric":[{"id":"consent-data","title":"Consent, privacy, and data stewardship","description":"Explains understandable and ongoing consent, genomic identifiability, future use, withdrawal limits, data access, and return-of-results policy.","weight":0.27,"coachingQuestions":["What future use cannot be specified precisely at enrollment?","What can withdrawal mean after data have been shared or aggregated?"]},{"id":"oversight-accountability","title":"Oversight and accountability","description":"Defines independent review, registration, monitoring, adverse-event reporting, conflicts management, cross-border responsibility, and enforcement paths.","weight":0.28,"coachingQuestions":["Who can pause the trial in every participating jurisdiction?","How will undisclosed or unsafe activity be reported and investigated?"]},{"id":"justice-engagement","title":"Justice and engagement","description":"Addresses fair participant selection, burdens and benefits, post-trial obligations, affordability, community input, and underrepresented populations without tokenism.","weight":0.27,"coachingQuestions":["Who bears the risks if the eventual product remains inaccessible?","At which decisions can participant communities exert real influence?"]},{"id":"technical-ethical-boundary","title":"Technical and ethical boundaries","description":"Accurately distinguishes somatic from heritable editing and identifies safety, efficacy, and uncertainty questions that governance cannot answer by itself.","weight":0.18,"coachingQuestions":["Why does persistence in a somatic stem-cell lineage not automatically make an edit heritable?","Which ethical judgment depends on an unresolved empirical probability?"]}],"coachingPrompts":["Treat informed consent as repeated communication and choice, not a signature.","Specify who owns each monitoring and enforcement responsibility.","Separate fair trial enrollment from fair eventual access.","Name one scientific uncertainty that materially changes the risk-benefit judgment."],"modelOutline":["Distinguish somatic intervention, research uncertainty, and non-heritable status","Design ongoing consent, privacy, future-use, withdrawal, and results policies","Assign independent oversight, registration, monitoring, reporting, and enforcement roles","Address fair selection, community power, post-trial duties, and access","Identify technical unknowns that materially change ethical and governance judgments"],"sources":[{"id":"who-genome-editing-governance","title":"Human Genome Editing: Recommendations","publisher":"World Health Organization","url":"https://www.who.int/publications/i/item/9789240030381","publishedAt":"2021-07-12T00:00:00Z","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"International collaboration, registries, reporting unsafe activity, engagement, equity, and governance review"},{"id":"nhgri-informed-consent","title":"The Informed Consent Process","publisher":"National Human Genome Research Institute","url":"https://www.genome.gov/about-genomics/educational-resources/fact-sheets/the-informed-consent-process","accessedAt":"2026-07-28T08:00:00Z","usage":"publicDomain","evidenceLocator":"Voluntary, understandable, ongoing consent and explanation of genomic information use"},{"id":"nhgri-genomic-research-participation","title":"Participation in Genomic Research","publisher":"National Human Genome Research Institute","url":"https://www.genome.gov/about-genomics/fact-sheets/Participation-in-Genomic-Research","accessedAt":"2026-07-28T08:00:00Z","usage":"publicDomain","evidenceLocator":"Underrepresentation, human genomic variation, and the limits of current population evidence"}],"tags":["bioethics","governance","consent","equity","data-sharing","essay"],"generatedAt":"2026-07-28T08:00:00Z","validUntil":"2027-07-28T08:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"space-kepler-period-scaling-002","category":"space","conceptID":"space.orbital-mechanics","conceptTitle":"Orbital mechanics","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"Two negligible-mass satellites move in nearly circular orbits around the same planet. Satellite B has a semimajor axis four times that of satellite A. Using Kepler's third law, how does B's orbital period compare with A's?","choices":[{"id":"a","text":"It is eight times as long.","rationale":"Correct. P² is proportional to a³, so the period ratio is 4^(3/2) = 8."},{"id":"b","text":"It is twice as long.","rationale":"This treats period as scaling with the square root of semimajor axis rather than its three-halves power."},{"id":"c","text":"It is four times as long.","rationale":"This assumes a linear period-distance relationship and misses the exponent in Kepler's third law."},{"id":"d","text":"It is sixteen times as long.","rationale":"This squares the distance ratio; Kepler's relation gives a three-halves power for the period ratio."}],"correctChoiceID":"a","explanation":"For bodies orbiting the same dominant mass, P² is proportional to a³. Taking the square root gives P proportional to a^(3/2), so increasing semimajor axis by a factor of 4 increases period by 4^(3/2) = 8.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"nasa-orbits-kepler-laws","title":"Orbits and Kepler's Laws","publisher":"NASA Science","url":"https://science.nasa.gov/solar-system/orbits-and-keplers-laws/","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Kepler's Third Law: P squared is proportional to a cubed"}],"tags":["kepler","orbital-period","quantitative-reasoning"],"generatedAt":"2026-07-28T08:00:00Z","validUntil":"2027-07-28T12:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"space-periapsis-prograde-burn-002","category":"space","conceptID":"space.orbital-mechanics","conceptTitle":"Orbital mechanics","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"A spacecraft is at periapsis in a bound elliptical orbit. It makes a brief prograde burn parallel to its velocity and then coasts. Assuming the burn is not large enough for escape, which description of the new orbit is best?","choices":[{"id":"a","text":"The burn point stays the periapsis, while the apoapsis rises.","rationale":"Correct. Added tangential speed at periapsis raises the opposite side of the orbit; the burn point remains the nearest point."},{"id":"b","text":"The burn point becomes the apoapsis, while the opposite side falls.","rationale":"That reverses the effect of a prograde burn; the spacecraft leaves the point with more orbital energy, not less."},{"id":"c","text":"The periapsis rises, while the apoapsis stays where it was.","rationale":"Raising periapsis is the effect of a prograde burn at apoapsis; a burn raises the far side of the orbit, not the burn point."},{"id":"d","text":"Both apsides rise, since the added energy lifts the whole orbit.","rationale":"The burn point lies on both the old and new orbits, so the periapsis distance cannot change at that instant."}],"correctChoiceID":"a","explanation":"An impulsive prograde burn increases orbital energy at the spacecraft's current position. At periapsis, this raises the subsequent apoapsis while the burn location remains the near point of the new orbit.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"nasa-basics-gravity-mechanics","title":"Chapter 3: Gravity & Mechanics","publisher":"NASA Science","url":"https://science.nasa.gov/learn/basics-of-space-flight/chapter3-4/","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"The Key to Space Flight"}],"tags":["orbital-energy","periapsis","maneuvers"],"generatedAt":"2026-07-28T08:00:00Z","validUntil":"2027-07-28T12:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"space-gravity-assist-reference-frame-002","category":"space","conceptID":"space.mission-tradeoffs","conceptTitle":"Mission tradeoffs","type":"multipleChoice","dimension":"application","difficulty":"advanced","prompt":"During an ideal unpowered planetary flyby, a spacecraft approaches and departs far from the planet with approximately the same speed relative to that planet, but its speed relative to the Sun changes. Which explanation resolves the apparent contradiction?","choices":[{"id":"a","text":"The Oberth effect amplifies a small engine burn at closest approach, adding Sun-relative speed.","rationale":"The Oberth effect requires a propulsive burn; an ideal gravity assist is unpowered."},{"id":"b","text":"The flyby turns the planet-relative velocity; adding the planet's motion changes the Sun-relative speed.","rationale":"Correct. The planet-relative speed is unchanged but its direction rotates, and vector addition with the moving planet changes the heliocentric result."},{"id":"c","text":"Speed is the same in both frames; only the measured direction of motion differs between them.","rationale":"Speeds differ between frames moving relative to each other, which is why the heliocentric speed can change."},{"id":"d","text":"Gravity is conservative, so the spacecraft's Sun-relative speed only appears to change.","rationale":"In the Sun's frame the planet moves, so its field is time-dependent; real energy is exchanged with the planet."}],"correctChoiceID":"b","explanation":"In the planet's frame, an ideal flyby mainly turns the spacecraft's velocity vector. In the Sun's frame, the planet is moving, so vector addition before and after the turn yields a heliocentric gain or loss of orbital energy. The planet experiences an immeasurably small reciprocal change.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"esa-gravity-assists","title":"What Are Gravity Assists?","publisher":"European Space Agency","url":"https://www.esa.int/Enabling_Support/Operations/What_are_gravity_assists","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"It all depends on your frame of reference"}],"tags":["gravity-assist","reference-frames","mission-design"],"generatedAt":"2026-07-28T08:00:00Z","validUntil":"2027-07-28T12:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"space-aperture-photon-scaling-002","category":"space","conceptID":"space.observation-instrumentation","conceptTitle":"Observation and instruments","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"Two telescopes observe the same steady point source at the same wavelength for the same exposure time. Their total throughput is equal, but one has an 8-meter aperture and the other a 2-meter aperture. Ignoring detector saturation, approximately how many source photons does the larger telescope collect relative to the smaller one?","choices":[{"id":"a","text":"Four times as many.","rationale":"This scales photon collection linearly with diameter instead of with collecting area."},{"id":"b","text":"Twice as many.","rationale":"The diameter ratio is 4, not 2, and collection scales with area rather than linear size."},{"id":"c","text":"Sixty-four times as many.","rationale":"This cubes the diameter ratio; a circular collecting area scales with the square."},{"id":"d","text":"Sixteen times as many.","rationale":"Correct. Collecting area is proportional to diameter squared, so the ratio is (8/2)² = 16."}],"correctChoiceID":"d","explanation":"A telescope's light-gathering area scales as the square of its aperture diameter. Sixteen times the photon count does not automatically mean sixteen times the signal-to-noise ratio or angular resolution; those depend on noise, wavelength, optics, and observing conditions.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"nasa-hubble-vs-webb","title":"Hubble vs. Webb","publisher":"NASA Science","url":"https://science.nasa.gov/mission/hubble/observatory/hubble-vs-webb/","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Mirrors, collecting area, and light-gathering power"},{"id":"nasa-telescopes-101","title":"Telescopes 101","publisher":"NASA Science","url":"https://science.nasa.gov/universe/telescopes-101/","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Telescopes"}],"tags":["telescopes","aperture","signal","quantitative-reasoning"],"generatedAt":"2026-07-28T08:00:00Z","validUntil":"2027-07-28T12:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"space-cluster-turnoff-age-002","category":"space","conceptID":"space.stellar-evolution","conceptTitle":"Stellar evolution","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"After correcting for distance and extinction, astronomers compare two star clusters with similar chemical composition. Cluster A's main sequence turns off among hot, highly luminous stars; Cluster B's turns off among cooler, less luminous stars. What is the strongest age inference?","choices":[{"id":"a","text":"Cluster A is older, because its turnoff stars have had time to grow brighter and hotter.","rationale":"Hot, luminous main-sequence stars are massive and short-lived, so a turnoff among them indicates a younger cluster."},{"id":"b","text":"Cluster B is older, because its turnoff stars have been cooling since they formed.","rationale":"The conclusion is right but the reason is wrong: main-sequence stars do not simply cool with age; the turnoff marks which masses have exhausted core hydrogen."},{"id":"c","text":"Cluster B is older, because its lower-mass stars have already exhausted core hydrogen.","rationale":"Correct. In a coeval cluster, progressively lower-mass stars leave the main sequence as the cluster ages."},{"id":"d","text":"Neither: turnoff luminosity tracks how far away a cluster is, not how old it is.","rationale":"The stem states that distance and extinction were corrected, and turnoff luminosity is a standard age indicator."}],"correctChoiceID":"c","explanation":"Stars in a cluster form at roughly the same time, while high-mass stars exhaust core hydrogen sooner. A turnoff at lower mass and luminosity therefore indicates an older cluster, given the stated controls for composition, distance, and extinction.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"nasa-ntrs-cluster-turnoff-age","title":"The Gap in the Color-Magnitude Diagram of NGC 2420","publisher":"NASA Technical Reports Server","url":"https://ntrs.nasa.gov/citations/19950038771","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Abstract: main-sequence turnoff morphology and cluster-age model"},{"id":"nasa-stars","title":"Stars","publisher":"NASA Science","url":"https://science.nasa.gov/universe/stars/","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Life"}],"tags":["stellar-evolution","hr-diagram","cluster-age"],"generatedAt":"2026-07-28T08:00:00Z","validUntil":"2027-07-28T12:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"space-crater-density-resurfacing-002","category":"space","conceptID":"space.observation-instrumentation","conceptTitle":"Observation and instruments","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"Two adjacent terrains on the same airless moon are mapped at the same resolution and over equal areas. Terrain X has about one-quarter as many primary craters in the measured size range as Terrain Y. Which conclusion is best calibrated?","choices":[{"id":"a","text":"Terrain X is about one-quarter the age of Terrain Y, since crater counts grow linearly with time.","rationale":"Impact flux was much higher early in solar-system history, so crater density is not linear in age without a calibrated chronology."},{"id":"b","text":"Terrain X is older, since its craters have had more time to be erased by later impacts.","rationale":"Erosion by later impacts limits counts only near saturation; a fourfold deficit on adjacent terrain points to a younger surface."},{"id":"c","text":"Both terrains are probably the same age; X's harder crust simply resisted crater formation.","rationale":"Target strength modestly changes crater size, not a fourfold count difference, and nothing in the stem indicates different crust."},{"id":"d","text":"Terrain X was likely resurfaced more recently, if impact rates and crater preservation were similar.","rationale":"Correct. Fewer accumulated primary craters indicate a younger surface-exposure age, with the assumptions keeping the claim conditional."}],"correctChoiceID":"d","explanation":"On comparable terrain, greater primary-crater density usually indicates longer exposure since resurfacing. Turning that relative chronology into an absolute date requires assumptions about impactor flux, detection completeness, secondary craters, and calibration from sampled surfaces.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"nasa-tycho-crater-dating","title":"Tycho Crater on the Moon","publisher":"NASA Science","url":"https://science.nasa.gov/resource/tycho-crater-on-the-moon-labeled/","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Crater counting and sampled-surface calibration"},{"id":"nasa-galilean-crater-counting","title":"Europa, Ganymede, and Callisto: Surface Comparison at High Spatial Resolution","publisher":"NASA Science","url":"https://science.nasa.gov/science-research/europa-ganymede-and-callisto-surface-comparison-at-high-spatial-resolution/","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Surface age, crater counting, and impactor-flux assumptions"}],"tags":["planetary-geology","crater-counting","uncertainty"],"generatedAt":"2026-07-28T08:00:00Z","validUntil":"2027-07-28T12:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"space-exoplanet-mass-radius-density-002","category":"space","conceptID":"space.planetary-systems","conceptTitle":"Planetary systems","type":"multipleChoice","dimension":"application","difficulty":"advanced","prompt":"A planet produces repeatable transits across a well-characterized star, and the star shows a radial-velocity signal with the same period and an orbital phase consistent with the transits. What important property becomes estimable from the combined measurements that neither technique establishes as well alone?","choices":[{"id":"a","text":"Its mass, since transit depth shows how much material blocks the star.","rationale":"Transit depth measures the planet-to-star area ratio, which constrains radius, not mass."},{"id":"b","text":"Its atmospheric composition, from comparing the two signals' strengths.","rationale":"Composition requires spectroscopy, such as wavelength-dependent transit depths; broadband transits and radial velocity do not provide it."},{"id":"c","text":"Bulk density, from the transit radius and the radial-velocity mass.","rationale":"Correct. Transit depth constrains radius and radial velocity constrains mass; together they give mean density."},{"id":"d","text":"Its orbital eccentricity, which neither method can constrain on its own.","rationale":"Radial-velocity data alone constrain eccentricity, so this is not something only the combination provides."}],"correctChoiceID":"c","explanation":"Transit depth constrains the planet-to-star radius ratio, while radial velocity constrains the planet's dynamical influence and hence mass. With host-star and orbital parameters, the combination yields bulk density, which narrows—but does not uniquely determine—composition.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"nasa-eprv-final-report","title":"Extreme Precision Radial Velocity Working Group Final Report","publisher":"NASA Exoplanet Exploration Program","url":"https://assets.science.nasa.gov/content/dam/science/astro/programs/exep/nnexplore/files/EPRV_Final_Report.pdf","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Planet mass combined with radius constrains bulk density"},{"id":"nasa-exoplanet-methods","title":"How We Find and Characterize Exoplanets","publisher":"NASA Science","url":"https://science.nasa.gov/exoplanets/how-we-find-and-characterize/","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Radial Velocity and Transits"}],"tags":["exoplanets","transits","radial-velocity","density"],"generatedAt":"2026-07-28T08:00:00Z","validUntil":"2027-07-28T12:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"space-hubble-flow-local-motion-002","category":"space","conceptID":"space.cosmology-evidence","conceptTitle":"Cosmological evidence","type":"multipleChoice","dimension":"application","difficulty":"advanced","prompt":"A student estimates the Hubble constant from only five very nearby galaxies. The velocity-distance plot has large scatter, and one galaxy is blueshifted. Which revision most directly reduces the influence of local peculiar motions on the expansion estimate?","choices":[{"id":"a","text":"Drop the blueshifted galaxy as an outlier and refit the remaining four.","rationale":"Removing an inconvenient point biases the fit, and the remaining nearby galaxies are still dominated by peculiar motions."},{"id":"b","text":"Use many more distant galaxies across the sky, each with an independent distance.","rationale":"Correct. At larger distances expansion velocity dominates local motions, and a broad sample reduces any one galaxy's leverage."},{"id":"c","text":"Remeasure the five redshifts at higher spectral resolution to shrink the velocity errors.","rationale":"Peculiar velocities are real motions, not measurement error, so more precise redshifts do not remove them."},{"id":"d","text":"Force the fit through the origin, since zero distance must mean zero velocity.","rationale":"The constraint is reasonable but leaves the scatter from peculiar velocities untouched."}],"correctChoiceID":"b","explanation":"Nearby galaxies can have peculiar velocities comparable to their recession velocities, producing scatter or even blueshift. Independent distances for many galaxies at greater distances and across the sky better isolate the large-scale velocity-distance relation.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"nasa-hubble-constant-local-motion","title":"Hubble Space Telescope Measures Precise Distance to the Most Remote Galaxy Yet","publisher":"NASA Science","url":"https://science.nasa.gov/missions/hubble/hubble-space-telescope-measures-precise-distance-to-the-most-remote-galaxy-yet/","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Background: use galaxies far enough away that local gravitational motions are small"},{"id":"nasa-hubble-cosmological-redshift","title":"Hubble Cosmological Redshift","publisher":"NASA Science","url":"https://science.nasa.gov/mission/hubble/science/science-behind-the-discoveries/hubble-cosmological-redshift/","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Distance, recession, and cosmic expansion"}],"tags":["cosmology","hubble-law","peculiar-velocity","sampling"],"generatedAt":"2026-07-28T08:00:00Z","validUntil":"2027-07-28T12:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"space-outer-mission-trade-study-essay-002","category":"space","conceptID":"space.mission-tradeoffs","conceptTitle":"Mission tradeoffs","type":"essay","dimension":"synthesis","difficulty":"advanced","prompt":"A proposed outer-planet mission has two feasible architectures. A direct trajectory arrives in 6 years but leaves mass for only two science instruments and little propellant reserve. A gravity-assist trajectory arrives in 10 years, carries five instruments and a larger reserve, but adds two critical flybys and four years of radiation exposure and component aging. Write a trade study that recommends one architecture for a defined science priority. Explain how you would compare trajectory energy, payload, schedule, reliability, navigation, operations cost, and scientific return; identify the uncertainties that could reverse your recommendation.","choices":[],"explanation":"Strong work should connect orbital choices to mission-level consequences, make the value judgment explicit, and preserve uncertainty rather than treating one metric as automatically decisive.","rubric":[{"id":"objective","title":"Decision objective","description":"Defines a science priority and decision criteria before comparing architectures.","weight":0.2,"coachingQuestions":["Which science outcome is mission-critical, and which outcomes are desirable but expendable?"]},{"id":"trajectory","title":"Trajectory reasoning","description":"Explains how direct flight and gravity assists change energy, time, payload, geometry, and navigation demands.","weight":0.3,"coachingQuestions":["In which reference frame does the gravity assist change mission energy?","Which launch-window or flyby dependency creates the largest schedule risk?"]},{"id":"systems","title":"Whole-mission tradeoffs","description":"Connects travel time and payload to reliability, power, radiation, communications, operations, reserves, and science return.","weight":0.3,"coachingQuestions":["What capability is gained by the extra mass, and what new failure modes arrive with the longer cruise?"]},{"id":"uncertainty","title":"Uncertainty and reversibility","description":"States assumptions, compares sensitivity, and identifies evidence or thresholds that would change the recommendation.","weight":0.2,"coachingQuestions":["Which uncertain input has the greatest leverage on your choice?"]}],"coachingPrompts":["State the mission objective before optimizing the trajectory.","Distinguish propellant or payload benefits from schedule and reliability costs.","Give at least one condition under which the other architecture becomes preferable."],"modelOutline":["Mission objective and decision criteria","Trajectory and reference-frame analysis","Payload, reliability, schedule, and operations comparison","Sensitivity analysis","Conditional recommendation"],"sources":[{"id":"esa-gravity-assists","title":"What Are Gravity Assists?","publisher":"European Space Agency","url":"https://www.esa.int/Enabling_Support/Operations/What_are_gravity_assists","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Trading energy with the planets"},{"id":"nasa-basics-gravity-mechanics","title":"Chapter 3: Gravity & Mechanics","publisher":"NASA Science","url":"https://science.nasa.gov/learn/basics-of-space-flight/chapter3-4/","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Orbital energy and maneuver timing"}],"tags":["mission-design","gravity-assist","trade-study","uncertainty"],"generatedAt":"2026-07-28T08:00:00Z","validUntil":"2027-07-28T12:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"space-cluster-age-inference-essay-002","category":"space","conceptID":"space.stellar-evolution","conceptTitle":"Stellar evolution","type":"essay","dimension":"synthesis","difficulty":"advanced","prompt":"A survey team claims Cluster B is older than Cluster A because B's color-magnitude diagram has a fainter, redder main-sequence turnoff. The clusters lie at different distances; B is behind more dust, has a different measured metallicity, and both catalogs contain unresolved binaries and probable field stars. Build an analysis that could support or overturn the age claim. Explain the physical turnoff argument, the corrections and membership tests required, how stellar models enter, and how the final uncertainty should be reported.","choices":[],"explanation":"The goal is to reason from stellar physics through a noisy observational pipeline, not merely repeat that a lower turnoff means an older cluster.","rubric":[{"id":"physics","title":"Stellar-evolution mechanism","description":"Connects initial mass, fuel-consumption rate, main-sequence lifetime, and the movement of the turnoff with age.","weight":0.25,"coachingQuestions":["Why do the most massive coeval stars leave the main sequence first?"]},{"id":"observations","title":"Observational controls","description":"Addresses distance, extinction and reddening, photometric calibration, completeness, membership, and unresolved binaries.","weight":0.3,"coachingQuestions":["Which effect could make a turnoff look fainter or redder without making the cluster older?","How would you identify likely field-star contamination?"]},{"id":"models","title":"Model comparison","description":"Uses metallicity-appropriate isochrones and explains assumptions or degeneracies in fitting them.","weight":0.25,"coachingQuestions":["How could composition shift the inferred age at a fixed observed color and luminosity?"]},{"id":"claim","title":"Calibrated conclusion","description":"Reports an age comparison with statistical and systematic uncertainty and states what evidence would change it.","weight":0.2,"coachingQuestions":["Which uncertainty is shared by both clusters, and which differs between them?"]}],"coachingPrompts":["Separate what the turnoff physically encodes from what the detector measures.","Name at least two age-mimicking effects.","End with a bounded comparative claim, not a certainty."],"modelOutline":["Turnoff mechanism and initial hypothesis","Photometric and membership corrections","Metallicity-aware model fitting","Alternative explanations","Uncertainty-bounded comparison"],"sources":[{"id":"nasa-ntrs-cluster-turnoff-age","title":"The Gap in the Color-Magnitude Diagram of NGC 2420","publisher":"NASA Technical Reports Server","url":"https://ntrs.nasa.gov/citations/19950038771","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Abstract: main-sequence turnoff morphology and cluster-age model"},{"id":"nasa-stars","title":"Stars","publisher":"NASA Science","url":"https://science.nasa.gov/universe/stars/","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Mass and main-sequence lifetime"}],"tags":["stellar-evolution","color-magnitude-diagram","modeling","uncertainty"],"generatedAt":"2026-07-28T08:00:00Z","validUntil":"2027-07-28T12:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"space-crater-chronology-essay-002","category":"space","conceptID":"space.planetary-systems","conceptTitle":"Planetary systems","type":"essay","dimension":"synthesis","difficulty":"advanced","prompt":"Orbital images show an old-looking plain cut by a lava flow, a younger impact crater superposed on both units, and clusters of small craters downrange from that impact. The lava flow has fewer small craters than the plain. Construct the strongest relative chronology and a plan for estimating model ages. Distinguish superposition from crater statistics, address secondary craters and image completeness, explain the assumptions about impact flux and resurfacing, and state what a returned radiometric sample would—and would not—calibrate.","choices":[],"explanation":"Strong work should combine independent geological relations while keeping relative age, model age, rock age, and planetary age distinct.","rubric":[{"id":"chronology","title":"Relative chronology","description":"Uses cross-cutting and superposition relationships to order the plain, lava flow, primary impact, ejecta, and secondary craters.","weight":0.25,"coachingQuestions":["Which relationships can be read directly from the map without a cratering-rate model?"]},{"id":"counts","title":"Crater-population method","description":"Defines comparable mapped areas and size bins, separates primary and secondary craters, and addresses resolution and completeness.","weight":0.3,"coachingQuestions":["How could clustered secondary craters bias a small-crater age estimate?","What detection threshold should be held constant across units?"]},{"id":"assumptions","title":"Model assumptions","description":"Explains impact-flux history, preservation, erosion or burial, resurfacing, saturation, and transfer of lunar calibration to another world.","weight":0.25,"coachingQuestions":["Does a crater count date the rock's formation or the last major surface reset?"]},{"id":"sample","title":"Sample calibration and claim limits","description":"Shows how a well-contextualized radiometric sample anchors a crater chronology while preserving provenance and extrapolation uncertainty.","weight":0.2,"coachingQuestions":["What must be known about the sampled material before its date can calibrate the mapped unit?"]}],"coachingPrompts":["Build the event order before assigning any numerical age.","Separate primary craters from ejecta-produced secondaries.","State exactly which surface-reset event each model age would represent."],"modelOutline":["Map-based event sequence","Crater measurement and classification plan","Chronology assumptions and sensitivity","Sample provenance and radiometric anchor","Relative and model-age conclusions"],"sources":[{"id":"nasa-galilean-crater-counting","title":"Europa, Ganymede, and Callisto: Surface Comparison at High Spatial Resolution","publisher":"NASA Science","url":"https://science.nasa.gov/science-research/europa-ganymede-and-callisto-surface-comparison-at-high-spatial-resolution/","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Surface-age inference and impactor-flux assumptions"},{"id":"nasa-tycho-crater-dating","title":"Tycho Crater on the Moon","publisher":"NASA Science","url":"https://science.nasa.gov/resource/tycho-crater-on-the-moon-labeled/","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Sample dating and crater chronology calibration"},{"id":"usgs-mars-crater-dating","title":"Crater-based Dating of Geological Units on Mars","publisher":"U.S. Geological Survey","url":"https://www.usgs.gov/publications/crater-based-dating-geological-units-mars-methods-and-application-new-global","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Methods, resurfacing histories, and limitations"}],"tags":["planetary-geology","crater-chronology","stratigraphy","uncertainty"],"generatedAt":"2026-07-28T08:00:00Z","validUntil":"2027-07-28T12:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"space-supernova-acceleration-essay-002","category":"space","conceptID":"space.cosmology-evidence","conceptTitle":"Cosmological evidence","type":"essay","dimension":"synthesis","difficulty":"advanced","prompt":"A survey finds that standardized distant Type Ia supernovae are systematically dimmer than predicted by a cosmological model in which expansion only coasts or decelerates. Build an evidence chain from measured fluxes and spectra to the inference of cosmic acceleration. Explain calibration through the distance ladder, redshift and luminosity distance, and tests for dust, selection effects, supernova evolution, lensing, and instrument drift. Conclude with what the observations support about acceleration and what they do not by themselves establish about the physical nature of dark energy.","choices":[],"explanation":"The aim is to connect an unexpected observation to a model comparison while testing mundane alternatives and separating cosmic acceleration from claims about its unknown cause.","rubric":[{"id":"measurement","title":"Measurement chain","description":"Traces calibrated photometry, supernova standardization, spectra and redshift, distance-ladder anchors, and uncertainty into a luminosity-distance comparison.","weight":0.3,"coachingQuestions":["Which measured quantity gives redshift, and which gives distance after standardization?","Where can calibration uncertainty propagate between rungs of the ladder?"]},{"id":"model","title":"Cosmological comparison","description":"Explains why supernovae farther away than predicted at a given redshift challenge a coasting or decelerating history.","weight":0.25,"coachingQuestions":["What does 'dimmer than predicted' imply only after intrinsic luminosity is standardized?"]},{"id":"alternatives","title":"Alternative explanations","description":"Tests dust, population evolution, selection, gravitational lensing, contamination, and instrument or analysis drift using explicit cross-checks.","weight":0.3,"coachingQuestions":["Which alternative would change supernova color as well as brightness?","How could independent probes or instruments expose a shared systematic?"]},{"id":"limits","title":"Claim discipline","description":"Distinguishes evidence for accelerated expansion from a unique identification of dark energy's mechanism.","weight":0.15,"coachingQuestions":["Which competing physical explanations remain after acceleration is supported?"]}],"coachingPrompts":["Trace every rung from detector counts to the cosmological residual.","Give a discriminating test for at least three non-cosmological explanations.","Separate the observed expansion history from the name assigned to its unknown cause."],"modelOutline":["Photometric and spectroscopic measurements","Distance calibration and model prediction","Observed residual and acceleration inference","Systematic-error tests and independent checks","Supported conclusion and unresolved mechanism"],"sources":[{"id":"nasa-dark-energy","title":"What Is Dark Energy?","publisher":"NASA Science","url":"https://science.nasa.gov/dark-energy/","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Expansion Is Speeding Up, Supernovae Show"},{"id":"nasa-hubble-constant-tension","title":"Hubble Constant and Tension","publisher":"NASA Science","url":"https://science.nasa.gov/mission/hubble/science/science-behind-the-discoveries/hubble-constant-and-tension/","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Cosmic distance ladder using Cepheids and Type Ia supernovae"},{"id":"nasa-hubble-young-universe-dark-energy","title":"Hubble Finds Evidence for Dark Energy in the Young Universe","publisher":"NASA Science","url":"https://science.nasa.gov/missions/hubble/hubble-finds-evidence-for-dark-energy-in-the-young-universe/","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Type Ia supernova evidence and checks against supernova evolution"}],"tags":["cosmology","supernovae","distance-ladder","systematics","dark-energy"],"generatedAt":"2026-07-28T08:00:00Z","validUntil":"2027-07-28T12:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"philosophy-depth-argument-affirming-consequent-20260728-001","category":"philosophy","conceptID":"philosophy.argument-validity","conceptTitle":"Arguments and validity","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"A policy researcher argues: If a forecasting model has captured the true causal mechanism, it will remain accurate after a tax policy changes. The model remained accurate after one tax change. Therefore, it captured the true causal mechanism. Which response most directly evaluates the inference?","choices":[{"id":"a","text":"Invalid: a model could stay accurate for other reasons, such as offsetting effects.","rationale":"Correct. The argument affirms the consequent; a countermodel with true premises and a false conclusion shows invalidity."},{"id":"b","text":"Valid: it is modus ponens, since observing the consequent confirms the antecedent.","rationale":"Modus ponens moves from 'if P then Q' and P to Q; this argument moves from Q to P."},{"id":"c","text":"Invalid: it denies the antecedent, inferring a missing cause from a missing effect.","rationale":"The verdict is right but the diagnosis is wrong; the argument affirms the consequent rather than denying the antecedent."},{"id":"d","text":"Valid but weak: the form is fine, but one tax change is too small a test.","rationale":"The form itself is invalid; the number of tests bears on inductive support, not validity."}],"correctChoiceID":"a","explanation":"The argument affirms the consequent. Capturing the true mechanism may be sufficient for post-policy accuracy without being necessary for it. Constructing an alternative explanation that preserves both premises while denying the conclusion shows why the deduction fails, even if the evidence still gives the conclusion some inductive support.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"stanford-philosophy:logic-classical","title":"Classical Logic","publisher":"Stanford Encyclopedia of Philosophy","url":"https://plato.stanford.edu/entries/logic-classical/","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Model-theoretic validity and counterinterpretations"}],"tags":["formal-logic","countermodel","affirming-the-consequent","application"],"generatedAt":"2026-07-28T08:00:00Z","validUntil":"2031-07-28T12:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"philosophy-depth-argument-induction-quantifier-20260728-002","category":"philosophy","conceptID":"philosophy.argument-validity","conceptTitle":"Arguments and validity","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"A genuinely random survey of 2,000 residents finds that 86 percent support a transit proposal. An advocate concludes, 'Therefore every resident supports the proposal.' What is the best assessment?","choices":[{"id":"a","text":"Inductively strong, since a random sample of 2,000 supports a claim about every resident.","rationale":"The sample itself contains 14% dissent; it supports an estimate of a proportion, not unanimity."},{"id":"b","text":"Deductively valid but unsound, since the 86 percent premise might be inaccurate.","rationale":"The form is invalid: the premise could be exactly true while the universal conclusion is false."},{"id":"c","text":"Invalid only because the sample is too small; a census would make the inference valid.","rationale":"No sample size turns 86% support into 'every'; a census showing 86% would refute the conclusion."},{"id":"d","text":"Deductively invalid, though the survey supports a qualified claim of high support.","rationale":"Correct. The evidence justifies a probabilistic estimate of about 86% support, not the universal conclusion."}],"correctChoiceID":"d","explanation":"Deductive validity requires that no interpretation make the premises true and the conclusion false. A population with approximately 86 percent support is precisely such a case. The mistake is not that survey evidence is worthless; it is that an inductive population estimate has been inflated into a universal deductive conclusion.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"stanford-philosophy:logic-classical","title":"Classical Logic","publisher":"Stanford Encyclopedia of Philosophy","url":"https://plato.stanford.edu/entries/logic-classical/","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Truth-preserving validity, quantification, and the limits of formal consequence"}],"tags":["logic","induction","quantifiers","survey-reasoning"],"generatedAt":"2026-07-28T08:00:00Z","validUntil":"2031-07-28T12:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"philosophy-depth-epistemology-canceling-errors-20260728-003","category":"philosophy","conceptID":"philosophy.epistemology-justification","conceptTitle":"Knowledge and justification","type":"multipleChoice","dimension":"application","difficulty":"advanced","prompt":"A technician reports that a sample's pH is 6.8. The number is true, and the technician reasonably trusted the laboratory workflow. Unknown to anyone, however, the sensor read 0.4 too high while a spreadsheet bug subtracted 0.4, so the errors happened to cancel. Which diagnosis best captures the epistemic problem?","choices":[{"id":"a","text":"A Gettier-style case: a true, justified belief that is right only by luck.","rationale":"Correct. Compensating hidden faults break the appropriate connection between the method and the truth."},{"id":"b","text":"Knowledge, since the belief is true, justified, and formed by a normally reliable method.","rationale":"Truth plus justification is not sufficient when the truth depends on canceling errors; that is the Gettier point."},{"id":"c","text":"Unjustified belief, since a faulty sensor gave the technician no real justification.","rationale":"Justification depends on the technician's evidence, and trust in the workflow was reasonable; the defect is luck, not lack of justification."},{"id":"d","text":"False belief, since a reading produced by two errors cannot count as true.","rationale":"Truth concerns whether the pH is 6.8, and it is; the errors affect how the belief was reached, not its truth."}],"correctChoiceID":"a","explanation":"The case separates having a true, apparently justified belief from arriving at truth in the right way. If the hidden faults were known, they would undercut reliance on this result. The lesson is not that instruments cannot yield knowledge or that certainty is required, but that epistemic luck and defeaters matter.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"internet-philosophy:epistemo","title":"Epistemology","publisher":"Internet Encyclopedia of Philosophy","url":"https://iep.utm.edu/epistemo/","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Justification, Gettier cases, defeaters, and reliabilism"}],"tags":["epistemic-luck","gettier","defeaters","reliability"],"generatedAt":"2026-07-28T08:00:00Z","validUntil":"2031-07-28T12:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"philosophy-depth-epistemology-peer-disagreement-essay-20260728-004","category":"philosophy","conceptID":"philosophy.epistemology-justification","conceptTitle":"Knowledge and justification","type":"essay","dimension":"synthesis","difficulty":"advanced","prompt":"Two research teams with comparable expertise inspect the same evidence about a low-probability infrastructure failure. One recommends immediate closure; the other recommends continued operation with monitoring. Their disagreement partly reflects different model priors and different costs assigned to false alarms. Analyze what rational revision, if any, each team owes in light of the disagreement, and design an evidence and decision process that does not pretend the dispute is purely factual.","choices":[],"explanation":"A strong analysis should distinguish first-order evidence from higher-order evidence about another competent reasoner, examine whether the teams are genuine epistemic peers, and separate justified credence from the practical threshold for action under asymmetric stakes.","rubric":[{"id":"peerhood","title":"Peerhood and evidence structure","description":"Assesses relevant expertise, independence, information access, and possible shared error before treating the disagreement as peer disagreement.","weight":0.3,"coachingQuestions":["Which differences make the teams less than exact epistemic peers?","Are their models independent evidence or descendants of the same assumptions?"]},{"id":"revision","title":"Rational response to disagreement","description":"Compares conciliatory and steadfast responses and defends a degree of confidence revision rather than asserting that one response is automatic.","weight":0.25,"coachingQuestions":["What does learning that a peer disagrees add beyond the original evidence?"]},{"id":"decision","title":"Belief-action distinction","description":"Separates credence from a policy threshold and analyzes how asymmetric harms, reversibility, and precaution affect action.","weight":0.25,"coachingQuestions":["Could both teams rationally share a credence while recommending different actions?"]},{"id":"process","title":"Discriminating evidence plan","description":"Proposes preregistered tests, sensitivity analysis, independent review, and decision rules capable of exposing which assumptions drive the result.","weight":0.2,"coachingQuestions":["What observation would move the two models in different directions?"]}],"coachingPrompts":["Inventory first-order evidence, higher-order evidence, value assumptions, and action costs separately.","Explain rather than merely name conciliationism or steadfastness.","Make the proposed review process capable of changing the decision."],"modelOutline":["Nature of the disagreement","Peerhood and independence","Credence revision","Decision threshold","Evidence and governance process"],"sources":[{"id":"stanford-philosophy:disagreement","title":"Disagreement","publisher":"Stanford Encyclopedia of Philosophy","url":"https://plato.stanford.edu/entries/disagreement/","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Peer disagreement, higher-order evidence, and rational response"},{"id":"internet-philosophy:epistemo","title":"Epistemology","publisher":"Internet Encyclopedia of Philosophy","url":"https://iep.utm.edu/epistemo/","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Fallibilism, justification, and evidence"}],"tags":["peer-disagreement","higher-order-evidence","decision-theory","synthesis"],"generatedAt":"2026-07-28T08:00:00Z","validUntil":"2031-07-28T12:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"philosophy-depth-ethics-public-rule-tradeoff-20260728-005","category":"philosophy","conceptID":"philosophy.ethics-frameworks","conceptTitle":"Ethical frameworks","type":"multipleChoice","dimension":"application","difficulty":"advanced","prompt":"A hospital publicly promised to allocate equally scarce treatments by lottery among patients with the same clinical need. After people enroll, administrators discover that switching immediately to a life-years rule would probably yield a modest aggregate benefit. Which comparison is most philosophically careful?","choices":[{"id":"a","text":"Consequentialists must switch, since the life-years gain is the only consequence at stake.","rationale":"Consequentialist analysis can also count trust, future participation, and rule-level effects."},{"id":"b","text":"Deontologists must switch, since equal respect requires maximizing life-years for all.","rationale":"Maximizing an aggregate is a consequentialist structure; equal-respect reasoning often favors the lottery."},{"id":"c","text":"Consequentialists should count effects on trust too, and deontologists may weigh the promise itself.","rationale":"Correct. This represents both frameworks accurately: neither is settled by the immediate life-years tally alone."},{"id":"d","text":"Rule consequentialists must keep the lottery, since promise-keeping rules can never be broken.","rationale":"Rule consequentialism justifies rules by their outcomes and can include exceptions; it does not make rules exceptionless."}],"correctChoiceID":"c","explanation":"Ethical frameworks organize reasons rather than mechanically outputting answers from a single fact. A consequentialist must define and estimate the relevant outcomes, including institutional ones. A deontologist must analyze what was promised, to whom, and which duties or rights apply. The modest benefit matters, but it does not by itself complete either argument.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"stanford-philosophy:consequentialism","title":"Consequentialism","publisher":"Stanford Encyclopedia of Philosophy","url":"https://plato.stanford.edu/entries/consequentialism/","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Act and rule forms, value, and consequences"},{"id":"stanford-philosophy:deontology","title":"Deontological Ethics","publisher":"Stanford Encyclopedia of Philosophy","url":"https://plato.stanford.edu/entries/ethics-deontological/","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Duties, constraints, permissions, and agent-relative reasons"}],"tags":["consequentialism","deontology","institutional-trust","allocation"],"generatedAt":"2026-07-28T08:00:00Z","validUntil":"2031-07-28T12:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"philosophy-depth-ethics-water-allocation-essay-20260728-006","category":"philosophy","conceptID":"philosophy.ethics-frameworks","conceptTitle":"Ethical frameworks","type":"essay","dimension":"synthesis","difficulty":"advanced","prompt":"During a severe drought, a regional authority proposes an algorithm that minimizes projected total economic loss when assigning water restrictions. The model would protect a high-output industrial district while imposing deeper cuts on several low-income communities already facing health burdens. Evaluate and redesign the policy through consequentialist, deontological or rights-based, and virtue- or care-ethical reasoning. State which empirical uncertainties could reverse your recommendation.","choices":[],"explanation":"The response should use each framework to expose different morally relevant features, including aggregate welfare, distribution, rights, relationships, and institutional character. It should also show where moral conclusions depend on contestable forecasts rather than treating the algorithm as neutral.","rubric":[{"id":"frameworks","title":"Framework accuracy","description":"Applies at least three frameworks through their underlying standards of right action or practical judgment rather than using labels.","weight":0.3,"coachingQuestions":["What is morally foundational within each framework?"]},{"id":"distribution","title":"Distribution and standing","description":"Examines whose interests, rights, vulnerabilities, relationships, and voices the optimization captures or erases.","weight":0.25,"coachingQuestions":["Would the same total loss be morally equivalent under a different distribution?"]},{"id":"uncertainty","title":"Empirical and model uncertainty","description":"Identifies assumptions about health, economic substitution, measurement, time horizon, and feedback effects that bear on the ethical judgment.","weight":0.25,"coachingQuestions":["Which uncertain variable has the greatest moral leverage?"]},{"id":"redesign","title":"Defensible policy redesign","description":"Proposes a transparent allocation rule, safeguards, participation, review, and a reasoned response to the strongest objection.","weight":0.2,"coachingQuestions":["Which safeguard follows from your argument rather than from generic good practice?"]}],"coachingPrompts":["Separate the objective function from the moral justification for choosing it.","Test whether indirect and long-term effects alter the consequentialist analysis.","Give affected communities a substantive role, then explain why that role is morally warranted."],"modelOutline":["Decision and affected parties","Consequentialist analysis","Rights and duties","Virtue or care analysis","Uncertainty, redesign, and objection"],"sources":[{"id":"stanford-philosophy:consequentialism","title":"Consequentialism","publisher":"Stanford Encyclopedia of Philosophy","url":"https://plato.stanford.edu/entries/consequentialism/","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Consequentialist theories and specification of value"},{"id":"stanford-philosophy:deontology","title":"Deontological Ethics","publisher":"Stanford Encyclopedia of Philosophy","url":"https://plato.stanford.edu/entries/ethics-deontological/","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Constraints, duties, rights, and special obligations"},{"id":"stanford-philosophy:virtue-ethics","title":"Virtue Ethics","publisher":"Stanford Encyclopedia of Philosophy","url":"https://plato.stanford.edu/entries/ethics-virtue/","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Practical wisdom, character, and human flourishing"}],"tags":["applied-ethics","algorithmic-allocation","environmental-justice","uncertainty"],"generatedAt":"2026-07-28T08:00:00Z","validUntil":"2031-07-28T12:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"philosophy-depth-mind-branching-identity-20260728-007","category":"philosophy","conceptID":"philosophy.mind-personhood","conceptTitle":"Mind and personhood","type":"multipleChoice","dimension":"application","difficulty":"advanced","prompt":"A scanner destroys an explorer's body while creating two beings on different stations. Each has the explorer's memories, character, intentions, and continuous-seeming experience up to the scan. What does this branching case most directly challenge?","choices":[{"id":"a","text":"That bodily continuity is necessary for remaining the same person.","rationale":"The case is consistent with a bodily view, which says the explorer did not survive; it pressures psychological sufficiency instead."},{"id":"b","text":"That identity is transitive, since both continuers seem to be the explorer.","rationale":"The puzzle relies on transitivity: if both were the explorer, they would be each other. It challenges the criterion, not transitivity."},{"id":"c","text":"That a person's memories could ever be copied into another body.","rationale":"The thought experiment stipulates copying; it explores what would follow rather than challenging its possibility."},{"id":"d","text":"That psychological continuity alone suffices for being the same person.","rationale":"Correct. Both continuers satisfy the psychological relation equally, but identity is one-to-one, so simple sufficiency fails."}],"correctChoiceID":"d","explanation":"Numerical identity is one-to-one: one earlier person cannot literally be identical to two later people who are distinct from one another. A psychological-continuity theory therefore needs a non-branching condition, a different account of persistence, or the view that survival and moral concern need not require strict identity.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"stanford-philosophy:personal-identity","title":"Personal Identity","publisher":"Stanford Encyclopedia of Philosophy","url":"https://plato.stanford.edu/entries/identity-personal/","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Psychological continuity, non-branching, and fission"}],"tags":["personal-identity","psychological-continuity","fission","numerical-identity"],"generatedAt":"2026-07-28T08:00:00Z","validUntil":"2031-07-28T12:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"philosophy-depth-mind-other-minds-ai-20260728-008","category":"philosophy","conceptID":"philosophy.mind-personhood","conceptTitle":"Mind and personhood","type":"multipleChoice","dimension":"application","difficulty":"advanced","prompt":"An artificial agent flexibly reports pain, learns to avoid damaging conditions, integrates those states into long-term plans, and behaves coherently in novel situations. No direct measurement reveals whether it has subjective experience. Which position is epistemically strongest?","choices":[{"id":"a","text":"Its behavior settles nothing, since only biological brains could produce experience.","rationale":"Origin alone does not settle mentality without a defended theory linking substrate to experience."},{"id":"b","text":"Its functional organization proves it is conscious, since functionalism is the settled view.","rationale":"Functionalism is contested, and even on it behavioral evidence is defeasible rather than proof."},{"id":"c","text":"Its behavior is defeasible evidence of experience, weighted by a theory of mind and analogy.","rationale":"Correct. This treats the evidence as meaningful without confusing inference to the best explanation with certainty."},{"id":"d","text":"Its behavior would be decisive only if it passed a Turing test, which settles the question.","rationale":"A Turing test is a behavioral criterion; passing it does not settle whether there is subjective experience."}],"correctChoiceID":"c","explanation":"We do not directly inspect another subject's experience, even in familiar human cases. Instead, we reason from behavior, embodiment, functional organization, analogy, and explanatory fit. Artificial systems may complicate those analogies, so the warranted conclusion is graded and theory-dependent rather than deductive proof or dismissal by origin.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"stanford-philosophy:other-minds","title":"Other Minds","publisher":"Stanford Encyclopedia of Philosophy","url":"https://plato.stanford.edu/entries/other-minds/","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Analogical, criterial, and explanatory approaches to other minds"}],"tags":["other-minds","consciousness","artificial-agents","abduction"],"generatedAt":"2026-07-28T08:00:00Z","validUntil":"2031-07-28T12:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"philosophy-depth-political-de-facto-authority-20260728-009","category":"philosophy","conceptID":"philosophy.political-legitimacy","conceptTitle":"Political legitimacy","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"A regional council reliably enforces its rules and most residents comply, but a large permanent minority is excluded from elections and meaningful review. What follows from these facts alone?","choices":[{"id":"a","text":"It is legitimate, since majority compliance amounts to tacit consent to its rule.","rationale":"Compliance is not consent, and the excluded minority has had no say; tacit-consent arguments need far more than obedience."},{"id":"b","text":"It has de facto authority; whether it is legitimate is a further normative question.","rationale":"Correct. Effective control and compliance establish a descriptive fact without establishing a justified right to rule."},{"id":"c","text":"It is illegitimate, since excluding a minority from elections settles the question.","rationale":"Exclusion is a strong objection on many theories, but the verdict depends on a normative theory, not on these facts alone."},{"id":"d","text":"It lacks authority of any kind, since authority requires the consent of the governed.","rationale":"This conflates de facto authority with legitimate authority; the council plainly has the former."}],"correctChoiceID":"b","explanation":"Political philosophy distinguishes possessing power or being treated as an authority from having a morally justified right to issue and enforce directives. Exclusion may be a powerful objection to legitimacy, but evaluating it requires a theory of consent, fair procedure, public justification, rights, or authority's functions.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"stanford-philosophy:authority","title":"Authority","publisher":"Stanford Encyclopedia of Philosophy","url":"https://plato.stanford.edu/entries/authority/","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"De facto authority, normative authority, and theories of legitimacy"}],"tags":["political-authority","legitimacy","democracy","exclusion"],"generatedAt":"2026-07-28T08:00:00Z","validUntil":"2031-07-28T12:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"philosophy-depth-political-emergency-authority-essay-20260728-010","category":"philosophy","conceptID":"philosophy.political-legitimacy","conceptTitle":"Political legitimacy","type":"essay","dimension":"synthesis","difficulty":"advanced","prompt":"After repeated catastrophic wildfires, a state creates an expert agency that can impose mandatory evacuations, close roads, and enter private land without advance hearings when its risk model crosses a threshold. Orders expire after 72 hours unless renewed, but false alarms burden remote and low-income communities most. Develop an account of when this authority is legitimate and what citizens could owe its directives.","choices":[],"explanation":"A strong response should distinguish the justification of coercive power from a general duty to obey, then connect expertise and coordination to public justification, proportionality, equal standing, accountability, and the distribution of error costs.","rubric":[{"id":"authority","title":"Concept of legitimate authority","description":"Distinguishes effective power, a justified right to issue directives, and citizens' possible political obligations.","weight":0.3,"coachingQuestions":["Does a justified order always generate a duty to comply?"]},{"id":"justification","title":"Substantive and procedural justification","description":"Analyzes coordination, expertise, necessity, proportionality, contestability, transparency, and time limits.","weight":0.25,"coachingQuestions":["Which conditions justify acting before an individual hearing?"]},{"id":"equality","title":"Equality and distribution of burdens","description":"Addresses unequal false-alarm costs, accommodations, reciprocity, compensation, and political inclusion.","weight":0.25,"coachingQuestions":["What would equal civic standing require beyond applying one threshold to everyone?"]},{"id":"limits","title":"Limits and resistance","description":"Defines renewal, review, remedies, evidentiary audit, and conditions for justified challenge or noncompliance.","weight":0.2,"coachingQuestions":["When would an otherwise useful authority lose its claim to obedience?"]}],"coachingPrompts":["State whether your account is consent-based, instrumental, democratic, public-reason based, or hybrid.","Explain why expertise can support authority without making experts politically infallible.","Address both false negatives and false positives in the risk model."],"modelOutline":["Authority and obligation","Emergency justification","Procedural safeguards","Unequal burdens and reciprocity","Review, remedies, and limits"],"sources":[{"id":"stanford-philosophy:authority","title":"Authority","publisher":"Stanford Encyclopedia of Philosophy","url":"https://plato.stanford.edu/entries/authority/","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Legitimate political authority and grounds of a right to rule"},{"id":"stanford-philosophy:political-obligation","title":"Political Obligation","publisher":"Stanford Encyclopedia of Philosophy","url":"https://plato.stanford.edu/entries/political-obligation/","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Theories and limits of duties to obey"},{"id":"stanford-philosophy:distributive-justice","title":"Distributive Justice","publisher":"Stanford Encyclopedia of Philosophy","url":"https://plato.stanford.edu/entries/justice-distributive/","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Competing principles for distributing benefits and burdens"}],"tags":["emergency-powers","political-obligation","public-justification","distributive-justice"],"generatedAt":"2026-07-28T08:00:00Z","validUntil":"2031-07-28T12:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"philosophy-depth-metaphysics-overdetermination-20260728-011","category":"philosophy","conceptID":"philosophy.metaphysics-causation","conceptTitle":"Metaphysics and causation","type":"multipleChoice","dimension":"application","difficulty":"advanced","prompt":"Two independent safety systems detect the same fault and simultaneously send shutdown signals. Either signal alone would have shut the reactor down at the same moment. A simple test says an event is a cause only if, without it, the outcome would not occur. What does the case show?","choices":[{"id":"a","text":"Neither signal is a cause, since removing either one leaves the shutdown unchanged.","rationale":"That is the simple test's verdict, and it is precisely the counterintuitive result the case exposes."},{"id":"b","text":"Overdetermination: each signal seems a cause, yet the outcome depends on neither alone.","rationale":"Correct. The case separates causal contribution from counterfactual necessity, exposing a problem for the simple but-for test."},{"id":"c","text":"Preemption: one signal is the real cause, and the other is a backup that never acted.","rationale":"Preemption is asymmetric, with one process cut short; here both signals complete simultaneously, which is symmetric overdetermination."},{"id":"d","text":"Each signal is half a cause, so responsibility for the shutdown splits equally.","rationale":"Each signal alone was sufficient; the case does not show causation divided into fractional shares."}],"correctChoiceID":"b","explanation":"When two events are independently sufficient, removing either one while holding the other fixed leaves the outcome unchanged. A naive counterfactual dependence test therefore excludes both. Refined theories alter the comparison, model causal structure, or distinguish dependence from causation rather than accepting that neither signal contributed.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"stanford-philosophy:counterfactual-causation","title":"Counterfactual Theories of Causation","publisher":"Stanford Encyclopedia of Philosophy","url":"https://plato.stanford.edu/entries/causation-counterfactual/","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Counterfactual dependence, overdetermination, and refinements"}],"tags":["causation","counterfactuals","overdetermination","but-for-test"],"generatedAt":"2026-07-28T08:00:00Z","validUntil":"2031-07-28T12:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"philosophy-depth-metaphysics-restored-object-essay-20260728-012","category":"philosophy","conceptID":"philosophy.metaphysics-causation","conceptTitle":"Metaphysics and causation","type":"essay","dimension":"synthesis","difficulty":"advanced","prompt":"Over fifty years, a museum replaces every decayed component of a historically important research vessel while preserving its location, function, name, records, and repair continuity. A second group later reassembles the original components into a vessel-shaped object. Both groups claim to possess the original vessel. Analyze the rival identity claims and recommend how the museum should describe each object without assuming that institutional labeling settles the metaphysics.","choices":[],"explanation":"The case asks for criteria of numerical identity over time, not a vote on which object looks more authentic. A strong response will distinguish material, spatiotemporal, functional, causal-historical, and conventional considerations and explain whether artifact identity may differ from identity for organisms or persons.","rubric":[{"id":"distinctions","title":"Identity distinctions","description":"Clearly separates numerical identity, qualitative similarity, persistence, composition, and authenticity.","weight":0.3,"coachingQuestions":["Could both objects be equally authentic in some respect without being numerically identical?"]},{"id":"theories","title":"Competing persistence criteria","description":"Develops at least two serious accounts using material, spatiotemporal, functional, causal-historical, or conventional continuity.","weight":0.25,"coachingQuestions":["Which changes can your favored criterion tolerate, and why?"]},{"id":"pressure","title":"Counterexamples and domain sensitivity","description":"Tests each account against gradual replacement, disassembly, branching claims, and differences between artifacts and living beings.","weight":0.25,"coachingQuestions":["Does your theory yield an implausible result when replacement happens all at once?"]},{"id":"recommendation","title":"Qualified museum recommendation","description":"Proposes transparent labels that separate historical facts, material provenance, and contested identity rather than hiding uncertainty.","weight":0.2,"coachingQuestions":["Which facts can the museum state without resolving the philosophical dispute?"]}],"coachingPrompts":["Begin by specifying the kind of identity at issue.","Do not treat continuity of name or institutional recognition as automatically decisive.","Use the recombination case to stress-test the criterion you prefer."],"modelOutline":["Numerical versus qualitative identity","Continuity-based account","Material-based account","Objections and artifact conventions","Transparent museum description"],"sources":[{"id":"stanford-philosophy:identity-time","title":"Identity Over Time","publisher":"Stanford Encyclopedia of Philosophy","url":"https://plato.stanford.edu/entries/identity-time/","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Persistence, composition, temporary identity, and criteria across time"},{"id":"internet-philosophy:material-composition","title":"Material Composition","publisher":"Internet Encyclopedia of Philosophy","url":"https://iep.utm.edu/mat-comp/","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Composition, constitution, ordinary objects, and identity puzzles"}],"tags":["identity-over-time","artifacts","composition","ship-of-theseus"],"generatedAt":"2026-07-28T08:00:00Z","validUntil":"2031-07-28T12:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"design-depth-research-survivorship-bias-20260728-001","category":"design","conceptID":"design.human-centered-research","conceptTitle":"Human-centered research","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"A transit team wants to understand why riders abandon route planning. Its analytics contain only completed searches, and its interview panel consists of frequent app users recruited from an in-app banner. Which research plan best addresses the blind spot?","choices":[{"id":"a","text":"Add an in-app exit survey that appears when a search is abandoned, capturing reasons in the moment.","rationale":"It reaches only people still inside the app who respond, missing nonusers and those who never start a search."},{"id":"b","text":"Weight the frequent-user interviews by ride frequency so occasional riders count proportionally.","rationale":"Reweighting cannot recover perspectives that are absent from the sample."},{"id":"c","text":"Recruit abandoners and nonusers through outside channels; pair contextual observation with drop-off data.","rationale":"Correct. This counters survivorship and channel bias while connecting observed behavior to quantitative patterns."},{"id":"d","text":"Analyze completed searches in depth, since their paths reveal where others probably got stuck.","rationale":"Completed searches are conditioned on success; they omit the failures under investigation."}],"correctChoiceID":"c","explanation":"Human-centered research depends on matching participants and methods to the decision. Here, both existing datasets condition on success: completed searches and people engaged enough to answer an in-app invitation. Purposeful recruitment beyond the product, contextual observation, and triangulation make hidden failure modes observable without treating any single method as complete.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"digital-gov-hcd:user-needs","title":"Capturing User Needs to Inform Your Design","publisher":"Digital.gov, U.S. General Services Administration","url":"https://digital.gov/guides/research-collaboration/user-needs","accessedAt":"2026-07-28T08:00:00Z","usage":"publicDomain","evidenceLocator":"User profiles, journeys, service blueprints, systems maps, and mental models"}],"tags":["user-research","sampling","survivorship-bias","triangulation"],"generatedAt":"2026-07-28T08:00:00Z","validUntil":"2028-07-26T08:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"design-depth-research-hospital-discharge-essay-20260728-002","category":"design","conceptID":"design.human-centered-research","conceptTitle":"Human-centered research","type":"essay","dimension":"synthesis","difficulty":"advanced","prompt":"A hospital asks a design team to improve discharge for patients managing several medications, transportation constraints, and follow-up appointments. Readmission data identify when failure occurs but not why. Design a research program that produces actionable evidence while respecting illness, dependency on staff, language differences, privacy, and the possibility that the hospital's own workflow causes harm.","choices":[],"explanation":"The response should align recruitment, context, ethics, and methods with the high-stakes service decision. It should not reduce patients to personas or assume that interviews alone reveal backstage operations and power relationships.","rubric":[{"id":"frame","title":"Research framing and decisions","description":"Defines the decisions the research must inform, maps affected actors, and distinguishes known performance patterns from unanswered causal questions.","weight":0.3,"coachingQuestions":["What could the team change if this research succeeds?","Which institutional assumption is currently treated as a patient failure?"]},{"id":"ethics","title":"Power, consent, and privacy","description":"Addresses voluntary participation, accessible consent, care dependence, sensitive data, compensation, withdrawal, and escalation of observed safety risks.","weight":0.25,"coachingQuestions":["How will patients know that refusing research cannot affect their care?"]},{"id":"methods","title":"Sampling and method fit","description":"Combines inclusive recruitment with contextual observation, interviews, artifact or journey analysis, staff research, and operational data for complementary purposes.","weight":0.25,"coachingQuestions":["Which participants are most likely to be missing from hospital data?"]},{"id":"synthesis","title":"Synthesis and validation","description":"Explains traceable analysis, disconfirming cases, participant review, prototype follow-up, and boundaries on what the evidence can support.","weight":0.2,"coachingQuestions":["How will you prevent a vivid story from outweighing the broader evidence?"]}],"coachingPrompts":["Write research questions before selecting methods.","Map patient-facing touchpoints and backstage handoffs together.","Specify what evidence would challenge the team's initial problem frame."],"modelOutline":["Decision and existing evidence","Participants and ethical protections","Mixed-method fieldwork","Service and power analysis","Synthesis, validation, and limits"],"sources":[{"id":"digital-gov-hcd:research-protection","title":"Recruiting, Compensating, and Protecting Users","publisher":"Digital.gov, U.S. General Services Administration","url":"https://digital.gov/guides/research-collaboration/basics","accessedAt":"2026-07-28T08:00:00Z","usage":"publicDomain","evidenceLocator":"Safe and ethical recruitment, compensation, and privacy"},{"id":"digital-gov-hcd:hcd-series","title":"Human-Centered Design Guide Series","publisher":"Digital.gov, U.S. General Services Administration","url":"https://digital.gov/guides/hcd","accessedAt":"2026-07-28T08:00:00Z","usage":"publicDomain","evidenceLocator":"Discovery, design, delivery, and measurement"}],"tags":["research-ethics","health-service-design","mixed-methods","power"],"generatedAt":"2026-07-28T08:00:00Z","validUntil":"2028-07-26T08:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"design-depth-accessibility-color-status-20260728-003","category":"design","conceptID":"design.accessibility-inclusion","conceptTitle":"Accessibility and inclusion","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"A medical portal marks abnormal results with a red dot and normal results with a green dot. Designers increase the contrast of both dots against the background. What additional change most directly addresses the remaining accessibility problem?","choices":[{"id":"a","text":"Swap red and green for a colorblind-safe pair of hues, such as orange and blue.","rationale":"This helps some color-vision deficiencies, but hue is still the only carrier of meaning."},{"id":"b","text":"Add a text label or distinct icon per status, and expose it programmatically.","rationale":"Correct. Redundant visual and semantic cues stop color from being the sole means of conveying status."},{"id":"c","text":"Add hidden alt text to each dot so screen readers announce its status.","rationale":"This helps screen-reader users, but sighted users who cannot distinguish the hues still lack a cue."},{"id":"d","text":"Raise the dots' contrast further, to the 4.5:1 ratio required for body text.","rationale":"Contrast and use of color are separate requirements; higher contrast does not convey which status is which."}],"correctChoiceID":"b","explanation":"Contrast and non-color communication solve different barriers. A design can meet a color-contrast threshold yet remain inaccessible when status is encoded only by hue. Visible text or a genuinely distinguishable symbol, paired with programmatic information for assistive technology, makes the relationship perceivable in multiple ways.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"w3c-wcag-22:wcag","title":"Web Content Accessibility Guidelines 2.2","publisher":"World Wide Web Consortium","url":"https://www.w3.org/TR/WCAG22/","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Success Criteria 1.4.1 Use of Color, 1.4.3 Contrast, and 4.1.3 Status Messages"}],"tags":["wcag","use-of-color","status-messages","inclusive-design"],"generatedAt":"2026-07-28T08:00:00Z","validUntil":"2028-07-26T08:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"design-depth-accessibility-emergency-alerts-essay-20260728-004","category":"design","conceptID":"design.accessibility-inclusion","conceptTitle":"Accessibility and inclusion","type":"essay","dimension":"synthesis","difficulty":"advanced","prompt":"Design an emergency-alert service for wildfire smoke that must work across web, SMS, voice, and public displays. Residents include people with low vision, hearing loss, cognitive disabilities, limited literacy, limited English, old devices, and intermittent connectivity. Define the content system, interaction priorities, channel fallbacks, testing plan, and governance needed to avoid treating WCAG conformance as proof that the whole service is inclusive.","choices":[],"explanation":"A strong response should connect standards-based requirements to real tasks, multiple disabilities, language and connectivity constraints, cognitive load, redundant channels, and testing with affected people. Conformance is a floor for web content, not a complete service outcome.","rubric":[{"id":"needs","title":"Inclusive needs analysis","description":"Maps disability, language, literacy, device, connectivity, location, and stress conditions to specific failure modes.","weight":0.3,"coachingQuestions":["Which users disappear if the team tests only the web interface?"]},{"id":"content","title":"Accessible content and interaction","description":"Prioritizes actionable information, clear language, meaningful sequence, redundant cues, operability, error recovery, and cognitive accessibility.","weight":0.25,"coachingQuestions":["What must a person understand and do in the first ten seconds?"]},{"id":"channels","title":"Channel and failure design","description":"Coordinates visual, audio, text, low-bandwidth, offline, and human-support channels with consistent updates and degraded-mode behavior.","weight":0.25,"coachingQuestions":["What happens when the preferred channel is delayed or unavailable?"]},{"id":"evaluation","title":"Evaluation and accountability","description":"Combines standards review, assistive-technology testing, realistic drills with diverse residents, outcome metrics, incident review, and ownership.","weight":0.2,"coachingQuestions":["Which metric demonstrates comprehension rather than message delivery?"]}],"coachingPrompts":["Translate each inclusion claim into a testable task or failure condition.","Distinguish normative WCAG criteria from supplemental cognitive-accessibility guidance.","Design for conflicting updates and uncertain conditions, not only a single perfect alert."],"modelOutline":["People, tasks, and constraints","Content hierarchy and language","Accessible interaction","Channels and degraded modes","Testing, metrics, and governance"],"sources":[{"id":"w3c-wcag-22:wcag","title":"Web Content Accessibility Guidelines 2.2","publisher":"World Wide Web Consortium","url":"https://www.w3.org/TR/WCAG22/","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Perceivable, operable, understandable, and robust requirements"},{"id":"w3c-wcag-22:coga","title":"Making Content Usable for People with Cognitive and Learning Disabilities","publisher":"World Wide Web Consortium","url":"https://www.w3.org/TR/coga-usable/","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Supplemental patterns, user inclusion, clear purpose, error avoidance, and support"}],"tags":["emergency-design","cognitive-accessibility","multi-channel","resilience"],"generatedAt":"2026-07-28T08:00:00Z","validUntil":"2028-07-26T08:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"design-depth-hierarchy-alert-triage-20260728-005","category":"design","conceptID":"design.information-hierarchy","conceptTitle":"Information hierarchy","type":"multipleChoice","dimension":"application","difficulty":"advanced","prompt":"An operations dashboard lists 140 alerts in reverse chronological order. A critical unresolved safety alert is pushed below dozens of recent low-risk notices, while color and tiny badges carry most of the priority information. Which redesign best aligns hierarchy with the operator's task?","choices":[{"id":"a","text":"Group unresolved critical alerts first with text severity labels, and reveal detail on demand.","rationale":"Correct. This structures content around triage while keeping evidence accessible and meaning available without color."},{"id":"b","text":"Sort strictly by severity, hiding low-risk notices unless the operator opens a filter.","rationale":"Severity alone ignores whether an alert is resolved, and hiding notices removes context the operator may need."},{"id":"c","text":"Keep recency order but pin a red banner counting the critical alerts at the top.","rationale":"A count does not make the alerts themselves actionable, and color still carries the meaning."},{"id":"d","text":"Use larger, brighter severity badges so critical items stand out within the time-ordered list.","rationale":"Stronger decoration does not repair the mismatch between list order and decision priority."}],"correctChoiceID":"a","explanation":"Information hierarchy should encode the order in which people need to perceive, decide, and act. Critical unresolved conditions deserve structural priority, not merely stronger decoration. Semantic grouping, explicit labels, meaningful sequence, and progressive disclosure allow urgency and evidence to coexist without flattening all information.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"w3c-wcag-22:wcag","title":"Web Content Accessibility Guidelines 2.2","publisher":"World Wide Web Consortium","url":"https://www.w3.org/TR/WCAG22/","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Info and Relationships, Meaningful Sequence, Use of Color, Headings and Labels"},{"id":"w3c-wcag-22:headings","title":"Headings","publisher":"W3C Web Accessibility Initiative","url":"https://www.w3.org/WAI/tutorials/page-structure/headings/","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Communicating page organization and supporting navigation"}],"tags":["information-architecture","triage","semantic-structure","progressive-disclosure"],"generatedAt":"2026-07-28T08:00:00Z","validUntil":"2028-07-26T08:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"design-depth-hierarchy-semantic-headings-20260728-006","category":"design","conceptID":"design.information-hierarchy","conceptTitle":"Information hierarchy","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"A long benefits page looks organized because section titles are large bold div elements. In a screen reader's heading list, however, the page appears flat and users must traverse every paragraph. What is the best correction?","choices":[{"id":"a","text":"Add a heading role to each div, without levels, so they appear in the heading list.","rationale":"Without aria-level every such heading defaults to the same level, so the hierarchy stays flat; native elements are preferred."},{"id":"b","text":"Mark each bold title as an h1, since every section deserves top-level prominence.","rationale":"Making every title top-level destroys the nesting that lets users understand section relationships."},{"id":"c","text":"Choose heading levels by font size, so the largest titles become h1 and smaller ones h3.","rationale":"Heading rank should express nesting, not typography; size-based levels can skip ranks or misstate structure."},{"id":"d","text":"Use real h1–h6 elements nested by section, then style them with CSS.","rationale":"Correct. This aligns the visible hierarchy with programmatic structure without choosing levels for appearance."}],"correctChoiceID":"d","explanation":"Typography alone does not create semantic structure. Proper headings communicate section relationships, enable efficient assistive-technology navigation, and can still be styled to match the visual system. Heading rank should express nesting, not font size or a desire for a particular default appearance.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"w3c-wcag-22:headings","title":"Headings","publisher":"W3C Web Accessibility Initiative","url":"https://www.w3.org/WAI/tutorials/page-structure/headings/","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Heading rank, nesting, organization, and assistive-technology navigation"},{"id":"w3c-wcag-22:wcag","title":"Web Content Accessibility Guidelines 2.2","publisher":"World Wide Web Consortium","url":"https://www.w3.org/TR/WCAG22/","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Success Criteria 1.3.1 Info and Relationships and 2.4.6 Headings and Labels"}],"tags":["semantic-html","headings","screen-readers","information-structure"],"generatedAt":"2026-07-28T08:00:00Z","validUntil":"2028-07-26T08:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"design-depth-prototype-fidelity-question-fit-20260728-007","category":"design","conceptID":"design.prototyping-evaluation","conceptTitle":"Prototyping and evaluation","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"Before engineering begins, a team needs to learn whether people understand the sequence for contesting an automated eligibility decision. Stakeholders instead request a pixel-perfect coded prototype. What is the strongest design response?","choices":[{"id":"a","text":"Build the pixel-perfect prototype, since realistic visuals produce more valid user feedback.","rationale":"Polish can distract participants and stakeholders; the question concerns comprehension of the sequence, not visuals."},{"id":"b","text":"Survey people on how they would prefer to contest an automated eligibility decision.","rationale":"Stated preferences do not show whether people can understand and complete the actual sequence."},{"id":"c","text":"Run an expert heuristic review first, since it can stand in for early user testing.","rationale":"Expert review can find domain and usability errors but cannot show how intended users interpret the flow."},{"id":"d","text":"Build a low-fidelity but task-complete prototype that tests sequence, wording, and recovery.","rationale":"Correct. Fidelity should match the learning question while minimizing cost and false commitment."}],"correctChoiceID":"d","explanation":"A prototype is an instrument for answering a question. The team needs enough interactivity and realistic content to observe the appeal journey, but visual and technical fidelity beyond that can slow iteration and cause stakeholders to mistake an exploratory artifact for a nearly finished product.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"digital-gov-hcd:design-operations","title":"Design Operations Guide","publisher":"Digital.gov, U.S. General Services Administration","url":"https://digital.gov/guides/hcd/design-operations","accessedAt":"2026-07-28T08:00:00Z","usage":"publicDomain","evidenceLocator":"Building, making, testing, feedback, and iterative design operations"},{"id":"digital-gov-hcd:design-concepts","title":"Design Concepts Guide","publisher":"Digital.gov, U.S. General Services Administration","url":"https://digital.gov/guides/hcd/design-concepts","accessedAt":"2026-07-28T08:00:00Z","usage":"publicDomain","evidenceLocator":"Iteration, participant collaboration, and designing products, services, or systems"}],"tags":["prototyping","fidelity","learning-question","iteration"],"generatedAt":"2026-07-28T08:00:00Z","validUntil":"2028-07-26T08:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"design-depth-evaluation-facilitator-bias-20260728-008","category":"design","conceptID":"design.prototyping-evaluation","conceptTitle":"Prototyping and evaluation","type":"multipleChoice","dimension":"application","difficulty":"advanced","prompt":"Five employees from the product team complete a new checkout flow in a moderated test. The facilitator explains unfamiliar controls whenever participants hesitate, and all five eventually finish. Which conclusion and next step are most defensible?","choices":[{"id":"a","text":"Promising evidence; repeat with 30 more employees under the same protocol to confirm it.","rationale":"A larger sample of insiders with the same coaching repeats both biases."},{"id":"b","text":"Weak evidence; retest with representative users, scripted prompts, and unaided success measured.","rationale":"Correct. This addresses participant mismatch, facilitator intervention, and measurement."},{"id":"c","text":"Good evidence of learnability, since every participant finished once controls were explained.","rationale":"Completion after hints shows the flow can be learned with help, not that intended users can complete it unaided."},{"id":"d","text":"Weak evidence; run a live A/B test instead, since lab studies cannot measure usability.","rationale":"The verdict is right, but moderated studies can measure usability with controlled prompting, and A/B tests do not explain why people fail."}],"correctChoiceID":"b","explanation":"The observed outcome combines product behavior with participant expertise and facilitator assistance. A valid evaluation defines the intended population, realistic tasks, moderator rules, and measures before interpreting success. Qualitative observations and performance measures should reveal where and why unaided interaction fails.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"digital-gov-hcd:testing","title":"Testing and Assessment","publisher":"Digital.gov, U.S. General Services Administration","url":"https://digital.gov/guides/research-collaboration/testing","accessedAt":"2026-07-28T08:00:00Z","usage":"publicDomain","evidenceLocator":"Usability testing, success metrics, qualitative analysis, and testing through development"},{"id":"international-journal-design:1515","title":"Understanding Design for Dynamic and Diverse Use Situations","publisher":"International Journal of Design","url":"https://www.ijdesign.org/index.php/IJDesign/article/view/1515/628","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Formative evaluation, end-user testing, and diversity of use situations"}],"tags":["usability-testing","facilitator-bias","sampling","measurement"],"generatedAt":"2026-07-28T08:00:00Z","validUntil":"2028-07-26T08:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"design-depth-systems-clinic-capacity-20260728-009","category":"design","conceptID":"design.systems-service-design","conceptTitle":"Systems and services","type":"multipleChoice","dimension":"application","difficulty":"advanced","prompt":"A clinic improves its appointment portal, and booking-task usability rises sharply. Patients still wait months because referral rules create duplicate review, clinic schedules do not share capacity, and cancellations are not returned to a common queue. What should the team do next?","choices":[{"id":"a","text":"Map the whole service, then prototype changes to referral rules, shared capacity, and cancellations.","rationale":"Correct. The delay is produced by backstage rules and capacity flows, so the next prototypes should target those relationships."},{"id":"b","text":"Add real-time wait estimates and reminders to the portal so patients feel less frustrated.","rationale":"This improves the frontstage experience but leaves duplicate review, siloed schedules, and lost cancellations unchanged."},{"id":"c","text":"Run another usability study, since high task scores may hide portal flaws causing the delays.","rationale":"The causes of delay are already identified as backstage rules and capacity, not portal usability."},{"id":"d","text":"Hand the problem to clinic operations, since backstage scheduling lies outside the scope of design.","rationale":"Service design includes the processes and relationships that produce the user outcome."}],"correctChoiceID":"a","explanation":"A usable touchpoint can sit on top of a failing service. Journey maps, service blueprints, systems maps, queue evidence, and actor analysis make the dependencies visible. The next prototype may be a referral rule, shared capacity process, cancellation recovery mechanism, or information handoff rather than another screen.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"digital-gov-hcd:user-needs","title":"Capturing User Needs to Inform Your Design","publisher":"Digital.gov, U.S. General Services Administration","url":"https://digital.gov/guides/research-collaboration/user-needs","accessedAt":"2026-07-28T08:00:00Z","usage":"publicDomain","evidenceLocator":"Journey maps, service blueprints, and systems maps"},{"id":"international-journal-design:4563","title":"Service Design in the Context of Complexity","publisher":"International Journal of Design","url":"https://www.ijdesign.org/index.php/IJDesign/article/view/4563","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Plural actors, tensions, relationships, and complex service systems"}],"tags":["service-blueprint","systems-thinking","queues","frontstage-backstage"],"generatedAt":"2026-07-28T08:00:00Z","validUntil":"2028-07-26T08:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"design-depth-systems-transit-disruption-essay-20260728-010","category":"design","conceptID":"design.systems-service-design","conceptTitle":"Systems and services","type":"essay","dimension":"synthesis","difficulty":"advanced","prompt":"A transit agency's disruption service sends accurate app notifications, yet riders still become stranded because station signs lag, drivers receive different instructions, replacement buses lack accessible boarding, call-center scripts conflict, and no team owns cross-channel recovery. Redesign the service as a system. Include actor relationships, frontstage and backstage operations, degraded modes, incentives, governance, and measures that reveal whether people actually complete their journeys.","choices":[],"explanation":"The response should treat disruption as a coordinated service outcome rather than a notification feature. It should trace how information, authority, vehicles, staff, accessibility, and recovery interact over time and under failure.","rubric":[{"id":"map","title":"System and actor map","description":"Identifies riders, staff, contractors, channels, infrastructure, data, decisions, dependencies, incentives, and power relationships.","weight":0.3,"coachingQuestions":["Which actor can block recovery without appearing in the app journey?"]},{"id":"operations","title":"Coordinated service design","description":"Connects frontstage touchpoints to backstage decision rights, information synchronization, accessible replacement capacity, and staff procedures.","weight":0.25,"coachingQuestions":["Who establishes one operational source of truth, and who may override it?"]},{"id":"failure","title":"Failure and recovery","description":"Designs for connectivity loss, stale data, capacity shortfall, conflicting updates, assistive needs, escalation, and compensation.","weight":0.25,"coachingQuestions":["How does the service fail safely when accurate prediction is impossible?"]},{"id":"measurement","title":"Governance and outcome measures","description":"Defines ownership, incident learning, equity measures, journey completion, recovery time, and checks against locally optimized metrics.","weight":0.2,"coachingQuestions":["Which dashboard could look green while riders remain stranded?"]}],"coachingPrompts":["Map the service before selecting a screen-level intervention.","Include riders who cannot use the app or board the replacement vehicle.","Show how post-incident evidence changes operations, contracts, and design."],"modelOutline":["Actors, journey, and dependencies","Frontstage and backstage coordination","Accessible degraded modes","Recovery and accountability","Outcome and equity measures"],"sources":[{"id":"digital-gov-hcd:hcd-series","title":"Human-Centered Design Guide Series","publisher":"Digital.gov, U.S. General Services Administration","url":"https://digital.gov/guides/hcd","accessedAt":"2026-07-28T08:00:00Z","usage":"publicDomain","evidenceLocator":"Designing and measuring products, services, and systems; frontstage and backstage"},{"id":"international-journal-design:4563","title":"Service Design in the Context of Complexity","publisher":"International Journal of Design","url":"https://www.ijdesign.org/index.php/IJDesign/article/view/4563","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Complexity, plurality, systemic tensions, and service relationships"}],"tags":["service-design","transit","resilience","governance"],"generatedAt":"2026-07-28T08:00:00Z","validUntil":"2028-07-26T08:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"design-depth-ethics-asymmetric-consent-20260728-011","category":"design","conceptID":"design.ethics-sustainability","conceptTitle":"Ethics and sustainability","type":"multipleChoice","dimension":"application","difficulty":"advanced","prompt":"A health app's consent screen offers a large one-tap 'Accept all' button. Refusing requires opening four panels, interpreting double negatives, and disabling twelve preselected purposes individually. Which redesign most directly addresses the ethical design problem?","choices":[{"id":"a","text":"Keep 'Accept all' but add a 'Manage settings' link that opens the same twelve toggles.","rationale":"Refusal still takes far more effort than acceptance, so the asymmetry remains."},{"id":"b","text":"Add a plain-language summary above the button so users understand what they accept.","rationale":"Clearer explanation helps, but the asymmetric effort and preselected purposes still steer the choice."},{"id":"c","text":"Give accept and reject equal prominence and effort, with no purposes preselected.","rationale":"Correct. Symmetric, unbiased choices preserve informed agency instead of steering disclosure."},{"id":"d","text":"Preselect only the purposes most users accept, so fewer toggles need to be changed.","rationale":"Any preselection still makes disclosure the default and burdens refusal."}],"correctChoiceID":"c","explanation":"The problem is not simply that the interface contains many settings. The asymmetry, defaults, language, and friction are arranged to steer disclosure while preserving a nominal path to refuse. Ethical redesign makes material choices intelligible and comparably actionable, then limits collection rather than treating interface consent as permission for unlimited processing.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"ftc-dark-patterns:report","title":"Bringing Dark Patterns to Light","publisher":"U.S. Federal Trade Commission","url":"https://www.ftc.gov/reports/bringing-dark-patterns-light","accessedAt":"2026-07-28T08:00:00Z","usage":"publicDomain","evidenceLocator":"Interface practices that obscure, subvert, or impair consumer choice"},{"id":"international-journal-design:4547","title":"Engagements and Articulations of Ethics in Design Practice","publisher":"International Journal of Design","url":"https://www.ijdesign.org/index.php/IJDesign/article/view/4547/990","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Ethical responsibility, impact, and design decisions across interfaces and systems"}],"tags":["dark-patterns","consent","privacy","choice-architecture"],"generatedAt":"2026-07-28T08:00:00Z","validUntil":"2028-07-26T08:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"},{"id":"design-depth-ethics-connected-appliance-lifecycle-essay-20260728-012","category":"design","conceptID":"design.ethics-sustainability","conceptTitle":"Ethics and sustainability","type":"essay","dimension":"synthesis","difficulty":"advanced","prompt":"A company plans a connected home-heating controller with a five-year retail price target. Lower-cost construction would seal the battery, pair replacement parts to the cloud account, collect room-occupancy data by default, and depend on subscription servers for core scheduling. Develop an ethical and sustainable design proposal spanning materials, energy, repair, labor and supply-chain visibility, privacy, security updates, service shutdown, accessibility, and the risk that efficiency feedback causes rebound behavior.","choices":[],"explanation":"The response should evaluate the full product-service lifecycle rather than optimizing purchase price or operational energy alone. It should make boundaries, tradeoffs, uncertainties, affected parties, and enforceable commitments explicit.","rubric":[{"id":"lifecycle","title":"Lifecycle and system boundary","description":"Examines extraction, manufacture, transport, use, maintenance, repair, software support, reuse, and end-of-life while identifying possible burden shifting.","weight":0.3,"coachingQuestions":["Which impact falls outside the company's proposed accounting boundary?"]},{"id":"people","title":"Rights, labor, and inclusion","description":"Addresses workers, suppliers, renters, disabled users, low-connectivity households, repairers, privacy, ownership, and unequal exposure to failure.","weight":0.25,"coachingQuestions":["Who loses essential heating control if the account, network, or company disappears?"]},{"id":"architecture","title":"Product-service architecture","description":"Proposes repairable hardware, local core function, minimal data, update commitments, interoperability, secure retirement, take-back, and recoverable failure modes.","weight":0.25,"coachingQuestions":["Which commitments must be technical, contractual, and operational rather than aspirational?"]},{"id":"evidence","title":"Evidence and accountability","description":"Defines comparative baselines, lifecycle measures, privacy-risk review, rebound monitoring, supplier evidence, uncertainty, and public reporting.","weight":0.2,"coachingQuestions":["What result would show that the efficiency feature increased total consumption?"]}],"coachingPrompts":["Compare at least two architectures using the same declared lifecycle boundary.","Treat cloud dependence and end-of-support as design materials, not future business details.","Identify where a lower upfront price externalizes cost or risk to someone else."],"modelOutline":["Stakeholders and lifecycle boundary","Environmental and labor tradeoffs","Privacy, ownership, and accessibility","Repairable and resilient architecture","Evidence, rebound, and enforceable governance"],"sources":[{"id":"epa-sustainable-materials:basics","title":"Sustainable Materials Management Basics","publisher":"U.S. Environmental Protection Agency","url":"https://www.epa.gov/smm/sustainable-materials-management-basics","accessedAt":"2026-07-28T08:00:00Z","usage":"publicDomain","evidenceLocator":"Whole-life-cycle materials perspective, durability, disassembly, reuse, and supply relationships"},{"id":"nist-privacy-framework:framework","title":"NIST Privacy Framework","publisher":"National Institute of Standards and Technology","url":"https://www.nist.gov/privacy-framework","accessedAt":"2026-07-28T08:00:00Z","usage":"publicDomain","evidenceLocator":"Privacy risk identification and management across products, services, and data processing"},{"id":"international-journal-design:2153","title":"Evaluating Feedback Interventions: A Design for Sustainable Behaviour Case Study","publisher":"International Journal of Design","url":"https://www.ijdesign.org/index.php/IJDesign/article/view/2153/741","accessedAt":"2026-07-28T08:00:00Z","usage":"linkOnly","evidenceLocator":"Ethics, user control, unintended effects, rebound, and stakeholder participation"}],"tags":["lifecycle-design","right-to-repair","privacy","rebound-effects"],"generatedAt":"2026-07-28T08:00:00Z","validUntil":"2027-07-27T08:00:00Z","generatorVersion":"curated-focus-v2","reviewerVersion":"editorial-focus-v2","reviewStatus":"verified"}]},{"id":"hiculture-learning-expansion-v3","schemaVersion":1,"version":"3.0.0","generatedAt":"2026-10-21T06:00:00Z","questions":[{"id":"law-v3-circuit-precedent-001","category":"law","conceptID":"law.courts-appeals","conceptTitle":"How courts and appeals work","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"A federal district court in Louisiana must decide whether a federal statute covers a certain kind of contractor. The Fifth Circuit, which hears appeals from Louisiana's federal courts, decided the identical question last year; this year the Ninth Circuit reached the opposite answer, and the Supreme Court has not ruled. How should the district judge treat the two appellate decisions?","choices":[{"id":"a","text":"Follow the Ninth Circuit, because the more recent appellate ruling on a federal question supersedes the earlier one.","rationale":"Recency does not matter across circuits. A Ninth Circuit decision does not bind courts in the Fifth Circuit at all."},{"id":"b","text":"Choose freely between them, because neither one is binding until the Supreme Court resolves the circuit split.","rationale":"A circuit split does not free lower courts. The Fifth Circuit's holding still binds the district courts within that circuit."},{"id":"c","text":"Follow the Fifth Circuit as binding precedent, while treating the Ninth Circuit's reasoning as persuasive only.","rationale":"Correct. An appellate holding binds lower courts within its jurisdiction; another circuit's decision is persuasive authority only."},{"id":"d","text":"Reconcile them by narrowing each to its facts, because every federal appellate ruling binds all district courts.","rationale":"Only Supreme Court decisions bind every federal court. A circuit's holdings bind only the courts within that circuit."}],"correctChoiceID":"c","explanation":"A holding of an appellate court is binding precedent for the lower courts within its jurisdiction. Louisiana's federal courts sit in the Fifth Circuit, so the district judge must follow the Fifth Circuit's answer. The Ninth Circuit's contrary decision is persuasive authority: the judge may discuss its reasoning but is not bound by it, regardless of which ruling is more recent. Only the Supreme Court can resolve the split with a ruling that binds every federal court.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"lii-binding-precedent","title":"binding precedent","publisher":"Legal Information Institute, Cornell Law School","url":"https://www.law.cornell.edu/wex/binding_precedent","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"A holding of an appellate court is binding on all lower courts within its jurisdiction; only the Supreme Court's decisions bind all U.S. courts"},{"id":"lii-persuasive-authority","title":"persuasive authority","publisher":"Legal Information Institute, Cornell Law School","url":"https://www.law.cornell.edu/wex/persuasive_authority","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"A decision by a court of one jurisdiction is persuasive, not binding, authority for courts of another jurisdiction"}],"tags":["precedent","stare-decisis","circuit-split","court-hierarchy"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"law-v3-standard-of-review-002","category":"law","conceptID":"law.courts-appeals","conceptTitle":"How courts and appeals work","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"After a bench trial in a federal civil case, the judge found that a delivery driver ran a red light, crediting one eyewitness over another. On appeal, the driver argues only that the judge believed the wrong witness. What standard will the court of appeals most likely apply to that finding?","choices":[{"id":"a","text":"De novo review, deciding the question afresh because an appellate panel owes no deference to a trial judge's conclusions.","rationale":"De novo review applies to questions of law. Findings of fact from a bench trial receive deferential review."},{"id":"b","text":"A new evidentiary hearing, in which the appellate panel hears both eyewitnesses itself before deciding who was credible.","rationale":"Courts of appeals decide cases on the trial record and the parties' briefs; they do not retake witness testimony."},{"id":"c","text":"Preponderance review, asking whether the appellate panel itself finds it more likely than not that the driver ran the light.","rationale":"Preponderance of the evidence is the plaintiff's burden at trial, not the standard an appellate court uses to review findings."},{"id":"d","text":"Clear-error review, giving due regard to the trial judge's opportunity to observe the witnesses and judge their credibility.","rationale":"Correct. Federal Rule of Civil Procedure 52(a)(6) sets this deferential standard for a judge's findings of fact."}],"correctChoiceID":"d","explanation":"Federal Rule of Civil Procedure 52(a)(6) provides that a trial judge's findings of fact must not be set aside unless clearly erroneous, and that the reviewing court must give due regard to the trial court's opportunity to judge witnesses' credibility. A dispute over which eyewitness to believe is a classic finding of fact, so the driver faces a deferential standard. De novo review is reserved for legal questions, and the appellate panel works from the record and briefs rather than hearing witnesses. Preponderance of the evidence is the trial burden of proof, not an appellate standard of review.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"lii-frcp-52","title":"Rule 52. Findings and Conclusions by the Court; Judgment on Partial Findings","publisher":"Legal Information Institute, Cornell Law School","url":"https://www.law.cornell.edu/rules/frcp/rule_52","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Rule 52(a)(6): findings of fact must not be set aside unless clearly erroneous, with due regard to the trial court's opportunity to judge witnesses' credibility"},{"id":"uscourts-appeals","title":"Appeals","publisher":"Administrative Office of the U.S. Courts","url":"https://www.uscourts.gov/about-federal-courts/types-cases/appeals","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Appeals are decided by three-judge panels on written briefs arguing that the trial court made an error"}],"tags":["standard-of-review","clear-error","appeals","fact-finding"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"law-v3-acquittal-civil-suit-003","category":"law","conceptID":"law.procedure-remedies","conceptTitle":"Civil and criminal procedure","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"A jury acquits Dana of criminal assault. The alleged victim then sues Dana in state court for damages arising from the same incident. Dana moves to dismiss, arguing that the acquittal ends the matter. How should the court most likely rule?","choices":[{"id":"a","text":"Deny the motion, because a civil damages suit is not a prosecution and needs proof only by a preponderance of the evidence.","rationale":"Correct. Double jeopardy concerns repeated criminal prosecution and punishment, and the civil burden of proof is lower."},{"id":"b","text":"Grant the motion, because the Double Jeopardy Clause bars any second proceeding of any kind arising from the same incident.","rationale":"The clause protects against being prosecuted twice for the same crime; it generally covers criminal punishment, not a private suit for damages."},{"id":"c","text":"Deny the motion, but require the victim to prove the assault beyond a reasonable doubt because a jury already acquitted Dana.","rationale":"The civil plaintiff's burden stays preponderance of the evidence; the earlier acquittal does not raise it."},{"id":"d","text":"Grant the motion, because an acquittal is a binding finding that the assault did not occur, which the civil court must accept.","rationale":"An acquittal establishes only that guilt was not proved beyond a reasonable doubt; it is not a finding that the conduct never happened."}],"correctChoiceID":"a","explanation":"The Double Jeopardy Clause protects against being prosecuted twice for the same crime and generally reaches criminal punishment, not private civil claims for damages. An acquittal means only that the government failed to prove guilt beyond a reasonable doubt. In the civil case the plaintiff must prove the claim by a preponderance of the evidence, a lower burden, so the same evidence can support civil liability even after a criminal acquittal. The acquittal therefore neither bars the suit nor raises the plaintiff's burden.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"lii-double-jeopardy","title":"double jeopardy","publisher":"Legal Information Institute, Cornell Law School","url":"https://www.law.cornell.edu/wex/double_jeopardy","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"The Double Jeopardy Clause protects against being prosecuted twice for the same crime and generally covers criminal punishment, not all sanctions"},{"id":"uscourts-civil-cases","title":"Civil Cases","publisher":"Administrative Office of the U.S. Courts","url":"https://www.uscourts.gov/about-federal-courts/types-cases/civil-cases","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"In a civil case the plaintiff must prove the claim by a preponderance of the evidence (more likely than not)"},{"id":"uscourts-criminal-cases","title":"Criminal Cases","publisher":"Administrative Office of the U.S. Courts","url":"https://www.uscourts.gov/about-federal-courts/types-cases/criminal-cases","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"In a criminal case the government must prove guilt beyond a reasonable doubt"}],"tags":["double-jeopardy","burden-of-proof","civil-vs-criminal","acquittal"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"law-v3-plea-colloquy-004","category":"law","conceptID":"law.procedure-remedies","conceptTitle":"Civil and criminal procedure","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"In federal court, Marcus agrees to plead guilty in exchange for the prosecutor's promise to recommend an 18-month sentence. Under Federal Rule of Criminal Procedure 11, what must the judge do before accepting the plea?","choices":[{"id":"a","text":"Confirm that the victim consents to the deal, since a victim's objection automatically blocks a negotiated guilty plea.","rationale":"Rule 11 contains no victim-consent requirement. Federal law gives crime victims a right to be heard, not a veto over pleas."},{"id":"b","text":"Question Marcus personally in open court to confirm the plea is voluntary and that he understands the rights he waives.","rationale":"Correct. Rule 11(b) requires a personal colloquy covering the rights waived and voluntariness, plus a factual basis for the plea."},{"id":"c","text":"Hold a short bench trial, since the judge must find Marcus guilty beyond a reasonable doubt before accepting any plea.","rationale":"A guilty plea replaces trial. The court must find a factual basis for the plea, not conduct a trial."},{"id":"d","text":"Promise Marcus the recommended 18 months, since a prosecutor's sentencing recommendation in a plea deal binds the judge.","rationale":"Under Rule 11(c)(1)(B), a recommendation does not bind the court, and the defendant must be told so."}],"correctChoiceID":"b","explanation":"Federal Rule of Criminal Procedure 11(b) requires the court, before accepting a guilty plea, to address the defendant personally in open court, inform him of the rights he gives up (including trial by jury and confrontation of witnesses), and determine that the plea is voluntary and not the product of force, threats, or promises outside the plea agreement. Before entering judgment the court must also find a factual basis for the plea. A prosecutor's agreement to recommend a sentence is a Rule 11(c)(1)(B) agreement, which does not bind the judge. Victims may be heard, but their consent is not a condition of the plea.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"lii-frcrmp-11","title":"Rule 11. Pleas","publisher":"Legal Information Institute, Cornell Law School","url":"https://www.law.cornell.edu/rules/frcrmp/rule_11","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Rule 11(b): court must address the defendant personally in open court, advise of rights waived, ensure the plea is voluntary, and find a factual basis; 11(c)(1)(B) recommendations do not bind the court"}],"tags":["plea-bargaining","guilty-plea","rule-11","criminal-procedure"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"law-v3-state-action-005","category":"law","conceptID":"law.rights-government-power","conceptTitle":"Constitutional rights in practice","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"Priya works for a privately owned software company. After she posts sharp criticism of the CEO on social media, the company fires her. She sues, claiming the firing violated her First Amendment right to free speech. What is the strongest response to her constitutional claim?","choices":[{"id":"a","text":"It succeeds, because the First Amendment protects speech on public issues from retaliation by any employer in the country.","rationale":"The First Amendment restrains government. It does not, by itself, regulate a purely private employer's personnel decisions."},{"id":"b","text":"It fails, because speech posted on social media platforms is categorically excluded from First Amendment protection.","rationale":"Online speech can be constitutionally protected against government action; the claim fails for a different reason."},{"id":"c","text":"It fails, because the First Amendment restrains government actors, and a purely private employer is not a state actor.","rationale":"Correct. Constitutional free-speech claims require state action; a private company acting on its own is not the government."},{"id":"d","text":"It succeeds, because Pickering balancing protects employees who speak as citizens on matters of public concern.","rationale":"Pickering v. Board of Education governs speech by public employees, whose employer is the government."}],"correctChoiceID":"c","explanation":"Most constitutional rights, including freedom of speech, limit what government may do; this is the state action requirement. Because the First Amendment restrains government, a purely private employer cannot violate it, so Priya's constitutional claim fails. The Pickering balancing test protects some speech by government employees, which is why it is a tempting but inapplicable answer here. Any protection Priya has would have to come from a statute or contract (for example, labor-law protection for some concerted activity), not from the First Amendment itself.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"lii-state-action","title":"state action requirement","publisher":"Legal Information Institute, Cornell Law School","url":"https://www.law.cornell.edu/wex/state_action_requirement","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Because the First Amendment restrains government, it is impossible for a purely private party to violate it"}],"tags":["first-amendment","state-action","free-speech","employment"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"law-v3-miranda-custody-006","category":"law","conceptID":"law.rights-government-power","conceptTitle":"Constitutional rights in practice","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"Two detectives visit Omar at home, tell him he is not under arrest and may end the conversation at any time, and ask about a burglary. Privately they regard him as their main suspect. They give no Miranda warnings; Omar answers, and they leave without arresting him. Can he suppress his statements because no warnings were given?","choices":[{"id":"a","text":"No, because Miranda covers only custodial interrogation, and a reasonable person here would have felt free to end it.","rationale":"Correct. Custody is judged objectively, and the facts here describe a voluntary, non-custodial interview."},{"id":"b","text":"Yes, because Miranda warnings become mandatory once the police treat a person as their prime suspect, even before an arrest.","rationale":"The Supreme Court has rejected a 'focus of suspicion' test; an officer's undisclosed suspicion does not create custody."},{"id":"c","text":"Yes, because police must warn anyone they question about a crime, whether or not the person is in custody at the time.","rationale":"Miranda's warning requirement is triggered by custodial interrogation, not by every police question."},{"id":"d","text":"No, because Miranda protections begin only after formal charges are filed and the defendant first appears in court.","rationale":"That describes when the Sixth Amendment right to counsel attaches. Miranda can apply before any charges, if there is custody."}],"correctChoiceID":"a","explanation":"Miranda v. Arizona requires warnings before custodial interrogation. Custody depends on the objective circumstances: whether a reasonable person would have felt free to end the questioning and leave. In Stansbury v. California (1994), the Court held that an officer's unarticulated belief that the person is a suspect does not make questioning custodial. Omar was told he was not under arrest and could stop, so no warnings were required. The choice that ties Miranda to the filing of formal charges confuses it with the Sixth Amendment right to counsel, which attaches when formal proceedings begin.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"lii-miranda-warning","title":"Miranda warning","publisher":"Legal Information Institute, Cornell Law School","url":"https://www.law.cornell.edu/wex/miranda_warning","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Miranda v. Arizona (1966) requires warnings before custodial interrogation"},{"id":"lii-stansbury-v-california","title":"Stansbury v. California, 511 U.S. 318 (1994)","publisher":"Legal Information Institute, Cornell Law School","url":"https://www.law.cornell.edu/supremecourt/text/511/318","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Custody turns on objective circumstances; an officer's unarticulated suspicion that the person is a suspect does not create custody"}],"tags":["miranda","custodial-interrogation","fifth-amendment","police-questioning"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"law-v3-loper-bright-review-007","category":"law","conceptID":"law.administrative-agencies","conceptTitle":"Agencies and statutory interpretation","type":"multipleChoice","dimension":"application","difficulty":"advanced","prompt":"In 2026, a business challenges a federal agency rule in court. The rule depends on the agency's reading of an ambiguous phrase in the statute the agency administers. Under Loper Bright Enterprises v. Raimondo (2024), how should the reviewing court treat the agency's interpretation?","choices":[{"id":"a","text":"Uphold it if it is a reasonable construction, because courts defer to permissible agency readings whenever a statute is ambiguous.","rationale":"That was the Chevron framework, which Loper Bright overruled in 2024."},{"id":"b","text":"Set it aside automatically, because after 2024 agencies lack any authority to interpret the statutes they administer.","rationale":"Agencies still interpret statutes; courts simply decide the legal question independently and may find the agency's view persuasive."},{"id":"c","text":"Remand the question to Congress, because only the legislature may resolve an ambiguity left open in the enacted text.","rationale":"Courts decide questions of statutory meaning in the cases before them; they do not send interpretive questions to Congress."},{"id":"d","text":"Decide the statute's best meaning independently, while weighing the agency's view according to its power to persuade.","rationale":"Correct. Courts exercise independent judgment and may seek aid from agency interpretations, as under Skidmore v. Swift & Co."}],"correctChoiceID":"d","explanation":"Loper Bright held that the Administrative Procedure Act requires courts to exercise independent judgment in deciding whether an agency acted within its statutory authority, and that courts may not defer to an agency's interpretation simply because a statute is ambiguous; Chevron was overruled. Courts may still give careful attention to an agency's views for their power to persuade (the Skidmore approach). Where the best reading of a statute is that Congress delegated discretionary authority, the court respects that delegation while policing its boundaries. Agencies keep interpreting their statutes; what changed is the deference courts give those interpretations.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"scotus-loper-bright","title":"Loper Bright Enterprises v. Raimondo, 603 U.S. ___ (2024)","publisher":"Supreme Court of the United States","url":"https://www.supremecourt.gov/opinions/23pdf/22-451_7m58.pdf","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Syllabus and opinion: courts must exercise independent judgment, may seek aid from agency views (Skidmore), must respect valid delegations, and prior Chevron-based holdings retain statutory stare decisis"},{"id":"lii-5-usc-706","title":"5 U.S. Code § 706 - Scope of review","publisher":"Legal Information Institute, Cornell Law School","url":"https://www.law.cornell.edu/uscode/text/5/706","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"The reviewing court shall decide all relevant questions of law and interpret constitutional and statutory provisions"}],"tags":["loper-bright","chevron","administrative-law","statutory-interpretation"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"law-v3-after-chevron-essay-008","category":"law","conceptID":"law.administrative-agencies","conceptTitle":"Agencies and statutory interpretation","type":"essay","dimension":"synthesis","difficulty":"advanced","prompt":"A city official asks whether Loper Bright Enterprises v. Raimondo (2024) means that every federal regulation built on Chevron deference is now invalid. Write an explanation for an educated non-lawyer that covers what the Court held, how reviewing courts now treat agency interpretations, what happens to earlier cases decided under Chevron, and what still constrains both judges and agencies. Distinguish clearly between what the opinion says and predictions about future litigation.","choices":[],"explanation":"Coaching should push the learner to state the holding precisely, separate the change in interpretive method from the status of existing rules and precedents, and avoid both extremes: that nothing changed, or that every Chevron-era regulation is automatically void.","rubric":[{"id":"holding","title":"Accurate holding","description":"States that courts must exercise independent judgment under the APA and may not defer merely because a statute is ambiguous, and that Chevron was overruled.","weight":0.3,"coachingQuestions":["What exactly did the Court say courts may not do anymore?","Which statute did the Court rely on for its reasoning?"]},{"id":"method","title":"How review works now","description":"Explains independent judgment, respectful consideration of agency views for their power to persuade, and respect for genuine statutory delegations of discretion.","weight":0.25,"coachingQuestions":["When may a court still give weight to an agency's reading?","How should a court handle a statute that expressly delegates authority to the agency?"]},{"id":"prior-cases","title":"Earlier cases and existing rules","description":"Explains that holdings of prior Chevron-based cases remain subject to statutory stare decisis and that reliance on Chevron alone is not a special justification to overrule them; distinguishes court holdings from untested regulations.","weight":0.25,"coachingQuestions":["Did the Court invalidate its own earlier Chevron-based holdings?","How is a rule upheld in a past case different from a rule never litigated?"]},{"id":"limits-uncertainty","title":"Limits and uncertainty","description":"Separates the opinion's text from predictions, notes that challenges still require proper parties and timely claims, and identifies open questions lower courts will work out.","weight":0.2,"coachingQuestions":["What parts of your answer are predictions rather than holdings?","Which questions about agency discretion remain contested?"]}],"coachingPrompts":["Quote or paraphrase the holding before drawing implications.","Separate the interpretive method from the fate of specific rules.","Explain statutory stare decisis in plain language.","Flag any statement that is a forecast rather than a holding."],"modelOutline":["State the Chevron framework and what Loper Bright replaced it with","Describe independent judgment, persuasive weight for agency views, and respect for delegations","Explain why prior Chevron-based holdings generally stand under statutory stare decisis","Distinguish regulations already upheld from those open to new challenges","Identify constraints on courts and agencies and the questions still unsettled"],"sources":[{"id":"scotus-loper-bright","title":"Loper Bright Enterprises v. Raimondo, 603 U.S. ___ (2024)","publisher":"Supreme Court of the United States","url":"https://www.supremecourt.gov/opinions/23pdf/22-451_7m58.pdf","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Syllabus and opinion: courts must exercise independent judgment, may seek aid from agency views (Skidmore), must respect valid delegations, and prior Chevron-based holdings retain statutory stare decisis"},{"id":"lii-5-usc-706","title":"5 U.S. Code § 706 - Scope of review","publisher":"Legal Information Institute, Cornell Law School","url":"https://www.law.cornell.edu/uscode/text/5/706","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"The reviewing court shall decide all relevant questions of law and interpret constitutional and statutory provisions"}],"tags":["loper-bright","administrative-law","precedent","essay"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"history-v3-columbian-mortality-001","category":"history","conceptID":"history.causation-change","conceptTitle":"Causation and historical change","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"Within about a century after 1492, many Indigenous populations in the Americas fell catastrophically. A student attributes the collapse mainly to battlefield deaths during conquest. Which revision best fits the evidence historians emphasize?","choices":[{"id":"a","text":"Famine caused by Europeans replacing Indigenous staple crops with newly introduced maize and potatoes was the main driver.","rationale":"Maize and potatoes are American crops that moved from the Americas to the rest of the world, not the reverse."},{"id":"b","text":"Old World diseases such as smallpox and measles, new to the Americas, drove most deaths, compounded by war and enslavement.","rationale":"Correct. Native Americans had no prior exposure to these Eurasian and African diseases, and conquest made the toll worse."},{"id":"c","text":"Battlefield deaths were decisive, since epidemic disease reached the Americas only after the population collapse had ended.","rationale":"Epidemics such as smallpox struck early in the contact period and were central to the collapse, not a later afterthought."},{"id":"d","text":"A sudden climate shift that ruined harvests across both continents explains most deaths, with contact itself a minor factor.","rationale":"Historians tie the collapse to contact, above all to introduced diseases, rather than to an independent climate shock."}],"correctChoiceID":"b","explanation":"Before 1492, Native Americans had no exposure to the acute infectious diseases long established in Eurasia and Africa, including smallpox, measles, and influenza. When these diseases arrived, they caused catastrophic mortality among populations without acquired immunity. War, enslavement, forced labor, and displacement compounded the toll, but battlefield deaths alone cannot explain the scale of the collapse. Maize and potatoes traveled from the Americas outward, so they cannot have been European impositions.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"britannica-columbian-exchange","title":"Columbian Exchange","publisher":"Encyclopaedia Britannica","url":"https://www.britannica.com/event/Columbian-exchange","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Before 1492 Native Americans hosted none of Eurasia's acute infectious diseases such as smallpox and measles; their introduction caused catastrophic mortality"}],"tags":["columbian-exchange","epidemics","causation","colonialism"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"history-v3-print-reformation-002","category":"history","conceptID":"history.causation-change","conceptTitle":"Causation and historical change","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"Jan Hus attacked the sale of indulgences in Prague roughly a century before Martin Luther did, yet Luther's challenge spread far faster and wider after 1517. Which factor best explains the difference in reach?","choices":[{"id":"a","text":"Luther was the first reformer to question indulgences, so his ideas faced no rival claims on public attention.","rationale":"Hus had already opposed the sale of indulgences in the early 1400s, so Luther was not first."},{"id":"b","text":"Church authorities endorsed Luther's early theses, giving them official channels of distribution that Hus lacked.","rationale":"The papacy condemned Luther and excommunicated him in 1521; his ideas did not spread through official Church channels."},{"id":"c","text":"Printers could cheaply reprint Luther's short German pamphlets for buyers far beyond the circle of clerics.","rationale":"Correct. Luther's brief vernacular works were reprinted repeatedly across Germany's printing centers."},{"id":"d","text":"Near-universal literacy in the German lands let handwritten copies alone carry his arguments to most adults.","rationale":"Literacy was limited in the early sixteenth century; print, often read aloud, mattered precisely because copying by hand was slow."}],"correctChoiceID":"c","explanation":"Hus opposed the sale of indulgences and was condemned at the Council of Constance and burned in 1415, before printing spread in Europe. Luther wrote in the age of the press: his short, accessible German works, such as the Sermon on Indulgences and Grace (reprinted 14 times in its first year), reached buyers who had never bought books before. Print did not by itself cause the Reformation, but it explains much of the speed and reach of Luther's message. The Church condemned rather than endorsed Luther.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"britannica-jan-hus","title":"Jan Hus","publisher":"Encyclopaedia Britannica","url":"https://www.britannica.com/biography/Jan-Hus","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Hus opposed the sale of indulgences in the early fifteenth century and was condemned at the Council of Constance"},{"id":"harvard-divinity-luther-media","title":"Luther's Media Phenomenon","publisher":"Harvard Divinity School","url":"https://news-archive.hds.harvard.edu/news/2016/03/23/reformation-luthers-media-phenomenon","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Pettegree: Luther wrote short, accessible vernacular works; the Sermon on Indulgences and Grace was reprinted 14 times in its first year across Germany's printing centers"}],"tags":["reformation","printing","causation","media-history"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"history-v3-slave-trade-destinations-003","category":"history","conceptID":"history.comparison-context","conceptTitle":"Comparison and context","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"A student writing about the transatlantic slave trade assumes that the territory that became the United States was the trade's main destination. Which correction is best supported by the estimates in the Trans-Atlantic Slave Trade Database?","choices":[{"id":"a","text":"Brazil and the Caribbean took most captives; the United States absorbed only about 5 percent of arrivals.","rationale":"Correct. The database's estimates place the great majority of arrivals in Brazil and the Caribbean."},{"id":"b","text":"Mainland North America received about half of all captives, with the remainder split between Brazil and the Caribbean.","rationale":"Mainland North America received only a small fraction of captives, far below half."},{"id":"c","text":"Most captives went to Spanish Mexico and Peru, because silver mining there demanded more labor than plantation agriculture.","rationale":"Plantation regions, especially sugar colonies in Brazil and the Caribbean, absorbed most captives, not the Andean or Mexican mines."},{"id":"d","text":"Captives were spread almost evenly across the Americas, because every colonial economy depended equally on enslaved labor.","rationale":"Arrivals were heavily concentrated, with Brazil alone accounting for roughly 40 percent of the trade."}],"correctChoiceID":"a","explanation":"Estimates built on the Trans-Atlantic Slave Trade Database show that the great majority of enslaved Africans were carried to Brazil and the Caribbean, where sugar drove demand for labor. Brazil alone received about 40 percent of the trade, and Brazil plus the British Americas took more than seven of every ten captives, while the United States absorbed only about 5 percent. The large enslaved population of the United States grew mainly through natural increase and a domestic slave trade rather than continued imports. Comparing destinations this way corrects a U.S.-centered picture of the trade.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"slavevoyages-overview","title":"A Brief Overview of the Trans-Atlantic Slave Trade","publisher":"SlaveVoyages (Rice University and partners)","url":"https://www.slavevoyages.org/blog/-brief-overview-of-the-transatlantic-slave-trade/154","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Brazil received about 40 percent of the trade; Brazil and the British Americas took more than seven in ten captives; the United States absorbed only about 5 percent"}],"tags":["atlantic-slave-trade","comparison","quantitative-history","slavevoyages"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"history-v3-de-gouges-declaration-004","category":"history","conceptID":"history.primary-source-criticism","conceptTitle":"Reading primary sources","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"In 1791 Olympe de Gouges published a 'Declaration of the Rights of Woman and of the Female Citizen,' modeled article by article on the 1789 Declaration of the Rights of Man and of the Citizen. How should a historian most accurately characterize her text?","choices":[{"id":"a","text":"As an official amendment the National Assembly adopted in 1791 to extend full political rights to French women.","rationale":"The revolutionary assemblies never adopted it; French women did not gain the vote until the twentieth century."},{"id":"b","text":"As a restatement of Rousseau's view that women's proper civic role lay in the household rather than in political life.","rationale":"De Gouges argued the opposite, claiming for women the political rights the 1789 declaration announced for men."},{"id":"c","text":"As a private diary entry never circulated during her lifetime, useful chiefly for what it reveals of her personal feelings.","rationale":"It was a published political pamphlet addressed to a public audience, not a private document."},{"id":"d","text":"As a critique that borrowed the 1789 declaration's own form to expose how its universal language excluded women.","rationale":"Correct. By imitating the original's structure, she showed that its 'universal' rights were in practice reserved for men."}],"correctChoiceID":"d","explanation":"De Gouges's declaration answered the 1789 Declaration of the Rights of Man by reproducing its form and extending each claim explicitly to women. Reading it as a primary source means attending to genre, audience, and purpose: it was a published polemic that used the revolution's own language to expose a contradiction in it. The Assembly did not adopt it, and de Gouges was arrested after the fall of the Girondins and guillotined in November 1793. Treating it as an official act or as private reflection would misread its purpose.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"britannica-olympe-de-gouges","title":"Olympe de Gouges","publisher":"Encyclopaedia Britannica","url":"https://www.britannica.com/biography/Olympe-de-Gouges","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Her 1791 pamphlet was a reply to the Declaration of the Rights of Man adopted two years earlier; she was arrested after the fall of the Girondins and guillotined on November 3, 1793"}],"tags":["french-revolution","primary-sources","womens-rights","rights-of-man"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"history-v3-statute-of-labourers-005","category":"history","conceptID":"history.causation-change","conceptTitle":"Causation and historical change","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"In 1351, a few years after the Black Death reached England, the crown enacted the Statute of Labourers, which tried to hold wages at pre-plague levels and restrict laborers' movement. What does the law most directly suggest about conditions after the plague?","choices":[{"id":"a","text":"Plague deaths had produced a surplus of workers, so the statute aimed to shield laborers from falling wages and unemployment.","rationale":"The plague created a shortage, not a surplus, of labor; the statute capped wages rather than propping them up."},{"id":"b","text":"Mass mortality had made labor scarce, giving surviving workers leverage to demand higher pay and seek better terms elsewhere.","rationale":"Correct. Landowners and employers used the law to resist the rising wages and mobility that labor scarcity produced."},{"id":"c","text":"The population had already recovered, so the statute simply codified wage levels that the market had restored on its own.","rationale":"Population did not recover within a few years; the law was needed precisely because market wages had risen."},{"id":"d","text":"The crown wanted higher wages to draw workers back to towns, so the law set minimum rather than maximum rates of pay.","rationale":"The statute fixed wages at earlier, lower levels and limited movement; it was a ceiling, not a floor."}],"correctChoiceID":"b","explanation":"The Black Death killed a large share of England's population, sharply reducing the supply of labor. Surviving workers could demand higher wages and move in search of better terms, which threatened landowners' incomes. The Statute of Labourers of 1351 tried to freeze wages at pre-plague levels and restrict laborers' movement. A law like this is evidence of the conditions it tried to suppress, a useful way to reason about causation from legislation.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"britannica-statute-of-labourers","title":"Statute of Labourers","publisher":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/Statute-of-Labourers","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Enacted 1351 after the Black Death to freeze wages at pre-plague levels and restrict laborers' movement amid labor shortages"}],"tags":["black-death","labor-history","medieval-england","causation"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"history-v3-haiti-vs-american-revolution-006","category":"history","conceptID":"history.comparison-context","conceptTitle":"Comparison and context","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"Comparing the American Revolution (1775-83) with the Haitian Revolution (1791-1804), which difference is most significant for the history of slavery?","choices":[{"id":"a","text":"Haiti's revolution was fought chiefly against Spain, whereas the American Revolution was fought against Britain.","rationale":"Saint-Domingue was a French colony; the decisive struggle was against French rule, though Spain and Britain also intervened."},{"id":"b","text":"The American Revolution abolished slavery throughout the new nation, while Haiti's revolution kept plantation slavery.","rationale":"This reverses the outcomes: slavery survived in the United States, while Haiti's revolution destroyed it."},{"id":"c","text":"Enslaved people in Saint-Domingue overthrew slavery and founded an independent state; the new United States kept slavery.","rationale":"Correct. Haiti became an independent country founded and governed by former slaves; U.S. slavery lasted until 1865."},{"id":"d","text":"Both revolutions ended slavery in their territories, but Haiti's independence came several decades after America's.","rationale":"Only the Haitian Revolution ended slavery; the United States did not abolish it nationally until the Thirteenth Amendment."}],"correctChoiceID":"c","explanation":"The Haitian Revolution began in 1791 with a general revolt of enslaved people in the French colony of Saint-Domingue; its success pushed France to abolish slavery in 1794, and it ended in 1804 with an independent country founded and governed by former slaves. The American Revolution, by contrast, created a republic that preserved slavery, which persisted until the Civil War and the Thirteenth Amendment. Comparing the two highlights how the age of revolutions' language of liberty could either exclude enslaved people or be seized by them.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"britannica-haitian-revolution","title":"Haitian Revolution","publisher":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/Haitian-Revolution","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Overthrow of French rule by formerly enslaved Africans and their descendants, establishing an independent country founded and governed by former slaves; pushed France to abolish slavery in 1794"}],"tags":["haitian-revolution","age-of-revolutions","slavery","comparison"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"history-v3-annales-longue-duree-007","category":"history","conceptID":"history.historiography-interpretation","conceptTitle":"Historiography and interpretation","type":"multipleChoice","dimension":"application","difficulty":"advanced","prompt":"A historian studies the sixteenth-century Mediterranean mainly through slow-moving structures (mountains, seas, climate, trade routes) and treats battles and royal decisions as surface events. Which historiographical tradition does this approach best exemplify?","choices":[{"id":"a","text":"The Annales school, associated with Fernand Braudel's attention to long-term structures over political events.","rationale":"Correct. Under Braudel the Annales school turned from leaders and wars to climate, trade, and society."},{"id":"b","text":"The Whig interpretation, which narrates the past as steady progress toward present-day liberal institutions.","rationale":"Whig history is defined by a progress narrative judged from the present, not by an emphasis on geography and structure."},{"id":"c","text":"Great-man history, which explains change mainly through the decisive choices of exceptional individual leaders.","rationale":"The approach described explicitly downplays rulers' decisions, the focus of great-man history."},{"id":"d","text":"Rankean diplomatic history, which reconstructs state decisions mainly from governments' archival correspondence.","rationale":"Leopold von Ranke's tradition centered on states and diplomacy, the 'events' this historian treats as surface."}],"correctChoiceID":"a","explanation":"The Annales school, rooted in the journal founded by Lucien Febvre and Marc Bloch, turned historians toward social, economic, and environmental structures. Under Fernand Braudel's direction it replaced the study of leaders, politics, diplomacy, and wars with inquiries into climate, demography, agriculture, commerce, technology, and social groups. The other traditions all center on political actors or progress narratives that this approach deliberately subordinates. Recognizing such traditions helps readers see what a historian's framework makes visible and what it sidelines.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"britannica-annales-school","title":"Annales school","publisher":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/Annales-school","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Founded by Febvre and Bloch; under Braudel it replaced the study of leaders, politics, diplomacy, and wars with climate, demography, agriculture, commerce, and social groups"}],"tags":["historiography","annales","braudel","longue-duree"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"history-v3-printing-reformation-essay-008","category":"history","conceptID":"history.causation-change","conceptTitle":"Causation and historical change","type":"essay","dimension":"synthesis","difficulty":"advanced","prompt":"Evaluate the claim that 'the printing press caused the Protestant Reformation.' Build an argument that distinguishes necessary conditions, sufficient causes, and contingent events. Use evidence such as earlier reform movements (for example, Jan Hus), Luther's vernacular pamphlets, the political protection Luther received from German princes, and the Church's response. Explain what evidence would weaken your conclusion.","choices":[],"explanation":"Coaching should push the learner beyond a single-cause story: print as an enabling condition, earlier reformers as a comparison case, and politics and contingency as factors that print alone cannot explain.","rubric":[{"id":"claim-precision","title":"Precise causal claim","description":"States a clear thesis that specifies what kind of cause printing was (enabling, accelerating, necessary, or sufficient) and for which outcome.","weight":0.25,"coachingQuestions":["Are you explaining why the Reformation began, why it spread, or why it survived?","What would 'cause' have to mean for the claim to be true?"]},{"id":"comparison","title":"Comparative evidence","description":"Uses earlier reform movements such as Hus's as a comparison case to isolate what was new after 1517.","weight":0.25,"coachingQuestions":["What did Hus lack that Luther had?","What did they share that print cannot explain?"]},{"id":"multiple-factors","title":"Political and religious factors","description":"Weighs princely protection, Church responses, theology, and social grievances alongside media, without treating any one as automatic.","weight":0.3,"coachingQuestions":["Would Luther's ideas have survived without political protection?","How did the Church's response shape the outcome?"]},{"id":"counterevidence","title":"Counterevidence and limits","description":"Identifies evidence that would weaken the argument and acknowledges uncertainty in reconstructing readership and influence.","weight":0.2,"coachingQuestions":["What evidence would show print mattered less than you claim?","How do we know who actually read or heard the pamphlets?"]}],"coachingPrompts":["Separate enabling conditions from triggers and outcomes.","Use Hus as a control case, with its limits acknowledged.","Name at least one non-media factor and weigh it explicitly.","End with what evidence would change your mind."],"modelOutline":["Define the outcome being explained and the sense of 'cause' at issue","Compare Hus and Luther to isolate what changed","Assess print as an accelerating or enabling condition","Weigh political protection, Church response, and theology","Conclude with a qualified judgment and possible counterevidence"],"sources":[{"id":"harvard-divinity-luther-media","title":"Luther's Media Phenomenon","publisher":"Harvard Divinity School","url":"https://news-archive.hds.harvard.edu/news/2016/03/23/reformation-luthers-media-phenomenon","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Pettegree: Luther wrote short, accessible vernacular works; the Sermon on Indulgences and Grace was reprinted 14 times in its first year across Germany's printing centers"},{"id":"britannica-jan-hus","title":"Jan Hus","publisher":"Encyclopaedia Britannica","url":"https://www.britannica.com/biography/Jan-Hus","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Hus opposed the sale of indulgences in the early fifteenth century and was condemned at the Council of Constance"},{"id":"britannica-reformation","title":"Reformation","publisher":"Encyclopaedia Britannica","url":"https://www.britannica.com/event/Reformation","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Overview of the sixteenth-century Reformation, Luther's challenge, and its political setting"}],"tags":["reformation","causation","printing","essay"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"people-v3-demographic-transition-001","category":"people","conceptID":"people.demography","conceptTitle":"Population and demography","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"Over two decades, a country's death rate falls sharply as vaccination and clean water spread, while its birth rate stays high. According to the demographic transition model, what should demographers expect during this period?","choices":[{"id":"a","text":"Rapid population aging, because longer lives immediately push the median age above that of wealthier countries.","rationale":"Falling child mortality in this stage usually makes populations younger, not older, because more children survive."},{"id":"b","text":"Population stability, because high birth rates and high death rates continue to offset each other as before.","rationale":"Offsetting high rates describe the model's first stage; here the death rate has already fallen."},{"id":"c","text":"Slowing growth, because lower death rates quickly lead families to have fewer children within the same decade.","rationale":"Fertility decline typically lags mortality decline by years or decades; that lag is what produces rapid growth."},{"id":"d","text":"Rapid population growth, because births now far exceed deaths until fertility also begins to fall.","rationale":"Correct. The gap between a fallen death rate and a still-high birth rate drives fast natural increase."}],"correctChoiceID":"d","explanation":"The demographic transition model describes a shift from high birth and death rates to low ones. Death rates usually fall first, as public health, sanitation, and medicine improve, while birth rates remain high for a time. The resulting gap between births and deaths produces rapid population growth until fertility declines as well. The model is a generalization rather than a law, but this stage-two pattern is its most robust feature.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"prb-intro-demography","title":"Population: An Introduction to Demography (Population Bulletin 75, no. 1)","publisher":"Population Reference Bureau","url":"https://www.prb.org/app/uploads/2023/11/population-bulletin-75-no1-an-introduction-to-demography.pdf","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Demographic balancing equation (fertility, mortality, migration); Stage 2 of the transition: death rate drops while birth rate remains high, so population grows; replacement requires a TFR slightly above 2 because some children die"}],"tags":["demographic-transition","mortality","fertility","population-growth"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"people-v3-replacement-fertility-002","category":"people","conceptID":"people.demography","conceptTitle":"Population and demography","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"Demographers often cite a total fertility rate of about 2.1 children per woman as 'replacement level' in low-mortality countries. Why is the figure slightly above 2.0?","choices":[{"id":"a","text":"Women outlive men on average, so extra births are needed to offset the longer female lifespan.","rationale":"Longer survival at older ages does not raise the number of births needed for replacement."},{"id":"b","text":"Each couple must also replace any grandparents still living, which adds a fraction of a child.","rationale":"Replacement is defined across generations of mothers and daughters; living grandparents do not enter the calculation."},{"id":"c","text":"Net immigration is built into the definition, adding roughly 0.1 child per woman in most countries.","rationale":"Replacement fertility describes a closed population; migration is analyzed separately."},{"id":"d","text":"Some girls die before reaching childbearing age, and slightly more boys than girls are born.","rationale":"Correct. Replacement means each woman is succeeded by a daughter who survives to bear children herself."}],"correctChoiceID":"d","explanation":"Replacement-level fertility is the average number of children a woman must have to be replaced by a daughter who survives to childbearing age. Because some children die before adulthood and about 105 boys are born for every 100 girls, the figure is a little above 2.0: close to 2.1 where mortality is low and the sex ratio at birth is normal. Where infant, child, or maternal mortality is higher, replacement fertility is higher as well, in some countries above 3. Migration and older-age survival are separate components of population change.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"un-popfacts-2017-3","title":"PopFacts 2017/3: The end of high fertility is near","publisher":"United Nations, Population Division","url":"https://population.un.org/wpp/assets/Files/PopFacts_2017-3_The-end-of-high-fertility.pdf","accessedAt":"2026-10-21T06:00:00Z","usage":"publicDomain","evidenceLocator":"Replacement fertility is close to 2.1 births per woman where the sex ratio at birth is normal (about 105 boys per 100 girls) and mortality is relatively low"},{"id":"un-tfr-methodology","title":"Total Fertility Rate (indicator methodology sheet)","publisher":"United Nations, Department of Economic and Social Affairs","url":"https://www.un.org/esa/sustdev/natlinfo/indicators/methodology_sheets/demographics/total_fertility_rate.pdf","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Replacement fertility of about 2.1 is the average number of children a woman needs to bear a daughter who survives to childbearing age"},{"id":"prb-intro-demography","title":"Population: An Introduction to Demography (Population Bulletin 75, no. 1)","publisher":"Population Reference Bureau","url":"https://www.prb.org/app/uploads/2023/11/population-bulletin-75-no1-an-introduction-to-demography.pdf","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Demographic balancing equation (fertility, mortality, migration); Stage 2 of the transition: death rate drops while birth rate remains high, so population grows; replacement requires a TFR slightly above 2 because some children die"}],"tags":["fertility","replacement-level","demography","sex-ratio"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"people-v3-bystander-diffusion-003","category":"people","conceptID":"people.social-psychology","conceptTitle":"Social psychology","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"In a classic experiment, participants who believed they alone could hear a peer having a seizure over an intercom tended to help quickly, while those who believed four others were also listening were slower and less likely to help. Which explanation did the researchers emphasize?","choices":[{"id":"a","text":"Groupthink, in which a cohesive group suppresses dissent to preserve harmony and reaches a poor collective decision.","rationale":"Groupthink concerns decision-making in cohesive groups; these participants were isolated and never deliberated together."},{"id":"b","text":"Social loafing, in which people exert less effort on a shared task because their individual output cannot be identified.","rationale":"Social loafing involves effort on a collective task, not the decision to intervene in an emergency."},{"id":"c","text":"Diffusion of responsibility, in which each bystander feels less personally obligated to act when others could also act.","rationale":"Correct. Latane and Darley argued that perceived others dilute each person's sense of responsibility."},{"id":"d","text":"Obedience to authority, in which people defer to an experimenter's instructions even when they conflict with conscience.","rationale":"No authority instructed participants not to help; the key variable was the number of other presumed listeners."}],"correctChoiceID":"c","explanation":"Bibb Latane and John Darley's research on bystander intervention, prompted in part by public reaction to the 1964 murder of Kitty Genovese, found that people are less likely to help when they believe others are present. In their intercom study, the presumed presence of other listeners slowed and reduced helping. They emphasized diffusion of responsibility: when others could act, each person feels less personally obligated. Groupthink and social loafing are real phenomena but describe different situations.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"darley-latane-1968","title":"Bystander Intervention in Emergencies: Diffusion of Responsibility (Journal of Personality and Social Psychology, 1968)","publisher":"John M. Darley and Bibb Latane (hosted by University of Colorado Denver)","url":"https://www.ucdenver.edu/docs/librariesprovider102/default-document-library/bystander-intervention-john-darley-and-bibb-latane.pdf","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Participants who believed others also heard a seizure over an intercom reported it less often and more slowly; the authors attribute this to diffusion of responsibility"},{"id":"britannica-bystander-effect","title":"Bystander effect","publisher":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/bystander-effect","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Latane and Darley's research; diffusion of responsibility reduces each bystander's felt obligation to help when others are present"}],"tags":["bystander-effect","diffusion-of-responsibility","helping","experiments"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"people-v3-attribution-error-004","category":"people","conceptID":"people.social-psychology","conceptTitle":"Social psychology","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"A manager learns that a new hire missed a deadline and concludes she is disorganized, without checking that her workload doubled that week and two teammates were out sick. Which bias does this judgment best illustrate?","choices":[{"id":"a","text":"Self-serving bias, in which people credit their own successes to skill and blame their own failures on circumstances.","rationale":"Self-serving bias concerns explanations of one's own outcomes; the manager is judging someone else."},{"id":"b","text":"Fundamental attribution error, in which observers overweight personality and underweight situational pressures on others.","rationale":"Correct. The manager attributes the miss to a trait while ignoring obvious situational causes."},{"id":"c","text":"Hindsight bias, in which people believe after the fact that an outcome was predictable all along from the start.","rationale":"Hindsight bias distorts judgments of predictability, not explanations of a person's behavior."},{"id":"d","text":"Halo effect, in which one positive impression of a person spills over into favorable judgments of unrelated traits.","rationale":"The halo effect inflates judgments after a positive impression; here a single event produces a negative trait judgment."}],"correctChoiceID":"b","explanation":"The fundamental attribution error is the tendency, when explaining other people's behavior, to overemphasize internal dispositions such as personality and to underestimate external, situational factors. The manager infers a trait (disorganization) from one missed deadline and ignores a doubled workload and absent teammates. Self-serving bias would apply if the manager were explaining her own failures. Recognizing the error encourages checking situational causes before drawing conclusions about character.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"britannica-fundamental-attribution-error","title":"Fundamental attribution error","publisher":"Encyclopaedia Britannica","url":"https://www.britannica.com/science/fundamental-attribution-error","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Observers overemphasize dispositional factors and underestimate situational factors when explaining others' behavior"}],"tags":["attribution","fundamental-attribution-error","social-cognition","workplace"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"people-v3-sunk-cost-005","category":"people","conceptID":"people.everyday-economics","conceptTitle":"Economics of everyday life","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"Lena paid $150 for a nonrefundable, nontransferable concert ticket. On the night of the show she has a fever, a storm has made driving risky, and she would honestly rather stay home. Which reasoning about the ticket is economically sound?","choices":[{"id":"a","text":"She should go, because staying home would turn the $150 into a pure loss that attending would at least partly recover.","rationale":"The $150 is gone either way; attending does not recover it. This is the sunk cost fallacy."},{"id":"b","text":"She should go only if the ticket price exceeds her expected travel costs, since that is when attending pays off.","rationale":"Comparing the past ticket price with future travel costs still lets an unrecoverable cost drive the decision."},{"id":"c","text":"She should stay home only if she can find a buyer, since otherwise the ticket price counts against staying home.","rationale":"The ticket cannot be transferred, and in any case the price already paid is not a cost of either future choice."},{"id":"d","text":"She should decide by weighing only tonight's costs and benefits, since the $150 is spent whichever choice she makes.","rationale":"Correct. A sunk cost is unrecoverable and should not affect a forward-looking decision."}],"correctChoiceID":"d","explanation":"A sunk cost is money already spent that cannot be recovered whatever one does next. Because the ticket is nonrefundable and nontransferable, the $150 is gone whether Lena attends or not, so it should not enter her decision. Sound reasoning compares only future costs and benefits: the enjoyment of the concert against illness, risk, and discomfort. Feeling that attending 'saves' the money is the sunk cost fallacy.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"britannica-sunk-cost","title":"Sunk cost","publisher":"Britannica Money","url":"https://www.britannica.com/money/sunk-cost","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Costs already incurred and unrecoverable should not affect decisions about future actions"}],"tags":["sunk-cost","decision-making","opportunity-cost","behavioral-economics"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"people-v3-median-income-006","category":"people","conceptID":"people.social-measurement","conceptTitle":"Measuring society","type":"multipleChoice","dimension":"application","difficulty":"foundation","prompt":"News reports on U.S. household income usually cite the Census Bureau's median rather than the mean. Why is the median generally the better guide to a typical household?","choices":[{"id":"a","text":"Very high incomes pull the mean upward, while the median marks the middle household and resists such extremes.","rationale":"Correct. Income distributions are right-skewed, so the mean sits above what a typical household earns."},{"id":"b","text":"The median includes households with zero income, while the mean leaves those households out by design.","rationale":"Both measures are computed over the same set of households; the difference lies in sensitivity to extremes."},{"id":"c","text":"The mean can be computed only from tax records, which miss households that do not file income tax returns.","rationale":"Survey data can yield both a mean and a median; the choice is not dictated by data source."},{"id":"d","text":"The median is adjusted for inflation each year, whereas the mean is always reported in unadjusted dollars.","rationale":"Either statistic can be reported in current or inflation-adjusted dollars."}],"correctChoiceID":"a","explanation":"Household income is right-skewed: a relatively small number of very high incomes pulls the mean well above what most households earn. The median is the income of the household in the middle of the distribution, so it is not affected by extreme highs and lows. That is why analysts treat the median as a better indicator of a typical household's situation. Both measures can be computed from the same survey and adjusted for inflation; the difference is their sensitivity to outliers.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"pew-census-trends-income","title":"Chapter 6: Census Trends for Income and Demography","publisher":"Pew Research Center","url":"https://www.pewresearch.org/social-trends/2012/08/22/chapter-6-census-trends-for-income-and-demography/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"The median is preferred because it is not affected by extreme lows and highs in reported incomes"}],"tags":["median","income-distribution","statistics","census"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"people-v3-discouraged-worker-007","category":"people","conceptID":"people.social-measurement","conceptTitle":"Measuring society","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"Jordan lost his job eight months ago. He wants work but stopped searching six weeks ago because he believes no jobs are available in his field. How does the Bureau of Labor Statistics count him in the official unemployment rate?","choices":[{"id":"a","text":"As unemployed, because the official rate counts every jobless adult who says they would accept a job if one were offered.","rationale":"Wanting a job is not enough; the official definition also requires active job search in the past four weeks."},{"id":"b","text":"As not in the labor force, because he has not actively looked for work at any point in the past four weeks.","rationale":"Correct. Jordan is a discouraged worker, outside the labor force and excluded from the official rate."},{"id":"c","text":"As unemployed for up to one year after a layoff, after which he would be reclassified as outside the labor force.","rationale":"Classification depends on active job search in the past four weeks, not on time since the job ended."},{"id":"d","text":"As employed part time for economic reasons, because he wants work but cannot find a suitable full-time position.","rationale":"That category applies to people who are working part time; Jordan is not working at all."}],"correctChoiceID":"b","explanation":"In the Current Population Survey, people are counted as unemployed if they have no job, are available for work, and actively looked for work in the prior four weeks. Jordan stopped searching six weeks ago, so he is classified as not in the labor force. Because he wants a job but stopped looking because he believes none is available in his line of work, he is a 'discouraged worker,' a subset of the marginally attached who are excluded from the official rate. This is one reason analysts track labor-force participation alongside unemployment.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"bls-how-unemployment-measured","title":"How the Government Measures Unemployment","publisher":"U.S. Bureau of Labor Statistics","url":"https://www.bls.gov/cps/cps_htgm.htm","accessedAt":"2026-10-21T06:00:00Z","usage":"publicDomain","evidenceLocator":"Unemployed people are jobless, available, and actively looked for work in the prior 4 weeks; discouraged workers are not in the labor force"}],"tags":["unemployment","labor-force","bls","discouraged-workers"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"people-v3-shrinking-county-essay-008","category":"people","conceptID":"people.demography","conceptTitle":"Population and demography","type":"essay","dimension":"synthesis","difficulty":"advanced","prompt":"A rural county's population has fallen for fifteen years while its median age has risen. Local leaders blame young people leaving. Using the components of population change (births, deaths, in-migration, and out-migration), design an analysis that tests that explanation against alternatives such as low fertility, an aging age structure, or reduced in-migration. Explain what data you would need and which policy responses each finding would and would not justify.","choices":[],"explanation":"Coaching should push the learner to decompose change into natural increase and net migration, consider age structure and momentum, and avoid jumping from a plausible story to a policy without evidence.","rubric":[{"id":"decomposition","title":"Components of change","description":"Decomposes population change into births, deaths, in-migration, and out-migration and explains how each could produce decline and aging.","weight":0.3,"coachingQuestions":["Could the county shrink even if no one left?","Which component would show up first in the data?"]},{"id":"age-structure","title":"Age structure and momentum","description":"Explains how an older age structure raises deaths and lowers births independent of current behavior.","weight":0.25,"coachingQuestions":["How does an aging population affect future births even at constant fertility?","What would an age pyramid reveal?"]},{"id":"data-design","title":"Data and comparison","description":"Identifies concrete data (vital statistics, census and survey migration estimates by age) and comparison counties or periods.","weight":0.25,"coachingQuestions":["Which ages are leaving, and which are not arriving?","What comparison would show whether this county is unusual?"]},{"id":"policy-fit","title":"Policy implications","description":"Matches policies to findings and notes what each finding does not justify.","weight":0.2,"coachingQuestions":["If the problem is low in-migration, would retention programs help?","What uncertainty remains in small-area estimates?"]}],"coachingPrompts":["Write the balancing equation before telling a story.","Separate natural decrease from net out-migration.","Disaggregate migration by age group.","Tie each policy to a specific finding."],"modelOutline":["State the demographic balancing equation for the county","List competing explanations and the data pattern each predicts","Specify data sources, age breakdowns, and comparison cases","Interpret possible findings, including age-structure effects","Match policy responses to findings and note remaining uncertainty"],"sources":[{"id":"prb-intro-demography","title":"Population: An Introduction to Demography (Population Bulletin 75, no. 1)","publisher":"Population Reference Bureau","url":"https://www.prb.org/app/uploads/2023/11/population-bulletin-75-no1-an-introduction-to-demography.pdf","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Demographic balancing equation (fertility, mortality, migration); Stage 2 of the transition: death rate drops while birth rate remains high, so population grows; replacement requires a TFR slightly above 2 because some children die"}],"tags":["demography","migration","aging","essay"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"investing-v3-fee-compounding-001","category":"investing","conceptID":"investing.fees-taxes-compounding","conceptTitle":"Fees, taxes, and compounding","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"An SEC bulletin models $100,000 growing 4% a year for 20 years. With a 0.25% annual fee it ends near $208,000; with a 1% fee, near $179,000. Why is that roughly $29,000 gap larger than 0.75% x $100,000 x 20 years = $15,000?","choices":[{"id":"a","text":"The higher fee is charged as a flat dollar amount that rises each year with inflation, independent of returns.","rationale":"In the illustration both fees are percentages of the account balance, not inflation-indexed flat charges."},{"id":"b","text":"The bulletin assumes the higher-fee portfolio also earns a lower gross return, so the gap reflects worse performance.","rationale":"Both portfolios earn the same 4% before fees; only the fee differs."},{"id":"c","text":"Each year's fee is a percentage of a growing balance and also removes money that would have compounded afterward.","rationale":"Correct. Fees reduce the base that future returns compound on, so their cost grows over time."},{"id":"d","text":"Fees are taxed as capital gains when they are deducted, so each fee costs more than its stated percentage.","rationale":"Deducting a fee does not trigger a capital gains tax; the extra cost comes from lost compounding."}],"correctChoiceID":"c","explanation":"A percentage fee is charged on the account balance each year, so as the balance grows, the dollar fee grows too. More importantly, every dollar paid in fees is a dollar that no longer earns returns in later years, so the cost compounds. That is why a 0.75 percentage-point difference in annual fees costs far more over 20 years than a simple multiplication suggests. The SEC uses this illustration to show why small-looking fee differences matter for long-term investors.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"investor-gov-fees-bulletin","title":"How Fees and Expenses Affect Your Investment Portfolio","publisher":"U.S. Securities and Exchange Commission (Investor.gov)","url":"https://www.investor.gov/introduction-investing/general-resources/news-alerts/alerts-bulletins/investor-bulletins/updated","accessedAt":"2026-10-21T06:00:00Z","usage":"publicDomain","evidenceLocator":"Illustration: $100,000 growing 4% a year for 20 years ends near $208,000 with a 0.25% annual fee and near $179,000 with a 1% fee"}],"tags":["fees","compounding","expense-ratio","long-term-investing"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"investing-v3-rule-of-72-002","category":"investing","conceptID":"investing.fees-taxes-compounding","conceptTitle":"Fees, taxes, and compounding","type":"multipleChoice","dimension":"application","difficulty":"foundation","prompt":"Using the Rule of 72, roughly how long would an investment earning a steady 6% a year, compounded annually, take to grow to about four times its starting value?","choices":[{"id":"a","text":"About 24 years, since it doubles roughly every 12 years and quadrupling takes two doublings.","rationale":"Correct. 72 / 6 = 12 years per doubling; two doublings give about four times the starting value."},{"id":"b","text":"About 50 years, since 300% of growth at 6% a year requires fifty years of steady returns.","rationale":"This treats growth as simple interest; compounding reaches four times far sooner."},{"id":"c","text":"About 12 years, since 72 divided by 6 gives the time needed to reach four times the value.","rationale":"The Rule of 72 estimates the time to double, not to quadruple."},{"id":"d","text":"About 36 years, since each doubling takes 12 years and quadrupling requires three doublings.","rationale":"Three doublings would multiply the value by eight, not four."}],"correctChoiceID":"a","explanation":"The Rule of 72 estimates doubling time by dividing 72 by the annual rate of return. At 6%, money doubles in about 12 years. Quadrupling is two doublings (2 x 2 = 4), so it takes about 24 years; indeed 1.06 raised to the 24th power is about 4.05. Treating growth as simple interest (300% / 6% = 50 years) ignores compounding.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"investor-gov-compound-interest","title":"What is compound interest?","publisher":"U.S. Securities and Exchange Commission (Investor.gov)","url":"https://www.investor.gov/additional-resources/information/youth/teachers-classroom-resources/what-compound-interest","accessedAt":"2026-10-21T06:00:00Z","usage":"publicDomain","evidenceLocator":"Rule of 72: divide 72 by the annual rate of return to estimate the years needed to double"}],"tags":["rule-of-72","compounding","doubling-time","math"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"investing-v3-correlation-diversification-003","category":"investing","conceptID":"investing.diversification-correlation","conceptTitle":"Diversification and index investing","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"A portfolio is invested entirely in U.S. large-company stocks. An adviser suggests adding a fairly volatile asset whose returns have historically had low correlation with those stocks. How could adding a volatile asset lower the overall portfolio's volatility?","choices":[{"id":"a","text":"It cannot; adding an asset lowers overall volatility only if that asset is less volatile than every existing holding.","rationale":"Portfolio volatility depends on how holdings move together, not only on each asset's own volatility."},{"id":"b","text":"Because its returns often move independently of the stocks, its swings can partly offset theirs in the combined portfolio.","rationale":"Correct. Low correlation means gains in one holding often coincide with losses in another, smoothing the total."},{"id":"c","text":"Because a volatile asset carries a higher expected return, and higher returns mathematically lower portfolio volatility.","rationale":"Expected return and volatility are different quantities; a higher return does not by itself reduce volatility."},{"id":"d","text":"Because holding two asset classes eliminates market-wide risk, leaving only the small risk specific to individual firms.","rationale":"Diversification reduces but cannot eliminate risk, and correlations can rise during market stress."}],"correctChoiceID":"b","explanation":"Diversification works because different asset categories often rise and fall under different market conditions. When an added asset's returns have low correlation with existing holdings, its ups and downs partly offset theirs, so the combined portfolio can fluctuate less than either alone, even if the new asset is volatile by itself. The benefit depends on correlations that can change, and they often rise in crises. Diversification reduces risk; it does not eliminate it or guarantee against loss.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"sec-asset-allocation-guide","title":"Beginners' Guide to Asset Allocation, Diversification, and Rebalancing","publisher":"U.S. Securities and Exchange Commission","url":"https://www.sec.gov/about/reports-publications/investorpubsassetallocationhtm","accessedAt":"2026-10-21T06:00:00Z","usage":"publicDomain","evidenceLocator":"Including asset categories whose returns move up and down under different market conditions can reduce portfolio risk"}],"tags":["diversification","correlation","asset-allocation","volatility"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"investing-v3-active-arithmetic-004","category":"investing","conceptID":"investing.diversification-correlation","conceptTitle":"Diversification and index investing","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"William Sharpe's 'arithmetic of active management' argues that, over any given period, the average actively managed dollar must trail the average passively managed dollar after costs. What is the core of his argument?","choices":[{"id":"a","text":"Active managers are on average less skilled than the analysts who construct market indexes, so they pick worse stocks.","rationale":"Sharpe's argument requires no assumption about skill; it follows from accounting identities."},{"id":"b","text":"Index funds are legally required to hold safer securities, so they lose less in downturns and win over full cycles.","rationale":"Index funds hold the market, not a legally mandated set of safer securities."},{"id":"c","text":"Active managers trade more often, and frequent trading by itself pushes market prices against them before costs.","rationale":"Sharpe's point holds before any price-impact story: active investors as a group earn the market return before costs."},{"id":"d","text":"Before costs, active investors as a group hold the market and earn its return, so their higher costs leave them behind.","rationale":"Correct. Passive plus active equals the market; if passive earns the market return, so must active, before costs."}],"correctChoiceID":"d","explanation":"Sharpe divides investors in a market into passive investors, who hold every security in market proportions, and everyone else. Since passive investors earn the market return before costs, active investors as a group must also earn the market return before costs, because together they hold the whole market. Active management usually costs more, so after costs the average active dollar must earn less than the average passive dollar. Individual active managers can beat the market, but the average cannot after costs.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"sharpe-arithmetic-active","title":"The Arithmetic of Active Management","publisher":"William F. Sharpe, Stanford University","url":"https://web.stanford.edu/~wfsharpe/art/active/active.htm","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Before costs, the return on the average actively managed dollar equals the average passively managed dollar; after costs it must be less"}],"tags":["index-funds","active-management","costs","market-return"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"investing-v3-bond-maturity-risk-005","category":"investing","conceptID":"investing.valuation-cash-flows","conceptTitle":"Bonds and interest rates","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"An investor holds two high-quality fixed-rate bonds from the same issuer with similar coupons: one matures in 2 years, the other in 20 years. If market interest rates rise by one percentage point, which outcome is most likely?","choices":[{"id":"a","text":"Both prices fall, and the 20-year bond's price falls by a larger percentage because its payments stretch further out.","rationale":"Correct. Longer maturities carry more interest rate risk, so the 20-year bond is more sensitive."},{"id":"b","text":"Both prices fall by about the same percentage, because both bonds face the identical one-point rise in rates.","rationale":"The same rate change affects bonds differently depending on how far away their cash flows are."},{"id":"c","text":"The 2-year bond's price falls more, because it matures sooner and must reprice more quickly to reflect new rates.","rationale":"The short bond returns principal soon and can be reinvested at higher rates, so its price moves less."},{"id":"d","text":"Neither price changes, because fixed coupons insulate a bond's market value from changes in prevailing rates.","rationale":"Fixed coupons are exactly why prices fall: the bond's payments become less attractive than new, higher-paying bonds."}],"correctChoiceID":"a","explanation":"When market interest rates rise, prices of existing fixed-rate bonds fall, because new bonds offer higher coupons. The longer a bond's maturity, the longer its fixed payments are locked in below market rates, so its price is more sensitive to rate changes. The SEC notes that bonds with longer maturities generally have higher interest rate risk than similar shorter bonds. Duration is the standard measure of this sensitivity.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"investor-gov-interest-rate-risk","title":"Investor Bulletin: Interest Rate Risk - When Interest Rates Go Up, Prices of Fixed-Rate Bonds Fall","publisher":"U.S. Securities and Exchange Commission (Investor.gov)","url":"https://www.investor.gov/introduction-investing/general-resources/news-alerts/alerts-bulletins/investor-bulletins-86","accessedAt":"2026-10-21T06:00:00Z","usage":"publicDomain","evidenceLocator":"Bonds with longer maturities generally have higher interest rate risk than similar bonds with shorter maturities"}],"tags":["bonds","interest-rate-risk","maturity","duration"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"investing-v3-disposition-effect-006","category":"investing","conceptID":"investing.behavioral-finance","conceptTitle":"Investor behavior and risk","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"Studying 10,000 discount-brokerage accounts, Terrance Odean found that investors sold stocks that had risen far more readily than stocks that had fallen, even though, for taxable accounts, this lowered after-tax returns and was not justified by later performance. What is this tendency called?","choices":[{"id":"a","text":"Home bias, the tendency to overweight domestic securities relative to their share of global market value.","rationale":"Home bias concerns where investors invest, not which positions they choose to sell."},{"id":"b","text":"Herding, the tendency to buy or sell a security mainly because many other investors are doing the same.","rationale":"Herding involves following others' trades; Odean's finding concerns each investor's own gains and losses."},{"id":"c","text":"The disposition effect, a reluctance to realize losses combined with an eagerness to lock in gains.","rationale":"Correct. Odean tested and documented this pattern in discount-brokerage records."},{"id":"d","text":"Recency bias, the expectation that whatever returns occurred most recently will simply continue indefinitely.","rationale":"Recency bias would predict holding recent winners, the opposite of selling them readily."}],"correctChoiceID":"c","explanation":"The disposition effect is the tendency to sell winning investments too early and hold losing investments too long. Odean's study of 10,000 discount-brokerage accounts found a strong preference for realizing gains over losses that was not justified by subsequent portfolio performance and, for taxable investments, led to lower after-tax returns. Behavioral explanations point to loss aversion and reluctance to admit a mistake. Awareness of the bias helps investors judge positions on future prospects rather than purchase price.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"odean-disposition","title":"Are Investors Reluctant to Realize Their Losses?","publisher":"Terrance Odean, University of California, Berkeley (Journal of Finance, 1998)","url":"https://faculty.haas.berkeley.edu/odean/papers/disposition/disposition.html","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Discount-brokerage investors showed a strong preference for realizing winners rather than losers, not justified by later performance and costly for taxes"}],"tags":["behavioral-finance","disposition-effect","loss-aversion","taxes"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"investing-v3-real-after-tax-return-007","category":"investing","conceptID":"investing.fees-taxes-compounding","conceptTitle":"Fees, taxes, and compounding","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"A taxable bond fund yields 5% this year. The investor's marginal tax rate on that income is 24%, and inflation is 3%. Approximately what real, after-tax return did the investor earn?","choices":[{"id":"a","text":"About 2.0%, because the real return is simply the 5% yield minus the 3% rate of inflation.","rationale":"This adjusts for inflation but ignores the tax owed on the 5% of income."},{"id":"b","text":"About 0.8%, because taxes leave 3.8%, and inflation then cuts that to roughly 0.8%.","rationale":"Correct. 5% x (1 - 0.24) = 3.8% after tax; 3.8% - 3% is about 0.8% real."},{"id":"c","text":"About 1.5%, because tax applies only to the 2% real part of the yield, leaving about 1.5%.","rationale":"Taxes are levied on the full nominal income, not just the portion above inflation."},{"id":"d","text":"About 3.8%, because inflation erodes only the principal and not the interest the bond pays.","rationale":"Inflation reduces the purchasing power of the whole return, interest included."}],"correctChoiceID":"b","explanation":"Investor.gov defines real return as the return after taxes and inflation. Tax is owed on the full 5% of nominal income, leaving 5% x (1 - 0.24) = 3.8% after tax. Subtracting 3% inflation leaves about 0.8% in purchasing-power terms (more precisely 1.038 / 1.03 - 1, about 0.78%). The example shows how taxes on nominal income can consume much of a low real return.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"investor-gov-real-return","title":"Real Return","publisher":"U.S. Securities and Exchange Commission (Investor.gov)","url":"https://www.investor.gov/introduction-investing/investing-basics/glossary/real-return","accessedAt":"2026-10-21T06:00:00Z","usage":"publicDomain","evidenceLocator":"Real return is the return after taxes and inflation, unlike the nominal return"}],"tags":["real-return","inflation","taxes","bonds"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"investing-v3-too-good-offer-essay-008","category":"investing","conceptID":"investing.behavioral-finance","conceptTitle":"Investor behavior and risk","type":"essay","dimension":"synthesis","difficulty":"college","prompt":"A friend invites you into a private fund that has reportedly paid 1% a month for three years with no down months, pays bonuses to investors who recruit others, and is not registered with the SEC. Without giving personal investment advice, analyze the offer using the relationship between risk and return, the warning signs regulators publish, and the documents and verifications a careful investor would demand. Explain what evidence would change your assessment and why social trust can make such offers persuasive.","choices":[],"explanation":"Coaching should push the learner to reason from risk and return, map each feature of the offer to a published red flag, and propose concrete verification steps rather than relying on the friend's experience.","rubric":[{"id":"risk-return","title":"Risk and return reasoning","description":"Explains why steady high returns with no losses are implausible for real risky assets and what such consistency usually signals.","weight":0.25,"coachingQuestions":["What does a 1%-a-month return with no losing months imply about risk?","Which legitimate assets behave like that?"]},{"id":"red-flags","title":"Regulatory red flags","description":"Maps the offer's features (consistent returns, recruitment bonuses, unregistered offering) to published fraud warning signs.","weight":0.3,"coachingQuestions":["Which features match published Ponzi-scheme warnings?","Why does recruitment pay matter?"]},{"id":"verification","title":"Verification steps","description":"Specifies concrete checks: registration of the offering and seller, audited statements, custody of assets, and an explanation of the strategy.","weight":0.25,"coachingQuestions":["Who holds the money, and who audits it?","How would you check registration and licensing?"]},{"id":"behavior","title":"Behavioral and social factors","description":"Analyzes how trust, affinity, and early payouts make such offers persuasive, and states what evidence would change the assessment.","weight":0.2,"coachingQuestions":["Why are early payouts persuasive?","What evidence would actually reassure a skeptic?"]}],"coachingPrompts":["Start from what returns that high and smooth would require.","Match each feature of the pitch to a specific warning sign.","Propose checks that do not depend on the promoter's word.","Keep the analysis educational rather than advising a specific decision."],"modelOutline":["Describe the offer's claimed returns and structure","Explain the risk-return relationship and what smooth high returns suggest","Map features to published fraud red flags","List verification steps and documents to request","Discuss affinity, trust, and what evidence would change the conclusion"],"sources":[{"id":"investor-gov-ponzi","title":"Ponzi Scheme","publisher":"U.S. Securities and Exchange Commission (Investor.gov)","url":"https://www.investor.gov/protect-your-investments/fraud/types-fraud/ponzi-scheme","accessedAt":"2026-10-21T06:00:00Z","usage":"publicDomain","evidenceLocator":"Red flags: high returns with little or no risk, overly consistent returns, unregistered investments, unlicensed sellers, secretive strategies"}],"tags":["fraud","risk-return","behavioral-finance","essay"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"business-v3-prepaid-insurance-001","category":"business","conceptID":"business.accounting-basics","conceptTitle":"Accounting basics","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"On January 1, a company pays $12,000 in cash for a one-year insurance policy. Under accrual accounting, how should the payment be reflected in January's financial statements?","choices":[{"id":"a","text":"A $12,000 insurance expense in January, because accrual accounting records costs in the month the cash is paid out.","rationale":"Recording the cost when cash is paid is cash-basis thinking; accrual accounting matches the expense to the coverage period."},{"id":"b","text":"No entry at all until December, because the policy's cost is recognized only after the full coverage period has ended.","rationale":"The cash payment and the prepaid asset are recorded at once, and expense is recognized month by month as coverage is used."},{"id":"c","text":"A $12,000 liability for unearned insurance, because the company still owes the insurer the remaining months of coverage.","rationale":"Unearned revenue is the insurer's liability; the buyer holds a prepaid asset, not a liability."},{"id":"d","text":"A $1,000 insurance expense for January, with the remaining $11,000 carried as a prepaid insurance asset.","rationale":"Correct. One-twelfth of the coverage is used in January; the rest remains an asset to be expensed later."}],"correctChoiceID":"d","explanation":"Under accrual accounting, an expense is recognized when the related benefit is used, not when cash is paid. Paying $12,000 for a year of coverage creates a prepaid insurance asset. Each month an adjusting entry moves the used portion, $1,000, from the asset to insurance expense. At the end of January the company reports $1,000 of expense and an $11,000 prepaid asset.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"openstax-adjusting-entries","title":"4.2 Discuss the Adjustment Process and Illustrate Common Types of Adjusting Entries (Principles of Accounting, Volume 1)","publisher":"OpenStax, Rice University","url":"https://openstax.org/books/principles-financial-accounting/pages/4-2-discuss-the-adjustment-process-and-illustrate-common-types-of-adjusting-entries","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Prepaid insurance is recorded as an asset and expensed as coverage is used, e.g., one month's share of a multi-month policy"}],"tags":["accrual-accounting","prepaid-expenses","adjusting-entries","matching"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"business-v3-loan-principal-002","category":"business","conceptID":"business.accounting-basics","conceptTitle":"Accounting basics","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"A small manufacturer repays $10,000 of principal on a bank loan in March. Interest for March was paid and recorded separately. How does the $10,000 principal repayment affect the company's financial statements?","choices":[{"id":"a","text":"Cash and loan liabilities each fall by $10,000, the outflow is a financing activity, and net income is unaffected.","rationale":"Correct. Repaying principal settles a liability; it is not an expense, and it appears under financing cash flows."},{"id":"b","text":"It is recorded as a $10,000 expense that lowers March net income, since paying down debt is a cost of doing business.","rationale":"Only interest is an expense. Principal repayment reduces a liability rather than generating an expense."},{"id":"c","text":"Cash and loan liabilities each fall by $10,000, but the outflow is an operating activity that also lowers net income.","rationale":"The balance-sheet effect is right, but principal repayment is a financing outflow and does not touch net income."},{"id":"d","text":"It reduces stockholders' equity by $10,000 and appears among investing cash flows, since lenders are treated like owners.","rationale":"Lenders are creditors, not owners; equity is unchanged, and the cash flow is classified as financing."}],"correctChoiceID":"a","explanation":"Repaying loan principal decreases cash and decreases the loan liability by the same amount, so the accounting equation stays balanced without any income-statement effect. Only interest is an expense; here it was recorded separately. On the statement of cash flows, principal repayment of notes or loans payable is a financing activity, while interest paid is classified as operating. Confusing debt repayment with an expense overstates costs and understates profit.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"openstax-cash-flow-activities","title":"16.2 Differentiate between Operating, Investing, and Financing Activities (Principles of Accounting, Volume 1)","publisher":"OpenStax, Rice University","url":"https://openstax.org/books/principles-financial-accounting/pages/16-2-differentiate-between-operating-investing-and-financing-activities","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Financing activities include principal repayment or redemption of notes or bonds payable"}],"tags":["cash-flow-statement","financing-activities","liabilities","net-income"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"business-v3-break-even-units-003","category":"business","conceptID":"business.unit-economics","conceptTitle":"Unit economics and pricing","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"A meal-kit startup sells each kit for $40. Ingredients, packaging, and delivery cost $25 per kit, and fixed monthly costs (rent, salaries, software) total $30,000. How many kits must it sell each month to break even?","choices":[{"id":"a","text":"750 kits, found by dividing the $30,000 of fixed costs by the $40 selling price of each kit.","rationale":"Dividing by price ignores the $25 of variable cost each kit consumes."},{"id":"b","text":"1,200 kits, found by dividing the $30,000 of fixed costs by the $25 variable cost of each kit.","rationale":"Variable cost is what each kit uses up, not what it contributes toward fixed costs."},{"id":"c","text":"2,000 kits, found by dividing the $30,000 of fixed costs by the $15 contribution margin per kit.","rationale":"Correct. Each kit contributes $40 - $25 = $15 toward fixed costs; $30,000 / $15 = 2,000."},{"id":"d","text":"No minimum, because each kit's $40 price already exceeds its $25 cost, so every sale is profitable.","rationale":"A positive margin per kit still has to cover $30,000 of fixed costs before the business earns a profit."}],"correctChoiceID":"c","explanation":"The break-even point in units equals total fixed costs divided by contribution margin per unit. Each kit sells for $40 and uses $25 of variable cost, so it contributes $15 toward fixed costs. $30,000 / $15 = 2,000 kits per month; sales beyond that generate profit. The same result in dollars is $80,000 of sales (2,000 x $40), or fixed costs divided by the 37.5% contribution margin ratio.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"openstax-break-even","title":"3.2 Calculate a Break-Even Point in Units and Dollars (Principles of Accounting, Volume 2)","publisher":"OpenStax, Rice University","url":"https://openstax.org/books/principles-managerial-accounting/pages/3-2-calculate-a-break-even-point-in-units-and-dollars","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Break-even units = total fixed costs / contribution margin per unit"}],"tags":["break-even","contribution-margin","unit-economics","fixed-costs"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"business-v3-five-forces-substitutes-004","category":"business","conceptID":"business.competitive-strategy","conceptTitle":"Competitive strategy","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"After high-quality video conferencing became cheap and reliable, many companies cut business air travel for internal meetings. In Michael Porter's five forces framework, which force does video conferencing chiefly represent for airlines?","choices":[{"id":"a","text":"Rivalry among existing competitors, since video platforms now compete with airlines for corporate travel budgets.","rationale":"Rivalry refers to competition among firms in the same industry, such as other airlines."},{"id":"b","text":"Threat of substitutes, since a different product meets the same underlying need for a meeting in another way.","rationale":"Correct. Substitutes perform the same or a similar function by a different means and cap industry profitability."},{"id":"c","text":"Threat of new entrants, since video companies have entered the air travel industry with a lower-cost model.","rationale":"Video firms do not enter the airline industry; they offer an alternative to flying."},{"id":"d","text":"Bargaining power of suppliers, since technology vendors can now raise the prices they charge airlines.","rationale":"Supplier power concerns the industry's inputs; video conferencing replaces the airlines' product instead."}],"correctChoiceID":"b","explanation":"Porter's five forces are rivalry among existing competitors, the threat of new entrants, the bargaining power of suppliers, the bargaining power of buyers, and the threat of substitutes. A substitute performs the same or a similar function as an industry's product by a different means. Video conferencing meets the need behind many business trips, a face-to-face meeting, without flying, so it limits how much airlines can charge business travelers. Because substitutes come from outside the industry, they are easy to overlook.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"hbs-isc-five-forces","title":"The Five Forces","publisher":"Institute for Strategy and Competitiveness, Harvard Business School","url":"https://www.isc.hbs.edu/strategy/business-strategy/Pages/the-five-forces.aspx","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Five forces: rivalry, threat of new entrants, supplier power, buyer power, and threat of substitutes that meet the same need in a different way"}],"tags":["five-forces","porter","substitutes","industry-analysis"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"business-v3-disruptive-innovation-005","category":"business","conceptID":"business.competitive-strategy","conceptTitle":"Competitive strategy","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"An entrant sells a simpler, cheaper product to customers whom incumbents consider too small or unprofitable to serve. The incumbents keep improving premium products for their best customers, and the entrant later moves upmarket and wins their mainstream customers. Which concept describes this pattern?","choices":[{"id":"a","text":"Sustaining innovation, in which a firm improves its products along the dimensions its best customers already value.","rationale":"This describes what the incumbents were doing, which is why they missed the entrant."},{"id":"b","text":"First-mover advantage, in which the earliest entrant to a market wins by locking in customers before rivals arrive.","rationale":"The incumbents arrived first; the entrant succeeded by starting where they were not competing."},{"id":"c","text":"Blue ocean strategy, in which a firm escapes competition by creating demand in an uncontested market space.","rationale":"Blue ocean strategy avoids head-to-head competition, whereas this entrant eventually takes the incumbents' customers."},{"id":"d","text":"Disruptive innovation, in which an entrant starts at the low end or in a new market and then moves upmarket.","rationale":"Correct. Clayton Christensen's theory describes entrants who gain footholds the incumbents ignore and then move up."}],"correctChoiceID":"d","explanation":"Clayton Christensen's theory of disruptive innovation describes entrants that gain a foothold at the low end of a market or in a new market with simpler, more affordable offerings. Incumbents, focused on sustaining innovations for their most demanding and profitable customers, rationally ignore these segments. As the entrant's product improves, it moves upmarket and attracts mainstream customers. Not every successful newcomer is disruptive; the defining feature is this foothold-then-upmarket path.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"christensen-disruptive-innovation","title":"Disruptive Innovation Theory","publisher":"Clayton Christensen Institute","url":"https://www.christenseninstitute.org/theory/disruptive-innovation/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Disruption: entrants start with simpler, cheaper offerings for overlooked or new customers, then move upmarket while incumbents focus on sustaining improvements"}],"tags":["disruptive-innovation","christensen","strategy","incumbents"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"business-v3-agency-problem-006","category":"business","conceptID":"business.management-org","conceptTitle":"Management and incentives","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"A board ties most of its CEO's pay to the share price at the end of the coming year. The CEO then cuts research spending that would have paid off over a decade, lifting near-term earnings. Which concept best explains the problem the board created?","choices":[{"id":"a","text":"An agency problem, in which an agent's incentives diverge from the long-term interests of the principals.","rationale":"Correct. The CEO (agent) responds to a short-term pay formula at the expense of shareholders (principals)."},{"id":"b","text":"Adverse selection, in which a board hires a weaker CEO because it cannot observe candidates' true ability.","rationale":"Adverse selection concerns hidden information before a contract; here the issue is behavior induced by the pay design."},{"id":"c","text":"The sunk cost fallacy, in which past research spending is wrongly used to justify continuing an unprofitable project.","rationale":"The CEO is cutting research, not continuing it because of past spending."},{"id":"d","text":"Diseconomies of scale, in which unit costs rise as a firm grows too large for its managers to coordinate well.","rationale":"The problem stems from incentives, not from the firm's size or coordination costs."}],"correctChoiceID":"a","explanation":"Agency theory studies relationships in which a principal, such as shareholders, delegates work to an agent, such as a CEO, whose interests may differ. When pay depends heavily on next year's share price, the agent gains from boosting short-term results even at the expense of long-term value. Cutting research to inflate near-term earnings is a textbook agency cost created by the incentive design. Boards often respond with longer vesting periods, multi-year metrics, or clawbacks.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"britannica-agency-theory","title":"Agency theory","publisher":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/agency-theory","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Agency theory examines principal-agent relationships in which an agent's interests may conflict with the principal's"}],"tags":["agency-theory","incentives","executive-pay","corporate-governance"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"business-v3-price-elasticity-revenue-007","category":"business","conceptID":"business.unit-economics","conceptTitle":"Unit economics and pricing","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"A cafe raises the price of its signature drink from $5.00 to $5.50, and weekly sales fall from 1,000 drinks to 750. What happened to weekly revenue from the drink, and what does that suggest about demand in this price range?","choices":[{"id":"a","text":"Revenue rose about 10%, because each drink now brings in 10% more money, showing demand is price inelastic.","rationale":"Revenue is price times quantity; the 25% drop in quantity outweighs the 10% price rise."},{"id":"b","text":"Revenue fell to $4,125 from $5,000, suggesting demand is price elastic, since quantity fell faster than price rose.","rationale":"Correct. $5.50 x 750 = $4,125; a 25% quantity drop against a 10% price rise indicates elastic demand."},{"id":"c","text":"Revenue fell by exactly 15%, because the 25% drop in quantity is offset by the 10% price rise, showing unit elasticity.","rationale":"Percentage changes do not simply subtract; revenue actually fell 17.5%, and unit elasticity would leave revenue unchanged."},{"id":"d","text":"Revenue was unchanged, because a higher price and a lower quantity always offset each other along any demand curve.","rationale":"Revenue stays constant only when demand is unit elastic; it is not a general rule."}],"correctChoiceID":"b","explanation":"Total revenue equals price times quantity. Before the change it was $5.00 x 1,000 = $5,000; after, $5.50 x 750 = $4,125, a 17.5% decline. Quantity fell by a larger percentage (25%) than price rose (10%), so demand in this range is price elastic, and raising price lowers revenue. Profit could still rise if costs fall enough with lower volume, but that is a separate calculation.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"openstax-elasticity-pricing","title":"5.3 Elasticity and Pricing (Principles of Economics 3e)","publisher":"OpenStax, Rice University","url":"https://openstax.org/books/principles-economics-3e/pages/5-3-elasticity-and-pricing","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Total revenue is price times quantity; with elastic demand a price increase lowers total revenue"}],"tags":["price-elasticity","total-revenue","pricing","microeconomics"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"business-v3-discounter-entry-essay-008","category":"business","conceptID":"business.competitive-strategy","conceptTitle":"Competitive strategy","type":"essay","dimension":"synthesis","difficulty":"advanced","prompt":"A regional grocery chain with loyal customers and aging stores learns that a national discount chain will open three stores in its market next year. Using Porter's five forces and the distinction between competing on cost and competing on differentiation, analyze the threat and recommend a positioning. Specify the evidence you would gather (customer data, unit economics, competitor costs) and the signals that would tell you the strategy is failing.","choices":[],"explanation":"Coaching should push the learner to analyze industry structure before prescribing tactics, choose a coherent position rather than trying to beat the discounter on everything, and define measurable signals of success or failure.","rubric":[{"id":"industry-analysis","title":"Industry structure","description":"Applies the five forces concretely (rivalry, buyers, suppliers, entrants, substitutes) to the local grocery market and the entrant.","weight":0.3,"coachingQuestions":["Which force does the entrant change most?","How much power do shoppers have to switch?"]},{"id":"positioning","title":"Coherent positioning","description":"Chooses between cost-based and differentiation-based competition (or a defensible niche) and explains why it fits the chain's capabilities.","weight":0.3,"coachingQuestions":["Can the chain match the discounter's costs?","What do loyal customers value that a discounter cannot easily copy?"]},{"id":"evidence","title":"Evidence and unit economics","description":"Identifies data to gather, including basket analysis, margins by category, store-level economics, and competitor cost structure.","weight":0.25,"coachingQuestions":["Which product categories are most exposed?","What would a price match cost in margin?"]},{"id":"signals","title":"Failure signals","description":"Defines leading indicators and decision points for revising the strategy.","weight":0.15,"coachingQuestions":["What metric would move first if the strategy failed?","When would you change course?"]}],"coachingPrompts":["Analyze structure before tactics.","Pick a position and accept its trade-offs.","Ground claims in unit economics, not slogans.","Name measurable warning signals in advance."],"modelOutline":["Summarize the market and the entrant's likely advantages","Apply the five forces to the local grocery industry","Evaluate cost and differentiation positions against the chain's capabilities","Specify evidence and unit-economics analysis to gather","Recommend a positioning with milestones and failure signals"],"sources":[{"id":"hbs-isc-five-forces","title":"The Five Forces","publisher":"Institute for Strategy and Competitiveness, Harvard Business School","url":"https://www.isc.hbs.edu/strategy/business-strategy/Pages/the-five-forces.aspx","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Five forces: rivalry, threat of new entrants, supplier power, buyer power, and threat of substitutes that meet the same need in a different way"},{"id":"openstax-break-even","title":"3.2 Calculate a Break-Even Point in Units and Dollars (Principles of Accounting, Volume 2)","publisher":"OpenStax, Rice University","url":"https://openstax.org/books/principles-managerial-accounting/pages/3-2-calculate-a-break-even-point-in-units-and-dollars","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Break-even units = total fixed costs / contribution margin per unit"}],"tags":["competitive-strategy","five-forces","retail","essay"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"recipe-v3-altitude-boiling-001","category":"recipe","conceptID":"recipe.heat-transfer","conceptTitle":"Heat and cooking","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"A cook in Denver (about 5,300 feet above sea level) finds that pasta and dried beans take noticeably longer at a full boil than they did at sea level. What best explains this?","choices":[{"id":"a","text":"Lower air pressure lets water boil at a lower temperature, so food in boiling water cooks more slowly.","rationale":"Correct. Boiling water at altitude is cooler than at sea level, so heat reaches the food more slowly."},{"id":"b","text":"Thinner air carries heat away from the pot so quickly that the water never truly reaches a full boil.","rationale":"The water does boil; it simply boils at a lower temperature because of reduced pressure."},{"id":"c","text":"Water at altitude boils at a higher temperature, which toughens starches and proteins and slows cooking.","rationale":"Lower pressure lowers, not raises, water's boiling point."},{"id":"d","text":"Drier air at altitude dries the food's surface, which slows the transfer of heat from water into the food.","rationale":"Food submerged in boiling water is not dried by the surrounding air; the water's temperature is the issue."}],"correctChoiceID":"a","explanation":"Water boils when its vapor pressure equals the surrounding air pressure. At higher altitudes atmospheric pressure is lower, so water boils at a lower temperature: already 208 F at 2,000 feet instead of 212 F at sea level, and lower still in Denver. Because the boiling water is cooler, foods cooked in it take longer to reach doneness. Turning up the heat does not help, because water cannot exceed its boiling point; cooks compensate with longer times or a pressure cooker.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"usda-fsis-high-altitude","title":"High Altitude Cooking","publisher":"USDA Food Safety and Inspection Service","url":"https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/high-altitude-cooking","accessedAt":"2026-10-21T06:00:00Z","usage":"publicDomain","evidenceLocator":"As altitude increases and atmospheric pressure decreases, water's boiling point decreases (208 F at 2,000 feet), so cooking time must be increased"}],"tags":["altitude","boiling-point","pressure","heat-transfer"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"recipe-v3-overmixed-muffins-002","category":"recipe","conceptID":"recipe.ingredient-function","conceptTitle":"Ingredient function","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"A baker's muffins come out tough, with long tunnels running through the crumb and peaked tops. She beat the batter with an electric mixer until it was completely smooth. What is the most likely cause?","choices":[{"id":"a","text":"Too little mixing left pockets of dry flour that expanded into tunnels as the muffins baked in the oven.","rationale":"The batter was beaten smooth, so undermixing is not the problem; dry pockets do not form tunnels."},{"id":"b","text":"Prolonged mixing developed the flour's gluten network, giving a tough, chewy crumb riddled with tunnels.","rationale":"Correct. Muffin batter should be stirred only until moistened; overbeating builds gluten and causes tunnels."},{"id":"c","text":"Smooth batter traps too little air, so the leavening could not react and the muffins collapsed inward.","rationale":"Chemical leaveners react with liquid and heat regardless of how smooth the batter is."},{"id":"d","text":"Overmixing dissolved the sugar too completely, and fully dissolved sugar hardens into a tough crumb.","rationale":"Dissolved sugar tenderizes baked goods; it does not toughen them."}],"correctChoiceID":"b","explanation":"Wheat flour forms gluten when its proteins are hydrated and worked. Muffin and quick-bread batters are meant to be mixed only until the dry ingredients are moistened, leaving the batter lumpy. Beating until smooth develops the gluten network, producing a tough, chewy texture, peaked tops, and long tunnels where gas travels through the strengthened batter. The fix is gentle, minimal mixing.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"usu-quick-bread","title":"What is Quick Bread? 6 Tips for Baking the Perfect Loaf Every Time!","publisher":"Utah State University Extension","url":"https://extension.usu.edu/createbetterhealth/blog/whatisquickbread","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Overmixing can develop the gluten in the flour, resulting in a tough and chewy quick bread"},{"id":"msstate-quick-breads","title":"4-H Bread Project: Fun with Quick Breads","publisher":"Mississippi State University Extension","url":"https://extension.msstate.edu/publications/4-h-bread-project-fun-quick-breads","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Overbeating muffin batter causes heavy, irregular grain with tunnels and peaked tops"}],"tags":["gluten","quick-breads","mixing","baking"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"recipe-v3-soda-vs-powder-003","category":"recipe","conceptID":"recipe.ingredient-function","conceptTitle":"Ingredient function","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"A pancake recipe made with plain milk, and no buttermilk, yogurt, or other acidic ingredient, calls for baking powder. A cook substitutes the same amount of baking soda. What is the most likely result?","choices":[{"id":"a","text":"Better rise, because baking soda is a stronger, double-acting version of baking powder that releases gas twice.","rationale":"Double-acting describes some baking powders; baking soda is a single base, not a stronger baking powder."},{"id":"b","text":"Identical pancakes, because baking soda and baking powder are the same chemical sold under two different names.","rationale":"Baking powder contains baking soda plus an acid; they are not the same product."},{"id":"c","text":"Faster rise, because baking soda reacts with the milk's lactose sugar to give off a quick burst of carbon dioxide.","rationale":"Baking soda reacts with acids, not with lactose; plain milk supplies little acid."},{"id":"d","text":"Poor rise, because baking soda needs an acid to react with and this batter supplies almost none.","rationale":"Correct. Baking powder carries its own acid; baking soda alone has little to react with in plain milk."}],"correctChoiceID":"d","explanation":"Baking soda is sodium bicarbonate, a base that releases carbon dioxide when it reacts with an acid. Baking powder combines a carbonate or bicarbonate base with a weak acid, so it can leaven batters that contain no acidic ingredient. Using baking soda alone in a batter without an acidic ingredient leaves it little to react with, so the pancakes rise poorly. That is why recipes with buttermilk or yogurt often use baking soda, and recipes with plain milk use baking powder.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"britannica-baking-powder","title":"Baking powder","publisher":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/baking-powder","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Baking powder consists of a mixture of a base (carbonate or bicarbonate) and a weak acid"}],"tags":["leavening","baking-soda","baking-powder","acid-base"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"recipe-v3-pressure-canning-004","category":"recipe","conceptID":"recipe.food-preservation","conceptTitle":"Food preservation and safety","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"A home canner wants to put up plain green beans in a boiling-water canner, as she does for pickles and jams. Why do food-safety authorities insist on a pressure canner for plain green beans?","choices":[{"id":"a","text":"Green beans hold more sugar than jams, so they need higher pressure to stop fermentation inside the sealed jar.","rationale":"The issue is acidity and bacterial spores, not sugar or fermentation."},{"id":"b","text":"Boiling water would overcook the beans, and pressure canning shortens processing to keep the beans crisp.","rationale":"Pressure canning is a safety requirement, not a texture technique."},{"id":"c","text":"Low-acid foods can harbor botulinum spores that survive 212 F; only pressure canning reaches about 240 F.","rationale":"Correct. Spores of Clostridium botulinum survive boiling and can produce toxin in sealed low-acid jars."},{"id":"d","text":"Pressure is needed to force the lids to seal, because low-acid foods release gases that keep jars open.","rationale":"Jars seal in both methods; the difference is the temperature reached inside the jar."}],"correctChoiceID":"c","explanation":"Clostridium botulinum spores survive boiling at 212 F, and in a sealed, oxygen-free jar of low-acid food they can germinate and produce botulinum toxin. Acid foods such as pickles and most jams are safe in a boiling-water canner because their acidity prevents spore growth. Plain vegetables such as green beans are low-acid, so they must be processed at about 240 to 250 F, temperatures reachable only under pressure. That is why the CDC and USDA-backed guidance call pressure canning the only safe method for low-acid foods.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"cdc-home-canned-foods","title":"Home-Canned Foods","publisher":"U.S. Centers for Disease Control and Prevention","url":"https://www.cdc.gov/botulism/prevention/home-canned-foods.html","accessedAt":"2026-10-21T06:00:00Z","usage":"publicDomain","evidenceLocator":"Pressure canning is the only recommended method for low-acid foods; a boiling-water canner will not protect against botulism"},{"id":"nchfp-ensuring-safe-canned-foods","title":"Ensuring Safe Canned Foods","publisher":"National Center for Home Food Preservation (University of Georgia)","url":"https://nchfp.uga.edu/how/can/general-information/ensuring-safe-canned-foods/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Botulinum spores are very hard to destroy at boiling-water temperatures; low-acid foods should be sterilized at 240-250 F, attainable with pressure canners"}],"tags":["canning","botulism","food-safety","low-acid-foods"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"recipe-v3-anachronistic-ingredient-005","category":"recipe","conceptID":"recipe.culinary-history","conceptTitle":"Culinary history","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"A historical novel set in Naples in 1450 describes a cook preparing the evening meal. Which detail would be anachronistic in that scene?","choices":[{"id":"a","text":"Tomatoes simmered into a sauce for supper.","rationale":"Correct. Tomatoes come from the Americas and were introduced to Europe only in the early sixteenth century."},{"id":"b","text":"Black pepper ground over a roasted bird.","rationale":"Black pepper is an Indian spice traded to Europe since antiquity; Venetian and Genoese merchants distributed it in the Middle Ages."},{"id":"c","text":"Lemons squeezed over fish fried in a pan.","rationale":"Lemons and other citrus fruits are Eurasian; Europeans later carried them to the Americas, not the reverse."},{"id":"d","text":"Rice simmered in broth into a thick soup.","rationale":"Rice is an Old World staple that Europeans later introduced to the Americas."}],"correctChoiceID":"a","explanation":"The wild tomato originated in the Andes of South America and reached Europe only through the Columbian Exchange, introduced by the Spanish in the early sixteenth century. Black pepper, by contrast, had been traded from India to Europe since antiquity, while citrus fruits and rice are Old World crops that Europeans later carried westward to the Americas. Spotting anachronisms requires knowing which foods crossed the Atlantic, and in which direction, after 1492. Many cuisines now strongly identified with Europe depend on American plants.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"britannica-tomato","title":"Tomato","publisher":"Encyclopaedia Britannica","url":"https://www.britannica.com/plant/tomato","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"The wild tomato originated in the Andes of South America and was introduced to Europe by the Spanish in the early 16th century"},{"id":"britannica-black-pepper","title":"Black pepper","publisher":"Encyclopaedia Britannica","url":"https://www.britannica.com/plant/black-pepper-plant","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Black pepper, native to India's Malabar Coast, was traded to Europe since antiquity; in the Middle Ages Venetians and Genoese were its main European distributors"},{"id":"britannica-columbian-exchange","title":"Columbian Exchange","publisher":"Encyclopaedia Britannica","url":"https://www.britannica.com/event/Columbian-exchange","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Transfer of plants, animals, and diseases between the Americas and Afro-Eurasia after 1492"}],"tags":["columbian-exchange","tomato","italian-cuisine","anachronism"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"recipe-v3-nixtamalization-006","category":"recipe","conceptID":"recipe.culinary-history","conceptTitle":"Culinary history","type":"multipleChoice","dimension":"application","difficulty":"advanced","prompt":"Maize became a staple in parts of southern Europe and the U.S. South, where pellagra, a niacin-deficiency disease, became widespread. In Mesoamerica, where maize had been a staple for millennia, pellagra was rare. Which practice best explains the difference?","choices":[{"id":"a","text":"Mesoamerican farmers grew maize varieties containing far more niacin, which European farmers never imported.","rationale":"The protective difference lay in how maize was processed, not in special high-niacin varieties."},{"id":"b","text":"Mesoamerican cooks soaked and cooked maize in an alkaline solution such as lime, freeing its bound niacin.","rationale":"Correct. Nixtamalization makes maize niacin available; populations that adopted maize without it suffered pellagra."},{"id":"c","text":"Mesoamerican cooks ground maize far more finely, so digestive enzymes could reach the niacin in each kernel.","rationale":"Grinding alone does not release the bound niacin; alkaline treatment does."},{"id":"d","text":"Mesoamerican cooks fermented most maize into beer, and the yeasts made enough niacin to prevent deficiency.","rationale":"The protective practice was alkaline cooking, which remains the basis of masa and tortillas."}],"correctChoiceID":"b","explanation":"Much of the niacin in maize is not available to the body unless the grain is processed. Mesoamerican cooks traditionally cooked maize in an alkaline solution such as lime (calcium hydroxide), a process called nixtamalization that makes niacin available and increases calcium. Where maize-heavy diets spread without this technique, as in the U.S. South into the twentieth century, pellagra became common. The case shows that foodways carry nutritional knowledge, not just ingredients.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"tmc-pellagra-nutshell","title":"Texas Medical Center Library Centennial: Pellagra in a nutshell","publisher":"McGovern Historical Center, Texas Medical Center Library","url":"https://library.tmc.edu/mcgovern/2014/07/24/texas-medical-center-library-centennial-pellagra-in-a-nutshell/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Native American populations that relied on corn developed nixtamalization, an alkaline treatment that makes corn's niacin available and spared them pellagra; pellagra was common in the American South"},{"id":"unl-nixtamalization","title":"Effect of Nixtamalization on Mycotoxin-Contaminated Corn (G2329)","publisher":"University of Nebraska-Lincoln Extension","url":"https://extensionpubs.unl.edu/publication/g2329/na/html/view","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Originating in Mesoamerica, nixtamalization is the alkaline (lime) cooking of corn; it increases calcium and makes niacin available"}],"tags":["nixtamalization","pellagra","maize","food-history"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"recipe-v3-pasteurized-vs-uht-007","category":"recipe","conceptID":"recipe.food-preservation","conceptTitle":"Food preservation and safety","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"Conventionally pasteurized milk must be refrigerated and keeps a couple of weeks, while ultra-high-temperature (UHT) milk in sealed aseptic cartons can sit unopened on a shelf for months. What explains the difference?","choices":[{"id":"a","text":"Conventional pasteurization adds preservatives that break down over time, while UHT milk relies on its carton alone.","rationale":"Neither process depends on added preservatives; the difference is the heat treatment and packaging."},{"id":"b","text":"UHT milk has its water removed and later restored, while pasteurized milk keeps all its water and spoils faster.","rationale":"UHT milk is not dehydrated; it is heated briefly to a much higher temperature."},{"id":"c","text":"Pasteurization targets pathogens and the milk can still spoil; UHT heat plus sterile packing makes it commercially sterile.","rationale":"Correct. Pasteurization targets disease-causing microbes; UHT plus aseptic packaging makes milk commercially sterile."},{"id":"d","text":"Conventional pasteurization uses higher heat that damages milk proteins, making them easier for bacteria to digest.","rationale":"Conventional pasteurization uses lower temperatures than UHT, not higher."}],"correctChoiceID":"c","explanation":"Pasteurization heats milk enough to destroy disease-causing bacteria, but pasteurized milk can still spoil readily, so it needs refrigeration and has a limited shelf life. Ultra-high-temperature processing heats milk to roughly twice the temperature of normal pasteurization and, combined with aseptic filling into sealed packaging, produces a commercially sterile product that is shelf-stable until opened. Once opened, UHT milk must be refrigerated like any other milk. Ultra-pasteurized milk falls in between: longer-lasting, but still refrigerated.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"clemson-milk-handling","title":"Safe Handling of Milk & Dairy Products","publisher":"Clemson University Cooperative Extension (Home & Garden Information Center)","url":"https://hgic.clemson.edu/factsheet/safe-handling-of-milk-dairy-products/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Pasteurization destroys disease-causing bacteria but pasteurized milk can readily spoil and must be refrigerated; UHT milk is flash-sterilized and packed in sterilized airtight containers"},{"id":"idfa-pasteurization","title":"Pasteurization","publisher":"International Dairy Foods Association","url":"https://www.idfa.org/pasteurization","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Aseptic (UHT) processing fills milk under aseptic conditions into hermetically sealed packaging; it is shelf stable until opened, unlike ultra-pasteurized milk"}],"tags":["pasteurization","uht","food-preservation","dairy"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"recipe-v3-dish-origins-essay-008","category":"recipe","conceptID":"recipe.culinary-history","conceptTitle":"Culinary history","type":"essay","dimension":"synthesis","difficulty":"advanced","prompt":"Many dishes come with tidy origin stories: a named inventor, a single date, a famous occasion. Choose a widely eaten dish or ingredient (for example, tomato sauce in Italian cooking, chili peppers in South or East Asian cuisines, or maize in African diets) and build a historically careful account of how it became part of a cuisine. Distinguish documented evidence (cookbooks, trade records, botanical and archaeological evidence) from legend, and explain how the Columbian Exchange, trade, migration, or colonialism shaped its adoption.","choices":[],"explanation":"Coaching should push the learner to treat origin stories as claims to test, use dated evidence, and explain adoption as a process shaped by trade, ecology, and power rather than a single moment of invention.","rubric":[{"id":"evidence-legend","title":"Evidence versus legend","description":"Separates documented evidence (dated cookbooks, records, botanical evidence) from anecdotes and legends, and explains how each was tested.","weight":0.3,"coachingQuestions":["What is the earliest dated evidence for your dish?","Which part of the popular story has no contemporary source?"]},{"id":"process","title":"Adoption as a process","description":"Explains adoption over time, including initial reception, adaptation, and spread across social groups or regions.","weight":0.25,"coachingQuestions":["Who adopted the ingredient first, and why?","How did the dish change as it spread?"]},{"id":"structural-forces","title":"Trade, migration, and power","description":"Connects adoption to the Columbian Exchange, trade networks, migration, or colonial systems with specific evidence.","weight":0.25,"coachingQuestions":["How did the ingredient physically arrive?","Who benefited from or controlled its spread?"]},{"id":"uncertainty","title":"Uncertainty and limits","description":"Acknowledges gaps in the record and how ordinary people's cooking may be under-documented.","weight":0.2,"coachingQuestions":["Whose cooking left no written trace?","What would change your account?"]}],"coachingPrompts":["Date your evidence before telling the story.","Treat a named inventor as a claim to test.","Explain how the ingredient traveled, not just that it did.","Note whose foodways the sources omit."],"modelOutline":["Introduce the dish or ingredient and its popular origin story","Present the earliest dated evidence and assess the legend","Trace transmission through exchange, trade, or migration","Explain adaptation and spread within the cuisine","Conclude with what remains uncertain and why"],"sources":[{"id":"britannica-columbian-exchange","title":"Columbian Exchange","publisher":"Encyclopaedia Britannica","url":"https://www.britannica.com/event/Columbian-exchange","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Transfer of plants, animals, and diseases between the Americas and Afro-Eurasia after 1492"},{"id":"britannica-tomato","title":"Tomato","publisher":"Encyclopaedia Britannica","url":"https://www.britannica.com/plant/tomato","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"The wild tomato originated in the Andes of South America and was introduced to Europe by the Spanish in the early 16th century"}],"tags":["culinary-history","columbian-exchange","evidence","essay"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"obscure-v3-hokulea-wayfinding-001","category":"obscure","conceptID":"obscure.knowledge-systems","conceptTitle":"Indigenous knowledge systems","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"In 1976 the double-hulled voyaging canoe Hokule'a sailed from Hawai'i to Tahiti, navigated by Mau Piailug without compass, charts, or other instruments. What did the voyage most directly demonstrate for debates about how Polynesia was settled?","choices":[{"id":"a","text":"That Polynesia was settled mainly from South America, as raft experiments decades earlier had suggested.","rationale":"The voyage tested Polynesian navigation methods on a Polynesian route; it did not support an American origin."},{"id":"b","text":"That ancient Polynesians must have used magnetic compasses, since open-ocean routes are impossible without one.","rationale":"Piailug sailed without a compass, showing that instrument-free navigation could work."},{"id":"c","text":"That most islands were reached by accidental drift, since the canoe repeatedly lost its way before landfall.","rationale":"The canoe made a planned landfall in Tahiti; its success counted against the drift hypothesis."},{"id":"d","text":"That deliberate long-distance voyages guided by stars, winds, and swells were feasible, countering drift theories.","rationale":"Correct. The voyage showed that intentional, instrument-free navigation over thousands of miles was possible."}],"correctChoiceID":"d","explanation":"Some mid-twentieth-century scholars argued that Polynesian islands were settled largely by accidental drift because long, deliberate voyages without instruments seemed impossible. In 1976 Hokule'a, a reconstructed voyaging canoe, sailed from Hawai'i to Tahiti in about a month, navigated by master navigator Mau Piailug of Satawal in Micronesia, who read the stars, winds, waves, and clouds. The voyage did not prove how every island was settled, but it demonstrated that purposeful two-way voyaging with traditional methods was feasible. It also helped revive Hawaiian wayfinding traditions.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"pvs-1976-voyage","title":"1976: Hawai'i to Tahiti","publisher":"Polynesian Voyaging Society","url":"https://archive.hokulea.com/finney76.html","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Ben Finney: the canoe was guided without instruments; the voyage demonstrated planned long-distance voyaging and turned the tide against the accidental-settlement hypothesis"},{"id":"pvs-1976-50th-anniversary","title":"Polynesian Voyaging Society Honors the 50th Anniversary of Hokule'a's 1976 Maiden Voyage to Tahiti","publisher":"Polynesian Voyaging Society","url":"https://hokulea.com/polynesian-voyaging-society-honors-the-50th-anniversary-of-hokule%CA%BBas-1976-maiden-voyage-to-tahiti/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Departed May 1, 1976, guided by master navigator Mau Piailug of Satawal by stars, winds, waves, and clouds; the voyage challenged theories of accidental drift"}],"tags":["wayfinding","polynesia","navigation","hokulea"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"obscure-v3-potlatch-ban-002","category":"obscure","conceptID":"obscure.ritual-social-practice","conceptTitle":"Ritual and social practice","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"From 1885 until 1951, Canada's Indian Act outlawed the potlatch of Northwest Coast peoples. A historian argues that the ban disrupted Indigenous systems of law and government, not merely festivities. Which feature of the potlatch gives the strongest support for that argument?","choices":[{"id":"a","text":"Marriages, inherited names, and the standing up of new chiefs were publicly confirmed before invited witnesses.","rationale":"Correct. If status, rights, and leadership were confirmed through public witnessing, outlawing the gathering interfered with governance itself."},{"id":"b","text":"Officials of the period condemned the giving away of large quantities of goods at these gatherings as wasteful.","rationale":"This records an objection officials raised to the ceremony, not evidence of how it ordered Indigenous law or leadership."},{"id":"c","text":"Guests traveled from many villages for days of feasting, dancing, and the display of ceremonial masks and regalia.","rationale":"Accurate, but this describes the celebration itself; it does not show that legal or political business was being done."},{"id":"d","text":"Government agents and missionaries regarded the ceremonies as an obstacle to the assimilation of Indigenous peoples.","rationale":"This explains why officials wanted the ban, not what the potlatch did within Indigenous societies."}],"correctChoiceID":"a","explanation":"Among Northwest Coast peoples, the potlatch is a central institution in which hosts distribute gifts and invited guests serve as witnesses to births, marriages, name-giving, the standing up of new chiefs, and deaths. Because that public witnessing is how status, rights, and leadership were confirmed, outlawing it interfered with governance, not just with celebration. The feasting and dancing, the gift-giving that officials called wasteful, and the goal of assimilation are all real parts of the story, but they describe the festivities or the motives for the ban rather than the potlatch's legal and political role. Canada banned the potlatch from 1885 to 1951; many communities continued potlatching in secret, and regalia confiscated under the ban later became the focus of repatriation.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"canadian-encyclopedia-potlatch-ban","title":"Potlatch Ban","publisher":"The Canadian Encyclopedia","url":"https://www.thecanadianencyclopedia.ca/en/article/potlatch-ban","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"The Indian Act banned the potlatch from 1885 until the 1951 revision; officials and missionaries saw it as an obstacle to assimilation"},{"id":"britannica-potlatch","title":"Potlatch","publisher":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/potlatch","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Ceremonial distribution of property and gifts to affirm or reaffirm social status among Indigenous peoples of the Northwest Pacific coast"},{"id":"umista-potlatch-collection","title":"The History of the Potlatch Collection","publisher":"U'mista Cultural Society","url":"https://www.umista.ca/pages/collection-history","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"The potlatch marks births, marriages, name-giving, the standing up of a new chief, and deaths before invited witnesses; regalia confiscated under the ban were later repatriated to the Kwakwaka'wakw"}],"tags":["potlatch","indian-act","colonialism","northwest-coast"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"obscure-v3-dia-de-muertos-003","category":"obscure","conceptID":"obscure.ritual-social-practice","conceptTitle":"Ritual and social practice","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"UNESCO's listing of Mexico's 'Indigenous festivity dedicated to the dead' describes families preparing altars and offerings at the end of October and beginning of November. Which interpretation best fits the practice as UNESCO describes it?","choices":[{"id":"a","text":"A Mexican adaptation of Halloween costume customs, introduced from the United States during the twentieth century.","rationale":"The festivity has deep Indigenous and colonial-era roots; it is not a borrowing of U.S. Halloween."},{"id":"b","text":"A solemn period of mourning in which families avoid food, music, and decoration out of fear of the dead.","rationale":"The celebration is festive, with food, flowers, and decoration offered to welcome the dead."},{"id":"c","text":"A festive welcoming of returning souls of the dead that blends Indigenous traditions with Catholic observances.","rationale":"Correct. UNESCO describes offerings for returning souls and a fusion of pre-Hispanic and Catholic practice."},{"id":"d","text":"A purely Catholic feast imported from Spain, with no roots in pre-Hispanic beliefs about death and the dead.","rationale":"UNESCO emphasizes the festivity's Indigenous roots alongside its Catholic calendar."}],"correctChoiceID":"c","explanation":"UNESCO inscribed the Indigenous festivity dedicated to the dead on its intangible heritage lists. As it describes the practice, families welcome the temporary return of deceased relatives' souls with altars, food, flowers, and other offerings around the start of November. The timing coincides with the Catholic All Saints' and All Souls' days, and the festivity merges pre-Hispanic beliefs with Catholic observance. Reading it as borrowed Halloween or as fearful mourning misses both its meaning and its history.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"unesco-indigenous-festivity-dead","title":"Indigenous festivity dedicated to the dead","publisher":"UNESCO Intangible Cultural Heritage","url":"https://ich.unesco.org/en/RL/indigenous-festivity-dedicated-to-the-dead-00054","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Families welcome the temporary return of deceased relatives' souls with altars and offerings at the end of October and beginning of November; blends pre-Hispanic and Catholic traditions"}],"tags":["dia-de-muertos","intangible-heritage","mexico","syncretism"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"obscure-v3-rosetta-stone-004","category":"obscure","conceptID":"obscure.language-meaning","conceptTitle":"Language and meaning","type":"multipleChoice","dimension":"application","difficulty":"foundation","prompt":"Why did the Rosetta Stone make it possible for scholars such as Jean-Francois Champollion to decipher Egyptian hieroglyphs?","choices":[{"id":"a","text":"It was an ancient bilingual dictionary listing each hieroglyphic sign beside its Latin equivalent.","rationale":"The stone records a royal decree, not a dictionary, and it contains no Latin."},{"id":"b","text":"It carries one decree in hieroglyphic, Demotic, and Greek, and scholars could already read the Greek.","rationale":"Correct. The known Greek text gave a parallel key to the two Egyptian scripts."},{"id":"c","text":"It was written in three languages (Greek, Latin, and Egyptian), so any one could unlock the others.","rationale":"It uses three scripts but two languages, Egyptian and Greek; there is no Latin text."},{"id":"d","text":"It labeled every hieroglyph with a picture of the object it named, proving the script was purely pictorial.","rationale":"Decipherment showed that hieroglyphs include sound signs, not only pictures of objects."}],"correctChoiceID":"b","explanation":"The Rosetta Stone, carved in 196 BCE, records a decree of Ptolemy V in three scripts: hieroglyphic, Demotic, and ancient Greek. Because scholars could read Greek, the stone provided a parallel text against which the Egyptian scripts could be compared. Champollion recognized that some hieroglyphic signs were alphabetic, some syllabic, and some determinative (standing for a whole idea). A common error is to say the stone has three languages; it has two languages written in three scripts.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"britannica-rosetta-stone","title":"Rosetta Stone","publisher":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/Rosetta-Stone","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Decree of Ptolemy V in hieroglyphic, demotic, and Greek; the Greek text provided the key used to decipher Egyptian scripts"}],"tags":["rosetta-stone","decipherment","hieroglyphs","egypt"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"obscure-v3-linear-a-b-005","category":"obscure","conceptID":"obscure.language-meaning","conceptTitle":"Language and meaning","type":"multipleChoice","dimension":"application","difficulty":"advanced","prompt":"Michael Ventris deciphered the Bronze Age Aegean script Linear B in 1952, but the related Linear A remains undeciphered. What best explains the difference?","choices":[{"id":"a","text":"Linear B is an alphabet of a few dozen letters, while Linear A uses thousands of picture signs no one can sound out.","rationale":"Both are syllabic scripts, and most Linear A sign values are known from Linear B; the obstacle is the unknown language."},{"id":"b","text":"Linear A survives on only one short inscription, far too little text for any decipherment method to succeed.","rationale":"Linear A is attested across Crete and several Aegean islands over centuries, not on a single inscription."},{"id":"c","text":"Linear B was found alongside a bilingual inscription in Egyptian, which supplied a ready-made key to its signs.","rationale":"Ventris worked without a bilingual text, using internal patterns and place names."},{"id":"d","text":"Linear B turned out to record an early form of Greek, a known language, while Linear A's language is unidentified.","rationale":"Correct. Sound values guessed for Linear B produced recognizable Greek; Linear A's language is unknown."}],"correctChoiceID":"d","explanation":"Ventris deciphered Linear B without a bilingual inscription by analyzing sign patterns and testing sound values, which yielded recognizable words in Mycenaean Greek, the oldest known form of Greek. Linear A, used earlier on Crete, is also syllabic, and the approximate sound values of most of its signs are known from Linear B. But the language those sounds spell out remains unknown, so the texts cannot be understood. Decipherment usually requires either a bilingual text or a script that records a language already known.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"britannica-linear-b","title":"Linear B","publisher":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/Linear-B","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Linear B, a syllabic script adapted from Linear A, records Mycenaean Greek, the oldest known form of Greek; deciphered by Michael Ventris in 1952"},{"id":"britannica-linear-a","title":"Linear A","publisher":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/Linear-A","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Linear A, a syllabic script attested in Crete and Aegean islands c. 1850-1400 BCE; most sign values are known from Linear B, but the language it writes remains unknown"}],"tags":["linear-b","linear-a","decipherment","aegean"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"obscure-v3-maya-long-count-006","category":"obscure","conceptID":"obscure.time-cosmology","conceptTitle":"Calendars and cosmology","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"December 21, 2012, marked the completion of the 13th bak'tun in the Classic Maya Long Count calendar. How do Maya scholars generally interpret that date?","choices":[{"id":"a","text":"As the completion of a large calendrical cycle, after which the count continues, much like an odometer rolling over.","rationale":"Correct. Scholars such as David Stuart describe it as a cycle ending, not a prophesied apocalypse."},{"id":"b","text":"As the date the Maya prophesied for the end of the world, recorded in dozens of Classic-period inscriptions.","rationale":"The La Corona text Stuart studied is only the second known ancient reference to the date, and it promotes continuity, not doom."},{"id":"c","text":"As the final day the Maya calendar could represent, since the system had no units for longer periods of time.","rationale":"The 13-bak'tun cycle is one cycle among others; as Stuart notes, many more bak'tuns are still to come."},{"id":"d","text":"As a date invented by modern astronomers, because the Long Count was never used during the Classic period.","rationale":"The Long Count was widely used in Classic Maya inscriptions; 2012 follows from their own system."}],"correctChoiceID":"a","explanation":"The Long Count tracks days in nested units, and its 13-bak'tun cycle of 1,872,000 days ended on December 21, 2012. Maya scholars, including David Stuart, explain that this marked the completion of a cycle, a symbolically important anniversary, not a prophesied end of the world. Very few ancient inscriptions even mention the date, and the one Stuart deciphered at La Corona used it to promote continuity during a time of crisis. The doomsday idea is a modern invention projected onto the Maya.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"utexas-maya-2012","title":"Maya Scholar Debunks World-Ending Myth","publisher":"The University of Texas at Austin","url":"https://news.utexas.edu/2012/12/17/maya-scholar-debunks-world-ending-myth/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"David Stuart: the 13th bak'tun's end marked a cycle completion, not a prophesied end of the world; the Maya calendar continues"},{"id":"nmai-maya-calendar","title":"The Calendar System","publisher":"National Museum of the American Indian, Smithsonian","url":"https://maya.nmai.si.edu/calendar/calendar-system","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Explains the Maya Long Count and the completion of 13 bak'tuns on December 21, 2012"}],"tags":["maya","long-count","calendars","2012"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"obscure-v3-lunar-vs-lunisolar-007","category":"obscure","conceptID":"obscure.time-cosmology","conceptTitle":"Calendars and cosmology","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"Ramadan begins about 11 days earlier each year on the Gregorian calendar, while Lunar New Year always falls between late January and late February. What best explains the difference?","choices":[{"id":"a","text":"The Islamic calendar follows the sun but starts each year from a moon sighting, which moves it earlier every year.","rationale":"The Islamic calendar is purely lunar; it does not track the solar year at all."},{"id":"b","text":"The Chinese calendar is purely lunar like the Islamic one, but its New Year is fixed to the winter solstice.","rationale":"The Chinese calendar is lunisolar, and its New Year begins with a new moon between January 21 and February 20."},{"id":"c","text":"The Islamic calendar is purely lunar with no leap months, while the Chinese calendar adds leap months to keep pace.","rationale":"Correct. A 354-355-day lunar year drifts through the seasons; intercalary months keep the Chinese year aligned."},{"id":"d","text":"Both calendars are lunisolar, but the Islamic calendar adds its leap month only once every thirty-two years.","rationale":"The Islamic calendar adds no leap months; its months cycle through the seasons in about 32.5 solar years."}],"correctChoiceID":"c","explanation":"The Islamic (Hijri) calendar has 12 lunar months totaling 354 or 355 days and adds no intercalary months, so each date, including the start of Ramadan, moves about 11 days earlier each solar year and cycles through all seasons in roughly 32.5 years. The Chinese calendar is lunisolar: its months follow the moon, but it periodically inserts an intercalary month to stay aligned with the solar year. That keeps Lunar New Year, which begins with a new moon, between January 21 and February 20. The difference reflects different priorities: strict lunar reckoning versus agricultural seasonality.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"britannica-islamic-calendar","title":"Islamic calendar","publisher":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/Islamic-calendar","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"A lunar year of 354 or 355 days with no intercalated months, so months retrogress through the seasons"},{"id":"britannica-chinese-calendar","title":"Chinese calendar","publisher":"Encyclopaedia Britannica","url":"https://www.britannica.com/science/Chinese-calendar","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"A lunar-solar calendar of 12 months totaling 354 days; intercalary months are added to align with the solar year"},{"id":"britannica-chinese-new-year","title":"Chinese New Year","publisher":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/Chinese-New-Year","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Lunar New Year begins with the new moon between January 21 and February 20"}],"tags":["calendars","islamic-calendar","chinese-calendar","lunisolar"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"obscure-v3-potlatch-exhibit-essay-008","category":"obscure","conceptID":"obscure.ritual-social-practice","conceptTitle":"Ritual and social practice","type":"essay","dimension":"synthesis","difficulty":"advanced","prompt":"A museum plans an exhibition of potlatch regalia and masks. Some were confiscated by Canadian authorities during the potlatch ban and later repatriated to their communities; others remain in the museum's collection. Design an interpretive plan that explains the objects' ceremonial meaning without presenting the culture as frozen in the past. Address who should hold interpretive authority, how to present the history of the ban and repatriation, and how to distinguish community knowledge, archival records, and curatorial inference.","choices":[],"explanation":"Coaching should push the learner to center source communities, present colonial history honestly without reducing the culture to victimhood, and be explicit about the kinds of knowledge behind each label.","rubric":[{"id":"authority","title":"Interpretive authority","description":"Explains how source-community members share or lead interpretation, including protocols for restricted knowledge.","weight":0.3,"coachingQuestions":["Who decides what can be displayed or said?","What should happen if community and curatorial views differ?"]},{"id":"history","title":"Ban and repatriation history","description":"Presents the potlatch ban, confiscations, and repatriation accurately with dates and sources.","weight":0.25,"coachingQuestions":["How did the objects leave their communities?","What does repatriation mean for the objects still held?"]},{"id":"living-culture","title":"Living culture","description":"Shows potlatch as a continuing practice rather than a vanished one.","weight":0.25,"coachingQuestions":["How will visitors learn that potlatches continue today?","What contemporary voices or works could be included?"]},{"id":"knowledge-types","title":"Types of knowledge","description":"Distinguishes community knowledge, archival documentation, and curatorial inference in labels and texts.","weight":0.2,"coachingQuestions":["How will a label signal the source of each claim?","What remains uncertain about specific objects?"]}],"coachingPrompts":["Start with who has the right to tell the story.","Date the ban, confiscations, and returns precisely.","Avoid past-tense framing of a living practice.","Label the source of each interpretive claim."],"modelOutline":["Define the exhibition's purpose and partners","Describe the potlatch's ceremonial and legal meaning","Present the ban, confiscations, and repatriation history","Set out shared interpretive authority and protocols","Explain labeling that distinguishes knowledge sources and uncertainty"],"sources":[{"id":"canadian-encyclopedia-potlatch-ban","title":"Potlatch Ban","publisher":"The Canadian Encyclopedia","url":"https://www.thecanadianencyclopedia.ca/en/article/potlatch-ban","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"The Indian Act banned the potlatch from 1885 until the 1951 revision; officials and missionaries saw it as an obstacle to assimilation"},{"id":"umista-potlatch-collection","title":"The History of the Potlatch Collection","publisher":"U'mista Cultural Society","url":"https://www.umista.ca/pages/collection-history","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"The potlatch marks births, marriages, name-giving, the standing up of a new chief, and deaths before invited witnesses; regalia confiscated under the ban were later repatriated to the Kwakwaka'wakw"},{"id":"britannica-potlatch","title":"Potlatch","publisher":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/potlatch","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Ceremonial distribution of property and gifts to affirm or reaffirm social status among Indigenous peoples of the Northwest Pacific coast"}],"tags":["potlatch","museums","repatriation","essay"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"literature-v3-tell-tale-narrator-001","category":"literature","conceptID":"literature.narrative-voice","conceptTitle":"Narrative voice","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"In Edgar Allan Poe's 'The Tell-Tale Heart,' the narrator repeatedly insists that he is not mad, pointing to the calm precision with which he planned and carried out a killing. How does this insistence chiefly function?","choices":[{"id":"a","text":"It establishes an omniscient narrator whose access to every character's thoughts makes the account authoritative.","rationale":"The story is told in the first person by a participant with no access to other characters' minds."},{"id":"b","text":"It marks an unreliable narrator, since his offered proof of sanity is itself evidence against his judgment.","rationale":"Correct. The reader learns to distrust the narrator precisely through his self-justifications."},{"id":"c","text":"It creates free indirect discourse, blending a third-person narrator's voice with a character's unspoken thoughts.","rationale":"Free indirect discourse is a third-person technique; this story is a first-person confession."},{"id":"d","text":"It produces dramatic irony alone, because the police know of the murder from the start and simply await a confession.","rationale":"The officers arrive in response to a reported shriek and do not know of the murder; the narrator confesses."}],"correctChoiceID":"b","explanation":"Poe's narrator speaks in the first person, asks why the listener will say he is mad, and offers the calm precision of his story as proof. The more he argues, the more the reader recognizes obsession and madness in his account, which makes him a classic unreliable narrator. The gap between his self-image and what the story shows generates much of its horror. Recognizing unreliability means reading against a narrator's claims while still using them as evidence.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"gutenberg-poe-works-vol2","title":"The Works of Edgar Allan Poe, Volume 2 (includes 'The Tell-Tale Heart')","publisher":"Project Gutenberg","url":"https://www.gutenberg.org/ebooks/2148","accessedAt":"2026-10-21T06:00:00Z","usage":"publicDomain","evidenceLocator":"Opening: the narrator asks why the listener will say he is mad and offers his calm telling as proof; officers arrive after a neighbour reports a shriek"}],"tags":["unreliable-narrator","poe","first-person","narrative-voice"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"literature-v3-petrarchan-sonnet-002","category":"literature","conceptID":"literature.form-genre","conceptTitle":"Form and genre","type":"multipleChoice","dimension":"recognition","difficulty":"foundation","prompt":"A fourteen-line poem in iambic pentameter rhymes abbaabba cdecde. Its first eight lines lay out a problem, and line nine begins a turn toward a response. Which form is it?","choices":[{"id":"a","text":"A Petrarchan sonnet, with an octave and a sestet divided by a turn after line eight.","rationale":"Correct. The abbaabba octave and the turn at line nine are the Italian sonnet's signature."},{"id":"b","text":"A Shakespearean sonnet, with three quatrains and a turn saved for the closing couplet.","rationale":"A Shakespearean sonnet rhymes abab cdcd efef gg and has no abbaabba octave."},{"id":"c","text":"A Spenserian sonnet, with linked quatrains whose rhymes interlock across the stanzas.","rationale":"Spenserian sonnets interlock quatrains (abab bcbc cdcd) and end in a couplet."},{"id":"d","text":"A villanelle, with two refrains that alternate and finally return together at the end.","rationale":"A villanelle has nineteen lines and repeated refrains, not fourteen lines in this scheme."}],"correctChoiceID":"a","explanation":"The Petrarchan, or Italian, sonnet divides into an octave rhyming abbaabba and a sestet with rhymes such as cdecde or cdcdcd. The octave typically presents a problem or tension, and the sestet, beginning at line nine (the volta), responds or resolves it. The Shakespearean sonnet instead uses three quatrains and a couplet (abab cdcd efef gg), often saving its turn for the end. Identifying the form helps readers see where the argument pivots.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"britannica-sonnet","title":"Sonnet","publisher":"Encyclopaedia Britannica","url":"https://www.britannica.com/art/sonnet","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Petrarchan sonnet: octave rhyming abbaabba and sestet (e.g., cdecde); Shakespearean sonnet: three quatrains and a couplet, abab cdcd efef gg"},{"id":"poetry-foundation-sonnet","title":"Sonnet (Glossary of Poetic Terms)","publisher":"Poetry Foundation","url":"https://www.poetryfoundation.org/education/glossary/sonnet","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Petrarchan octave ABBAABBA and sestet CDCDCD or CDECDE; the Spenserian sonnet interlocks its quatrains (ABAB BCBC CDCD EE)"}],"tags":["sonnet","petrarchan","poetic-form","volta"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"literature-v3-waste-land-modernism-003","category":"literature","conceptID":"literature.literary-movements","conceptTitle":"Literary movements and history","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"T. S. Eliot's The Waste Land (1922) shifts abruptly among speakers, languages, and quotations from earlier literature, with no single narrator to connect them. Which literary movement does this technique most clearly exemplify?","choices":[{"id":"a","text":"Romanticism, which prized the individual poet's emotion and imagination, often in communion with nature.","rationale":"Romantic poetry centers a unified lyric self, the opposite of Eliot's fractured voices."},{"id":"b","text":"Naturalism, which showed characters shaped by heredity and environment in a detached, documentary style.","rationale":"Naturalism is a mode of realist fiction, not a technique of fragmentation and allusion."},{"id":"c","text":"Modernism, which used fragmentation, allusion, and shifting perspectives to register a loss of shared meaning.","rationale":"Correct. The Waste Land is a landmark of modernist poetry."},{"id":"d","text":"Neoclassicism, which valued order, decorum, and imitation of ancient models, often in balanced couplets.","rationale":"Neoclassical verse values order and regularity, not abrupt collage."}],"correctChoiceID":"c","explanation":"The Waste Land, written in the shadow of World War I, assembles fragments of speech and quotation in mixed registers and languages, without a stable narrator to bind them. Rife with allusions and linguistic fragments, it became the archetypal modernist text. Romanticism, by contrast, centers a unified lyric voice, and neoclassicism prizes order and decorum. Recognizing a movement's techniques helps readers see how form expresses a historical moment.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"poetry-foundation-modernism","title":"Modernism (Glossary of Poetic Terms)","publisher":"Poetry Foundation","url":"https://www.poetryfoundation.org/education/glossary/modernism","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"The Waste Land (1922) became the archetypal Modernist text, rife with allusions, linguistic fragments, and mixed registers and languages"}],"tags":["modernism","eliot","allusion","fragmentation"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"literature-v3-anagnorisis-004","category":"literature","conceptID":"literature.form-genre","conceptTitle":"Form and genre","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"Near the end of Sophocles' Oedipus the King, Oedipus discovers that the man he killed years earlier was his father and that his wife is his mother. In Aristotle's vocabulary for tragedy, what is this moment called?","choices":[{"id":"a","text":"Catharsis, the purging of pity and fear that a tragedy produces in its audience.","rationale":"Catharsis describes the audience's emotional response, not an event in the plot."},{"id":"b","text":"Hamartia, the error or flaw in judgment that sets the hero's downfall in motion.","rationale":"Hamartia is the mistaken act; the moment described here is learning the truth about it."},{"id":"c","text":"Deus ex machina, an abrupt resolution imposed from outside the plot's own logic.","rationale":"Nothing external intervenes; the discovery arises from the plot's own chain of events."},{"id":"d","text":"Anagnorisis, the recognition in which a character discovers a concealed truth.","rationale":"Correct. Oedipus's recognition is Aristotle's model example of anagnorisis."}],"correctChoiceID":"d","explanation":"Anagnorisis, Greek for 'recognition,' is the startling discovery that moves a character from ignorance to knowledge. Aristotle singles out Oedipus's discovery as the finest kind because it coincides with the reversal of his fortune (peripeteia). Hamartia is the error that set events in motion, and catharsis refers to the effect on the audience. Using these terms precisely helps readers analyze how tragic plots are built.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"britannica-anagnorisis","title":"Anagnorisis","publisher":"Encyclopaedia Britannica","url":"https://www.britannica.com/art/anagnorisis","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Anagnorisis (recognition): the startling discovery that produces a change from ignorance to knowledge; Oedipus is the classic example"}],"tags":["tragedy","aristotle","anagnorisis","oedipus"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"literature-v3-racial-mountain-005","category":"literature","conceptID":"literature.literary-movements","conceptTitle":"Literary movements and history","type":"multipleChoice","dimension":"application","difficulty":"advanced","prompt":"In 'The Negro Artist and the Racial Mountain' (1926), Langston Hughes criticized a young Black poet's wish to be 'a poet--not a Negro poet.' What position did Hughes's essay advance?","choices":[{"id":"a","text":"Black artists should draw freely on Black life, including jazz and the blues, without seeking white or middle-class approval.","rationale":"Correct. Hughes urged Black artists to express their racial identity without fear or shame."},{"id":"b","text":"Black artists should avoid racial subjects altogether, because only universal themes could earn lasting critical respect.","rationale":"This is close to the attitude Hughes criticized as a retreat from racial identity."},{"id":"c","text":"Black artists should write chiefly political protest, since art without a direct social message was a luxury to avoid.","rationale":"Hughes championed artistic freedom and vernacular forms, not a requirement that art be propaganda."},{"id":"d","text":"Black artists should model their work on European classics to prove mastery of forms prized by established critics.","rationale":"Hughes criticized the pull toward white standards and celebrated jazz, blues, and the lives of ordinary people."}],"correctChoiceID":"a","explanation":"Hughes's essay, a cornerstone of the Harlem Renaissance, argued that the urge within the race toward whiteness was the 'mountain' standing in the way of a true Black art. He praised the culture of ordinary Black people, including jazz and the blues, as rich material, and declared that young Black artists would express themselves without fear or shame, whether white or Black audiences approved or not. The essay also answered George Schuyler, who had questioned the need for a separate African American artistic tradition. It remains a key text in debates about identity and artistic freedom.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"poetry-foundation-racial-mountain","title":"The Negro Artist and the Racial Mountain","publisher":"Poetry Foundation (essay by Langston Hughes, 1926)","url":"https://www.poetryfoundation.org/articles/69395/the-negro-artist-and-the-racial-mountain","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Hughes answers the wish to be 'a poet--not a Negro poet,' celebrates blues, spirituals, and jazz, and declares that younger Black artists will express themselves without fear or shame"}],"tags":["harlem-renaissance","langston-hughes","manifesto","identity"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"literature-v3-bildungsroman-006","category":"literature","conceptID":"literature.form-genre","conceptTitle":"Form and genre","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"Charles Dickens's Great Expectations follows Pip from a poor childhood through ambition and disillusionment to a hard-won moral maturity. Which genre label best fits this structure?","choices":[{"id":"a","text":"Picaresque novel, a loosely episodic series of adventures of a roguish hero who changes little along the way.","rationale":"Pip's story is organized around inner development, not a string of roguish episodes."},{"id":"b","text":"Bildungsroman, a novel of formation that traces a protagonist's growth from youth into maturity.","rationale":"Correct. Britannica cites Great Expectations as an example of the bildungsroman."},{"id":"c","text":"Epistolary novel, a story told mainly through letters or documents exchanged among its characters.","rationale":"Great Expectations is narrated by the adult Pip in retrospect, not told through letters."},{"id":"d","text":"Roman a clef, a novel depicting real people and events behind a thin fictional disguise.","rationale":"The novel is not a disguised account of identifiable real people and events."}],"correctChoiceID":"b","explanation":"A bildungsroman, or novel of formation, follows a protagonist's moral and psychological development from youth to maturity, often through conflict with society and the loss of illusions. Great Expectations traces Pip's ambitions, his disillusionment, and his eventual moral growth, making it a classic English example. The picaresque, by contrast, strings together episodes around a hero who changes little. Genre labels help readers anticipate structure and notice where a novel departs from convention.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"britannica-bildungsroman","title":"Bildungsroman","publisher":"Encyclopaedia Britannica","url":"https://www.britannica.com/art/bildungsroman","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Novel of formation dealing with the formative years of the protagonist; Dickens's David Copperfield and Great Expectations are cited examples"}],"tags":["bildungsroman","dickens","genre","novel"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"literature-v3-magic-realism-007","category":"literature","conceptID":"literature.literary-movements","conceptTitle":"Literary movements and history","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"In Gabriel Garcia Marquez's One Hundred Years of Solitude, Remedios the Beauty rises bodily to heaven one afternoon, and the narrator reports it as calmly as any household event. Which mode does this narration exemplify?","choices":[{"id":"a","text":"High fantasy, which builds an invented secondary world with its own geography, history, and system of magic.","rationale":"Macondo is grounded in recognizable Latin American history, not a separate invented world."},{"id":"b","text":"Surrealism, which used automatic writing and dream logic to free the unconscious from rational control.","rationale":"The narration is calm, orderly, and realistic in manner, not dreamlike automatic writing."},{"id":"c","text":"Magic realism, which presents extraordinary events matter-of-factly within an otherwise realistic world.","rationale":"Correct. The deadpan treatment of the miraculous is the hallmark of magic realism."},{"id":"d","text":"Gothic fiction, which uses supernatural terror and decaying settings chiefly to provoke fear and suspense.","rationale":"The supernatural here prompts neither terror nor suspense; it is narrated as ordinary."}],"correctChoiceID":"c","explanation":"Magic realism introduces fantastic events into an otherwise realistic narrative and reports them in the same matter-of-fact tone as everyday life. The Nobel committee honored Garcia Marquez for fiction in which the fantastic and the realistic are combined, and the ascension of Remedios the Beauty in One Hundred Years of Solitude is a famous example. The effect is not to create terror or a separate fantasy world but to unsettle the boundary between the ordinary and the marvelous. The mode is especially associated with twentieth-century Latin American fiction.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"nobel-literature-1982","title":"The Nobel Prize in Literature 1982","publisher":"Nobel Prize Outreach","url":"https://www.nobelprize.org/prizes/literature/1982/summary/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Garcia Marquez honored for novels and stories in which the fantastic and the realistic are combined in a richly composed world of imagination"},{"id":"revista-ascent-to-glory","title":"Ascent to Glory: How One Hundred Years of Solitude was Written and Became a Global Classic","publisher":"ReVista, Harvard Review of Latin America","url":"https://revista.drclas.harvard.edu/ascent-to-glory-how-one-hundred-years-of-solitude-was-written-and-became-a-global-classic/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Refers to Remedios the Beauty soaring to heaven and to the novel's association with magical realism"}],"tags":["magic-realism","garcia-marquez","latin-american-literature","narration"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"literature-v3-sonnet-form-essay-008","category":"literature","conceptID":"literature.close-reading","conceptTitle":"Close reading","type":"essay","dimension":"synthesis","difficulty":"advanced","prompt":"Choose a public-domain sonnet, such as Shakespeare's Sonnet 73 or Sonnet 130. Argue how the poem's form (its rhyme scheme, its division into quatrains and couplet, and the placement of its turn) shapes the meaning of its argument. Support your claim with close attention to specific words and lines, and address one reading that differs from yours.","choices":[],"explanation":"Coaching should push the learner to make an arguable claim about form and meaning, ground it in specific lines, and engage a genuine alternative reading rather than summarizing the poem.","rubric":[{"id":"thesis","title":"Arguable thesis about form","description":"Makes a specific, arguable claim connecting formal features to the poem's meaning.","weight":0.25,"coachingQuestions":["Could someone reasonably disagree with your claim?","Which formal feature does the most work in your reading?"]},{"id":"close-reading","title":"Close reading evidence","description":"Analyzes specific words, images, and line positions rather than paraphrasing.","weight":0.3,"coachingQuestions":["Which single word carries the most weight in the couplet?","How does imagery change from quatrain to quatrain?"]},{"id":"structure-turn","title":"Structure and turn","description":"Explains how the sonnet's divisions and turn organize the argument.","weight":0.25,"coachingQuestions":["Where does the poem pivot, and what changes there?","How would the meaning differ if the couplet were removed?"]},{"id":"counterreading","title":"Alternative reading","description":"Engages a plausible competing interpretation and responds with evidence.","weight":0.2,"coachingQuestions":["What would a reader who disagrees point to?","Which lines does your reading explain less well?"]}],"coachingPrompts":["Name the rhyme scheme and divisions before interpreting.","Quote briefly and analyze each quotation.","Locate the turn and explain what it changes.","Answer a real counterreading."],"modelOutline":["Introduce the sonnet and state a thesis about form and meaning","Map the rhyme scheme, quatrains, couplet, and turn","Analyze imagery and diction quatrain by quatrain","Show how the couplet or turn reframes the argument","Address an alternative reading and conclude"],"sources":[{"id":"gutenberg-shakespeare-sonnets","title":"Shakespeare's Sonnets","publisher":"Project Gutenberg","url":"https://www.gutenberg.org/ebooks/1041","accessedAt":"2026-10-21T06:00:00Z","usage":"publicDomain","evidenceLocator":"Public-domain text of Shakespeare's 154 sonnets"},{"id":"britannica-sonnet","title":"Sonnet","publisher":"Encyclopaedia Britannica","url":"https://www.britannica.com/art/sonnet","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Petrarchan sonnet: octave rhyming abbaabba and sestet (e.g., cdecde); Shakespearean sonnet: three quatrains and a couplet, abab cdcd efef gg"}],"tags":["sonnet","close-reading","shakespeare","essay"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"art-v3-buon-fresco-001","category":"art","conceptID":"art.materials-techniques","conceptTitle":"Materials and techniques","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"Italian painters working in true (buon) fresco plastered and painted only as much wall as they could finish in one working session, a section called a giornata. Why?","choices":[{"id":"a","text":"Oil paint applied to wet plaster yellows unless varnished the same day, so painters worked in small patches.","rationale":"Buon fresco uses water-based pigments, not oil, and needs no same-day varnish."},{"id":"b","text":"Church rules required each day's section to be blessed before work continued, so painters divided ceilings by day.","rationale":"The daily sections are a technical necessity of the medium, not a liturgical rule."},{"id":"c","text":"Pigments bind as the wet lime plaster dries and sets, so color had to be applied before each section cured.","rationale":"Correct. Pigment must go onto fresh plaster, which limits work to what can be painted before it sets."},{"id":"d","text":"Wet plaster is too heavy to hold overhead, so painters laid only small amounts to keep ceilings from collapsing.","rationale":"Weight is not the constraint; the setting time of the plaster is."}],"correctChoiceID":"c","explanation":"In buon fresco, pigments diluted in water are applied to a freshly laid layer of smooth plaster (the intonaco). As the plaster dries, a chemical reaction binds the pigment to it, making the image durable. Painters therefore worked in sections called giornate, Italian for 'a day's work,' laying only as much plaster as they could paint while it was wet. Additions painted on dry plaster (fresco a secco) are far less durable and tend to flake off.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"met-italian-painting-later-middle-ages","title":"Italian Painting of the Later Middle Ages","publisher":"The Metropolitan Museum of Art","url":"https://www.metmuseum.org/essays/italian-painting-of-the-later-middle-ages","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Frescoes were painted in sections called giornate ('a day's work'); pigments applied to wet intonaco bond chemically as the plaster dries; fresco secco is far less durable"}],"tags":["fresco","technique","renaissance","michelangelo"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"art-v3-oil-glazes-002","category":"art","conceptID":"art.materials-techniques","conceptTitle":"Materials and techniques","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"Egg tempera dries within minutes, so painters working in it built up tones from many fine hatched strokes. When fifteenth-century Netherlandish painters such as Jan van Eyck exploited the oil medium, what did it most directly allow them to do that tempera did not?","choices":[{"id":"a","text":"Blend tones smoothly while the paint stayed workable and layer thin transparent glazes for luminous depth.","rationale":"Correct. Slow-drying oil fuses tones readily, and transparent glazes give luminosity, depth, and brilliance."},{"id":"b","text":"Finish a panel far more quickly, because oil dries faster than tempera and layers can be stacked in one sitting.","rationale":"Oil dries far more slowly than tempera; that slowness is what permits blending, and painters sometimes add driers to speed it up."},{"id":"c","text":"Paint directly on fresh plaster walls, because oil bonds chemically with the lime as the surface cures.","rationale":"Binding pigment into curing lime plaster describes fresco; early Netherlandish oils were mostly on wood panels."},{"id":"d","text":"Skip the preparatory drawing and ground, because oil is opaque enough to hide whatever lies beneath it.","rationale":"The technique depends on oil's transparency, not opacity; these painters glazed over carefully prepared and drawn panels."}],"correctChoiceID":"a","explanation":"Egg tempera dries almost at once, so tonal transitions have to be built from many small hatched strokes. Oil dries slowly and allows an outstanding fusion of tones, and thin transparent layers called glazes give forms luminosity, depth, and brilliance. Early Netherlandish painters such as Jan van Eyck used oil glazes over carefully drawn panels prepared in the tempera tradition, producing jewel-like color and minute detail. Oil painting is recorded in Europe centuries earlier, so van Eyck did not invent it, but his manipulation of the medium was crucial to his effects. Fusing pigment into wet plaster, by contrast, describes fresco.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"met-van-eyck-essay","title":"Jan van Eyck (ca. 1390-1441)","publisher":"The Metropolitan Museum of Art","url":"https://www.metmuseum.org/essays/jan-van-eyck-ca-1390-1441","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Van Eyck's ability to manipulate the properties of the oil medium was crucial to his effects of light and detail"},{"id":"britannica-oil-painting","title":"Oil painting","publisher":"Encyclopaedia Britannica","url":"https://www.britannica.com/art/oil-painting","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Oil allows outstanding fusion of tones; transparent glazes impart luminosity and depth; van Eyck used oil glazes over tempera-based panels; driers are added to speed drying"}],"tags":["oil-painting","glazing","van-eyck","northern-renaissance"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"art-v3-monet-series-003","category":"art","conceptID":"art.movements-periods","conceptTitle":"Movements and periods","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"Around 1890-91 Claude Monet painted many canvases of the same grain stacks at different times of day and in different seasons. What aim does this practice best reveal?","choices":[{"id":"a","text":"Producing a precise architectural and agricultural record that could guide later restorers and farmers.","rationale":"The series dissolve detail into color and light; they are not documentary records."},{"id":"b","text":"Breaking each subject into geometric facets seen from several viewpoints, as the Cubists later did.","rationale":"Monet kept a single viewpoint; multiple simultaneous viewpoints are a Cubist strategy."},{"id":"c","text":"Applying a fixed academic formula for rendering light that he had learned through Salon training.","rationale":"Monet worked against academic formulas, observing changing effects directly."},{"id":"d","text":"Studying how changing light and atmosphere transform the appearance of a single subject over time.","rationale":"Correct. Repeating one motif isolated light and atmosphere as the real subject."}],"correctChoiceID":"d","explanation":"Impressionist painters emphasized the effects of light, using broken brushstrokes and unblended color. In his series paintings, Monet repeated a single motif, such as grain stacks, at various times of year and moments of the day, so that changing light rather than the object became the true subject. When the stacks were exhibited in 1891 they were widely praised by his peers. Each canvas records a particular moment of perception.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"aic-monet-stacks-of-wheat","title":"Stacks of Wheat, Claude Monet","publisher":"Art Institute of Chicago","url":"https://www.artic.edu/artworks/186316/stacks-of-wheat","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Grain stacks are among the most iconic motifs of Monet's exploration of changing light; he painted them at various times of year and moments of the day"},{"id":"met-impressionism","title":"Impressionism: Art and Modernity","publisher":"The Metropolitan Museum of Art","url":"https://www.metmuseum.org/essays/impressionism-art-and-modernity","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Impressionist techniques: broken brushstrokes, unblended colors, and an emphasis on the effects of light"}],"tags":["impressionism","monet","series","light"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"art-v3-analytic-cubism-004","category":"art","conceptID":"art.movements-periods","conceptTitle":"Movements and periods","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"Around 1910-12, Pablo Picasso and Georges Braque painted still lifes and portraits fractured into small, overlapping planes in muted browns and grays, presenting several viewpoints of an object at once. Which movement is this?","choices":[{"id":"a","text":"Fauvism, which used intense, arbitrary color applied in bold strokes to express emotion over description.","rationale":"Fauvism is known for vivid, arbitrary color, the opposite of these muted tones."},{"id":"b","text":"Analytic Cubism, which broke objects into faceted planes to show them from multiple angles at once.","rationale":"Correct. Picasso and Braque's analytic phase fragmented form into muted, overlapping planes."},{"id":"c","text":"Futurism, which used repeated lines and forms to convey speed, machines, and the dynamism of modern life.","rationale":"Futurism focused on motion and speed and was led by Italian artists, not Picasso and Braque."},{"id":"d","text":"Surrealism, which drew on dreams and the unconscious to stage strange and irrational juxtapositions.","rationale":"Surrealism emerged in the 1920s and centered on dream imagery, not faceted planes."}],"correctChoiceID":"b","explanation":"Cubism, developed by Picasso and Braque, broke with the single, stable perspective of earlier Western painting and incorporated multiple perspectives into a single composition. In its Analytic phase, 1910 to 1912, they abstracted their works into overlapping planes and facets in near-monochromatic browns, grays, or blacks, so that structure dominated. From the winter of 1912-13, pasted-paper works (papiers colles) opened a new phase that brought everyday materials such as newspaper into the picture. The movement transformed how twentieth-century artists thought about representation.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"met-cubism","title":"Cubism","publisher":"The Metropolitan Museum of Art","url":"https://www.metmuseum.org/essays/cubism","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Cubists fractured objects into geometric forms with multiple vantage points; in Analytic Cubism (1910-12) Picasso and Braque reduced works to overlapping planes and facets in near-monochromatic browns, grays, or blacks"},{"id":"moma-cubism","title":"Cubism","publisher":"The Museum of Modern Art","url":"https://www.moma.org/collection/terms/cubism","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Cubism originated with Braque and Picasso (1907-14), using geometric planes and multiple perspectives within a single composition"}],"tags":["cubism","picasso","braque","modern-art"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"art-v3-tenebrism-005","category":"art","conceptID":"art.formal-analysis","conceptTitle":"Formal analysis","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"In many of Caravaggio's paintings, figures emerge from near-black backgrounds under a harsh, directed light that leaves much of the scene in deep shadow. Which term best describes this treatment of light?","choices":[{"id":"a","text":"Tenebrism, a heightened chiaroscuro in which darkness dominates and light falls sharply on select forms.","rationale":"Correct. Caravaggio is the artist most closely associated with tenebrism."},{"id":"b","text":"Sfumato, a soft blending of tones without sharp outlines, giving forms a hazy and smoky transition.","rationale":"Sfumato, associated with Leonardo, softens transitions; Caravaggio's contrasts are abrupt."},{"id":"c","text":"Atmospheric perspective, in which distant forms grow paler and bluer to suggest depth and distance.","rationale":"Atmospheric perspective concerns depth in landscapes, not dramatic spotlighting of figures."},{"id":"d","text":"Impasto, a thick application of paint that stands up from the surface and catches the light.","rationale":"Impasto describes paint texture, not the distribution of light and shadow in a composition."}],"correctChoiceID":"a","explanation":"Tenebrism, from the Latin tenebrae ('darkness'), uses extreme contrasts of light and dark: figures are set against intense darkness and lit by a bright, searching light. Caravaggio introduced the technique, and painters he influenced, such as Georges de La Tour and Francisco de Zurbaran, took it up in the early seventeenth century. The technique heightens drama and focuses attention. Sfumato, by contrast, softens edges rather than sharpening contrasts.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"britannica-tenebrism","title":"Tenebrism","publisher":"Encyclopaedia Britannica","url":"https://www.britannica.com/art/tenebrism","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Extreme contrasts of light and dark; figures set against intense darkness and lit by a bright, searching light; introduced by Caravaggio"}],"tags":["tenebrism","chiaroscuro","caravaggio","baroque"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"art-v3-duchamp-fountain-006","category":"art","conceptID":"art.reception-interpretation","conceptTitle":"Reception and interpretation","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"In 1917 Marcel Duchamp submitted Fountain, a mass-produced porcelain urinal signed 'R. Mutt,' to an exhibition. Why do art historians treat it as a turning point?","choices":[{"id":"a","text":"It showed Duchamp's technical skill as a ceramicist, since he modeled and glazed the porcelain form himself.","rationale":"Duchamp did not make the object; it was a manufactured urinal, which is the point of a readymade."},{"id":"b","text":"It was the first sculpture accepted into a museum collection directly after appearing in a public exhibition.","rationale":"Its importance is conceptual, not institutional; the version Tate shows is a 1964 replica."},{"id":"c","text":"It proposed that an artist's choice and framing of an object, rather than making it, could make it art.","rationale":"Correct. As a readymade, it shifted attention from craft to the artist's idea and selection."},{"id":"d","text":"It revived classical ideals of proportion by presenting a smooth, symmetrical form as an image of beauty.","rationale":"Duchamp aimed to challenge, not revive, conventional ideas of beauty and taste."}],"correctChoiceID":"c","explanation":"Fountain is Duchamp's most notorious readymade: an ordinary manufactured urinal, signed with a false name in New York in 1917. Duchamp deliberately chose ordinary, functional objects, and a 1917 editorial in The Blind Man defended the work on the grounds that it did not matter who made it: 'He CHOSE it.' Its significance lies in the idea that an artist's choice and the new context and title, rather than handcraft, can make something art. That idea shaped conceptual art and later debates about what counts as art.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"tate-readymade","title":"Readymade (Art Term)","publisher":"Tate","url":"https://www.tate.org.uk/art/art-terms/r/readymade","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Fountain (1917), a urinal signed with a false name; Duchamp deliberately chose ordinary objects, and The Blind Man argued that it mattered only that 'He CHOSE it'"}],"tags":["duchamp","readymade","conceptual-art","dada"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"art-v3-japonisme-007","category":"art","conceptID":"art.movements-periods","conceptTitle":"Movements and periods","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"After Japan's ports reopened to Western trade in 1853, artists such as Edgar Degas and Mary Cassatt studied Japanese ukiyo-e woodblock prints. Which features of those prints most influenced their work?","choices":[{"id":"a","text":"Strict one-point linear perspective and modeling in light and shade, which reinforced academic illusionism.","rationale":"Japanese prints offered an alternative to academic illusionism, not a reinforcement of it."},{"id":"b","text":"Thick, textured layers of paint, which encouraged them to build heavy surfaces with a palette knife.","rationale":"Woodblock prints offered flat color and line, not thick paint handling."},{"id":"c","text":"Large-scale religious narrative cycles, which inspired them to paint church murals in a Japanese manner.","rationale":"Ukiyo-e prints presented simple, everyday subjects from 'the floating world,' not religious mural cycles."},{"id":"d","text":"Asymmetrical compositions, high vantage points, and spaces pared down to flat color and line.","rationale":"Correct. These features of ukiyo-e prints reshaped Western composition and color."}],"correctChoiceID":"d","explanation":"Japonisme describes the wave of Western enthusiasm for Japanese art after Japan's ports reopened to trade in 1853. Ukiyo-e prints showed that simple, everyday subjects could be presented in appealingly decorative ways, and Degas absorbed their elongated formats, asymmetrical compositions, aerial perspective, and spaces emptied to abstract elements of color and line. These devices offered an alternative to academic perspective and modeling. Mary Cassatt likewise found in Japanese woodcuts a fresh approach to scenes of everyday life.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"met-japonisme","title":"Japonisme","publisher":"The Metropolitan Museum of Art","url":"https://www.metmuseum.org/essays/japonisme","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"After Japan's ports reopened to Western trade in 1853, ukiyo-e prints transformed Impressionist and Post-Impressionist art; Degas absorbed asymmetrical compositions, aerial perspective, and spaces reduced to color and line; Cassatt also responded"}],"tags":["japonisme","ukiyo-e","printmaking","impressionism"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"art-v3-cleaning-dilemma-essay-008","category":"art","conceptID":"art.materials-techniques","conceptTitle":"Materials and techniques","type":"essay","dimension":"synthesis","difficulty":"advanced","prompt":"A museum must decide whether to remove a discolored varnish layer and later retouching from a centuries-old oil painting. Some argue that cleaning will reveal the artist's true colors; others warn it could strip original glazes or a surface the artist expected to tone down. Build a decision framework that uses technical analysis (for example, cross-sections, X-radiography, infrared reflectography, and solvent tests), documentation, reversibility, and the history of the work's reception. Explain what uncertainty would remain and how the museum should communicate it.","choices":[],"explanation":"Coaching should push the learner to separate questions of evidence (what layers are original) from questions of value (what appearance to aim for), and to design a cautious, documented, reversible process.","rubric":[{"id":"technical-evidence","title":"Technical evidence","description":"Explains which analyses distinguish original paint and glazes from later varnish and retouching, and what each can and cannot show.","weight":0.3,"coachingQuestions":["Which test tells you whether a glaze is original?","What can X-rays reveal that the eye cannot?"]},{"id":"ethics","title":"Conservation principles","description":"Applies minimal intervention, reversibility, and documentation, and weighs risks of acting versus not acting.","weight":0.25,"coachingQuestions":["Can the proposed treatment be undone?","What happens to the painting if nothing is done?"]},{"id":"values","title":"Aesthetic and historical values","description":"Considers the artist's intentions, the painting's aging, and its reception history as competing values.","weight":0.25,"coachingQuestions":["Is there one 'true' appearance to recover?","How has the darkened painting itself been part of its history?"]},{"id":"communication","title":"Uncertainty and communication","description":"States remaining uncertainty and how the museum will explain the decision publicly.","weight":0.2,"coachingQuestions":["What would you tell visitors who notice the change?","Which questions will remain open after treatment?"]}],"coachingPrompts":["Separate what evidence can settle from what values must decide.","Specify tests before any irreversible step.","Treat reversibility and documentation as requirements.","Plan how to explain the decision to the public."],"modelOutline":["Describe the painting's condition and the competing proposals","Lay out technical analyses and what each would reveal","Apply conservation principles to treatment options","Weigh aesthetic, historical, and reception values","Recommend a process and a plan for communicating uncertainty"],"sources":[{"id":"aic-code-of-ethics","title":"Code of Ethics and Guidelines for Practice","publisher":"American Institute for Conservation","url":"https://www.culturalheritage.org/conservation-at-work/uphold-professional-standards/code","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Conservators must document examination, investigation, and treatment in permanent records; compensation for loss should be detectable and reversible"},{"id":"met-paintings-conservation","title":"Paintings Conservation","publisher":"The Metropolitan Museum of Art","url":"https://www.metmuseum.org/departments/paintings-conservation","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Conservation requires collaboration among art historians, conservators, and conservation scientists; technical examination informs treatment"}],"tags":["conservation","technical-art-history","ethics","essay"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"architecture-v3-pantheon-dome-001","category":"architecture","conceptID":"architecture.structure-loads","conceptTitle":"Structure and loads","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"The Pantheon's unreinforced concrete dome, built under Hadrian, uses concrete graded to be lighter toward the top, a shell that tapers from about 22 feet thick at its base to about 5 feet, and an open 27-foot oculus at the crown. What structural purpose do these three choices share?","choices":[{"id":"a","text":"They add tensile strength near the crown, where an unreinforced shell would otherwise be pulled apart by its own weight.","rationale":"None of them adds tensile strength, which unreinforced concrete largely lacks; the crown region of a dome is in compression."},{"id":"b","text":"They remove weight from the upper dome, reducing the load and outward thrust the lower shell and walls must resist.","rationale":"Correct. Lighter, thinner material high up and an open crown mean less mass pressing down and outward on the structure below."},{"id":"c","text":"They let the shell flex with heat and cold, since thin, lightweight concrete can expand and contract without cracking.","rationale":"Unreinforced concrete is rigid and brittle; these choices cut weight rather than add flexibility."},{"id":"d","text":"They concentrate mass at the crown, locking the shell in place much as a heavy keystone locks the stones of an arch.","rationale":"They do the opposite, taking mass away from the crown; the open oculus shows the dome needs no keystone-like weight there."}],"correctChoiceID":"b","explanation":"The Pantheon's dome is cast Roman concrete without steel reinforcement, so it has to work almost entirely in compression. Its builders reduced weight where it mattered most: the shell tapers from about 22 feet thick to about 5 feet, the concrete is graded so the material is lighter near the top, and a 27-foot open oculus replaces the crown. Less mass overhead means less load and less outward thrust on the lower shell and the rotunda walls. A deep foundation ring and concentric outer support rings help resist the remaining thrust.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"uh-engines-pantheon","title":"No. 1345: The Pantheon (The Engines of Our Ingenuity)","publisher":"University of Houston","url":"https://engines.egr.uh.edu/episode/1345","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"The cast-concrete shell tapers from 22 feet to 5 feet thick, the concrete is graded to be lighter near the top, and a 27-foot oculus opens the crown"}],"tags":["pantheon","roman-concrete","dome","structure"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"architecture-v3-arch-thrust-002","category":"architecture","conceptID":"architecture.structure-loads","conceptTitle":"Structure and loads","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"A builder sets a semicircular masonry arch over a wide opening between two slender walls. Soon the walls begin to lean outward and the arch's crown sags. What is the most likely structural cause?","choices":[{"id":"a","text":"The arch's stones are in tension, and since masonry is weak in tension, the keystone is pulling apart from its neighbors.","rationale":"A masonry arch works by keeping its stones in compression, not tension."},{"id":"b","text":"The arch carries no horizontal force at all, so the walls are leaning only because their footings were set unevenly.","rationale":"Arches always produce horizontal thrust; that thrust is the likely culprit here."},{"id":"c","text":"The arch is too heavy at the crown, and that vertical load alone crushes the stones at the points where it springs.","rationale":"Crushing would not explain walls leaning outward; the outward movement signals horizontal thrust."},{"id":"d","text":"The arch pushes outward as well as down, and the slender walls lack the mass or buttressing to resist that thrust.","rationale":"Correct. Unresisted thrust lets the supports spread, and the crown drops as the span widens."}],"correctChoiceID":"d","explanation":"An arch carries loads by pressing its wedge-shaped stones (voussoirs) together in compression, but it also pushes diagonally outward at its supports. That thrust must be resisted by strong supports, such as heavy abutments or buttresses, or the arch can collapse. If the supporting walls are too slender, they rotate outward, the span widens, and the crown sags until the arch fails. Managing thrust is the central problem behind buttresses, flying buttresses, and tied arches.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"britannica-arch","title":"Arch","publisher":"Encyclopaedia Britannica","url":"https://www.britannica.com/technology/arch-architecture","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Pressure forces an arch's voussoirs together; the supports must be strong enough to handle the thrust, a diagonal force that can cause collapse if not buttressed"}],"tags":["arch","thrust","masonry","structure"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"architecture-v3-ionic-order-003","category":"architecture","conceptID":"architecture.history-styles","conceptTitle":"Architectural history and styles","type":"multipleChoice","dimension":"recognition","difficulty":"foundation","prompt":"A neoclassical bank's columns have slender fluted shafts standing on bases, topped by capitals formed mainly by a pair of large spiral scrolls, without leaf carving. Which classical order do they follow?","choices":[{"id":"a","text":"Doric, whose columns typically have a plain cushion-like capital and, in Greek examples, no base at all.","rationale":"The Doric capital lacks volutes; this one is defined by them."},{"id":"b","text":"Corinthian, whose capitals are carved with layers of acanthus leaves sprouting small corner scrolls.","rationale":"Corinthian capitals are dominated by acanthus leaves, which this capital lacks."},{"id":"c","text":"Ionic, whose capitals are defined by a pair of spiral volutes above a slender shaft on a molded base.","rationale":"Correct. Paired volutes are the Ionic order's identifying feature."},{"id":"d","text":"Tuscan, a Roman simplification of the Doric with an unfluted shaft and a plain, unadorned capital.","rationale":"Tuscan columns are unfluted with plain capitals, not volutes."}],"correctChoiceID":"c","explanation":"The classical orders are distinguished chiefly by their capitals and proportions. The Ionic capital is defined by a pair of spiral volutes, and Ionic columns are slenderer than Doric ones and stand on bases. The Doric has a plain cushion-shaped capital, the Corinthian an acanthus-leaf capital, and the Tuscan a simplified, unfluted form. Recognizing the orders helps read the classical vocabulary of later buildings, from Renaissance churches to American banks.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"britannica-order","title":"Order (architecture)","publisher":"Encyclopaedia Britannica","url":"https://www.britannica.com/technology/order-architecture","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Capitals distinguish the orders: Ionic volutes; Corinthian acanthus leaves with scrolls; Greek Doric with no base; Tuscan a plainer Roman Doric with unfluted shaft"}],"tags":["classical-orders","ionic","neoclassicism","columns"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"architecture-v3-villa-savoye-frame-004","category":"architecture","conceptID":"architecture.history-styles","conceptTitle":"Architectural history and styles","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"Le Corbusier's Villa Savoye (1929-31) has long horizontal strip windows, an open interior plan, and a main floor lifted on slender columns. What made these features structurally possible?","choices":[{"id":"a","text":"A reinforced-concrete frame carried the loads, so walls bore no weight and windows and rooms could be placed freely.","rationale":"Correct. With columns carrying the loads, walls and openings could be placed where design required."},{"id":"b","text":"Thick load-bearing masonry walls carried the loads, and their great strength allowed long openings anywhere along them.","rationale":"Long openings weaken load-bearing walls; the villa's freedom comes from not relying on walls structurally."},{"id":"c","text":"Steel cables hung the floors from a rooftop truss, so the facade could be glazed without needing any columns.","rationale":"The villa stands on reinforced-concrete columns (pilotis), not suspended floors."},{"id":"d","text":"Prefabricated timber panels braced one another like a box, so walls could be pierced wherever views were wanted.","rationale":"The villa is a reinforced-concrete structure, not a timber panel system."}],"correctChoiceID":"a","explanation":"Le Corbusier's 'five points of a new architecture' (pilotis, free plan, free facade, horizontal ribbon windows, and roof garden) depended on a reinforced-concrete frame. Because slender columns carried the building's loads, exterior walls no longer had to be load-bearing, so long horizontal windows could run across the facade and interior partitions could be placed freely. Villa Savoye is the best-known demonstration of these principles. Le Corbusier had set out these principles in the 1920s.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"moma-villa-savoye-learning","title":"The House on Stilts: Villa Savoye","publisher":"The Museum of Modern Art","url":"https://www.moma.org/momaorg/shared/pdfs/moma_learning/docs/CL_3.pdf","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Villa Savoye incorporates Le Corbusier's five points; pilotis are reinforced-concrete columns; in a free plan the columns, not the walls, carry the building's weight"},{"id":"britannica-villa-savoye","title":"Villa Savoye","publisher":"Encyclopaedia Britannica","url":"https://www.britannica.com/place/Villa-Savoye","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Villa Savoye (1929-31) is characterized by pilotis, ribbon windows, and an open floor plan"}],"tags":["le-corbusier","modernism","reinforced-concrete","five-points"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"architecture-v3-gothic-pointed-arch-005","category":"architecture","conceptID":"architecture.history-styles","conceptTitle":"Architectural history and styles","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"Compared with the round arches of Romanesque churches, why did the pointed arch help Gothic builders raise taller vaults over bays of different widths?","choices":[{"id":"a","text":"Pointed arches carry no outward thrust at all, so the walls beneath them could be made as thin as builders wished.","rationale":"Pointed arches still produce thrust, which is why Gothic builders needed buttresses and flying buttresses."},{"id":"b","text":"A pointed arch has less lateral thrust and adapts easily to openings of different widths and heights.","rationale":"Correct. Reduced outward thrust and flexible proportions suited tall vaults over bays of varied size."},{"id":"c","text":"Pointed arches are carved from a single stone, so they avoid the weak mortar joints that limit round arches.","rationale":"Pointed arches are built from many voussoirs, like round arches."},{"id":"d","text":"Pointed arches were required to hold stained glass, so their use simply followed the demand for larger windows.","rationale":"Large windows were a consequence of Gothic structure, not the reason pointed arches work structurally."}],"correctChoiceID":"b","explanation":"Romanesque barrel and groin vaults needed thick walls to counter outward thrust, which allowed only small windows. Gothic builders adopted the pointed arch, which has less lateral thrust than the round arch and adapts easily to openings of various widths and heights. Combined with stone ribs that carried the vault's weight to piers and with flying buttresses (from the 1170s), it allowed taller vaults, thinner walls, and ever-larger windows. Pointed arches still produce thrust, which is why buttressing remained essential.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"met-gothic-art","title":"Gothic Art","publisher":"The Metropolitan Museum of Art","url":"https://www.metmuseum.org/essays/gothic-art","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"The pointed arch has less lateral thrust than the round arch and adapts easily to openings of various widths and heights; ribs and flying buttresses allowed thinner walls and larger windows"}],"tags":["gothic","pointed-arch","rib-vault","structure"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"architecture-v3-jacobs-street-life-006","category":"architecture","conceptID":"architecture.urban-design","conceptTitle":"Urban design","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"A city replaces several short blocks of small shops with apartments above them by a single superblock: residential towers set back in a landscaped plaza, with retail moved into an enclosed mall. Whose ideas most directly predict quieter, less safe sidewalks as a result?","choices":[{"id":"a","text":"Le Corbusier's, whose 'towers in a park' vision held that separating uses and lifting housing into towers improves cities.","rationale":"Le Corbusier's ideas inspired superblock designs like this one rather than predicting their failures."},{"id":"b","text":"Ebenezer Howard's, whose garden-city model favored planned towns of limited size ringed by permanent greenbelts.","rationale":"Howard's model concerned new towns and greenbelts, not the life of existing city sidewalks."},{"id":"c","text":"Robert Moses's, whose highway and urban-renewal projects reshaped New York around automobile traffic.","rationale":"Moses championed large clearance projects; he was the target of this critique, not its source."},{"id":"d","text":"Jane Jacobs's, who argued that mixed uses and short blocks keep sidewalks busy, watched, and safe.","rationale":"Correct. Jacobs championed mixed-use, short-block neighborhoods against the kind of renewal described."}],"correctChoiceID":"d","explanation":"In The Death and Life of Great American Cities (1961), Jane Jacobs argued that city neighborhoods depend on mixed uses, short blocks, a diversity of buildings, and dense concentrations of people. Ground-floor shops and apartments facing the street keep people around at different times and keep watch over the sidewalk. She observed that many rebuilding projects of her day were not safe, interesting, or alive. Her activism also opposed the clearance and highway building championed by Robert Moses.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"pps-jane-jacobs","title":"Jane Jacobs","publisher":"Project for Public Spaces","url":"https://www.pps.org/article/jjacobs-2","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Jacobs advocated mixed-use development, short blocks, and dense downtowns; she found many urban-renewal projects not safe, interesting, or alive, and opposed Robert Moses's highway plans"},{"id":"britannica-jane-jacobs","title":"Jane Jacobs","publisher":"Encyclopaedia Britannica","url":"https://www.britannica.com/biography/Jane-Jacobs","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Published The Death and Life of Great American Cities in 1961, a reinterpretation of the multiple needs of modern urban places"}],"tags":["jane-jacobs","urban-design","mixed-use","street-life"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"architecture-v3-adobe-thermal-mass-007","category":"architecture","conceptID":"architecture.climate-passive-design","conceptTitle":"Climate-responsive design","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"Traditional adobe houses in hot, dry regions have thick earthen walls. In a desert climate where days are hot and nights are cool, how do those walls mainly keep interiors comfortable?","choices":[{"id":"a","text":"Earth is an excellent insulator that blocks nearly all heat flow, so the walls work just like modern foam insulation.","rationale":"Adobe's benefit comes mainly from mass and time lag, not from high insulating value."},{"id":"b","text":"The walls release stored moisture that evaporates indoors, so rooms are cooled mainly by evaporation during the day.","rationale":"Evaporative cooling is not the primary mechanism of thick, dry adobe walls."},{"id":"c","text":"Their thermal mass absorbs daytime heat and releases it at night, delaying and damping indoor temperature swings.","rationale":"Correct. Heavy walls take hours to pass heat inward, smoothing large day-night swings."},{"id":"d","text":"Thick walls reflect most sunlight away from the house, so they stay cool because they absorb almost no solar heat.","rationale":"Earthen walls absorb solar heat; the point is that they store it and release it slowly."}],"correctChoiceID":"c","explanation":"Thick adobe walls have high thermal mass (thermal inertia): heat absorbed at the outer surface during the day moves inward slowly, over as long as six hours for a heavy wall. By the time stored heat reaches the interior, the desert night has cooled the outside air, and the walls release heat when it is least harmful or even welcome. The effect works best where day-night temperature swings are large. In climates without cool nights, mass alone does much less.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"nps-preservation-brief-24","title":"Preservation Brief 24: Heating, Ventilating, and Cooling Historic Buildings","publisher":"U.S. National Park Service","url":"https://www.nps.gov/orgs/1739/upload/preservation-brief-24-heating-cooling.pdf","accessedAt":"2026-10-21T06:00:00Z","usage":"publicDomain","evidenceLocator":"In warm, dry, sunny climates, thick adobe walls offered shelter from the sun and kept inside temperatures cool"},{"id":"nps-preservation-brief-3","title":"Preservation Brief 3: Improving Energy Efficiency in Historic Buildings","publisher":"U.S. National Park Service","url":"https://www.nps.gov/orgs/1739/upload/preservation-brief-03-energy-efficiency.pdf","accessedAt":"2026-10-21T06:00:00Z","usage":"publicDomain","evidenceLocator":"A wall with high thermal inertia absorbs an hour of solar heat at its surface but transfers it inward over as long as six hours"}],"tags":["thermal-mass","adobe","passive-design","climate"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"},{"id":"architecture-v3-urban-highway-essay-008","category":"architecture","conceptID":"architecture.urban-design","conceptTitle":"Urban design","type":"essay","dimension":"synthesis","difficulty":"advanced","prompt":"A city must decide whether to replace an elevated downtown highway with a surface boulevard, cap it with a park, or rebuild the viaduct. Evaluate the options using street life and land use (for example, Jane Jacobs's arguments about mixed use and active sidewalks), traffic and access, displacement and equity, cost, and climate. Explain what evidence from comparable projects you would seek and what trade-offs would remain.","choices":[],"explanation":"Coaching should push the learner to define goals and stakeholders before comparing options, use evidence from comparable cases rather than slogans, and address who gains and who bears costs.","rubric":[{"id":"goals-stakeholders","title":"Goals and stakeholders","description":"Defines the project's goals and identifies affected groups, including residents displaced when the highway was built.","weight":0.2,"coachingQuestions":["Whose neighborhood did the original highway divide?","Which goals conflict with each other?"]},{"id":"urban-form","title":"Urban form and street life","description":"Analyzes how each option shapes land use, block structure, and sidewalk activity.","weight":0.25,"coachingQuestions":["Which option creates new street frontage for buildings?","Would a capped park be active or empty at night?"]},{"id":"mobility-cost","title":"Mobility, cost, and climate","description":"Weighs traffic diversion, transit, construction cost, maintenance, and emissions with evidence.","weight":0.3,"coachingQuestions":["Where would the traffic go?","Which comparable projects measured these effects?"]},{"id":"equity","title":"Equity and displacement","description":"Considers who benefits from rising land values and how to prevent new displacement.","weight":0.25,"coachingQuestions":["Who benefits if property values rise?","What protections would existing residents need?"]}],"coachingPrompts":["State goals and affected groups first.","Compare options on the same criteria.","Cite comparable projects and what they measured.","Address who bears costs, not just who gains."],"modelOutline":["Describe the site, its history, and stakeholders","Set evaluation criteria: street life, mobility, cost, climate, equity","Assess each option against the criteria with comparable evidence","Identify displacement risks and mitigation","Recommend an option and state remaining trade-offs"],"sources":[{"id":"pps-jane-jacobs","title":"Jane Jacobs","publisher":"Project for Public Spaces","url":"https://www.pps.org/article/jjacobs-2","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Jacobs advocated mixed-use development, short blocks, and dense downtowns; she found many urban-renewal projects not safe, interesting, or alive, and opposed Robert Moses's highway plans"},{"id":"britannica-jane-jacobs","title":"Jane Jacobs","publisher":"Encyclopaedia Britannica","url":"https://www.britannica.com/biography/Jane-Jacobs","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Published The Death and Life of Great American Cities in 1961, a reinterpretation of the multiple needs of modern urban places"},{"id":"usdot-reconnecting-communities","title":"Reconnecting Communities Pilot Program","publisher":"U.S. Department of Transportation","url":"https://www.transportation.gov/reconnecting","accessedAt":"2026-10-21T06:00:00Z","usage":"publicDomain","evidenceLocator":"Grants to study and carry out removing, retrofitting, or mitigating existing transportation facilities to restore community connectivity"}],"tags":["urban-design","highways","equity","essay"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-expansion-v3","reviewerVersion":"editorial-expansion-v3","reviewStatus":"verified"}]},{"id":"hiculture-learning-medicine-v1","schemaVersion":1,"version":"1.0.0","generatedAt":"2026-10-21T06:00:00Z","questions":[{"id":"medicine-v1-physiology-homeostasis-001","category":"medicine","conceptID":"medicine.physiology-homeostasis","conceptTitle":"Physiology and homeostasis","type":"multipleChoice","dimension":"recognition","difficulty":"foundation","prompt":"During a passive leg raise, venous return to the heart increases while heart rate, sympathetic tone, and afterload stay roughly constant. Which mechanism best explains the rise in stroke volume that follows?","choices":[{"id":"a","text":"Greater sympathetic drive raises contractility at any given filling, shifting the ventricle onto a higher function curve.","rationale":"That describes a positive inotropic effect, a different mechanism; the stem holds sympathetic tone constant."},{"id":"b","text":"Greater end-diastolic filling stretches sarcomeres toward optimal overlap, so the next contraction is more forceful.","rationale":"This is the Frank–Starling relationship: within the physiological range, more preload means more fiber stretch and a stronger contraction."},{"id":"c","text":"Greater aortic pressure stretches the ventricle during ejection, so the myocardium contracts harder against the load.","rationale":"Afterload is unchanged here, and a higher afterload by itself tends to reduce, not raise, stroke volume."},{"id":"d","text":"Greater baroreceptor firing slows the heart, lengthening diastole so that the ventricle empties more completely.","rationale":"Heart rate is held constant in the stem, and a baroreflex slowing of the heart is not the Frank–Starling mechanism."}],"correctChoiceID":"b","explanation":"The Frank–Starling relationship links myocardial fiber length to contractile force: as end-diastolic volume (preload) rises, sarcomeres are stretched toward their optimal length and the ventricle ejects a larger stroke volume. A passive leg raise works as a bedside preload challenge for exactly this reason. Increased sympathetic tone would change contractility (a shift to a different curve), and higher afterload would tend to lower stroke volume.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"frank-starling","title":"Physiology, Frank Starling Law (StatPearls)","publisher":"StatPearls Publishing via U.S. National Library of Medicine (PubMed)","url":"https://pubmed.ncbi.nlm.nih.gov/29262149/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Ventricular output increases as preload (end-diastolic volume/pressure) increases because greater diastolic stretch raises fiber tension and contractile force."}],"tags":["frank-starling","preload","stroke-volume","cardiac-physiology"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-medicine-v1","reviewerVersion":"editorial-medicine-v1","reviewStatus":"verified"},{"id":"medicine-v1-physiology-homeostasis-essay-001","category":"medicine","conceptID":"medicine.physiology-homeostasis","conceptTitle":"Physiology and homeostasis","type":"essay","dimension":"synthesis","difficulty":"advanced","prompt":"A previously healthy 25-year-old loses about 1.5 L of blood over 30 minutes from a femoral wound. Explain how the body defends oxygen delivery and blood pressure over the first minutes, hours, and days. Integrate the baroreceptor reflex, changes in heart rate, contractility and vascular tone, the renin–angiotensin–aldosterone system, antidiuretic hormone, fluid shifts, and red-cell production. Then explain why compensation can fail, and what clinical signs would show that it is failing.","choices":[],"explanation":"Coaching should push the learner to connect each reflex to a term in the oxygen delivery and cardiac output equations, separate fast neural from slower hormonal and hematologic responses, and recognize that compensation trades one variable for another until reserves are exhausted.","rubric":[{"id":"equations","title":"Governing relationships","description":"Uses DO2 = CO × CaO2, CO = HR × SV, and MAP ≈ CO × SVR to show what hemorrhage threatens and what each response restores.","weight":0.25,"coachingQuestions":["Which term in the oxygen delivery equation falls first after acute blood loss?","Why does hemoglobin concentration not fall immediately after a rapid bleed?"]},{"id":"timeline","title":"Time course of compensation","description":"Distinguishes seconds-to-minutes baroreflex effects from hours-long RAAS, ADH, and transcapillary refill, and days-long erythropoietin-driven red-cell production.","weight":0.3,"coachingQuestions":["What does sympathetic venoconstriction do to preload?","Why does hemoglobin drop over hours even without further bleeding?"]},{"id":"limits","title":"Limits and decompensation","description":"Explains why tachycardia shortens filling time, why vasoconstriction starves some organs, and how acidosis and myocardial ischemia lead to decompensation.","weight":0.3,"coachingQuestions":["Which organs are sacrificed first by sympathetic vasoconstriction?","What does a rising lactate imply about the balance of delivery and demand?"]},{"id":"clinical-signs","title":"Clinical indicators","description":"Links signs such as tachycardia, narrowed pulse pressure, oliguria, altered mental status, and late hypotension to the underlying physiology.","weight":0.15,"coachingQuestions":["Why can blood pressure stay near normal despite substantial blood loss?","Which sign would most worry you that compensation is ending?"]}],"coachingPrompts":["Write the delivery and cardiac output equations before describing reflexes.","Sort each response by its timescale and by which variable it restores.","Explain one way each compensation creates a new cost or limit.","Tie each bedside sign to a specific physiological change."],"modelOutline":["State DO2, CO, and MAP relationships and what blood loss changes first","Describe the immediate baroreflex: heart rate, contractility, venoconstriction, arteriolar tone","Describe hormonal and fluid responses over hours: RAAS, ADH, transcapillary refill, hemodilution","Describe erythropoietin-driven recovery of red-cell mass over days","Explain decompensation and the clinical signs that signal it"],"sources":[{"id":"cardiac-output","title":"Physiology, Cardiac Output (StatPearls)","publisher":"StatPearls Publishing via U.S. National Library of Medicine (PubMed)","url":"https://pubmed.ncbi.nlm.nih.gov/29262215/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Cardiac output as heart rate times stroke volume, and the determinants of stroke volume (preload, afterload, contractility)."},{"id":"homeostasis","title":"Physiology, Homeostasis (StatPearls)","publisher":"StatPearls Publishing via U.S. National Library of Medicine (PubMed)","url":"https://pubmed.ncbi.nlm.nih.gov/32644564/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Homeostasis as maintenance of internal variables within a narrow range around set points despite external disturbance."},{"id":"levy-do2","title":"Pathophysiology of oxygen delivery in respiratory failure (Chest, 2005)","publisher":"U.S. National Library of Medicine (PubMed)","url":"https://pubmed.ncbi.nlm.nih.gov/16306052/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Oxygen delivery depends on oxygenation, hemoglobin, and cardiac output; interventions to support DO2 carry their own risks."}],"tags":["hemorrhage","shock","baroreflex","oxygen-delivery","essay"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-medicine-v1","reviewerVersion":"editorial-medicine-v1","reviewStatus":"verified"},{"id":"medicine-v1-physiology-homeostasis-002","category":"medicine","conceptID":"medicine.physiology-homeostasis","conceptTitle":"Physiology and homeostasis","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"A 30-year-old has hemoglobin 15 g/dL, SaO2 98%, PaO2 95 mm Hg, and cardiac output 5.0 L/min. After a week of slow gastrointestinal bleeding, hemoglobin is 7.5 g/dL, SaO2 and PaO2 are unchanged, and cardiac output has risen to 6.0 L/min. Using CaO2 = (1.34 × Hb × SaO2) + (0.003 × PaO2) in mL O2/dL and DO2 = CO × CaO2 × 10 in mL/min, which statement best describes systemic oxygen delivery?","choices":[{"id":"a","text":"It falls from about 1,000 to 610 mL/min, because halving hemoglobin nearly halves O2 content.","rationale":"CaO2 drops from about 20.0 to 10.1 mL/dL; 6.0 L/min × 10.1 × 10 ≈ 610 mL/min, so the higher cardiac output only partly compensates."},{"id":"b","text":"It stays near 1,000 mL/min, because SaO2 is unchanged and saturation is what sets arterial O2 content.","rationale":"Saturation is the fraction of hemoglobin carrying oxygen; with half the hemoglobin, content falls even at 98% saturation."},{"id":"c","text":"It rises to about 1,200 mL/min, because the 20% rise in cardiac output outweighs the hemoglobin loss.","rationale":"About 1,200 mL/min would be correct only if hemoglobin had stayed at 15 g/dL."},{"id":"d","text":"It falls to about 500 mL/min, because cardiac output changes do not enter the oxygen delivery equation.","rationale":"Cardiac output is a direct multiplier of DO2; about 500 mL/min would be the value if output had stayed at 5.0 L/min."}],"correctChoiceID":"a","explanation":"Arterial O2 content is dominated by hemoglobin-bound oxygen: before bleeding, CaO2 ≈ 1.34 × 15 × 0.98 + 0.003 × 95 ≈ 20.0 mL/dL and DO2 ≈ 5.0 × 20.0 × 10 ≈ 1,000 mL/min. After bleeding, CaO2 ≈ 10.1 mL/dL and DO2 ≈ 6.0 × 10.1 × 10 ≈ 610 mL/min. A normal saturation does not exclude reduced oxygen delivery in anemia, and the compensatory rise in cardiac output restores only part of the deficit.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"oxygen-saturation","title":"Oxygen Saturation: Monitoring and Interpretation (StatPearls)","publisher":"StatPearls Publishing via U.S. National Library of Medicine (PubMed)","url":"https://pubmed.ncbi.nlm.nih.gov/30247849/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Oxygen saturation reflects hemoglobin oxygen carriage only; normal saturation does not exclude tissue hypoxia in severe anemia, shock, or impaired extraction."},{"id":"levy-do2","title":"Pathophysiology of oxygen delivery in respiratory failure (Chest, 2005)","publisher":"U.S. National Library of Medicine (PubMed)","url":"https://pubmed.ncbi.nlm.nih.gov/16306052/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Oxygen delivery (DO2) depends jointly on oxygenation, hemoglobin, and cardiac output; failure of any factor threatens tissue oxygenation."}],"tags":["oxygen-delivery","anemia","cardiac-output","calculation"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-medicine-v1","reviewerVersion":"editorial-medicine-v1","reviewStatus":"verified"},{"id":"medicine-v1-physiology-homeostasis-003","category":"medicine","conceptID":"medicine.physiology-homeostasis","conceptTitle":"Physiology and homeostasis","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"A physiology student is sorting control loops. In which loop does the effector response push the variable further in the same direction as the initial change, rather than opposing it?","choices":[{"id":"a","text":"Rising plasma osmolality triggers ADH release, which increases water reabsorption and lowers osmolality.","rationale":"ADH restores osmolality toward its set point, so this is negative feedback."},{"id":"b","text":"Falling arterial pressure reduces baroreceptor firing, which raises sympathetic outflow and pressure.","rationale":"The baroreflex opposes the fall in pressure, which is negative feedback."},{"id":"c","text":"Cervical stretch in labor triggers oxytocin release, which intensifies contractions and further stretch.","rationale":"This is positive feedback: the response amplifies the stimulus until delivery ends the loop."},{"id":"d","text":"Rising blood glucose after a meal triggers insulin release, which increases uptake and lowers glucose.","rationale":"Insulin returns glucose toward baseline, so this loop is negative feedback."}],"correctChoiceID":"c","explanation":"Most homeostatic loops use negative feedback: a sensor detects deviation from a set point and an effector opposes it, as with ADH and osmolality, the baroreflex, and insulin. Positive feedback instead amplifies a change and is used for processes that must run to completion, such as the oxytocin–uterine contraction loop of labor (the Ferguson reflex). Recognizing the direction of the effector response relative to the stimulus is the key distinction.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"homeostasis","title":"Physiology, Homeostasis (StatPearls)","publisher":"StatPearls Publishing via U.S. National Library of Medicine (PubMed)","url":"https://pubmed.ncbi.nlm.nih.gov/32644564/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Homeostasis keeps internal variables within a narrow range around a set point despite external change, the framework within which negative and positive feedback loops are classified."}],"tags":["feedback-loops","homeostasis","oxytocin","set-point"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-medicine-v1","reviewerVersion":"editorial-medicine-v1","reviewStatus":"verified"},{"id":"medicine-v1-pathology-mechanisms-001","category":"medicine","conceptID":"medicine.pathology-mechanisms","conceptTitle":"Mechanisms of disease","type":"multipleChoice","dimension":"recognition","difficulty":"foundation","prompt":"Within minutes of a bee sting, the skin around the site becomes red, warm, and swollen. Which process is chiefly responsible for the swelling?","choices":[{"id":"a","text":"Arteriolar constriction that traps blood within the capillary beds downstream","rationale":"Acute inflammation causes arteriolar dilation, which explains redness and warmth; constriction is only brief and transient."},{"id":"b","text":"Fibroblast proliferation that deposits new collagen around the injured tissue","rationale":"Fibroblast activity belongs to repair over days, not to swelling within minutes."},{"id":"c","text":"Lymphatic vessel closure that blocks normal drainage of interstitial fluid","rationale":"Lymphatic flow increases during inflammation to clear the extra fluid."},{"id":"d","text":"Increased venular permeability letting protein-rich fluid leak into tissue","rationale":"Mediators such as histamine open gaps in postcapillary venules, producing an exudate that causes edema."}],"correctChoiceID":"d","explanation":"The classic signs of acute inflammation map onto vascular changes: arteriolar dilation causes redness (rubor) and warmth (calor), while increased permeability of postcapillary venules lets protein-rich exudate escape, causing swelling (tumor). Fibroblast proliferation and collagen deposition are features of healing that develop over days. Lymphatic drainage increases rather than stops in acute inflammation.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"inflammation","title":"Pathology, Inflammation (StatPearls)","publisher":"StatPearls Publishing via U.S. National Library of Medicine (PubMed)","url":"https://pubmed.ncbi.nlm.nih.gov/30521241/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Inflammation's classic signs include edema, erythema, warmth, pain, and loss of function, as a set of responses to tissue injury."}],"tags":["acute-inflammation","vascular-permeability","edema","cardinal-signs"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-medicine-v1","reviewerVersion":"editorial-medicine-v1","reviewStatus":"verified"},{"id":"medicine-v1-pathology-mechanisms-002","category":"medicine","conceptID":"medicine.pathology-mechanisms","conceptTitle":"Mechanisms of disease","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"At autopsy, a 74-year-old has two recent infarcts: one in the left ventricular wall from about 3 days earlier and one in the middle cerebral artery territory from about 10 days earlier. Which pairing of necrosis patterns is expected?","choices":[{"id":"a","text":"Heart: coagulative necrosis with preserved cell outlines; brain: liquefactive necrosis with softening","rationale":"Ischemic necrosis is coagulative in every solid organ except the brain, where it liquefies."},{"id":"b","text":"Heart: liquefactive necrosis with softening; brain: coagulative necrosis with preserved cell outlines","rationale":"This reverses the rule; the brain is the classic exception where ischemia produces liquefaction."},{"id":"c","text":"Heart: caseous necrosis with granulomas; brain: liquefactive necrosis with softening","rationale":"Caseous necrosis is typical of tuberculosis and some fungal infections, not myocardial ischemia."},{"id":"d","text":"Heart: coagulative necrosis with preserved cell outlines; brain: fat necrosis with calcium soaps","rationale":"Fat necrosis with saponification is typical of pancreatitis and breast trauma, not cerebral infarction."}],"correctChoiceID":"a","explanation":"Coagulative necrosis is the default pattern of ischemic or hypoxic injury in solid organs such as the heart and kidney: denatured proteins preserve tissue architecture and ghost cell outlines for days. The brain is the exception; ischemic infarcts there undergo liquefactive necrosis as enzymes digest the tissue into a soft, cystic mass. Caseous and fat necrosis are descriptive patterns tied to granulomatous infection and enzymatic fat destruction, respectively.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"necrosis","title":"Cell Liquefactive Necrosis (StatPearls)","publisher":"StatPearls Publishing via U.S. National Library of Medicine (PubMed)","url":"https://pubmed.ncbi.nlm.nih.gov/28613685/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Coagulative necrosis is the default pattern of necrosis associated with ischemia or hypoxia in every organ except the brain; liquefactive necrosis is seen following ischemic injury in the brain."}],"tags":["necrosis","infarction","ischemia","autopsy"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-medicine-v1","reviewerVersion":"editorial-medicine-v1","reviewStatus":"verified"},{"id":"medicine-v1-pathology-mechanisms-003","category":"medicine","conceptID":"medicine.pathology-mechanisms","conceptTitle":"Mechanisms of disease","type":"multipleChoice","dimension":"application","difficulty":"advanced","prompt":"A 9-month-old is diagnosed with tumors in both retinas; her father was treated for retinoblastoma in infancy. Under Knudson's two-hit model, which explanation best fits her disease?","choices":[{"id":"a","text":"She inherited a single activated oncogene allele, which by itself is enough to transform retinal cells.","rationale":"RB1 is a tumor suppressor gene, and loss of both copies, not one gain-of-function allele, drives tumor formation."},{"id":"b","text":"She inherited two inactivated RB1 alleles, one from each parent, so no further mutation was required.","rationale":"Only one germline mutation is inherited in familial cases; the second hit occurs somatically in retinal cells."},{"id":"c","text":"She inherited one inactivated RB1 allele, and a somatic hit removed the other in retinal cells.","rationale":"Hereditary retinoblastoma: the first hit is germline and each tumor needs only one more somatic hit, explaining early, bilateral disease."},{"id":"d","text":"Two somatic RB1 mutations arose in the same retinal cell, as in a typical sporadic retinoblastoma.","rationale":"Sporadic disease requires two somatic hits in one cell, so it is usually unilateral and later; it does not explain her family history."}],"correctChoiceID":"c","explanation":"Knudson proposed that retinoblastoma requires two mutational events. In the dominantly inherited form, one mutation is transmitted in the germline and the second occurs in a somatic retinal cell, so carriers develop multiple, often bilateral tumors early in life. In the nonhereditary form both hits are somatic, which typically produces a single, unilateral tumor at a later age. The model framed RB1 as the prototype tumor suppressor: recessive at the cellular level, yet dominantly inherited as a predisposition.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"knudson","title":"Mutation and cancer: statistical study of retinoblastoma (Knudson, PNAS 1971)","publisher":"U.S. National Library of Medicine (PubMed)","url":"https://pubmed.ncbi.nlm.nih.gov/5279523/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"In the dominantly inherited form, one mutation is inherited via the germinal cells and the second occurs in somatic cells; in the nonhereditary form, both mutations occur in somatic cells."}],"tags":["neoplasia","tumor-suppressor","two-hit-hypothesis","retinoblastoma"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-medicine-v1","reviewerVersion":"editorial-medicine-v1","reviewStatus":"verified"},{"id":"medicine-v1-pharmacology-principles-001","category":"medicine","conceptID":"medicine.pharmacology-principles","conceptTitle":"Principles of pharmacology","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"A drug with first-order elimination and a half-life of 8 hours is given at a fixed dose every 8 hours. On day 1, the clinician doubles the maintenance dose, hoping to reach steady state sooner. What is the expected effect?","choices":[{"id":"a","text":"Steady state arrives in about half the time, and the plateau concentration stays the same.","rationale":"Doubling the dose does not change the half-life, so the approach to steady state is no faster."},{"id":"b","text":"Steady state still takes about 32–40 hours, but the plateau concentration is about twice as high.","rationale":"Time to steady state depends on half-life (about 4–5 half-lives), while the plateau scales with the dosing rate."},{"id":"c","text":"Steady state still takes about 32–40 hours, and the plateau is unchanged as clearance rises to match.","rationale":"In first-order kinetics clearance is constant, so doubling the dosing rate doubles the steady-state level."},{"id":"d","text":"Steady state arrives in about half the time, and the plateau concentration also doubles.","rationale":"The plateau doubles, but the time to reach it is still set by the half-life, not by the dose."}],"correctChoiceID":"b","explanation":"With first-order elimination, the fraction of the eventual steady state reached depends only on the number of elapsed half-lives: about 94% after 4 and 97% after 5, here roughly 32–40 hours. The steady-state concentration is proportional to dosing rate divided by clearance, so doubling the maintenance dose doubles the plateau without speeding the approach. A loading dose, not a larger maintenance dose, is the way to reach a target concentration quickly.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"half-life","title":"Elimination Half-Life of Drugs (StatPearls)","publisher":"StatPearls Publishing via U.S. National Library of Medicine (PubMed)","url":"https://pubmed.ncbi.nlm.nih.gov/32119385/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Elimination half-life is the time for drug concentration to fall by half; it determines steady-state behavior, and most drugs follow first-order kinetics in which elimination rate is proportional to concentration."}],"tags":["half-life","steady-state","pharmacokinetics","loading-dose"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-medicine-v1","reviewerVersion":"editorial-medicine-v1","reviewStatus":"verified"},{"id":"medicine-v1-pharmacology-principles-002","category":"medicine","conceptID":"medicine.pharmacology-principles","conceptTitle":"Principles of pharmacology","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"Two drugs for the same indication are compared on the same efficacy and toxicity endpoints. Drug P has an ED50 of 2 mg and a TD50 of 10 mg. Drug Q has an ED50 of 20 mg and a TD50 of 800 mg. Which comparison is correct?","choices":[{"id":"a","text":"Drug P is safer, because a smaller dose is needed for the desired effect.","rationale":"A smaller effective dose reflects potency, not safety; P's toxic dose is only 5 times its effective dose."},{"id":"b","text":"Drug Q is more potent, because its toxic dose is so much higher (TI 40 vs 5).","rationale":"The TI values are right, but Q needs ten times more drug for the same effect, so it is less potent."},{"id":"c","text":"The two are equally safe, because each drug's toxic dose exceeds its effective dose.","rationale":"Any useful drug has TD50 above ED50; safety depends on the size of the ratio, which differs eightfold here."},{"id":"d","text":"Drug P is more potent, but Drug Q has the wider safety margin (TI 40 vs 5).","rationale":"Potency is about the dose needed for effect (P needs less); the therapeutic index TD50/ED50 is 5 for P and 40 for Q."}],"correctChoiceID":"d","explanation":"The therapeutic index compares the dose (or exposure) producing toxicity with the dose producing the desired effect, classically TD50/ED50. Drug P's index is 10/2 = 5, while Drug Q's is 800/20 = 40, so Q has the wider margin even though P is more potent. Potency (how much drug is needed) and safety margin (how far toxic exposure lies from effective exposure) are independent properties.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"therapeutic-index","title":"The determination and interpretation of the therapeutic index in drug development (Nature Reviews Drug Discovery, 2012)","publisher":"U.S. National Library of Medicine (PubMed)","url":"https://pubmed.ncbi.nlm.nih.gov/22935759/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"The therapeutic index is typically considered the ratio of the highest exposure that causes no toxicity to the exposure that produces the desired efficacy, used to balance safety and efficacy."}],"tags":["therapeutic-index","potency","dose-response","drug-safety"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-medicine-v1","reviewerVersion":"editorial-medicine-v1","reviewStatus":"verified"},{"id":"medicine-v1-pharmacology-principles-003","category":"medicine","conceptID":"medicine.pharmacology-principles","conceptTitle":"Principles of pharmacology","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"A 62-year-old taking simvastatin 40 mg daily is prescribed clarithromycin for pneumonia. Five days later he has diffuse muscle pain, dark urine, and a markedly elevated creatine kinase. Which mechanism best explains this reaction?","choices":[{"id":"a","text":"Clarithromycin inhibits CYP3A4, raising simvastatin levels and myopathy risk.","rationale":"A strong CYP3A inhibitor sharply raises levels of a sensitive CYP3A substrate such as simvastatin, causing rhabdomyolysis."},{"id":"b","text":"Clarithromycin induces CYP3A4, generating a myotoxic simvastatin metabolite.","rationale":"Clarithromycin inhibits rather than induces CYP3A; induction would lower simvastatin exposure."},{"id":"c","text":"Clarithromycin displaces simvastatin from albumin, raising its free fraction.","rationale":"Protein-binding displacement rarely causes lasting interactions because free drug is cleared faster; this is a metabolic interaction."},{"id":"d","text":"Clarithromycin is itself directly myotoxic, adding to simvastatin's effect.","rationale":"The reaction reflects a pharmacokinetic increase in statin exposure, not intrinsic muscle toxicity of the macrolide."}],"correctChoiceID":"a","explanation":"Simvastatin is a sensitive CYP3A substrate, and clarithromycin is a strong CYP3A inhibitor. Co-administration markedly increases simvastatin concentrations and with them the dose-dependent risk of myopathy and rhabdomyolysis, which is why the combination is avoided. The mechanism is pharmacokinetic inhibition of metabolism; enzyme induction would have the opposite effect, and protein-binding displacement is rarely clinically important.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"fda-cyp","title":"For Healthcare Professionals: FDA's Examples of Drugs that Interact with CYP Enzymes and Transporter Systems","publisher":"U.S. Food and Drug Administration","url":"https://www.fda.gov/drugs/drug-interactions-labeling/healthcare-professionals-fdas-examples-drugs-interact-cyp-enzymes-and-transporter-systems","accessedAt":"2026-10-21T06:00:00Z","usage":"publicDomain","evidenceLocator":"FDA table lists clarithromycin as a strong CYP3A inhibitor and simvastatin as a sensitive CYP3A substrate."}],"tags":["drug-interactions","cyp3a4","statins","rhabdomyolysis"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-medicine-v1","reviewerVersion":"editorial-medicine-v1","reviewStatus":"verified"},{"id":"medicine-v1-microbiology-immunity-001","category":"medicine","conceptID":"medicine.microbiology-immunity","conceptTitle":"Microbiology and immunity","type":"multipleChoice","dimension":"recognition","difficulty":"foundation","prompt":"Which feature most specifically distinguishes the adaptive immune system from the innate immune system?","choices":[{"id":"a","text":"Recognition of conserved microbial patterns, such as lipopolysaccharide, through Toll-like receptors","rationale":"Pattern recognition by germline-encoded receptors such as TLRs is the hallmark of innate immunity."},{"id":"b","text":"Recruitment of neutrophils and macrophages to the infected site within hours of a first exposure","rationale":"Rapid phagocyte recruitment on first exposure is an innate response."},{"id":"c","text":"Receptors assembled by gene-segment rearrangement, giving each lymphocyte clone a unique specificity","rationale":"V(D)J rearrangement in developing B and T cells creates a vast, clonally distributed receptor repertoire."},{"id":"d","text":"Activation of complement proteins that coat invading microbes and promote their phagocytosis","rationale":"Complement can be activated without antibody (alternative and lectin pathways) and is part of innate defense."}],"correctChoiceID":"c","explanation":"Innate immunity responds quickly using germline-encoded pattern recognition receptors, phagocytes, and complement. Adaptive immunity relies on T and B lymphocytes whose antigen receptors are created by rearranging gene segments during development, producing an enormously diverse, clonally distributed repertoire and, after exposure, immunologic memory. Speed, phagocyte recruitment, and complement activation all occur without that rearrangement step.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"adaptive-immunity","title":"Adaptive immunity (Journal of Allergy and Clinical Immunology, 2010)","publisher":"U.S. National Library of Medicine (PubMed)","url":"https://pubmed.ncbi.nlm.nih.gov/20061006/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"During lymphocyte development, sets of gene segments are rearranged and assembled to create genes encoding specific antigen receptors, generating a diverse repertoire; memory is another principal feature."},{"id":"niaid-immune","title":"Overview of the Immune System","publisher":"National Institute of Allergy and Infectious Diseases (NIH)","url":"https://www.niaid.nih.gov/research/immune-system-overview","accessedAt":"2026-10-21T06:00:00Z","usage":"publicDomain","evidenceLocator":"Innate immune cells are first-line responders; adaptive B and T cells mount responses to specific microbes based on previous encounters (immunological memory)."}],"tags":["innate-immunity","adaptive-immunity","vdj-recombination","lymphocytes"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-medicine-v1","reviewerVersion":"editorial-medicine-v1","reviewStatus":"verified"},{"id":"medicine-v1-microbiology-immunity-002","category":"medicine","conceptID":"medicine.microbiology-immunity","conceptTitle":"Microbiology and immunity","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"Plain pneumococcal polysaccharide vaccine gives weak, short-lived protection and little memory in children under 2 years, whereas protein–polysaccharide conjugate vaccines protect young infants and induce memory. What best explains the difference?","choices":[{"id":"a","text":"Conjugation adds a live attenuated organism, so the vaccine replicates and repeatedly boosts immunity.","rationale":"Conjugate vaccines are nonliving subunit vaccines; they do not replicate."},{"id":"b","text":"Conjugation lets the polysaccharide bind Toll-like receptors directly, bypassing the need for lymphocytes.","rationale":"Protection still depends on antibody from B cells; the gain comes from T-cell help, not from bypassing lymphocytes."},{"id":"c","text":"Conjugation routes the polysaccharide into MHC class I, triggering cytotoxic T cells against bacteria.","rationale":"Protection against encapsulated bacteria is antibody-mediated; the carrier protein engages CD4 helper T cells, not cytotoxic killing."},{"id":"d","text":"Conjugation to a carrier protein recruits helper T cells, enabling class switching and memory B cells.","rationale":"Carrier-specific T cells help polysaccharide-specific B cells, converting a T-independent antigen into a T-dependent response."}],"correctChoiceID":"d","explanation":"Polysaccharides are T cell-independent antigens: they cross-link B-cell receptors and elicit antibody but little affinity maturation or memory, and infants respond poorly. Chemically conjugating the polysaccharide to a protein carrier such as tetanus toxoid or CRM197 allows carrier-specific helper T cells to assist polysaccharide-specific B cells. The result is class switching, affinity maturation, memory B cells, and immunogenicity from about 2 months of age.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"vaccinology","title":"A guide to vaccinology: from basic principles to new developments","publisher":"Nature Reviews Immunology","url":"https://www.nature.com/articles/s41577-020-00479-7","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Polysaccharides are T cell-independent antigens; conjugation to a protein carrier lets carrier-specific T cells help B cells, giving vaccines that are immunogenic from 2 months of age and induce memory (section on conjugate vaccines, Fig. 6)."}],"tags":["vaccines","conjugate-vaccine","t-cell-help","immunologic-memory"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-medicine-v1","reviewerVersion":"editorial-medicine-v1","reviewStatus":"verified"},{"id":"medicine-v1-microbiology-immunity-003","category":"medicine","conceptID":"medicine.microbiology-immunity","conceptTitle":"Microbiology and immunity","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"A Staphylococcus aureus blood isolate is resistant to oxacillin, and PCR detects the mecA gene. Why would adding a beta-lactamase inhibitor such as clavulanate fail to restore beta-lactam activity against it?","choices":[{"id":"a","text":"mecA encodes a beta-lactamase variant that clavulanate cannot bind or inactivate.","rationale":"Methicillin and oxacillin already resist staphylococcal penicillinase; MRSA resistance is target alteration, not drug destruction."},{"id":"b","text":"mecA encodes an altered penicillin-binding protein (PBP2a) with low beta-lactam affinity.","rationale":"Cell-wall synthesis continues through PBP2a even when beta-lactams are present, regardless of beta-lactamase inhibition."},{"id":"c","text":"mecA encodes an efflux pump that expels beta-lactams before they can reach the cell wall.","rationale":"Efflux is not the mechanism of mecA-mediated resistance."},{"id":"d","text":"mecA alters the 50S ribosomal subunit so that beta-lactams can no longer bind it.","rationale":"Beta-lactams act on penicillin-binding proteins in cell-wall synthesis, not on ribosomes."}],"correctChoiceID":"b","explanation":"MRSA carries mecA (or mecC) on the SCCmec element, encoding PBP2a, a penicillin-binding protein with low affinity for beta-lactams that keeps building peptidoglycan when other PBPs are blocked. Because resistance comes from target alteration rather than enzymatic destruction, beta-lactamase inhibitors do not help. That distinction from penicillinase-mediated resistance is why oxacillin susceptibility testing or mecA detection defines MRSA.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"mrsa","title":"Methicillin-Resistant Staphylococcus aureus (StatPearls)","publisher":"StatPearls Publishing via U.S. National Library of Medicine (PubMed)","url":"https://pubmed.ncbi.nlm.nih.gov/29489200/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"MRSA carries mecA (or mecC), which confers oxacillin resistance by encoding a different penicillin-binding protein that allows cell wall synthesis in the presence of beta-lactams due to low binding affinity."}],"tags":["antibiotic-resistance","mrsa","penicillin-binding-protein","beta-lactams"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-medicine-v1","reviewerVersion":"editorial-medicine-v1","reviewStatus":"verified"},{"id":"medicine-v1-clinical-reasoning-001","category":"medicine","conceptID":"medicine.clinical-reasoning","conceptTitle":"Clinical reasoning","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"A clinician estimates a 10% pretest probability that a patient has a disease. A test with 90% sensitivity and 90% specificity comes back positive. What is the approximate post-test probability of disease?","choices":[{"id":"a","text":"About 90%, because the test's sensitivity is 90% for this disease","rationale":"Sensitivity is P(positive | disease); it is not the probability of disease given a positive result."},{"id":"b","text":"About 50%, because true and false positives are equal in number","rationale":"In 1,000 patients: 90 true positives (90% of 100) and 90 false positives (10% of 900), so 90/180 = 50%."},{"id":"c","text":"About 81%, because sensitivity times specificity gives 0.9 × 0.9 = 0.81","rationale":"Multiplying sensitivity by specificity has no probabilistic meaning for a single positive result."},{"id":"d","text":"About 19%, because a positive result roughly doubles the pretest odds","rationale":"The positive likelihood ratio is 0.9/0.1 = 9, so the odds rise ninefold, not twofold."}],"correctChoiceID":"b","explanation":"Post-test probability depends on both the test and the pretest probability. Here LR+ = sensitivity / (1 − specificity) = 9; pretest odds of 1:9 multiplied by 9 give post-test odds of 1:1, or 50%. A natural-frequency check gives the same answer: 90 true positives and 90 false positives per 1,000 patients tested. Confusing sensitivity with positive predictive value is the classic base-rate error.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"diagnostic-accuracy","title":"Diagnostic Testing Accuracy: Sensitivity, Specificity, Predictive Values and Likelihood Ratios (StatPearls)","publisher":"StatPearls Publishing via U.S. National Library of Medicine (PubMed)","url":"https://pubmed.ncbi.nlm.nih.gov/32491423/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Clinicians must integrate pretest probability with diagnostic test results using sensitivity, specificity, predictive values, and likelihood ratios."}],"tags":["bayes-theorem","pretest-probability","likelihood-ratio","predictive-value"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-medicine-v1","reviewerVersion":"editorial-medicine-v1","reviewStatus":"verified"},{"id":"medicine-v1-clinical-reasoning-essay-001","category":"medicine","conceptID":"medicine.clinical-reasoning","conceptTitle":"Clinical reasoning","type":"essay","dimension":"synthesis","difficulty":"advanced","prompt":"A 58-year-old man with a history of alcohol use disorder is brought to the emergency department confused, smelling of alcohol, and is labeled 'intoxicated' at triage. Four hours later he is still confused. Describe how you would re-approach his diagnosis. Use explicit pretest probabilities and likelihood-ratio reasoning for at least two dangerous alternatives, identify the cognitive biases that may have shaped the initial assessment, and propose specific debiasing steps that a team could build into its routine.","choices":[],"explanation":"Coaching should push the learner to treat the triage label as a hypothesis, generate a must-not-miss differential (for example hypoglycemia, head injury with intracranial hemorrhage, Wernicke encephalopathy, toxic alcohols, sepsis), reason quantitatively about how findings shift probability, and name biases precisely rather than generically.","rubric":[{"id":"differential","title":"Must-not-miss differential","description":"Generates a prioritized differential that includes time-critical, treatable causes and explains why each is plausible here.","weight":0.25,"coachingQuestions":["Which causes of confusion would be catastrophic to miss in the next hour?","What finding would make intoxication alone an inadequate explanation?"]},{"id":"bayesian","title":"Probabilistic reasoning","description":"Assigns reasonable pretest probabilities, explains how specific findings or tests change them using likelihood ratios or natural frequencies, and links results to action thresholds.","weight":0.3,"coachingQuestions":["How should persistent confusion after 4 hours change your estimate?","Which test result would move a diagnosis across your treatment threshold?"]},{"id":"biases","title":"Bias identification","description":"Names relevant biases such as anchoring, diagnosis momentum, premature closure, and stigma-driven attribution, and shows where each operated.","weight":0.25,"coachingQuestions":["At what moment was the label accepted without being tested?","How might attitudes toward alcohol use have affected the workup?"]},{"id":"debiasing","title":"Debiasing and systems","description":"Proposes concrete, routine safeguards such as diagnostic time-outs, checklists, and handoff prompts, and acknowledges their limits.","weight":0.2,"coachingQuestions":["What would trigger a mandatory reassessment?","How would you measure whether the safeguard works?"]}],"coachingPrompts":["State the triage label as a hypothesis and list what would refute it.","Put rough numbers on pretest probabilities before ordering tests.","Name a specific bias and the exact moment it operated.","Make each debiasing step something a busy team could actually do."],"modelOutline":["Restate the problem: persistent confusion not explained by the expected course of intoxication","Build a prioritized must-not-miss differential with rough pretest probabilities","Show how bedside findings and targeted tests update those probabilities","Identify the biases at triage and handoff","Propose routine debiasing safeguards and their limits"],"sources":[{"id":"croskerry","title":"The importance of cognitive errors in diagnosis and strategies to minimize them (Academic Medicine, 2003)","publisher":"U.S. National Library of Medicine (PubMed)","url":"https://pubmed.ncbi.nlm.nih.gov/12915363/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Cognitive dispositions to respond (such as anchoring and diagnosis momentum) and debiasing strategies including metacognition."},{"id":"diagnostic-accuracy","title":"Diagnostic Testing Accuracy: Sensitivity, Specificity, Predictive Values and Likelihood Ratios (StatPearls)","publisher":"StatPearls Publishing via U.S. National Library of Medicine (PubMed)","url":"https://pubmed.ncbi.nlm.nih.gov/32491423/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Integrating pretest probability with sensitivity, specificity, predictive values, and likelihood ratios to guide clinical decisions."}],"tags":["clinical-reasoning","cognitive-bias","bayesian-updating","diagnostic-error","essay"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-medicine-v1","reviewerVersion":"editorial-medicine-v1","reviewStatus":"verified"},{"id":"medicine-v1-clinical-reasoning-002","category":"medicine","conceptID":"medicine.clinical-reasoning","conceptTitle":"Clinical reasoning","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"At triage, a 34-year-old with pleuritic chest pain and a heart rate of 118 is recorded as 'probable panic attack.' The label is repeated at the resident's handoff and copied into the attending's note; no one re-examines it, and a pulmonary embolism is found 2 days later. Which cognitive error does this sequence best illustrate?","choices":[{"id":"a","text":"Availability bias: judging likelihood by how readily a recent, vivid case comes to mind","rationale":"Nothing in the stem suggests that a recent memorable case drove the judgment."},{"id":"b","text":"Base-rate neglect: misreading a test result by ignoring the disease's prevalence","rationale":"No test result was misinterpreted against prevalence; the error lay in an unexamined label."},{"id":"c","text":"Diagnostic momentum: a tentative label gains certainty as it passes between clinicians","rationale":"The provisional diagnosis hardened as it moved through triage, handoff, and documentation without being re-tested."},{"id":"d","text":"Framing effect: choosing differently because options were worded as gains or losses","rationale":"No choice between options framed as gains or losses is described."}],"correctChoiceID":"c","explanation":"Croskerry catalogued cognitive dispositions to respond that cause diagnostic error. Diagnosis momentum describes how a label attached early, often by someone else, gathers apparent certainty as it is passed along until it seems established, closing off alternatives. Here, tachycardia and pleuritic pain should have prompted reconsideration at each handoff. Debiasing strategies include deliberately re-deriving the diagnosis at transitions and asking what else must be ruled out.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"croskerry","title":"The importance of cognitive errors in diagnosis and strategies to minimize them (Academic Medicine, 2003)","publisher":"U.S. National Library of Medicine (PubMed)","url":"https://pubmed.ncbi.nlm.nih.gov/12915363/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Catalogue of cognitive dispositions to respond (biases and failed heuristics) that cause diagnostic error, with debiasing strategies such as metacognition."}],"tags":["cognitive-bias","diagnostic-error","handoffs","diagnostic-momentum"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-medicine-v1","reviewerVersion":"editorial-medicine-v1","reviewStatus":"verified"},{"id":"medicine-v1-clinical-reasoning-003","category":"medicine","conceptID":"medicine.clinical-reasoning","conceptTitle":"Clinical reasoning","type":"multipleChoice","dimension":"application","difficulty":"advanced","prompt":"For this exercise, assume a D-dimer assay has 95% sensitivity and 50% specificity for pulmonary embolism. It is negative in two patients: one with a 5% pretest probability and one with a 50% pretest probability. What are their approximate post-test probabilities?","choices":[{"id":"a","text":"About 0.5% and 9%, since the negative LR of 0.1 divides pretest odds by 10.","rationale":"LR− = 0.05/0.50 = 0.1; odds 0.053 → 0.005 (≈0.5%) and 1.0 → 0.1 (≈9%), too high to stop testing in the second patient."},{"id":"b","text":"About 5% for both, because a negative result leaves the 1 − sensitivity miss rate.","rationale":"1 − sensitivity is the miss rate among diseased patients, not the post-test probability for every patient."},{"id":"c","text":"About 0.25% and 2.5%, found by multiplying each pretest value by 1 − sensitivity.","rationale":"Likelihood ratios multiply odds, not probabilities, and the negative LR here is 0.1, not 0.05."},{"id":"d","text":"About 2.5% and 25%, found by multiplying each pretest value by 1 − specificity.","rationale":"This misuses the false-positive rate; a negative result is governed by the negative likelihood ratio."}],"correctChoiceID":"a","explanation":"The negative likelihood ratio, (1 − sensitivity)/specificity = 0.05/0.50 = 0.1, multiplies pretest odds. At a 5% pretest probability, odds of about 0.053 fall to 0.005, a post-test probability near 0.5%, low enough to stop. At 50%, odds of 1.0 fall to 0.1, a post-test probability near 9%, which remains above most testing thresholds, so imaging is still needed. The same negative result therefore rules out disease only when pretest probability is low.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"diagnostic-accuracy","title":"Diagnostic Testing Accuracy: Sensitivity, Specificity, Predictive Values and Likelihood Ratios (StatPearls)","publisher":"StatPearls Publishing via U.S. National Library of Medicine (PubMed)","url":"https://pubmed.ncbi.nlm.nih.gov/32491423/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Post-test probability is obtained by integrating pretest probability with test characteristics such as sensitivity, specificity, and likelihood ratios."}],"tags":["likelihood-ratio","rule-out","pretest-probability","d-dimer"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-medicine-v1","reviewerVersion":"editorial-medicine-v1","reviewStatus":"verified"},{"id":"medicine-v1-evidence-based-medicine-001","category":"medicine","conceptID":"medicine.evidence-based-medicine","conceptTitle":"Evidence-based medicine","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"In the RECOVERY trial, 28-day mortality among patients receiving invasive mechanical ventilation at randomization was 29.3% with dexamethasone versus 41.4% with usual care. Using these crude percentages, which set of effect measures is correct?","choices":[{"id":"a","text":"ARR about 29%, RRR 12.1 percentage points, NNT about 3","rationale":"This swaps the absolute and relative measures; the NNT must come from the absolute difference."},{"id":"b","text":"ARR 12.1 percentage points, RRR about 41%, NNT about 2","rationale":"41% is the control-group risk, not the relative reduction, and 1/0.41 is not an NNT."},{"id":"c","text":"ARR 12.1 percentage points, RRR about 29%, NNT about 12","rationale":"The NNT is the reciprocal of the ARR as a proportion (1/0.121 ≈ 8), not the ARR's numeric value."},{"id":"d","text":"ARR 12.1 percentage points, RRR about 29%, NNT about 8","rationale":"ARR = 41.4 − 29.3 = 12.1 points; RRR = 12.1/41.4 ≈ 29%; NNT = 1/0.121 ≈ 8.3."}],"correctChoiceID":"d","explanation":"Absolute risk reduction is the difference in event rates (41.4% − 29.3% = 12.1 percentage points). Relative risk reduction expresses that difference as a share of control risk (12.1/41.4 ≈ 29%). The number needed to treat is the reciprocal of the ARR, 1/0.121 ≈ 8.3, so about 8 to 9 ventilated patients needed dexamethasone to prevent one death at 28 days. RECOVERY's published age-adjusted rate ratio for this subgroup was 0.64, and the trial found no benefit in patients not receiving respiratory support.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"recovery","title":"Dexamethasone in Hospitalized Patients with Covid-19 (RECOVERY, NEJM 2021)","publisher":"The New England Journal of Medicine via PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/32678530/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Among patients receiving invasive mechanical ventilation, death within 28 days occurred in 29.3% with dexamethasone vs 41.4% with usual care (rate ratio 0.64)."},{"id":"nnt","title":"The number needed to treat: a clinically useful measure of treatment effect (BMJ, 1995)","publisher":"BMJ via PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/7873954/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"The number needed to treat is calculated as the inverse of the absolute risk reduction and is more meaningful for clinical decisions than relative measures."}],"tags":["absolute-risk","relative-risk","number-needed-to-treat","recovery-trial"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-medicine-v1","reviewerVersion":"editorial-medicine-v1","reviewStatus":"verified"},{"id":"medicine-v1-evidence-based-medicine-002","category":"medicine","conceptID":"medicine.evidence-based-medicine","conceptTitle":"Evidence-based medicine","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"In the Cardiac Arrhythmia Suppression Trial (CAST), post-MI patients with frequent ventricular premature beats were randomized to drug or placebo only after encainide, flecainide, or moricizine had suppressed their ectopy on Holter monitoring. What did the encainide/flecainide comparison show, and what is its main lesson?","choices":[{"id":"a","text":"Mortality fell with suppression, confirming ectopy as a valid surrogate endpoint for drug approval","rationale":"Mortality rose, not fell; that discordance is why CAST is cited against relying on surrogates."},{"id":"b","text":"Total mortality rose on drug (7.7% vs 3.0%), so improving a surrogate did not help patients","rationale":"The drugs suppressed the arrhythmia marker yet increased deaths, a classic surrogate-endpoint failure."},{"id":"c","text":"Mortality was unchanged, so the drugs were kept as safe options for relief of asymptomatic ectopy","rationale":"The encainide and flecainide arms were stopped early because of excess deaths and cardiac arrests."},{"id":"d","text":"Mortality was higher, but only because patients whose ectopy resisted the drugs were randomized","rationale":"Only patients whose ectopy was suppressed were randomized, so resistance cannot explain the harm."}],"correctChoiceID":"b","explanation":"CAST tested the plausible hypothesis that suppressing post-infarction ventricular ectopy, a marker of sudden-death risk, would save lives. Among patients whose ectopy was successfully suppressed, encainide or flecainide increased arrhythmic death or cardiac arrest (4.5% vs 1.2%) and total mortality (7.7% vs 3.0%) compared with placebo. Improvement in a surrogate endpoint does not guarantee benefit on outcomes that matter to patients, which is why hard clinical endpoints are needed.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"cast","title":"Preliminary report: effect of encainide and flecainide on mortality in a randomized trial of arrhythmia suppression after myocardial infarction (CAST, NEJM 1989)","publisher":"The New England Journal of Medicine via PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/2473403/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Encainide and flecainide increased arrhythmic death or nonfatal cardiac arrest (4.5% vs 1.2%) and total mortality (7.7% vs 3.0%) versus placebo despite initial arrhythmia suppression; those arms were discontinued."}],"tags":["surrogate-endpoints","randomized-trials","cast","antiarrhythmics"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-medicine-v1","reviewerVersion":"editorial-medicine-v1","reviewStatus":"verified"},{"id":"medicine-v1-evidence-based-medicine-003","category":"medicine","conceptID":"medicine.evidence-based-medicine","conceptTitle":"Evidence-based medicine","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"A cohort study finds that heavy coffee drinkers have twice the lung cancer risk of non-drinkers (crude RR 2.0). When the analysis is stratified by smoking status, the RR for coffee is 1.0 among current smokers and 1.0 among never-smokers. What is the best interpretation?","choices":[{"id":"a","text":"Smoking modifies coffee's effect, so the results should be reported separately for each stratum.","rationale":"Effect modification requires different stratum-specific estimates; here both strata show RR 1.0."},{"id":"b","text":"Smoking mediates coffee's effect, so the crude RR of 2.0 reflects coffee's total causal effect.","rationale":"A mediator lies on the causal path from exposure to outcome; coffee drinking does not cause smoking."},{"id":"c","text":"Smoking confounds the crude association; within strata, coffee shows no independent effect on lung cancer risk.","rationale":"The crude association disappears once smoking is held constant, the signature of confounding."},{"id":"d","text":"The strata are too small to trust, so the crude RR of 2.0 is the better estimate of coffee's effect.","rationale":"Nothing suggests sparse strata, and the crude estimate is the one distorted by the confounder."}],"correctChoiceID":"c","explanation":"A confounder is associated with the exposure and independently causes the outcome without lying on the causal pathway. Smoking is linked to coffee drinking and causes lung cancer, so the crude RR of 2.0 mixes coffee with smoking. Stratifying holds smoking constant; identical stratum-specific RRs of 1.0 indicate that coffee has no association of its own. Different stratum estimates would instead suggest effect modification.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"stratification","title":"Stratification for confounding, part 1: the Mantel-Haenszel formula (Nephron Clinical Practice, 2010)","publisher":"U.S. National Library of Medicine (PubMed)","url":"https://pubmed.ncbi.nlm.nih.gov/20664286/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Stratification controls confounding by creating subgroups in which the confounder does not vary; stratum-specific RRs are compared with the unstratified RR."}],"tags":["confounding","stratification","effect-modification","observational-studies"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-medicine-v1","reviewerVersion":"editorial-medicine-v1","reviewStatus":"verified"},{"id":"medicine-v1-landmark-studies-001","category":"medicine","conceptID":"medicine.landmark-studies","conceptTitle":"Landmark studies","type":"multipleChoice","dimension":"recall","difficulty":"college","prompt":"What design feature made the British Medical Research Council's 1948 trial of streptomycin for pulmonary tuberculosis a methodological landmark?","choices":[{"id":"a","text":"Patients were assigned by alternating admissions, so each ward held equal numbers in both arms","rationale":"Alternation was the older method, and it is predictable; the MRC trial replaced it with concealed random numbers."},{"id":"b","text":"Results were compared with historical controls treated by bed rest before streptomycin existed","rationale":"Controls were concurrent patients randomized to bed rest alone, not historical cases."},{"id":"c","text":"Each patient received streptomycin and then placebo in sequence, serving as his or her own control","rationale":"This was a parallel-group trial; streptomycin plus bed rest was compared with bed rest alone."},{"id":"d","text":"Allocation followed random numbers in sealed envelopes, concealed from those enrolling patients","rationale":"Bradford Hill's random sampling numbers, held in numbered sealed envelopes, removed clinician choice from allocation."}],"correctChoiceID":"d","explanation":"The 1948 MRC trial compared streptomycin plus bed rest with bed rest alone in acute progressive pulmonary tuberculosis. Allocation used series of random sampling numbers prepared by Austin Bradford Hill and placed in sealed, numbered envelopes, opened only after a patient was accepted. That concealment kept clinicians' expectations from shaping who received the drug, and radiographs were assessed by readers unaware of allocation. It is widely regarded as the first properly randomized clinical trial and the template for modern trials.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"mrc-1948","title":"Streptomycin treatment of pulmonary tuberculosis (Medical Research Council, BMJ 1948)","publisher":"BMJ via PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/18890300/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Original MRC report (BMJ 1948;2:769-82): streptomycin plus bed rest vs bed rest alone, with allocation by random sampling numbers in sealed envelopes."},{"id":"doll-1998","title":"Controlled trials: the 1948 watershed (Doll, BMJ 1998)","publisher":"BMJ via PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/9794864/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Retrospective account of the 1948 streptomycin trial as the watershed that established randomized controlled trials."}],"tags":["randomization","allocation-concealment","tuberculosis","history-of-trials"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-medicine-v1","reviewerVersion":"editorial-medicine-v1","reviewStatus":"verified"},{"id":"medicine-v1-landmark-studies-essay-001","category":"medicine","conceptID":"medicine.landmark-studies","conceptTitle":"Landmark studies","type":"essay","dimension":"synthesis","difficulty":"advanced","prompt":"Choose three of the following landmark studies, including at least one observational study and at least one randomized trial: the Framingham Heart Study (begun 1948), Doll and Hill's 1950 lung cancer study and the British Doctors Study that followed, SPRINT (2015), the DCCT (1993), and RECOVERY's dexamethasone comparison (2020–21). For each, explain what question it asked, how its design shaped what it could and could not establish, what it found, and how it changed practice. End by explaining why both observational and randomized evidence were needed to build modern preventive cardiology or tobacco control.","choices":[],"explanation":"Coaching should push the learner to tie each design (prospective cohort, case-control, randomized trial) to its strengths and blind spots, report specific findings accurately, and avoid treating any single design as automatically superior.","rubric":[{"id":"design","title":"Design and inference","description":"Correctly identifies each design and explains what it can establish (association, temporality, causation) and its key vulnerabilities such as confounding, recall bias, or limited generalizability.","weight":0.3,"coachingQuestions":["What could a case-control study of hospital patients not establish on its own?","Why does randomization license a causal claim that a cohort cannot?"]},{"id":"findings","title":"Accurate findings","description":"Reports each study's main results accurately with appropriate quantitative detail, including harms where relevant.","weight":0.3,"coachingQuestions":["What adverse effects accompanied intensive treatment in SPRINT or the DCCT?","In which patient group did dexamethasone not reduce mortality?"]},{"id":"impact","title":"Impact on practice","description":"Explains how each study changed guidelines, clinical practice, or public health policy, and what questions remained open.","weight":0.2,"coachingQuestions":["Which concept or term did Framingham introduce into medicine?","What population limits applied to SPRINT's conclusions?"]},{"id":"integration","title":"Integration across designs","description":"Argues how observational and randomized evidence complemented each other, using a coherent example.","weight":0.2,"coachingQuestions":["Why could no one randomize people to smoke?","Which questions did trials answer that cohorts had only raised?"]}],"coachingPrompts":["Name the design before describing the result.","Give at least one number per study.","State one limitation for every study, including the trials.","Explain why ethics or feasibility sometimes rules out randomization."],"modelOutline":["Introduce the evidence hierarchy and why design matters","Study 1: question, design, findings, limits, impact","Study 2: question, design, findings, limits, impact","Study 3: question, design, findings, limits, impact","Synthesis: how observational and randomized evidence combined"],"sources":[{"id":"fhs-about","title":"About the Framingham Heart Study","publisher":"Framingham Heart Study (NHLBI and Boston University)","url":"https://www.framinghamheartstudy.org/fhs-about/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Original Cohort of 5,209 adults aged 30 to 62 from Framingham, Massachusetts, enrolled in 1948 and followed prospectively to identify factors contributing to cardiovascular disease."},{"id":"fhs-milestones","title":"Framingham Heart Study Research Milestones","publisher":"Framingham Heart Study (NHLBI and Boston University)","url":"https://www.framinghamheartstudy.org/fhs-about/research-milestones/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Milestones: high blood pressure and cholesterol linked to heart disease (1957), cigarette smoking (1960), the term 'risk factor' introduced (1961)."},{"id":"doll-hill-1950","title":"Smoking and carcinoma of the lung: preliminary report (Doll and Hill, BMJ 1950)","publisher":"BMJ via PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/14772469/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Doll and Hill's 1950 preliminary report on smoking and carcinoma of the lung in London hospital patients."},{"id":"doll-2004","title":"Mortality in relation to smoking: 50 years' observations on male British doctors (BMJ, 2004)","publisher":"BMJ via PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/15213107/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Prospective study of 34,439 male British doctors from 1951 to 2001; continuing cigarette smokers died about 10 years younger, and stopping at younger ages recovered most of the lost life expectancy."},{"id":"sprint","title":"A Randomized Trial of Intensive versus Standard Blood-Pressure Control (SPRINT, NEJM 2015)","publisher":"The New England Journal of Medicine via PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/26551272/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"9,361 nondiabetic high-risk adults; target <120 vs <140 mm Hg; primary outcome HR 0.75 and all-cause mortality HR 0.73, with more hypotension, syncope, electrolyte abnormalities, and acute kidney injury."},{"id":"dcct","title":"The effect of intensive treatment of diabetes on the development and progression of long-term complications in insulin-dependent diabetes mellitus (DCCT, NEJM 1993)","publisher":"The New England Journal of Medicine via PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/8366922/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"1,441 patients with type 1 diabetes; intensive therapy reduced retinopathy development by 76% in primary prevention and slowed progression, with a two-to-threefold increase in severe hypoglycemia."},{"id":"recovery","title":"Dexamethasone in Hospitalized Patients with Covid-19 (RECOVERY, NEJM 2021)","publisher":"The New England Journal of Medicine via PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/32678530/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Dexamethasone reduced 28-day mortality in patients on invasive ventilation or oxygen, but not in those receiving no respiratory support."}],"tags":["study-design","cohort-studies","randomized-trials","landmark-studies","essay"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-medicine-v1","reviewerVersion":"editorial-medicine-v1","reviewStatus":"verified"},{"id":"medicine-v1-landmark-studies-002","category":"medicine","conceptID":"medicine.landmark-studies","conceptTitle":"Landmark studies","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"ISIS-2 randomized 17,187 patients with suspected acute myocardial infarction in a 2 × 2 factorial design: IV streptokinase or placebo infusion, and oral aspirin or placebo tablets. What did the design allow, and what did the trial find?","choices":[{"id":"a","text":"Every patient counted toward both comparisons; each drug cut vascular deaths by about a quarter, additively","rationale":"Factorial allocation answered two questions in one trial; odds reductions were about 25% and 23%, and 42% combined."},{"id":"b","text":"Each comparison used only a quarter of patients; aspirin cut vascular deaths, but streptokinase alone did not","rationale":"Each drug was compared across all patients (about half active, half placebo), and streptokinase alone was clearly beneficial."},{"id":"c","text":"Every patient counted toward both comparisons; streptokinase cut deaths, but aspirin raised cerebral hemorrhage","rationale":"Aspirin was not associated with a significant increase in cerebral hemorrhage or transfusion-requiring bleeds."},{"id":"d","text":"Every patient counted toward both comparisons; the combination of the two drugs was no better than either alone","rationale":"The combination was significantly better than either agent alone (8.0% vs 13.2% vascular deaths with neither)."}],"correctChoiceID":"a","explanation":"In a 2 × 2 factorial trial, each patient is randomized twice, so all participants contribute to both the streptokinase and the aspirin comparisons and the combination can be examined as well. ISIS-2 found that streptokinase (9.2% vs 12.0%) and aspirin (9.4% vs 11.8%) each reduced 5-week vascular mortality, with additive effects: 8.0% with both vs 13.2% with neither. Its large size and simple design produced reliable estimates of moderate effects, helping make aspirin and reperfusion standard care for acute MI.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"isis2","title":"Randomised trial of intravenous streptokinase, oral aspirin, both, or neither among 17,187 cases of suspected acute myocardial infarction: ISIS-2 (Lancet, 1988)","publisher":"The Lancet via PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/2899772/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"5-week vascular mortality: streptokinase 9.2% vs 12.0% (odds reduction 25%); aspirin 9.4% vs 11.8% (23%); both 8.0% vs neither 13.2% (42%); aspirin did not significantly increase cerebral hemorrhage."}],"tags":["factorial-design","isis-2","aspirin","myocardial-infarction"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-medicine-v1","reviewerVersion":"editorial-medicine-v1","reviewStatus":"verified"},{"id":"medicine-v1-landmark-studies-003","category":"medicine","conceptID":"medicine.landmark-studies","conceptTitle":"Landmark studies","type":"multipleChoice","dimension":"synthesis","difficulty":"advanced","prompt":"For decades, observational cohorts reported lower coronary heart disease rates among postmenopausal women using hormone therapy. The Women's Health Initiative then randomized 16,608 women aged 50–79 to conjugated equine estrogens plus medroxyprogesterone or placebo; in 2002 the trial was stopped early. Which statement best captures its findings and why its design mattered?","choices":[{"id":"a","text":"It confirmed the coronary benefit, showing that adjustment in cohorts had already removed healthy-user bias.","rationale":"The trial found a coronary hazard ratio of 1.29, not a benefit."},{"id":"b","text":"It was stopped for benefit, because fewer fractures and colorectal cancers outweighed small cardiovascular risks.","rationale":"It was stopped because invasive breast cancer crossed its harm boundary and the global index showed risks exceeding benefits."},{"id":"c","text":"It found no difference in any outcome, so it was stopped early for futility after about five years.","rationale":"There were clear differences: more CHD, stroke, PE, and breast cancer, but fewer hip fractures and colorectal cancers."},{"id":"d","text":"It found no coronary benefit (HR 1.29) and more breast cancer, stroke, and PE, with self-selection removed.","rationale":"Randomization balanced the health and social advantages of women who chose hormones, which observational adjustment had not removed."}],"correctChoiceID":"d","explanation":"Women who chose hormone therapy in observational studies tended to be healthier and more advantaged, a healthy-user effect that statistical adjustment could not fully remove. The WHI estrogen-plus-progestin trial randomized treatment, so these factors were balanced by design. After a mean of 5.2 years it found hazard ratios of 1.29 for CHD, 1.26 for breast cancer, 1.41 for stroke, and 2.13 for PE, offset partly by fewer colorectal cancers and hip fractures. It was stopped when breast cancer crossed the stopping boundary and the global index favored harm, reversing a widely held belief.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"whi","title":"Risks and benefits of estrogen plus progestin in healthy postmenopausal women: principal results from the Women's Health Initiative randomized controlled trial (JAMA, 2002)","publisher":"JAMA via PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/12117397/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Stopped after mean 5.2 years because invasive breast cancer exceeded the stopping boundary and the global index showed risks exceeding benefits; HRs: CHD 1.29, breast cancer 1.26, stroke 1.41, PE 2.13, colorectal cancer 0.63, hip fracture 0.66."}],"tags":["womens-health-initiative","hormone-therapy","healthy-user-bias","randomization"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-medicine-v1","reviewerVersion":"editorial-medicine-v1","reviewStatus":"verified"},{"id":"medicine-v1-breakthroughs-001","category":"medicine","conceptID":"medicine.breakthroughs","conceptTitle":"Medical breakthroughs","type":"multipleChoice","dimension":"recall","difficulty":"college","prompt":"Which pairing of a person with a medical breakthrough is historically accurate?","choices":[{"id":"a","text":"Edward Jenner: introduced variolation, inoculating material from human smallpox pustules","rationale":"Variolation long predated Jenner; his 1796 innovation was vaccination with cowpox material."},{"id":"b","text":"Alexander Fleming: purified penicillin and led the first patient trials of it at Oxford","rationale":"Fleming observed penicillin's effect in 1928 but did not isolate it; Florey and Chain's Oxford team did that work from 1939."},{"id":"c","text":"Frederick Banting and Charles Best: extracted insulin in Toronto in 1921 for treating diabetes","rationale":"Working in John Macleod's laboratory, they extracted insulin in 1921; Leonard Thompson received it in January 1922."},{"id":"d","text":"Joseph Lister: cut puerperal fever deaths with chlorinated-lime handwashing in Vienna","rationale":"That was Ignaz Semmelweis in the 1840s; Lister developed antiseptic surgery in Glasgow in the 1860s."}],"correctChoiceID":"c","explanation":"Banting and Best extracted insulin in Macleod's Toronto laboratory in 1921, Collip helped purify it, and 14-year-old Leonard Thompson received the first injections in January 1922; the 1923 Nobel Prize went to Banting and Macleod. The other pairings swap credit: Jenner replaced variolation with cowpox vaccination, Florey and Chain (not Fleming) isolated penicillin and showed its therapeutic power, and Semmelweis (not Lister) introduced chlorine handwashing in Vienna's maternity clinic.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"nobel-insulin-story","title":"The 'miracle' discovery that reversed the diabetes death sentence","publisher":"NobelPrize.org (Nobel Prize Outreach)","url":"https://www.nobelprize.org/the-miracle-discovery-that-reversed-the-diabetes-death-sentence/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"In Macleod's laboratory in 1921 Banting and Best extracted insulin; James Collip helped purify it; Leonard Thompson, 14, first received insulin in January 1922."},{"id":"nobel-1945-florey","title":"Howard Florey: Biographical (Nobel Prize in Physiology or Medicine 1945)","publisher":"NobelPrize.org (Nobel Prize Outreach)","url":"https://www.nobelprize.org/prizes/medicine/1945/florey/biographical/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Penicillin was discovered by Fleming in 1928 but the active substance was not isolated; from 1939 Florey and Chain's team achieved its isolation and small-scale manufacture."},{"id":"jenner","title":"Edward Jenner and the history of smallpox and vaccination (Proceedings, Baylor University Medical Center, 2005)","publisher":"U.S. National Library of Medicine (PubMed)","url":"https://pubmed.ncbi.nlm.nih.gov/16200144/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"History of smallpox, earlier variolation practice, and Jenner's development of vaccination."},{"id":"semmelweis","title":"A twenty-first century perspective on concepts of modern epidemiology in Ignaz Philipp Semmelweis' work on puerperal sepsis (European Journal of Epidemiology, 2022)","publisher":"U.S. National Library of Medicine (PubMed)","url":"https://pubmed.ncbi.nlm.nih.gov/35486338/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Semmelweis's work on puerperal sepsis mortality in maternity wards in relation to cadaver exposure and chlorine handwashing."}],"tags":["insulin","penicillin","vaccination","antisepsis"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-medicine-v1","reviewerVersion":"editorial-medicine-v1","reviewStatus":"verified"},{"id":"medicine-v1-breakthroughs-essay-001","category":"medicine","conceptID":"medicine.breakthroughs","conceptTitle":"Medical breakthroughs","type":"essay","dimension":"synthesis","difficulty":"college","prompt":"Choose two medical breakthroughs from different eras, for example surgical anesthesia (1840s), organ transplantation (first successful kidney transplant, 1954), oral rehydration therapy for cholera and diarrheal disease, CRISPR-based Casgevy for sickle cell disease (FDA approval, December 2023), or GLP-1 receptor agonists for obesity. For each, explain the biological insight behind it, the evidence that persuaded clinicians it worked, and the practical, economic, or ethical barriers that limited who benefited. Conclude with what the comparison reveals about how breakthroughs actually reach patients.","choices":[],"explanation":"Coaching should push the learner to separate discovery from validation and from delivery, use specific evidence rather than general praise, and compare a low-cost intervention with a high-cost one where possible.","rubric":[{"id":"mechanism","title":"Biological insight","description":"Explains the mechanism accurately for each breakthrough, such as coupled sodium–glucose absorption for oral rehydration or reactivation of fetal hemoglobin for Casgevy.","weight":0.3,"coachingQuestions":["Why can the gut absorb a sugar-salt solution even during cholera?","What does the edited gene change in a patient's red cells?"]},{"id":"evidence","title":"Evidence and validation","description":"Describes the studies, trials, or demonstrations that established effectiveness, with at least one specific result.","weight":0.3,"coachingQuestions":["What outcome did the pivotal study measure?","What would have counted as failure?"]},{"id":"access","title":"Barriers to benefit","description":"Analyzes cost, infrastructure, training, regulation, supply, or ethical constraints that shaped access.","weight":0.25,"coachingQuestions":["Who could deliver this treatment, and where?","How did price or supply change who benefited?"]},{"id":"comparison","title":"Comparative conclusion","description":"Draws a supported conclusion about the path from discovery to population impact.","weight":0.15,"coachingQuestions":["Which breakthrough saved more lives per dollar, and why?","What does the comparison suggest about future innovations?"]}],"coachingPrompts":["Keep discovery, proof, and delivery as separate steps.","Give at least one quantitative result for each breakthrough.","Name a concrete barrier, not just 'cost' in general.","Make your conclusion follow from the two cases you chose."],"modelOutline":["Introduce the two breakthroughs and their eras","Breakthrough 1: mechanism, evidence, barriers","Breakthrough 2: mechanism, evidence, barriers","Compare discovery-to-impact pathways","Conclude with a lesson about translation and equity"],"sources":[{"id":"ors-who","title":"Miracle cure for an old scourge (Bulletin of the World Health Organization, 2009)","publisher":"World Health Organization via PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/19274359/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Oral rehydration salts solution, once called by the Lancet 'potentially the most important medical advance' of the 20th century, saves millions of lives each year; adoption required convincing skeptics it could be given by minimally trained people."},{"id":"fda-casgevy","title":"FDA Approves First Gene Therapies to Treat Patients with Sickle Cell Disease","publisher":"U.S. Food and Drug Administration","url":"https://www.fda.gov/news-events/press-announcements/fda-approves-first-gene-therapies-treat-patients-sickle-cell-disease","accessedAt":"2026-10-21T06:00:00Z","usage":"publicDomain","evidenceLocator":"On December 8, 2023, FDA approved Casgevy and Lyfgenia for sickle cell disease in patients 12 and older; Casgevy, the first FDA-approved CRISPR/Cas9 therapy, edits patients' blood stem cells to increase fetal hemoglobin; 29 of 31 evaluable patients were free of severe vaso-occlusive crises for at least 12 consecutive months."},{"id":"step1-semaglutide","title":"Once-Weekly Semaglutide in Adults with Overweight or Obesity (STEP 1, NEJM 2021)","publisher":"The New England Journal of Medicine via PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/33567185/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"In STEP 1, once-weekly semaglutide 2.4 mg produced mean weight change of -14.9% vs -2.4% with placebo at 68 weeks; gastrointestinal effects were the most common adverse events."},{"id":"nobel-1990","title":"The Nobel Prize in Physiology or Medicine 1990","publisher":"NobelPrize.org (Nobel Prize Outreach)","url":"https://www.nobelprize.org/prizes/medicine/1990/summary/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"1990 Nobel Prize to Joseph E. Murray and E. Donnall Thomas for discoveries concerning organ and cell transplantation in the treatment of human disease."}],"tags":["oral-rehydration","gene-editing","glp-1","transplantation","essay"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-medicine-v1","reviewerVersion":"editorial-medicine-v1","reviewStatus":"verified"},{"id":"medicine-v1-breakthroughs-002","category":"medicine","conceptID":"medicine.breakthroughs","conceptTitle":"Medical breakthroughs","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"Before the 1980s, peptic ulcer disease was widely attributed to stress, lifestyle, and excess acid, and was managed with long-term acid suppression or surgery. What did Barry Marshall and Robin Warren's work, recognized with the 2005 Nobel Prize, change?","choices":[{"id":"a","text":"It showed ulcers result from autoimmune attack on parietal cells, so immunosuppression replaced surgery.","rationale":"Autoimmune destruction of parietal cells causes atrophic gastritis and pernicious anemia, not most peptic ulcers."},{"id":"b","text":"It showed most ulcers are caused by Helicobacter pylori, so antibiotics plus acid suppression cure them.","rationale":"H. pylori causes over 90% of duodenal ulcers and up to 80% of gastric ulcers; eradication prevents recurrence."},{"id":"c","text":"It showed H. pylori is a harmless commensal, so its presence no longer guides how ulcers are treated.","rationale":"The opposite: they showed H. pylori causes gastritis and ulcers, making eradication central to treatment."},{"id":"d","text":"It showed stress triggers acid hypersecretion via the vagus nerve, so vagotomy became standard therapy.","rationale":"Vagotomy predated their work and declined after it; the breakthrough was an infectious cause."}],"correctChoiceID":"b","explanation":"In 1982 Marshall and Warren cultured a spiral bacterium from gastric biopsies and linked it to gastritis and ulcers at a time when stress and lifestyle were considered the main causes. Later volunteer, treatment, and epidemiological studies established that Helicobacter pylori causes more than 90% of duodenal ulcers and up to 80% of gastric ulcers. Peptic ulcer disease became curable with a short course of antibiotics and acid suppression, and recurrence fell once the infection was eradicated.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"nobel-2005","title":"Press release: The Nobel Prize in Physiology or Medicine 2005","publisher":"NobelPrize.org (Nobel Prize Outreach)","url":"https://www.nobelprize.org/prizes/medicine/2005/press-release/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"In 1982, when Marshall and Warren discovered the bacterium, stress and lifestyle were considered the major causes; H. pylori causes more than 90% of duodenal and up to 80% of gastric ulcers; ulcers can be cured with antibiotics and acid secretion inhibitors."}],"tags":["helicobacter-pylori","peptic-ulcer","nobel-prize","paradigm-shift"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-medicine-v1","reviewerVersion":"editorial-medicine-v1","reviewStatus":"verified"},{"id":"medicine-v1-breakthroughs-003","category":"medicine","conceptID":"medicine.breakthroughs","conceptTitle":"Medical breakthroughs","type":"multipleChoice","dimension":"recognition","difficulty":"college","prompt":"Katalin Karikó and Drew Weissman shared the 2023 Nobel Prize in Physiology or Medicine. Which discovery did the prize recognize?","choices":[{"id":"a","text":"Nucleoside base modifications that keep lab-made mRNA from triggering harmful inflammatory reactions","rationale":"Modified bases, such as pseudouridine, let in vitro transcribed mRNA avoid innate immune activation and boost protein production."},{"id":"b","text":"Lipid nanoparticles that carry mRNA into cells, the delivery system used in COVID-19 vaccines","rationale":"Lipid carriers were essential to the vaccines but were not the discovery the 2023 prize cited."},{"id":"c","text":"Reverse transcription of vaccine mRNA into host DNA, which provides lasting antigen production","rationale":"mRNA vaccines do not integrate into the genome; their mRNA is degraded after translation."},{"id":"d","text":"The existence of messenger RNA as the intermediate that carries genetic code to the ribosomes","rationale":"mRNA was identified in the early 1960s, decades before Karikó and Weissman's work."}],"correctChoiceID":"a","explanation":"The 2023 prize was awarded for discoveries concerning nucleoside base modifications that enabled effective mRNA vaccines against COVID-19. Karikó and Weissman found that dendritic cells recognize in vitro transcribed mRNA as foreign and release inflammatory signals, whereas mRNA containing modified bases largely avoids this response. Lipid delivery systems were a separate, necessary advance, and mRNA itself had been discovered long before.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"nobel-2023","title":"Press release: The Nobel Prize in Physiology or Medicine 2023","publisher":"NobelPrize.org (Nobel Prize Outreach)","url":"https://www.nobelprize.org/prizes/medicine/2023/press-release/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Prize awarded jointly to Karikó and Weissman 'for their discoveries concerning nucleoside base modifications that enabled the development of effective mRNA vaccines against COVID-19'; in vitro transcribed mRNA otherwise triggered inflammatory reactions in dendritic cells."}],"tags":["mrna-vaccines","nobel-prize","innate-immunity","covid-19"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-medicine-v1","reviewerVersion":"editorial-medicine-v1","reviewStatus":"verified"},{"id":"medicine-v1-medical-training-001","category":"medicine","conceptID":"medicine.medical-training","conceptTitle":"Becoming a doctor","type":"multipleChoice","dimension":"recall","difficulty":"foundation","prompt":"How are USMLE examination results reported for exams taken on or after January 26, 2022?","choices":[{"id":"a","text":"Step 1 and Step 2 CK are pass/fail only; Step 3 alone still reports a three-digit numeric score.","rationale":"Step 2 CK continues to be reported as a three-digit score along with pass/fail."},{"id":"b","text":"Step 1 still reports a three-digit score, but programs may view it only after the residency Match.","rationale":"Step 1 no longer produces a numeric score for these administrations; transcripts show only pass or fail."},{"id":"c","text":"Step 1 is pass/fail only; Step 2 CK and Step 3 still report a three-digit score and a pass/fail result.","rationale":"USMLE moved only Step 1 to pass/fail-only reporting; the other Steps kept numeric scores."},{"id":"d","text":"All three Steps are pass/fail only, with numeric scores released only to state licensing boards.","rationale":"Only Step 1 changed; Step 2 CK and Step 3 remain scored on the three-digit scale."}],"correctChoiceID":"c","explanation":"The USMLE program announced in 2020, and confirmed in April 2021, that Step 1 would report pass/fail outcomes only for administrations on or after January 26, 2022. Step 2 Clinical Knowledge and Step 3 continue to report a three-digit score along with pass/fail. The program described the change as a way to reduce overemphasis on Step 1 scores in residency selection.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"usmle-pf","title":"Step 1 pass/fail score reporting implementation date","publisher":"United States Medical Licensing Examination (FSMB and NBME)","url":"https://www.usmle.org/step-1-passfail-score-reporting-implementation-date","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Step 1 score reporting transitioned to pass/fail outcomes only for administrations on or after January 26, 2022; Step 2 CK and Step 3 continue to be reported as a three-digit score and pass/fail."}],"tags":["usmle","step-1","licensing-exams","medical-school"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-medicine-v1","reviewerVersion":"editorial-medicine-v1","reviewStatus":"verified"},{"id":"medicine-v1-medical-training-002","category":"medicine","conceptID":"medicine.medical-training","conceptTitle":"Becoming a doctor","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"Priya, a fourth-year medical student, interviewed at Programs X and Y. She would most like to train at X but suspects X ranked her low, while Y signaled strong interest. In the NRMP Main Residency Match, how should she order her rank list?","choices":[{"id":"a","text":"Y first, because a program and applicant who rank each other first are matched before all others.","rationale":"The algorithm does not give priority to mutual first choices; it processes applicants' lists in their stated order."},{"id":"b","text":"X first, because the algorithm tries her top choice first and ranking X costs her nothing at Y.","rationale":"In the applicant-proposing algorithm, failing to match at X simply moves her to Y; ranking honestly is optimal."},{"id":"c","text":"Y first, because programs see where applicants rank them and favor those who list them first.","rationale":"Programs never see applicants' rank order lists, and their own rankings are already submitted."},{"id":"d","text":"X first, but only after she asks X how it ranked her, which the NRMP requires before certifying.","rationale":"The NRMP requires no such step, and programs' rank order lists are not disclosed to applicants."}],"correctChoiceID":"b","explanation":"The NRMP algorithm is applicant-proposing: it attempts to place each applicant in her most preferred program first and moves down the list only if that program does not also rank her highly enough. Listing X first therefore cannot hurt her chance at Y, and the NRMP advises ranking programs in order of true preference rather than where she thinks she may match. Because a match is binding, she should rank only programs where she is willing to train.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"nrmp-algorithm","title":"How the Matching Algorithm Works","publisher":"National Resident Matching Program","url":"https://www.nrmp.org/intro-to-the-match/how-matching-algorithm-works/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"The matching algorithm is applicant-proposing, attempting to place an applicant into the most preferred program on the rank order list before moving to the next; final matches are binding."},{"id":"nrmp-ranking","title":"Ranking in the 2026 Main Residency Match","publisher":"National Resident Matching Program","url":"https://www.nrmp.org/wp-content/uploads/2026/02/Ranking-in-the-2026-Main-Residency-Match.pdf","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Ranking guidelines: rank programs based on your true preference and not where you think you may match; placing a program on your list creates a binding commitment."}],"tags":["nrmp","residency-match","rank-order-list","graduate-medical-education"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-medicine-v1","reviewerVersion":"editorial-medicine-v1","reviewStatus":"verified"},{"id":"medicine-v1-medical-training-003","category":"medicine","conceptID":"medicine.medical-training","conceptTitle":"Becoming a doctor","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"A PGY-2 internal medicine resident logs these weekly totals for one four-week rotation, counting all in-house clinical and educational work, clinical work done from home, and moonlighting: 86, 78, 74, and 80 hours. No Review Committee exception applies. Under the ACGME Common Program Requirements, is she within the maximum weekly hours?","choices":[{"id":"a","text":"No, because the 80-hour cap applies to each week separately, and week 1 reached 86 hours.","rationale":"The requirement is an average over a four-week period, not a per-week ceiling."},{"id":"b","text":"Yes, because clinical work done from home is excluded, which brings week 1 below 80 hours.","rationale":"Clinical work done from home, such as EHR work and phone calls, counts toward the 80 hours."},{"id":"c","text":"No, because the cap is averaged over two weeks, and her first two weeks average 82 hours.","rationale":"The averaging period is four weeks, so the two-week figure is irrelevant."},{"id":"d","text":"Yes, because the 80-hour cap is averaged over four weeks, and her weekly average is 79.5 hours.","rationale":"318 hours over four weeks averages 79.5 hours per week, within the 80-hour limit."}],"correctChoiceID":"d","explanation":"ACGME requirement 6.20 limits clinical and educational work to no more than 80 hours per week, averaged over a four-week period, including in-house activities, clinical work done from home, and all moonlighting. Her four-week total of 318 hours averages 79.5, so she is compliant despite one 86-hour week. Related rules require at least one day in seven free (averaged over four weeks) and cap continuous work periods at 24 hours plus up to 4 hours for transitions.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"acgme-cpr","title":"ACGME Common Program Requirements (Residency), 2026","publisher":"Accreditation Council for Graduate Medical Education","url":"https://www.acgme.org/globalassets/pfassets/programrequirements/2026-prs/cprresidency_2026.pdf","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Requirement 6.20: clinical and educational work hours limited to no more than 80 hours per week, averaged over a four-week period, including in-house activities, clinical work done from home, and all moonlighting."}],"tags":["acgme","duty-hours","residency","graduate-medical-education"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-medicine-v1","reviewerVersion":"editorial-medicine-v1","reviewStatus":"verified"},{"id":"medicine-v1-medical-ethics-001","category":"medicine","conceptID":"medicine.medical-ethics","conceptTitle":"Medical ethics","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"A 78-year-old with mild Alzheimer disease refuses a recommended below-knee amputation for a gangrenous foot. On repeated discussion she states her choice consistently, accurately describes the risk of sepsis and death, acknowledges that the risk applies to her, and explains that she values dying at home over surgery. Her son asks the team to operate anyway. What is the most appropriate course?","choices":[{"id":"a","text":"Honor her refusal, since she demonstrates capacity for this specific treatment decision.","rationale":"She communicates a stable choice, understands the information, appreciates her situation, and reasons from her values."},{"id":"b","text":"Operate, because a diagnosis of dementia means she lacks decision-making capacity for surgery.","rationale":"Capacity is decision-specific and assessed by function; a dementia diagnosis alone does not remove it."},{"id":"c","text":"Seek a court ruling first, because only a judge can find a patient capable of refusing surgery.","rationale":"Clinicians assess decision-making capacity; courts adjudicate legal competence only in contested cases."},{"id":"d","text":"Defer to her son as next of kin, because family consent governs high-risk surgical decisions.","rationale":"A surrogate decides only when the patient lacks capacity; a capable patient's refusal stands."}],"correctChoiceID":"a","explanation":"Respect for autonomy means a patient with decision-making capacity may refuse even life-sustaining treatment. Capacity is judged for the specific decision by four abilities: communicating a choice, understanding relevant information, appreciating how it applies to oneself, and reasoning about options. She demonstrates all four, so her refusal should be honored, with continued discussion and palliative support. A dementia diagnosis, family wishes, or disagreement with the choice does not by itself establish incapacity.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"appelbaum","title":"Assessment of patients' competence to consent to treatment (NEJM, 2007)","publisher":"The New England Journal of Medicine via PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/17978292/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Clinical framework for assessing competence to consent: ability to communicate a choice, understand relevant information, appreciate the situation and its consequences, and reason about treatment options."},{"id":"informed-consent","title":"Informed Consent (StatPearls)","publisher":"StatPearls Publishing via U.S. National Library of Medicine (PubMed)","url":"https://pubmed.ncbi.nlm.nih.gov/28613577/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Informed consent rests on patient autonomy and requires decision-making capacity, disclosure, and voluntariness."}],"tags":["decision-making-capacity","autonomy","informed-refusal","dementia"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-medicine-v1","reviewerVersion":"editorial-medicine-v1","reviewStatus":"verified"},{"id":"medicine-v1-medical-ethics-essay-001","category":"medicine","conceptID":"medicine.medical-ethics","conceptTitle":"Medical ethics","type":"essay","dimension":"synthesis","difficulty":"advanced","prompt":"From 1932 to 1972, the U.S. Public Health Service's Untreated Syphilis Study at Tuskegee followed Black men with syphilis without obtaining informed consent and without offering treatment, even after penicillin became widely available. Analyze the study's ethical failures using the principles of respect for persons (autonomy), beneficence, nonmaleficence, and justice. Then explain how the Belmont Report and modern research protections responded, and evaluate whether those protections fully address the harms Tuskegee caused, including effects on trust in medicine.","choices":[],"explanation":"Coaching should push the learner to anchor each ethical failure in documented facts, map each to a specific principle and its practical application, and assess remaining gaps rather than presenting reform as complete.","rubric":[{"id":"facts","title":"Accurate historical account","description":"Describes the study's design, duration, participants, the absence of informed consent, and the withholding of available treatment accurately.","weight":0.2,"coachingQuestions":["When did effective treatment become available, and what happened then?","How was the study eventually ended?"]},{"id":"principles","title":"Principle-by-principle analysis","description":"Maps specific actions to violations of autonomy, beneficence, nonmaleficence, and justice with clear reasoning.","weight":0.35,"coachingQuestions":["Which decision violated justice rather than autonomy?","How did deception undermine any meaningful consent?"]},{"id":"reforms","title":"Regulatory response","description":"Explains the National Research Act, the Belmont Report's principles and applications, and institutional review and consent requirements.","weight":0.25,"coachingQuestions":["Which Belmont application addresses who is selected for research?","What does an institutional review board add that investigator judgment lacks?"]},{"id":"evaluation","title":"Critical evaluation","description":"Assesses remaining gaps, including mistrust, representation in research, and enforcement, with reasoned argument.","weight":0.2,"coachingQuestions":["Can regulation repair trust once it is broken?","What evidence would show that protections are working?"]}],"coachingPrompts":["Separate what happened from your judgment of it.","Tie each violated principle to a specific act or omission.","Explain what changed after 1972 and why.","Take a position on what remains unresolved."],"modelOutline":["Summarize the study's design, duration, and key facts","Analyze failures of respect for persons, beneficence, nonmaleficence, and justice","Explain the National Research Act and the Belmont Report's principles and applications","Evaluate the limits of reform and lasting effects on trust","Conclude with obligations for researchers today"],"sources":[{"id":"cdc-tuskegee","title":"About The Untreated Syphilis Study at Tuskegee","publisher":"Centers for Disease Control and Prevention","url":"https://www.cdc.gov/tuskegee/about/index.html","accessedAt":"2026-10-21T06:00:00Z","usage":"publicDomain","evidenceLocator":"Study conducted 1932-1972 without informed consent; participants were not offered treatment even after penicillin became widely available; ended on the recommendation of an advisory panel after news reports."},{"id":"belmont","title":"The Belmont Report: Ethical Principles and Guidelines for the Protection of Human Subjects of Research","publisher":"U.S. Department of Health and Human Services, Office for Human Research Protections","url":"https://www.hhs.gov/ohrp/regulations-and-policy/belmont-report/read-the-belmont-report/index.html","accessedAt":"2026-10-21T06:00:00Z","usage":"publicDomain","evidenceLocator":"Report issued under the National Research Act; principles of respect for persons, beneficence, and justice; cites the Tuskegee syphilis study as an injustice in the selection of research subjects."}],"tags":["tuskegee","research-ethics","belmont-report","health-equity","essay"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-medicine-v1","reviewerVersion":"editorial-medicine-v1","reviewStatus":"verified"},{"id":"medicine-v1-medical-ethics-002","category":"medicine","conceptID":"medicine.medical-ethics","conceptTitle":"Medical ethics","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"During therapy in California, a patient tells his psychologist that he intends to shoot his former business partner, whom he names, and describes buying a handgun the day before. Under the duty recognized in Tarasoff v. Regents of the University of California (1976), what is the psychologist's obligation?","choices":[{"id":"a","text":"Keep the disclosure confidential, because privilege protects all statements made in therapy.","rationale":"Tarasoff held that the protective privilege ends where the public peril begins."},{"id":"b","text":"Take reasonable steps to protect the named partner, such as warning him and notifying police.","rationale":"A serious threat of violence against an identifiable victim creates a duty to protect that overrides confidentiality."},{"id":"c","text":"Report the threat only if the patient consents, because any disclosure requires authorization.","rationale":"The duty to protect permits and requires disclosure without the patient's consent in these circumstances."},{"id":"d","text":"Warn the partner only after an overt violent act, because words alone never create a duty.","rationale":"A communicated serious threat against an identifiable person is enough to trigger the duty."}],"correctChoiceID":"b","explanation":"In Tarasoff, the California Supreme Court held that a therapist who determines, or reasonably should determine, that a patient poses a serious danger of violence to an identifiable person must use reasonable care to protect that person. The 1974 decision framed this as a duty to warn; the 1976 rehearing broadened it to a duty to protect, which may be met by warning the victim, notifying police, or initiating hospitalization. Confidentiality is a strong but not absolute duty, and states differ in whether such disclosure is mandatory or permissive.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"duty-to-warn","title":"Duty to Warn (StatPearls)","publisher":"StatPearls Publishing via U.S. National Library of Medicine (PubMed)","url":"https://pubmed.ncbi.nlm.nih.gov/31194393/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Tarasoff v. Regents of the University of California established the duty to warn in 1974, replaced by the duty to protect after rehearing in 1976, in tension with patient confidentiality."}],"tags":["confidentiality","tarasoff","duty-to-protect","psychiatry"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-medicine-v1","reviewerVersion":"editorial-medicine-v1","reviewStatus":"verified"},{"id":"medicine-v1-medical-ethics-003","category":"medicine","conceptID":"medicine.medical-ethics","conceptTitle":"Medical ethics","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"An investigator plans a minimal-risk, nontherapeutic study whose question concerns adults in general, but proposes to enroll only residents of a state psychiatric institution because they are easy to reach and rarely decline. All participants would give valid informed consent. Which Belmont Report principle does this plan most directly violate?","choices":[{"id":"a","text":"Respect for persons, which the report applies to the informed consent process","rationale":"The stem stipulates valid informed consent; the defect is in who is chosen, not how they consent."},{"id":"b","text":"Nonmaleficence, which the report lists as a principle separate from beneficence","rationale":"The Belmont Report has three principles; 'do no harm' is treated within beneficence, not as a fourth."},{"id":"c","text":"Beneficence, which the report applies to the assessment of risks and benefits","rationale":"The study is minimal-risk; the problem is the unfair distribution of research burdens."},{"id":"d","text":"Justice, which the report applies to the fair and equitable selection of research subjects","rationale":"The report warns against selecting institutionalized people for their easy availability rather than for reasons related to the problem studied."}],"correctChoiceID":"d","explanation":"The Belmont Report (1979) sets out three principles, respect for persons, beneficence, and justice, applied respectively through informed consent, assessment of risks and benefits, and selection of subjects. Justice requires scrutinizing whether some groups, such as welfare patients, particular racial and ethnic minorities, or persons confined to institutions, are being selected for their availability or manipulability rather than for scientific reasons. Nonmaleficence is a separate principle in Beauchamp and Childress's four-principle framework, but Belmont folds 'do no harm' into beneficence.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"belmont","title":"The Belmont Report: Ethical Principles and Guidelines for the Protection of Human Subjects of Research","publisher":"U.S. Department of Health and Human Services, Office for Human Research Protections","url":"https://www.hhs.gov/ohrp/regulations-and-policy/belmont-report/read-the-belmont-report/index.html","accessedAt":"2026-10-21T06:00:00Z","usage":"publicDomain","evidenceLocator":"Three basic principles (respect for persons, beneficence, justice) applied through informed consent, assessment of risks and benefits, and selection of subjects; warns against selecting welfare patients, minorities, or persons confined to institutions because of easy availability; treats 'do no harm' under beneficence."}],"tags":["belmont-report","research-ethics","justice","vulnerable-populations"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-medicine-v1","reviewerVersion":"editorial-medicine-v1","reviewStatus":"verified"},{"id":"medicine-v1-public-health-001","category":"medicine","conceptID":"medicine.public-health","conceptTitle":"Public health and epidemiology","type":"multipleChoice","dimension":"application","difficulty":"foundation","prompt":"In a well-mixed population with no prior immunity, a pathogen has a basic reproduction number (R0) of 5. Assuming a vaccine that gives complete, lasting protection, what is the approximate herd immunity threshold?","choices":[{"id":"a","text":"About 80%, since the threshold equals 1 − 1/R0","rationale":"1 − 1/5 = 0.8: when 80% are immune, each case infects on average one person or fewer."},{"id":"b","text":"About 20%, since the threshold equals 1/R0","rationale":"1/R0 is the susceptible fraction at which spread stalls; the immune fraction needed is 1 − 1/R0."},{"id":"c","text":"About 95%, the threshold used for every pathogen","rationale":"About 95% applies to highly transmissible infections such as measles; the threshold depends on R0."},{"id":"d","text":"About 50%, since majority immunity halts spread","rationale":"No fixed majority stops transmission; the required share rises with R0."}],"correctChoiceID":"a","explanation":"Under simple assumptions (homogeneous mixing, fully protective and lasting immunity), transmission declines once each case infects fewer than one other person, which happens when the immune fraction exceeds 1 − 1/R0. For R0 = 5 that is 80%. Real thresholds are higher when vaccines are less than fully effective or mixing is uneven, which is why highly transmissible measles needs coverage near 95%.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"herd-immunity","title":"\"Herd immunity\": a rough guide (Clinical Infectious Diseases, 2011)","publisher":"U.S. National Library of Medicine (PubMed)","url":"https://pubmed.ncbi.nlm.nih.gov/21427399/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Herd immunity used to refer to a threshold proportion of immune individuals above which incidence of infection should decline, and to indirect protection of susceptible individuals."}],"tags":["herd-immunity","basic-reproduction-number","vaccination","epidemiology"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-medicine-v1","reviewerVersion":"editorial-medicine-v1","reviewStatus":"verified"},{"id":"medicine-v1-public-health-essay-001","category":"medicine","conceptID":"medicine.public-health","conceptTitle":"Public health and epidemiology","type":"essay","dimension":"synthesis","difficulty":"advanced","prompt":"A city health department finds a 15-year gap in life expectancy between two neighborhoods a few miles apart. A council member proposes that the main response should be a mobile van offering free cancer screening in the lower-life-expectancy neighborhood. Evaluate the proposal. Explain how social determinants of health could produce the gap, what a screening program could and could not achieve (including lead-time bias, overdiagnosis, and follow-up capacity), and design a stronger, evidence-based strategy with measurable outcomes.","choices":[],"explanation":"Coaching should push the learner to decompose a life expectancy gap into causes, connect social conditions to specific pathways of disease, weigh screening's benefits against its biases and harms, and propose interventions whose effects can be measured.","rubric":[{"id":"determinants","title":"Social determinants","description":"Explains how conditions such as income, housing, education, environment, food access, and access to care create health differences, with plausible causal pathways.","weight":0.3,"coachingQuestions":["Which causes of death likely contribute most to a 15-year gap?","How could housing or neighborhood conditions affect cardiovascular or respiratory disease?"]},{"id":"screening","title":"Screening tradeoffs","description":"Assesses what screening could achieve and its limitations, including lead-time and length-time bias, overdiagnosis, false positives, and the need for diagnostic follow-up and treatment.","weight":0.3,"coachingQuestions":["What happens to people with abnormal results who cannot get follow-up?","Which outcome would show the van saves lives?"]},{"id":"strategy","title":"Alternative strategy","description":"Proposes multi-level interventions, such as primary care access, hypertension and diabetes control, tobacco and environmental policy, or income and housing supports, prioritized by expected impact.","weight":0.25,"coachingQuestions":["Which intervention targets the largest causes of excess deaths?","Who besides the health department must act?"]},{"id":"measurement","title":"Measurement and evaluation","description":"Specifies outcome measures, data sources, and an evaluation design that avoids misleading metrics such as survival from diagnosis.","weight":0.15,"coachingQuestions":["Why is mortality a better outcome than survival from diagnosis?","How would you know whether the gap narrowed because of your program?"]}],"coachingPrompts":["Start by asking which causes of death drive the gap.","Link each social condition to a biological or behavioral pathway.","Treat screening as a chain: test, follow-up, and treatment.","Choose outcomes that cannot be inflated by lead time or overdiagnosis."],"modelOutline":["Frame the gap and its likely leading causes of excess death","Explain social determinants and their pathways to disease","Evaluate the screening van's benefits, biases, and harms","Propose a prioritized, multi-sector strategy","Define measurable outcomes and an evaluation plan"],"sources":[{"id":"who-sdoh","title":"Social determinants of health","publisher":"World Health Organization","url":"https://www.who.int/health-topics/social-determinants-of-health","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Social determinants of health are the conditions in which people are born, grow, live, work and age, and their access to power, money and resources, which powerfully influence health inequities."},{"id":"health-screening","title":"Health Screening (StatPearls)","publisher":"StatPearls Publishing via U.S. National Library of Medicine (PubMed)","url":"https://pubmed.ncbi.nlm.nih.gov/28613785/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Screening raises debates over sensitivity, specificity, prevalence, predictive values, lead-time bias, intervals, cutoffs, and costs."},{"id":"welch-overdiagnosis","title":"Overdiagnosis in cancer (Journal of the National Cancer Institute, 2010)","publisher":"U.S. National Library of Medicine (PubMed)","url":"https://pubmed.ncbi.nlm.nih.gov/20413742/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Overdiagnosis estimates from randomized trials and population data; patients must be informed of the trade-offs of early detection."}],"tags":["social-determinants","health-equity","screening","program-evaluation","essay"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-medicine-v1","reviewerVersion":"editorial-medicine-v1","reviewStatus":"verified"},{"id":"medicine-v1-public-health-002","category":"medicine","conceptID":"medicine.public-health","conceptTitle":"Public health and epidemiology","type":"multipleChoice","dimension":"application","difficulty":"advanced","prompt":"A new screening test detects a cancer about 2 years before symptoms would appear. Median survival from diagnosis is 7 years for screen-detected cases and 5 years for clinically detected cases, yet the age at death from the cancer is identical in both groups. Which bias best explains the apparent survival gain?","choices":[{"id":"a","text":"Length-time bias: screening preferentially finds slow-growing tumors with long preclinical phases","rationale":"Length bias would make screen-detected cases intrinsically less aggressive; the stem's identical age at death points to lead time."},{"id":"b","text":"Overdiagnosis: screening finds tumors that would never have caused symptoms or death","rationale":"Overdiagnosed cases would not die of the cancer, yet here every case dies at the same age."},{"id":"c","text":"Lead-time bias: earlier diagnosis starts the survival clock sooner without delaying death","rationale":"The 2-year gain in survival matches the 2-year earlier diagnosis exactly, and deaths occur at the same age."},{"id":"d","text":"Healthy-volunteer bias: people who choose screening are healthier than those who do not","rationale":"Healthier volunteers would tend to live longer overall, not die of the cancer at an identical age."}],"correctChoiceID":"c","explanation":"Lead time is the interval by which screening advances diagnosis. If death occurs at the same age, survival measured from diagnosis lengthens by exactly that interval even though no life is extended. That is why screening is judged by disease-specific or all-cause mortality in randomized trials rather than by survival from diagnosis. Length-time bias and overdiagnosis also inflate survival statistics, but each predicts different patterns from the one described.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"health-screening","title":"Health Screening (StatPearls)","publisher":"StatPearls Publishing via U.S. National Library of Medicine (PubMed)","url":"https://pubmed.ncbi.nlm.nih.gov/28613785/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Screening debates involve sensitivity and specificity, disease prevalence, predictive values, lead-time bias, screening intervals, and cutoffs."},{"id":"welch-overdiagnosis","title":"Overdiagnosis in cancer (Journal of the National Cancer Institute, 2010)","publisher":"U.S. National Library of Medicine (PubMed)","url":"https://pubmed.ncbi.nlm.nih.gov/20413742/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Overdiagnosis is diagnosis of a cancer that would otherwise not go on to cause symptoms or death; it requires a silent disease reservoir and activities such as screening that detect it."}],"tags":["screening","lead-time-bias","survival-statistics","cancer"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-medicine-v1","reviewerVersion":"editorial-medicine-v1","reviewStatus":"verified"},{"id":"medicine-v1-public-health-003","category":"medicine","conceptID":"medicine.public-health","conceptTitle":"Public health and epidemiology","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"After thyroid ultrasound screening spread widely in South Korea, thyroid cancer diagnoses rose about 15-fold over roughly two decades, while thyroid cancer mortality stayed essentially flat. Which interpretation is best supported?","choices":[{"id":"a","text":"A true epidemic: a new exposure raised incidence, and better treatment held mortality steady.","rationale":"A real 15-fold rise in clinically important cancer would almost certainly raise deaths; the increase tracked screening."},{"id":"b","text":"Lead-time bias: the cancers were found earlier, but each patient's survival time was unchanged.","rationale":"Lead time distorts survival from diagnosis; it cannot explain a 15-fold rise in how many cancers are found."},{"id":"c","text":"Effective screening: earlier detection prevented the deaths that the rising incidence implied.","rationale":"Screening that saves lives lowers mortality below its prior level; here mortality never changed."},{"id":"d","text":"Overdiagnosis: screening found many small cancers that would never have caused harm or death.","rationale":"A large rise in incidence with no change in mortality is the signature of detecting a reservoir of indolent disease."}],"correctChoiceID":"d","explanation":"Overdiagnosis occurs when screening detects disease that would never have caused symptoms or death in a person's lifetime, which requires a reservoir of silent disease and an activity that finds it. Small papillary thyroid cancers are a large reservoir, and widespread ultrasound found them in great numbers. Rising incidence with flat mortality, along with treatment harms such as hypoparathyroidism and vocal-cord paralysis, is the classic signature. Lead-time bias affects survival time, not the number of cases detected.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"korea-thyroid","title":"Korea's thyroid-cancer \"epidemic\": screening and overdiagnosis (NEJM, 2014)","publisher":"The New England Journal of Medicine via PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/25372084/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"In South Korea, widespread screening was followed by about a 15-fold increase in thyroid cancer diagnoses with essentially unchanged thyroid cancer mortality, attributed to overdiagnosis."},{"id":"welch-overdiagnosis","title":"Overdiagnosis in cancer (Journal of the National Cancer Institute, 2010)","publisher":"U.S. National Library of Medicine (PubMed)","url":"https://pubmed.ncbi.nlm.nih.gov/20413742/","accessedAt":"2026-10-21T06:00:00Z","usage":"linkOnly","evidenceLocator":"Overdiagnosis requires a silent disease reservoir and activities leading to its detection; population statistics suggest overdiagnosis of thyroid cancer."}],"tags":["overdiagnosis","screening","thyroid-cancer","incidence-vs-mortality"],"generatedAt":"2026-10-21T06:00:00Z","generatorVersion":"curated-medicine-v1","reviewerVersion":"editorial-medicine-v1","reviewStatus":"verified"}]},{"id":"hiculture-learning-botany-v1","schemaVersion":1,"version":"1.0.0","generatedAt":"2026-11-10T12:00:00Z","questions":[{"id":"botany-v1-nail-in-trunk-001","category":"botany","conceptID":"botany.meristems-growth","conceptTitle":"Meristems and where plants grow","type":"multipleChoice","dimension":"application","difficulty":"foundation","prompt":"A hiker drives a nail into the trunk of a young oak, 1.5 meters above the ground. Twenty years later the tree stands 12 meters taller and its trunk is far wider. Where is the nail now, and why?","choices":[{"id":"a","text":"About 13.5 meters up, because cells all along the trunk keep dividing and stretching as the tree gains height.","rationale":"This treats a trunk like a growing animal limb. Mature stem tissue below the tips has stopped elongating, so it cannot carry the nail upward."},{"id":"b","text":"Still about 1.5 meters up, because height is added only at the shoot tips, while the trunk below just thickens.","rationale":"Correct. Apical meristems at the shoot tips add length; lateral meristems widen the trunk, so the nail stays at its height and is slowly buried in new wood."},{"id":"c","text":"Roughly halfway up the trunk, because growth in height is shared between the base of the tree and its shoot tips.","rationale":"Trees do not grow in length from the base. Grass leaves do, from intercalary meristems, but a woody trunk elongates only at its tips."},{"id":"d","text":"A little below 1.5 meters, because the wood laid down above the nail each year presses the older wood downward.","rationale":"New wood is added as layers around the trunk by the vascular cambium, not stacked on top, so nothing pushes older wood down."}],"correctChoiceID":"b","explanation":"Plants grow from meristems, localized zones of dividing cells. Apical meristems at the tips of shoots and roots produce growth in length, and lateral meristems (the vascular cambium and cork cambium) produce growth in girth. Once a section of trunk has matured it no longer elongates, so a mark on it stays at the same height while new wood grows outward around it.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"openstax-biology-2e-30-1","title":"Biology 2e, 30.1 The Plant Body","publisher":"OpenStax, Rice University","url":"https://openstax.org/books/biology-2e/pages/30-1-the-plant-body","accessedAt":"2026-11-10T12:00:00Z","usage":"openLicense","evidenceLocator":"Plant Tissues: apical meristems at the tips of stems and roots extend length; lateral meristems increase girth"},{"id":"openstax-biology-2e-30-2","title":"Biology 2e, 30.2 Stems","publisher":"OpenStax, Rice University","url":"https://openstax.org/books/biology-2e/pages/30-2-stems","accessedAt":"2026-11-10T12:00:00Z","usage":"openLicense","evidenceLocator":"Growth in Stems: primary growth from apical meristems, secondary growth from lateral meristems"}],"tags":["meristems","primary-growth","secondary-growth","trees"],"generatedAt":"2026-11-10T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"editorial-v1","reviewStatus":"verified"},{"id":"botany-v1-cam-night-acid-002","category":"botany","conceptID":"botany.photosynthesis-pathways","conceptTitle":"C3, C4 and CAM photosynthesis","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"A greenhouse technician monitoring a pineapple plant finds that its stomata open mainly at night. The sap in its leaf cells grows steadily more acidic until dawn, then loses that acidity during the day while the stomata stay shut. Which explanation best accounts for both observations?","choices":[{"id":"a","text":"The Calvin cycle runs at night in this plant on ATP saved from the day, and its first sugar products are acidic.","rationale":"The Calvin cycle depends on ATP and NADPH made by the light reactions and runs by day. The old label 'dark reactions' does not mean it happens in darkness."},{"id":"b","text":"Respiration at night releases CO2 that dissolves as carbonic acid, and daytime photosynthesis then uses it up.","rationale":"Respiratory CO2 would escape through the open stomata, and carbonic acid is far too weak to explain the swing. The stored acid is malic acid."},{"id":"c","text":"Open stomata at night let in oxygen for photorespiration, which builds up acids that sunlight later breaks down.","rationale":"Photorespiration is a daytime side reaction of Rubisco in the light. CAM in fact reduces it by raising CO2 around Rubisco behind closed stomata."},{"id":"d","text":"CO2 taken in at night is fixed into malic acid and stored; by day the acid releases CO2 for the Calvin cycle.","rationale":"Correct. This is crassulacean acid metabolism: carbon is captured at night, when opening stomata costs little water, and used in daylight."}],"correctChoiceID":"d","explanation":"CAM plants separate carbon capture from the Calvin cycle in time. At night, when the air is cooler and more humid, they open their stomata and fix CO2 into four-carbon acids that accumulate in the vacuole; by day they close the stomata and release that CO2 internally for the Calvin cycle. The trade-off is water economy against speed: storage space for acid limits how much carbon can be fixed, so CAM plants save water but usually grow slowly.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"openstax-biology-2e-8-3","title":"Biology 2e, 8.3 Using Light Energy to Make Organic Molecules","publisher":"OpenStax, Rice University","url":"https://openstax.org/books/biology-2e/pages/8-3-using-light-energy-to-make-organic-molecules","accessedAt":"2026-11-10T12:00:00Z","usage":"openLicense","evidenceLocator":"Evolution Connection, Photosynthesis: cacti fix and store CO2 at night and use it by day with stomata closed"},{"id":"britannica-crassulacean-acid-metabolism","title":"Crassulacean acid metabolism","publisher":"Encyclopaedia Britannica","url":"https://www.britannica.com/science/crassulacean-acid-metabolism","accessedAt":"2026-11-10T12:00:00Z","usage":"linkOnly","evidenceLocator":"Article text: nighttime CO2 uptake, storage as malic acid, daytime release with stomata closed"}],"tags":["photosynthesis","cam","stomata","water-use"],"generatedAt":"2026-11-10T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"editorial-v1","reviewStatus":"verified"},{"id":"botany-v1-xylem-tension-003","category":"botany","conceptID":"botany.water-transport","conceptTitle":"Water transport and transpiration","type":"multipleChoice","dimension":"application","difficulty":"advanced","prompt":"At midday a researcher cuts a leafy twig from a transpiring tree. Under a lens, the sap at the cut end is seen to draw back into the wood instead of oozing out. With the twig sealed in a pressure chamber and only the cut end exposed, about 1.5 MPa of gas pressure must be applied before sap returns to the cut surface. What do these observations indicate about water in the xylem of the intact tree?","choices":[{"id":"a","text":"It was under tension, pulled upward by evaporation from the leaves and not pushed up by pressure from below.","rationale":"Correct. Sap that retreats when the column is cut was being stretched, and the pressure needed to return it measures that tension."},{"id":"b","text":"It was under positive pressure from the roots, and cutting the twig removed the pump that had held sap in place.","rationale":"Sap under positive pressure would bleed from the cut, as it does from some plants at night. Root pressure is small and cannot supply a transpiring tree."},{"id":"c","text":"It was at atmospheric pressure, rising by capillary action alone, and the chamber measures how tightly wood grips it.","rationale":"Capillarity in conduits as wide as xylem vessels can lift water only about a meter or less, and it cannot explain a column that snaps back when cut."},{"id":"d","text":"It was being pumped upward by living cells along the stem, and cutting the twig cut off their supply of energy.","rationale":"Xylem conduits are dead and hollow at maturity, and water keeps rising through stems whose living cells have been killed."}],"correctChoiceID":"a","explanation":"The cohesion-tension theory holds that evaporation from leaf cell walls pulls on continuous water columns in the xylem, and that cohesion between water molecules transmits this pull all the way down to the roots. Water in a transpiring plant is therefore at negative pressure. The pressure chamber exploits this: the gas pressure needed to push sap back to the cut surface approximately equals the tension the column was under before the cut.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"openstax-biology-2e-30-5","title":"Biology 2e, 30.5 Transport of Water and Solutes in Plants","publisher":"OpenStax, Rice University","url":"https://openstax.org/books/biology-2e/pages/30-5-transport-of-water-and-solutes-in-plants","accessedAt":"2026-11-10T12:00:00Z","usage":"openLicense","evidenceLocator":"Movement of Water and Minerals in the Xylem: transpiration creates negative pressure (tension); cohesion-tension theory of sap ascent"},{"id":"prometheus-pressure-chamber","title":"Pressure chamber","publisher":"PROMETHEUS: Protocols in Ecological and Environmental Science","url":"https://prometheusprotocols.net/function/water-relations/measuring-plant-water-status/pressure-chamber/","accessedAt":"2026-11-10T12:00:00Z","usage":"linkOnly","evidenceLocator":"Definitions and Measurement approaches: external pressure is raised until xylem solution returns to the cut surface, balancing the tension on water in the xylem"}],"tags":["xylem","cohesion-tension","transpiration","water-potential"],"generatedAt":"2026-11-10T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"editorial-v1","reviewStatus":"verified"},{"id":"botany-v1-wilty-mutant-aba-004","category":"botany","conceptID":"botany.stomata-hormones","conceptTitle":"Stomata, guard cells and abscisic acid","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"A tomato mutant wilts on warm afternoons even when its soil is moist, while normal plants beside it stay firm. The mutant's roots and xylem are structurally normal, and its leaves stop wilting if they are sprayed with abscisic acid (ABA). What is the most likely reason the unsprayed mutant wilts?","choices":[{"id":"a","text":"Without ABA its roots cannot take in water by osmosis, so supply to the leaves falls behind even in moist soil.","rationale":"Roots take up water along a water-potential gradient whether or not ABA is present. The hormone's decisive action is at the other end of the pathway, on water loss from leaves."},{"id":"b","text":"Without ABA its leaf cells cannot build up solutes, so they lose turgor whenever the surrounding air is warm.","rationale":"ABA is not needed for cells to hold solutes. The mutant's cells are sound; they simply lose water faster than it arrives."},{"id":"c","text":"Without ABA its guard cells do not close the stomata, so it loses water faster than its roots can replace it.","rationale":"Correct. ABA made under water stress makes guard cells lose solutes and turgor, closing the pores; a plant that cannot make it keeps transpiring."},{"id":"d","text":"Without ABA its xylem vessels fill with air bubbles, so the water column to the leaves breaks each afternoon.","rationale":"ABA does not keep xylem free of air. Embolism is a consequence of extreme tension, and a spray on the leaves would not repair it."}],"correctChoiceID":"c","explanation":"Each stoma is flanked by two guard cells that open the pore when they swell with water and close it when they go limp. When a plant begins to run short of water it makes abscisic acid, which causes guard cells to release solutes, lose turgor and shut the pores. ABA-deficient mutants cannot make this adjustment, so they keep losing water through open stomata and wilt, and supplying the hormone restores normal behavior.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"openstax-biology-2e-30-6","title":"Biology 2e, 30.6 Plant Sensory Systems and Responses","publisher":"OpenStax, Rice University","url":"https://openstax.org/books/biology-2e/pages/30-6-plant-sensory-systems-and-responses","accessedAt":"2026-11-10T12:00:00Z","usage":"openLicense","evidenceLocator":"Growth Responses, Abscisic Acid: ABA accumulates under water stress and causes stomata to close"},{"id":"openstax-biology-2e-30-5","title":"Biology 2e, 30.5 Transport of Water and Solutes in Plants","publisher":"OpenStax, Rice University","url":"https://openstax.org/books/biology-2e/pages/30-5-transport-of-water-and-solutes-in-plants","accessedAt":"2026-11-10T12:00:00Z","usage":"openLicense","evidenceLocator":"Control of Transpiration: stomata regulate water loss from the leaf"}],"tags":["abscisic-acid","stomata","guard-cells","hormones"],"generatedAt":"2026-11-10T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"editorial-v1","reviewStatus":"verified"},{"id":"botany-v1-phloem-source-sink-005","category":"botany","conceptID":"botany.phloem-transport","conceptTitle":"Phloem transport from source to sink","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"A researcher lets one mature leaf, halfway up a tomato plant, photosynthesize in air containing radioactive carbon dioxide. A few hours later, labeled sugar is found in the roots below that leaf and in the young leaves and developing fruit above it, but hardly any in the other mature leaves. Which interpretation fits best?","choices":[{"id":"a","text":"Sugar dissolves in the xylem's transpiration stream, so it ends up wherever water is being pulled through the plant.","rationale":"Xylem sap moves one way, from roots toward transpiring leaves. It could not carry sugar down to the roots, and it would deliver most to mature leaves."},{"id":"b","text":"Phloem carries sugar by bulk flow from a source leaf to whichever sinks are drawing on it, upward or downward.","rationale":"Correct. Flow runs from where sugar is loaded to where it is unloaded, so one leaf can feed roots below and fruit above while bypassing other sources."},{"id":"c","text":"Sugar diffuses out of the leaf through living cells in all directions, so it reaches whatever tissue lies closest.","rationale":"Diffusion is far too slow over these distances, and it would label nearby mature leaves instead of skipping them."},{"id":"d","text":"Phloem moves sugar only downward to the roots, and the label found above the leaf got there later in the xylem.","rationale":"Phloem is not a one-way downward pipe. Growing shoot tips and fruits are sinks supplied directly by phloem from leaves below them."}],"correctChoiceID":"b","explanation":"In the pressure-flow model, sugar is actively loaded into sieve tubes at a source, water follows by osmosis, and the resulting pressure drives sap toward sinks, where sugar is unloaded. Direction is set by where the sources and sinks are, not by gravity, so phloem can run up and down the same stem at once. Mature leaves are net exporters, which is why label from one leaf does not accumulate in the others.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"openstax-biology-2e-30-5","title":"Biology 2e, 30.5 Transport of Water and Solutes in Plants","publisher":"OpenStax, Rice University","url":"https://openstax.org/books/biology-2e/pages/30-5-transport-of-water-and-solutes-in-plants","accessedAt":"2026-11-10T12:00:00Z","usage":"openLicense","evidenceLocator":"Transportation of Photosynthates in the Phloem; Translocation: Transport from Source to Sink"}],"tags":["phloem","pressure-flow","source-sink","translocation"],"generatedAt":"2026-11-10T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"editorial-v1","reviewStatus":"verified"},{"id":"botany-v1-semi-dwarf-wheat-006","category":"botany","conceptID":"botany.green-revolution","conceptTitle":"Gibberellin and the Green Revolution","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"Tall traditional wheat varieties gave little extra grain when heavily fertilized with nitrogen, and often yielded less. The semi-dwarf varieties bred in Norman Borlaug's program, whose stems respond only weakly to the hormone gibberellin, yielded far more under the same fertilizer. What best explains the difference?","choices":[{"id":"a","text":"Short stems lose less water to the air, so semi-dwarf plants could keep photosynthesizing through dry spells.","rationale":"The dwarfing genes do not confer drought tolerance; Green Revolution wheats did best with irrigation. The gain came from how they handled fertilizer."},{"id":"b","text":"Short plants can be sown far more densely, so yield per field rose even though each plant made no more grain.","rationale":"The gain was not just packing. Each semi-dwarf plant put a larger share of its growth into grain and stayed standing to ripen it."},{"id":"c","text":"Gibberellin normally suppresses grain filling, so plants that respond weakly to it set larger kernels by default.","rationale":"Gibberellin does not suppress grain filling. Its relevant effect here is promoting stem elongation, which the dwarfing genes blunt."},{"id":"d","text":"Tall fertilized plants grew top-heavy and fell over, while short stiff stems stayed up and sent more growth to grain.","rationale":"Correct. Extra nitrogen makes tall wheat lodge; short-strawed plants stand under heavy heads and partition more biomass to grain."}],"correctChoiceID":"d","explanation":"Gibberellins promote stem elongation. The dwarfing genes that came into modern wheat from the Japanese variety Norin 10 make stems respond poorly to gibberellin, producing short, stiff straw. Heavily fertilized tall wheat lodges, meaning it collapses under its own heads, while semi-dwarf wheat stays upright and devotes a larger fraction of its growth to grain, which is why these varieties could turn fertilizer and irrigation into yield.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"usda-ars-green-revolution","title":"The Green Revolution","publisher":"USDA Agricultural Research Service","url":"https://www.ars.usda.gov/oc/timeline/green/","accessedAt":"2026-11-10T12:00:00Z","usage":"publicDomain","evidenceLocator":"ARS Timeline entry: tall wheats under heavy nitrogen grew too tall, became top-heavy and lodged; Norin 10 dwarfing genes; Vogel and Borlaug"},{"id":"openstax-biology-2e-30-6","title":"Biology 2e, 30.6 Plant Sensory Systems and Responses","publisher":"OpenStax, Rice University","url":"https://openstax.org/books/biology-2e/pages/30-6-plant-sensory-systems-and-responses","accessedAt":"2026-11-10T12:00:00Z","usage":"openLicense","evidenceLocator":"Growth Responses, Gibberellins: gibberellins stimulate shoot elongation"}],"tags":["gibberellin","green-revolution","wheat","lodging","crops"],"generatedAt":"2026-11-10T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"editorial-v1","reviewStatus":"verified"},{"id":"botany-v1-phototropism-mica-007","category":"botany","conceptID":"botany.tropisms-auxin","conceptTitle":"Tropisms and auxin","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"In a classic experiment, grass seedlings were lit from one side. A thin sheet of mica, which blocks the movement of chemicals, was pushed halfway into the shoot just below the tip. With the mica on the shaded side the seedling did not bend; with the mica on the lit side it bent toward the light as usual. What does this result show?","choices":[{"id":"a","text":"A growth-promoting signal from the tip moves down the shaded side, where it makes cells elongate faster.","rationale":"Correct. Blocking the shaded side stops the bend and blocking the lit side does not, so the active signal travels down the shaded flank."},{"id":"b","text":"A growth-slowing signal from the tip moves down the lit side, where it holds back the elongation of cells.","rationale":"If an inhibitor traveled down the lit side, mica placed there would have prevented bending. It did not."},{"id":"c","text":"Light is sensed by the very cells that bend, so a barrier matters only if it happens to shade those cells.","rationale":"Earlier work showed the tip senses the light while the bend occurs lower down, and mica on the lit side changed nothing."},{"id":"d","text":"Cells on the lit side shrink as the light dries them, so the shoot bends without any signal from its tip.","rationale":"If drying caused the bend, a barrier on the shaded side would be irrelevant. Instead it abolished the response."}],"correctChoiceID":"a","explanation":"Phototropism depends on a chemical messenger made in the shoot tip, later identified as the auxin indole-3-acetic acid. Under one-sided light more auxin ends up on the shaded flank, where it stimulates cell elongation, so that side outgrows the lit side and the shoot curves toward the light. Barrier experiments like this one located the signal's route decades before the molecule itself was isolated.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"openstax-biology-2e-30-6","title":"Biology 2e, 30.6 Plant Sensory Systems and Responses","publisher":"OpenStax, Rice University","url":"https://openstax.org/books/biology-2e/pages/30-6-plant-sensory-systems-and-responses","accessedAt":"2026-11-10T12:00:00Z","usage":"openLicense","evidenceLocator":"Plant Responses to Light, The Blue Light Responses: Darwin and Boysen-Jensen experiments on phototropism; Growth Responses, Auxins"}],"tags":["phototropism","auxin","hormones","experiments"],"generatedAt":"2026-11-10T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"editorial-v1","reviewStatus":"verified"},{"id":"botany-v1-night-break-008","category":"botany","conceptID":"botany.photoperiodism","conceptTitle":"Photoperiodism and phytochrome","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"A grower keeps chrysanthemums on 9 hours of light and 15 hours of darkness, a schedule that normally brings them into flower. When a dim work lamp is switched on for an hour in the middle of each night, the plants stay leafy, although the light energy they receive each day has barely changed. An hour of darkness at midday has no such effect. What do these results indicate?","choices":[{"id":"a","text":"The plants flower once the total light energy they absorb in a day drops below a fixed threshold amount.","rationale":"An hour of dim lamp light adds almost nothing to the daily total, yet it blocked flowering completely."},{"id":"b","text":"The plants flower when daylight lasts less than a critical number of hours, however the dark is divided.","rationale":"This is what the name short-day plant suggests, but even counting the lamp the plants had only 10 hours of light. What changed was the continuity of the night."},{"id":"c","text":"The plants flower only after a long enough stretch of unbroken darkness, which the lamp split into two.","rationale":"Correct. Short-day plants are really long-night plants: they need the dark period to exceed a critical length without interruption."},{"id":"d","text":"The plants flower in response to cool night temperatures, which the warmth of the lamp raised for a time.","rationale":"Some plants do need cold to flower, but a dim lamp does not warm a greenhouse, and the response tracks light, not temperature."}],"correctChoiceID":"c","explanation":"Plants that flower by season measure the length of the night. Phytochrome is converted to its active form, Pfr, by red light and slowly reverts in darkness, so light in the middle of the night resets the pigment and the plant registers two short nights instead of one long one. Growers use this in both directions: night lighting holds chrysanthemums and poinsettias back, and blackout cloth brings them into bloom.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"openstax-biology-2e-30-6","title":"Biology 2e, 30.6 Plant Sensory Systems and Responses","publisher":"OpenStax, Rice University","url":"https://openstax.org/books/biology-2e/pages/30-6-plant-sensory-systems-and-responses","accessedAt":"2026-11-10T12:00:00Z","usage":"openLicense","evidenceLocator":"The Phytochrome System and the Red/Far-Red Response: Pr/Pfr and the measurement of night length; short-day and long-day plants"},{"id":"oregon-state-short-day-long-day","title":"What are short day and long day plants?","publisher":"Oregon State University Extension Service","url":"https://news.oregonstate.edu/news/what-are-short-day-and-long-day-plants","accessedAt":"2026-11-10T12:00:00Z","usage":"linkOnly","evidenceLocator":"Article text: the amount of uninterrupted darkness determines the formation of flowers; chrysanthemums and poinsettias as short-day plants"}],"tags":["photoperiodism","phytochrome","flowering","short-day-plants"],"generatedAt":"2026-11-10T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"editorial-v1","reviewStatus":"verified"},{"id":"botany-v1-double-fertilization-009","category":"botany","conceptID":"botany.life-cycles","conceptTitle":"Plant life cycles and double fertilization","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"A corn plant with genotype aa is pollinated by a plant with genotype AA; both are ordinary diploids. In the kernels that develop on the aa plant, what genotypes do you expect for the embryo and for the starchy endosperm that feeds it, and why?","choices":[{"id":"a","text":"Embryo Aa and endosperm Aaa, because one sperm joins the egg and a second joins two maternal polar nuclei.","rationale":"Correct. The egg (a) plus a sperm (A) gives Aa; two polar nuclei (a and a) plus the other sperm (A) give triploid Aaa."},{"id":"b","text":"Embryo Aa and endosperm AAa, because one sperm joins the egg and two more sperm join one maternal polar nucleus.","rationale":"This reverses the doses. A pollen tube delivers two sperm in all, and the endosperm gets one of them plus two maternal nuclei."},{"id":"c","text":"Embryo Aa and endosperm aa, because endosperm is maternal storage tissue that forms without any fertilization.","rationale":"That describes the food tissue in conifer seeds. In flowering plants the endosperm forms only after a second fertilization."},{"id":"d","text":"Embryo Aa and endosperm Aa, because the endosperm develops from the same fertilized egg that forms the embryo.","rationale":"Embryo and endosperm come from two separate fusions inside the ovule, not from one zygote, and the endosperm is triploid."}],"correctChoiceID":"a","explanation":"Flowering plants carry out double fertilization. Each pollen tube delivers two sperm: one fuses with the egg to form the diploid zygote, and the other fuses with the two polar nuclei of the central cell to form a triploid cell that grows into the endosperm. The endosperm therefore carries two maternal genome copies and one paternal copy, and the seed invests in food reserves only when an embryo has actually been made.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"openstax-biology-2e-32-2","title":"Biology 2e, 32.2 Pollination and Fertilization","publisher":"OpenStax, Rice University","url":"https://openstax.org/books/biology-2e/pages/32-2-pollination-and-fertilization","accessedAt":"2026-11-10T12:00:00Z","usage":"openLicense","evidenceLocator":"Double Fertilization: one sperm fertilizes the egg; the other fuses with the two polar nuclei to form triploid endosperm"}],"tags":["double-fertilization","endosperm","angiosperms","genetics"],"generatedAt":"2026-11-10T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"editorial-v1","reviewStatus":"verified"},{"id":"botany-v1-darwins-orchid-010","category":"botany","conceptID":"botany.pollination-coevolution","conceptTitle":"Pollination and coevolution","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"The Madagascan orchid Angraecum sesquipedale holds its nectar at the bottom of a spur about 30 centimeters long, and it is pollinated by a hawkmoth with a tongue of similar length. The orchid's pollen masses stick to a moth only when the moth presses its head against the mouth of the flower. Why would natural selection favor orchids whose spurs are slightly longer than the tongues of the local moths?","choices":[{"id":"a","text":"A longer spur holds more nectar, so the flower can reward more moths and each visit carries off more pollen.","rationale":"Nectar fills only the lowest part of the spur, and a bigger reward would not by itself bring the moth's head into contact with the pollen."},{"id":"b","text":"A moth must push in as far as it can to reach the nectar, so its head is pressed firmly against the pollen.","rationale":"Correct. A flower shallower than the tongue is drained from a distance without pollination; a slightly deeper one forces contact."},{"id":"c","text":"A longer spur shuts out short-tongued nectar thieves, and its close fit to the pollinating moth is incidental.","rationale":"Excluding other insects is a real side benefit, but it does not explain why spur length should track the pollinator's own tongue so closely."},{"id":"d","text":"A moth prefers the deepest flowers it can find, because it uses spur length as a cue to the richest nectar.","rationale":"Moths gain nothing from depth as such; a deeper spur makes nectar harder to reach. The advantage lies with the plant, not the moth's preference."}],"correctChoiceID":"b","explanation":"Darwin reasoned that a flower whose nectar is easy to reach is robbed without being pollinated, so plants with slightly deeper spurs leave more offspring, while moths with slightly longer tongues feed better. Repeated over generations, this reciprocal selection lengthens both. From the flower alone he predicted in 1862 that a moth with an extraordinarily long tongue must live in Madagascar; one was described in 1903 and named praedicta.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"kew-tales-pollination","title":"Tales from the world of pollination","publisher":"Royal Botanic Gardens, Kew","url":"https://www.kew.org/read-and-watch/tales-from-the-world-of-pollination","accessedAt":"2026-11-10T12:00:00Z","usage":"linkOnly","evidenceLocator":"Section on Darwin's orchid: the long nectar spur and Darwin's predicted moth pollinator"},{"id":"britannica-xanthopan-morganii-praedicta","title":"Xanthopan morganii praedicta","publisher":"Encyclopaedia Britannica","url":"https://www.britannica.com/animal/Xanthopan-morganii-praedicta","accessedAt":"2026-11-10T12:00:00Z","usage":"linkOnly","evidenceLocator":"Article text: the hawkmoth predicted by Darwin and Wallace as the pollinator of Angraecum sesquipedale"}],"tags":["pollination","coevolution","orchids","darwin"],"generatedAt":"2026-11-10T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"editorial-v1","reviewStatus":"verified"},{"id":"botany-v1-cold-stratification-011","category":"botany","conceptID":"botany.seeds-dormancy","conceptTitle":"Seeds, dormancy and dispersal","type":"multipleChoice","dimension":"application","difficulty":"foundation","prompt":"Seeds taken from a ripe apple in October and planted at once in warm, moist potting soil do not sprout. Seeds from the same apple that are kept moist in a refrigerator for three months and then planted the same way sprout readily. For the wild ancestors of apples, what was the most likely advantage of this requirement?","choices":[{"id":"a","text":"It made sure seeds sprouted only after passing through an animal's gut, which carried them away from the parent.","rationale":"Gut passage can wear down a hard seed coat, which is scarification. The refrigerator seeds met no animal; what they needed was a long chill."},{"id":"b","text":"It gave the seed time to take up enough water, since a dry seed coat needs several months to soften completely.","rationale":"Both groups of seeds were kept moist. Months of moisture at room temperature do not break this dormancy; the cold does."},{"id":"c","text":"It made seeds sprout in autumn right after the first frost, which gave seedlings a head start on the spring.","rationale":"A single frost is not enough. The need for weeks of cold exists precisely so that seeds do not sprout in autumn."},{"id":"d","text":"It kept seeds from sprouting during a warm autumn spell, so that seedlings came up in spring once winter had passed.","rationale":"Correct. A seed that counts a winter's worth of cold before germinating avoids sending a tender seedling into freezing weather."}],"correctChoiceID":"d","explanation":"Many temperate plants shed seeds that are alive but dormant: they will not germinate even in good conditions until some further cue has been received. A requirement for weeks of moist cold, which gardeners call stratification, lets the seed register that winter has come and gone. During the chill the seed's hormone balance shifts away from abscisic acid, which maintains dormancy, and toward gibberellins, which promote germination.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"openstax-biology-2e-32-2","title":"Biology 2e, 32.2 Pollination and Fertilization","publisher":"OpenStax, Rice University","url":"https://openstax.org/books/biology-2e/pages/32-2-pollination-and-fertilization","accessedAt":"2026-11-10T12:00:00Z","usage":"openLicense","evidenceLocator":"Seed Germination: dormancy; seeds of temperate plants may need a cold treatment so that they do not germinate until spring"},{"id":"okstate-propagation-by-seed","title":"Propagation of Fruit and Nuts by Seed","publisher":"Oklahoma State University Extension","url":"https://extension.okstate.edu/fact-sheets/propagation-of-fruit-and-nuts-by-seed","accessedAt":"2026-11-10T12:00:00Z","usage":"linkOnly","evidenceLocator":"Sections on dormancy and stratification: apple seed is dormant and requires moist cold storage before it will germinate"}],"tags":["seeds","dormancy","stratification","germination"],"generatedAt":"2026-11-10T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"editorial-v1","reviewStatus":"verified"},{"id":"botany-v1-fern-pine-dry-slope-012","category":"botany","conceptID":"botany.move-to-land","conceptTitle":"Plant evolution and the move to land","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"On a dry, sunny hillside, mature ferns set out by a gardener survive for years on drip irrigation at their roots, yet no new ferns ever establish from the millions of spores they shed. Pine seedlings, by contrast, come up across the same slope. Which difference between the two life cycles best explains this?","choices":[{"id":"a","text":"Fern spores carry no stored food, whereas a pine seed holds enough reserves to sprout with no water at all.","rationale":"Seeds do carry reserves, but they still need water to germinate. The decisive fern weakness comes at fertilization, not at sprouting."},{"id":"b","text":"Ferns have no vascular tissue in their roots, so their young plants cannot lift water as pine seedlings can.","rationale":"Ferns are vascular plants with xylem and phloem, which is why the mature transplants do well once watered."},{"id":"c","text":"Fern spores grow into tiny free-living gametophytes whose sperm must swim through a film of water to the egg.","rationale":"Correct. Pines deliver sperm inside pollen and shelter the embryo in a seed, so no surface water is needed to reproduce."},{"id":"d","text":"Ferns spread only by creeping rhizomes, and the spores that they shed are sterile leftovers of their evolution.","rationale":"Fern spores are fully functional. Each can grow into a gametophyte that produces eggs and sperm, given a damp surface."}],"correctChoiceID":"c","explanation":"Ferns have a tough, vascular sporophyte but a fragile second generation: each spore grows into a small gametophyte that lives on the soil surface and releases flagellated sperm, which need liquid water to reach the egg. Seed plants removed that dependence. The gametophytes are reduced and retained on the parent, pollen carries sperm through the air, and the embryo is dispersed inside a protective, provisioned seed.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"openstax-biology-2e-25-4","title":"Biology 2e, 25.4 Seedless Vascular Plants","publisher":"OpenStax, Rice University","url":"https://openstax.org/books/biology-2e/pages/25-4-seedless-vascular-plants","accessedAt":"2026-11-10T12:00:00Z","usage":"openLicense","evidenceLocator":"Ferns and Other Seedless Vascular Plants: the prothallus; flagellated sperm swim on a layer of moisture to reach the egg"},{"id":"openstax-biology-2e-26-1","title":"Biology 2e, 26.1 Evolution of Seed Plants","publisher":"OpenStax, Rice University","url":"https://openstax.org/books/biology-2e/pages/26-1-evolution-of-seed-plants","accessedAt":"2026-11-10T12:00:00Z","usage":"openLicense","evidenceLocator":"Seeds and Pollen as an Evolutionary Adaptation to Dry Land"}],"tags":["ferns","gymnosperms","alternation-of-generations","seeds","pollen"],"generatedAt":"2026-11-10T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"editorial-v1","reviewStatus":"verified"},{"id":"botany-v1-soybean-nodules-013","category":"botany","conceptID":"botany.symbioses","conceptTitle":"Mycorrhizae and nitrogen-fixing symbioses","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"A grower digs up soybean plants from two plots. In the unfertilized plot the roots carry many nodules that are pink inside. In a plot given heavy nitrogen fertilizer the plants are just as green, but their nodules are few and small. What best explains the fertilized plants?","choices":[{"id":"a","text":"Fixing nitrogen costs the plant a great deal of sugar, so it cuts back on nodules when soil nitrogen is easy to get.","rationale":"Correct. The legume feeds its bacteria with photosynthate and regulates nodulation, relying on soil nitrogen when that is the cheaper source."},{"id":"b","text":"Fertilizer salts poison the rhizobia in the soil, so the plants are left with no bacteria able to colonize them.","rationale":"Ordinary fertilizer rates do not sterilize soil of rhizobia. The plant, not a shortage of bacteria, limits nodule number."},{"id":"c","text":"Fertilized roots grow so quickly that the bacteria cannot keep pace, so the nodules are spread too thin to notice.","rationale":"Nodule number is not set by a race with root growth. The plant controls how many infections go on to form nodules."},{"id":"d","text":"Nodules are a sign of infection, and well-fed plants have the stronger immune defenses that are needed to resist it.","rationale":"Nodules are organs the plant builds to house a beneficial partner, not disease lesions. Fewer nodules reflects economy, not immunity."}],"correctChoiceID":"a","explanation":"Legumes house rhizobia in root nodules, where the bacterial enzyme nitrogenase converts atmospheric nitrogen to ammonia; the pink color comes from leghemoglobin, which controls the oxygen supply to the bacteria. The service is expensive, since a soybean can spend a large share of its photosynthate on active nodules. When nitrate or ammonium is plentiful in the soil, the plant takes that cheaper nitrogen and scales the symbiosis down.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"nmsu-nitrogen-fixation-legumes","title":"Nitrogen Fixation by Legumes (Guide A-129)","publisher":"New Mexico State University Cooperative Extension Service","url":"https://pubs.nmsu.edu/_a/A129/","accessedAt":"2026-11-10T12:00:00Z","usage":"linkOnly","evidenceLocator":"Legume Nodules; Nitrogen Fixation Efficiency and Nitrogen Fertilization: pink nodules, energy cost, fixation slows or shuts down when soil nitrogen is high"},{"id":"openstax-biology-2e-31-3","title":"Biology 2e, 31.3 Nutritional Adaptations of Plants","publisher":"OpenStax, Rice University","url":"https://openstax.org/books/biology-2e/pages/31-3-nutritional-adaptations-of-plants","accessedAt":"2026-11-10T12:00:00Z","usage":"openLicense","evidenceLocator":"Nitrogen Fixation: Root and Bacteria Interactions"}],"tags":["nitrogen-fixation","rhizobia","legumes","symbiosis"],"generatedAt":"2026-11-10T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"editorial-v1","reviewStatus":"verified"},{"id":"botany-v1-corn-wasp-signals-014","category":"botany","conceptID":"botany.plant-defenses","conceptTitle":"Plant defenses and secondary metabolites","type":"multipleChoice","dimension":"application","difficulty":"advanced","prompt":"Corn seedlings chewed by caterpillars release a blend of airborne chemicals that attracts parasitic wasps, which lay their eggs in the caterpillars. The blend comes from undamaged leaves of an attacked seedling as well as from chewed ones. Seedlings cut with a razor release very little of it, but razor-cut seedlings dabbed with caterpillar oral secretions release about as much as chewed ones. What is the best interpretation?","choices":[{"id":"a","text":"The attractive chemicals are part of the caterpillar's oral secretions and simply evaporate from the wounded leaf.","rationale":"Secretions sitting on a wound could not explain release from undamaged leaves elsewhere on the plant; the plant makes the compounds."},{"id":"b","text":"Any wound sets off the full response, and the razor cuts were just too clean to damage enough of the leaf cells.","rationale":"The same razor cuts produced the full response once secretions were added, so the amount of damage was not what was missing."},{"id":"c","text":"The wasps are drawn to the smell of the caterpillars, and the plant's chemicals only carry that scent farther.","rationale":"Razor-cut plants with secretions but no caterpillar present released the full blend, which is produced by the plant's own metabolism."},{"id":"d","text":"The plant detects compounds in the caterpillar's secretions and responds with a blend that draws its enemies.","rationale":"Correct. The response needs a herbivore-specific cue, is produced by the plant throughout its leaves, and recruits wasps that kill the attacker."}],"correctChoiceID":"d","explanation":"Besides constant defenses such as thorns and toxins, plants have induced defenses that switch on only under attack, which saves the cost of making them when they are not needed. Elicitors in a herbivore's oral secretions let the plant tell feeding from mere mechanical injury; the jasmonate signaling pathway then triggers responses that include volatile compounds attracting predators and parasitoids. This recruitment of an enemy's enemies is called indirect defense.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"openstax-biology-2e-30-6","title":"Biology 2e, 30.6 Plant Sensory Systems and Responses","publisher":"OpenStax, Rice University","url":"https://openstax.org/books/biology-2e/pages/30-6-plant-sensory-systems-and-responses","accessedAt":"2026-11-10T12:00:00Z","usage":"openLicense","evidenceLocator":"Defense Responses against Herbivores and Pathogens: jasmonates and volatile compounds that attract parasitoids"},{"id":"pubmed-turlings-1990","title":"Exploitation of herbivore-induced plant odors by host-seeking parasitic wasps (Turlings, Tumlinson and Lewis, Science 1990)","publisher":"PubMed, U.S. National Library of Medicine","url":"https://pubmed.ncbi.nlm.nih.gov/17829213/","accessedAt":"2026-11-10T12:00:00Z","usage":"linkOnly","evidenceLocator":"Abstract: corn seedlings release terpenoid volatiles after caterpillar feeding; artificial damage needs caterpillar oral secretions to induce release"}],"tags":["herbivory","induced-defense","volatiles","parasitoids","jasmonate"],"generatedAt":"2026-11-10T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"editorial-v1","reviewStatus":"verified"},{"id":"botany-v1-ponderosa-fire-015","category":"botany","conceptID":"botany.plant-ecology","conceptTitle":"Plant ecology: fire, succession and invasion","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"Fire scars preserved in the growth rings of old ponderosa pines show that one forest burned about once a decade for centuries, and that the big trees survived each fire. After 1900 fires were put out promptly, and no new scars formed for a hundred years. When a wildfire finally burned through, it killed most of the old trees. What best explains the change in outcome?","choices":[{"id":"a","text":"A century without fire let the old pines lose their thick protective bark, because bark thins when it is not needed.","rationale":"Bark does not thin from disuse; old ponderosas keep their thick, insulating bark. What changed was the fuel around them."},{"id":"b","text":"Without frequent surface fires, small trees and dead fuel built up and carried the flames into the crowns.","rationale":"Correct. Frequent low fires once cleared litter and saplings; a century of buildup fed a hotter fire that could climb into the canopy."},{"id":"c","text":"Fires simply burn hotter now than in past centuries, so the structure of the forest made no difference here.","rationale":"Hotter, drier weather does raise fire risk, but the forest's own fuel load and ladder of small trees largely decide whether flames reach the crowns."},{"id":"d","text":"The old trees had reached the end of their natural lifespan, so that any disturbance at all would have killed them.","rationale":"Ponderosa pines live for centuries, and these same trees had survived dozens of earlier fires at a wide range of ages."}],"correctChoiceID":"b","explanation":"Ponderosa pine is adapted to frequent, low-intensity fire: thick bark, deep roots and self-pruned lower limbs let mature trees survive flames that stay on the ground. Those fires also remove needle litter and thin young trees. When fire is excluded, fuel and dense understory trees accumulate and form a ladder into the canopy, so the eventual fire is far more severe. This is why managers use thinning and prescribed burns to restore such forests.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"nps-wildland-fire-ponderosa","title":"Wildland Fire in Ponderosa Pine: Western United States","publisher":"U.S. National Park Service","url":"https://www.nps.gov/articles/wildland-fire-in-ponderosa-pine.htm","accessedAt":"2026-11-10T12:00:00Z","usage":"publicDomain","evidenceLocator":"Article text: natural fire cycle of 5 to 25 years; thick bark and shed lower limbs; effects of fire exclusion on stand density, fuels and fire intensity"},{"id":"usfs-tree-rings-fire-history","title":"Tree Rings tell the history of fire and forest health","publisher":"USDA Forest Service","url":"https://www.fs.usda.gov/features/tree-rings-tell-history-fire-and-forest-health","accessedAt":"2026-11-10T12:00:00Z","usage":"publicDomain","evidenceLocator":"Feature text: fire scars in tree rings record how often forests burned before fire exclusion"}],"tags":["fire-ecology","ponderosa-pine","tree-rings","disturbance"],"generatedAt":"2026-11-10T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"editorial-v1","reviewStatus":"verified"},{"id":"botany-v1-wheat-polyploidy-016","category":"botany","conceptID":"botany.domestication-crops","conceptTitle":"Domestication and crop evolution","type":"multipleChoice","dimension":"application","difficulty":"advanced","prompt":"Bread wheat arose when a cultivated wheat with 28 chromosomes (four sets of 7) hybridized with a wild goatgrass with 14 chromosomes (two sets of 7). A first-generation hybrid from such a cross has 21 chromosomes and is sterile, but if its chromosome number spontaneously doubles to 42, the plant is fertile. Why does doubling restore fertility?","choices":[{"id":"a","text":"Doubling supplies extra copies of the genes for fertility, which make up for the copies the hybrid was missing.","rationale":"The hybrid is not short of particular genes. Its problem is mechanical: its chromosomes have nothing to pair with at meiosis."},{"id":"b","text":"Doubling eliminates the goatgrass chromosomes, which leaves a pure wheat genome able to go through meiosis.","rationale":"Nothing is eliminated. Bread wheat keeps all three ancestral genomes, including the goatgrass set, which contributes much to bread quality."},{"id":"c","text":"Doubling gives every chromosome an identical partner to pair with, so that meiosis produces balanced gametes.","rationale":"Correct. With two copies of each of the 21 chromosomes, pairing and segregation are regular and each gamete receives one complete set of 21."},{"id":"d","text":"Doubling makes the plant's cells larger and hardier, so pollen and eggs survive that would otherwise have died.","rationale":"Polyploid cells are often larger, but size is not what rescues fertility. Gametes fail in the hybrid because they get unbalanced chromosome sets."}],"correctChoiceID":"c","explanation":"In meiosis each chromosome must pair with a matching partner so that the two can be separated evenly. A hybrid carrying one set from each of three different ancestral genomes has no such partners, so its gametes receive random, unbalanced assortments and fail. Doubling the chromosomes gives each a duplicate and restores regular meiosis, creating at one stroke a new, fertile species (an allopolyploid) that is reproductively isolated from both parents.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"openstax-biology-2e-18-2","title":"Biology 2e, 18.2 Formation of New Species","publisher":"OpenStax, Rice University","url":"https://openstax.org/books/biology-2e/pages/18-2-formation-of-new-species","accessedAt":"2026-11-10T12:00:00Z","usage":"openLicense","evidenceLocator":"Sympatric Speciation: polyploidy and allopolyploidy; cultivated wheat, cotton and tobacco are allopolyploids"},{"id":"colostate-cwr-wheat-case-study","title":"Case Study: Wheat Domestication and Breeding","publisher":"Crop Wild Relatives and their Use in Plant Breeding, Colorado State University (Pressbooks)","url":"https://colostate.pressbooks.pub/cropwildrelatives/chapter/wheat-breeding-with-crop-wild-relatives/","accessedAt":"2026-11-10T12:00:00Z","usage":"linkOnly","evidenceLocator":"Wheat evolution and domestication: hybridization of emmer wheat (AABB) with Aegilops tauschii (DD) gave hexaploid bread wheat (AABBDD)"}],"tags":["polyploidy","wheat","speciation","domestication","meiosis"],"generatedAt":"2026-11-10T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"editorial-v1","reviewStatus":"verified"},{"id":"botany-v1-dicots-not-a-clade-017","category":"botany","conceptID":"botany.classification","conceptTitle":"Classification, naming and phylogeny","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"For two centuries, flowering plants whose seedlings have two seed leaves were classified together as 'dicots'. DNA-based family trees show that water lilies and a few other two-seed-leaf lineages branched off first, and that monocots, with one seed leaf, are more closely related to oaks, roses and sunflowers than water lilies are. What does this imply about the old group 'dicots'?","choices":[{"id":"a","text":"It remains a natural group, since sharing a visible trait such as two seed leaves is what makes plants related.","rationale":"Shared appearance is evidence about ancestry, not the definition of it. A trait kept from a distant ancestor can be shared by lineages that are not each other's closest relatives."},{"id":"b","text":"It should be merged with the monocots, since the DNA shows that the number of seed leaves has no genetic basis.","rationale":"Seed-leaf number is inherited and still useful for identification. The finding concerns which groupings reflect descent, not whether the trait is real."},{"id":"c","text":"It is a natural group only if water lilies are reclassified as monocots that later regained a second seed leaf.","rationale":"The trees place water lilies outside the monocots altogether, on a branch that split off earlier. Moving them would not repair the group."},{"id":"d","text":"It is not a natural group: two seed leaves is the ancestral state, and monocots arose from among such plants.","rationale":"Correct. A group that contains an ancestor but leaves out some of its descendants is not a clade, so 'dicots' was abandoned as a formal group."}],"correctChoiceID":"d","explanation":"Modern classification aims to name clades: an ancestor together with all of its descendants. A trait inherited unchanged from a remote ancestor, such as two seed leaves, cannot mark out a clade, because lineages that later changed (here the monocots) are left out. Molecular phylogenies therefore replaced 'dicots' with several groups, including the early-branching lineages, the magnoliids, and the eudicots, a true clade marked by pollen with three openings.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"openstax-biology-2e-26-3","title":"Biology 2e, 26.3 Angiosperms","publisher":"OpenStax, Rice University","url":"https://openstax.org/books/biology-2e/pages/26-3-angiosperms","accessedAt":"2026-11-10T12:00:00Z","usage":"openLicense","evidenceLocator":"Diversity of Angiosperms: Basal Angiosperms, Monocots, Eudicots"},{"id":"openstax-biology-2e-20-2","title":"Biology 2e, 20.2 Determining Evolutionary Relationships","publisher":"OpenStax, Rice University","url":"https://openstax.org/books/biology-2e/pages/20-2-determining-evolutionary-relationships","accessedAt":"2026-11-10T12:00:00Z","usage":"openLicense","evidenceLocator":"Shared Characteristics: shared ancestral and shared derived characters; monophyletic groups (clades)"}],"tags":["phylogenetics","classification","dicots","monophyly","apg"],"generatedAt":"2026-11-10T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"editorial-v1","reviewStatus":"verified"},{"id":"botany-v1-hollow-oak-girdling-018","category":"botany","conceptID":"botany.wood-secondary-growth","conceptTitle":"Wood, bark and tree growth","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"An old oak has a trunk so hollow that a person can stand inside it, yet it leafs out fully every spring. A younger oak nearby dies within two years after a strip of bark, cut down to the wood, is removed in a complete ring around its trunk. What best explains the difference?","choices":[{"id":"a","text":"The lost heartwood was dead and no longer conducting, while the ring cut removed the phloem that feeds the roots.","rationale":"Correct. Water still rises in the outer sapwood of both trees, but the girdled tree's roots are cut off from sugar and slowly starve."},{"id":"b","text":"The hollow tree seals its inner wound with resin, while the ring cut lets water in the outer wood evaporate away.","rationale":"Evaporation from the exposed wood is minor. The girdled tree keeps lifting water at first; it dies because sugar cannot reach its roots."},{"id":"c","text":"The lost heartwood carried only stored sugar, while the ring cut severed the vessels that lift water to the leaves.","rationale":"This has the tissues reversed. Water travels in the wood, which the ring cut leaves in place; sugar travels in the inner bark."},{"id":"d","text":"The hollow tree is old enough to live on its reserves, while a young tree has no stores with which to survive injury.","rationale":"Age is not the issue. A ring cut kills old trees too, and no tree can live for long on reserves once its roots are cut off from the leaves."}],"correctChoiceID":"a","explanation":"A tree trunk is alive mainly at its edge. The vascular cambium adds wood to the inside and inner bark (phloem) to the outside; the newest wood, the sapwood, carries water, while the older heartwood at the center is dead and serves only as support. Removing a ring of bark takes away the phloem and cambium, so sugars made in the leaves can no longer reach the roots, which eventually die and take the tree with them.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"usfs-anatomy-of-a-tree","title":"Anatomy of a tree","publisher":"USDA Forest Service","url":"https://www.fs.usda.gov/learn/trees/anatomy-of-tree","accessedAt":"2026-11-10T12:00:00Z","usage":"publicDomain","evidenceLocator":"Descriptions of inner bark (phloem), cambium, sapwood and heartwood"},{"id":"openstax-biology-2e-30-2","title":"Biology 2e, 30.2 Stems","publisher":"OpenStax, Rice University","url":"https://openstax.org/books/biology-2e/pages/30-2-stems","accessedAt":"2026-11-10T12:00:00Z","usage":"openLicense","evidenceLocator":"Growth in Stems: Secondary Growth; Annual Rings"}],"tags":["wood","heartwood","phloem","girdling","vascular-cambium"],"generatedAt":"2026-11-10T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"editorial-v1","reviewStatus":"verified"},{"id":"botany-v1-flytrap-nutrition-019","category":"botany","conceptID":"botany.carnivorous-parasitic","conceptTitle":"Carnivorous and parasitic plants","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"Venus flytraps grow wild in sunny, waterlogged, nutrient-poor bogs. A grower finds that plants fed insects grow faster than unfed ones when both stand in bright light, but that in deep shade both groups decline however many insects they catch. What does this pattern suggest that prey chiefly supplies?","choices":[{"id":"a","text":"Sugars and other energy-rich compounds, which allow the plant to grow without depending on photosynthesis.","rationale":"If prey supplied the plant's energy, fed plants would not decline in shade. Flytraps are green and still live by photosynthesis."},{"id":"b","text":"Mineral nutrients such as nitrogen and phosphorus, while photosynthesis still provides the plant's energy.","rationale":"Correct. Prey acts as fertilizer for a plant rooted in poor soil; it pays off only when there is enough light to use the nutrients."},{"id":"c","text":"Water, which the plant cannot draw up through its roots because bog soil is too acidic for them to absorb it.","rationale":"Bog plants stand in saturated soil and take up water through their roots normally. Water is the one thing they do not lack."},{"id":"d","text":"Carbon dioxide given off as the insect decays, which raises the rate of photosynthesis inside the closed trap.","rationale":"A decaying insect releases a trivial amount of CO2 compared with the air, and extra CO2 would not help a plant starved of minerals."}],"correctChoiceID":"b","explanation":"Carnivorous plants are photosynthetic; what they get from prey is mainly nitrogen and phosphorus, which are scarce in the bogs and wet sands where they live. Traps are costly to build and photosynthesize poorly, so carnivory pays only where light and water are plentiful and soil nutrients are the limiting factor. That is why these plants are confined to open, wet, infertile habitats and are easily outcompeted elsewhere.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"openstax-biology-2e-31-3","title":"Biology 2e, 31.3 Nutritional Adaptations of Plants","publisher":"OpenStax, Rice University","url":"https://openstax.org/books/biology-2e/pages/31-3-nutritional-adaptations-of-plants","accessedAt":"2026-11-10T12:00:00Z","usage":"openLicense","evidenceLocator":"Insectivorous Plants: the Venus flytrap grows in boggy, nutrient-poor soil and absorbs minerals from digested prey"}],"tags":["carnivorous-plants","venus-flytrap","mineral-nutrition","trade-offs"],"generatedAt":"2026-11-10T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"editorial-v1","reviewStatus":"verified"},{"id":"botany-v1-artemisinin-extraction-020","category":"botany","conceptID":"botany.ethnobotany-medicines","conceptTitle":"Ethnobotany and medicines from plants","type":"multipleChoice","dimension":"application","difficulty":"college","prompt":"In 1971, Tu Youyou's team found that hot-water extracts of sweet wormwood (Artemisia annua) gave promising but unrepeatable results against malaria in mice. A fourth-century text described soaking the herb in cold water and wringing out the juice. Tu switched to extracting the plant with ether at low temperature, and the new extract cleared parasites from mice and monkeys. What is the most reasonable inference?","choices":[{"id":"a","text":"The ancient recipe was already a proven cure, so the modern tests only confirmed what healers had established.","rationale":"The text supplied a lead, not proof. The herb as usually prepared had failed, and only controlled animal and human tests established a working drug."},{"id":"b","text":"Ether is itself toxic to malaria parasites, so the plant contributed little to the activity of the new extract.","rationale":"Ether is a volatile solvent that is removed from the extract. The active principle was later isolated from the plant as a crystalline compound, artemisinin."},{"id":"c","text":"The active compound is broken down by heat, so boiling the herb had destroyed much of what the plant contained.","rationale":"Correct. Removing heat from the extraction turned an unreliable preparation into a consistently active one, which points to a heat-sensitive compound."},{"id":"d","text":"The herb works only when its juice is taken fresh, so the wringing step and not the temperature was the key.","rationale":"Tu's successful method used a solvent extract, not fresh-pressed juice. What it shared with the old recipe was the absence of boiling."}],"correctChoiceID":"c","explanation":"Many drugs began as plant compounds found by following traditional use: salicylates from willow led to aspirin, cinchona bark gave quinine, and sweet wormwood gave artemisinin. Traditional knowledge supplies leads, and sometimes crucial details of preparation, but turning a lead into a medicine takes isolation of the active compound and controlled testing. Artemisinin-based combination therapies are now standard treatment for falciparum malaria, and the work earned Tu a share of the 2015 Nobel Prize.","rubric":[],"coachingPrompts":[],"modelOutline":[],"sources":[{"id":"lasker-artemisinin-2011","title":"Artemisinin therapy for malaria (2011 Lasker~DeBakey Clinical Medical Research Award)","publisher":"Albert and Mary Lasker Foundation","url":"https://laskerfoundation.org/winners/artemisinin-therapy-for-malaria/","accessedAt":"2026-11-10T12:00:00Z","usage":"linkOnly","evidenceLocator":"Award description: results were not reproducible; Ge Hong's recipe; boiling and high-temperature extraction could destroy the active ingredient; low-temperature ether extraction"}],"tags":["ethnobotany","artemisinin","drug-discovery","malaria"],"generatedAt":"2026-11-10T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"editorial-v1","reviewStatus":"verified"},{"id":"botany-v1-wood-wide-web-essay-021","category":"botany","conceptID":"botany.symbioses","conceptTitle":"Mycorrhizae and nitrogen-fixing symbioses","type":"essay","dimension":"synthesis","difficulty":"advanced","prompt":"A popular book claims that forest trees 'share food and send warnings to one another through a wood-wide web' of mycorrhizal fungi. Evaluate that claim for a general reader. Explain what mycorrhizae are and what is well established about them; describe what isotope-labeling field experiments, such as the 1997 study by Simard and colleagues, actually measured; set out the alternative explanations and gaps identified in the 2023 review by Karst, Jones and Hoeksema; and say what evidence would be needed to show that resources moving through a fungal network matter to the tree that receives them. Distinguish clearly between what has been demonstrated and what has been inferred or overstated.","choices":[],"explanation":"Coaching should push the learner to separate three layers: the well-established mutualism between roots and fungi, the experimental evidence that labeled carbon can move between neighboring plants, and the much larger claims about cooperation, kin support and warning signals. A strong answer neither dismisses the experiments nor repeats the popular story uncritically.","rubric":[{"id":"established-biology","title":"What is well established","description":"Explains mycorrhizae as a widespread mutualism in which fungi supply mineral nutrients such as phosphate and receive sugars, and notes that one fungus can colonize the roots of more than one plant.","weight":0.2,"coachingQuestions":["What does each partner gain in a mycorrhiza?","Which parts of the popular story rest on this basic, uncontested biology?"]},{"id":"experiments","title":"What the experiments measured","description":"Describes isotope labeling accurately: labeled carbon supplied to one seedling was detected in a neighbor, movement went both ways, and the net gain was a small fraction of the receiver's own carbon uptake and depended on conditions such as shade.","weight":0.3,"coachingQuestions":["What exactly was labeled, and where was the label later found?","How large was the net transfer compared with what the receiving seedling fixed for itself?"]},{"id":"alternatives-limits","title":"Alternative explanations and limits","description":"Identifies other routes (soil, root exudates, direct root contact), the difficulty of proving that fungal links carried the label, the small number of forests and species studied, inconsistent effects on seedling growth, the lack of field evidence for warning signals or preferential support of kin, and the role of citation bias.","weight":0.3,"coachingQuestions":["By what routes other than a fungal link could labeled carbon reach a neighboring plant?","Which popular claims have no peer-reviewed field evidence behind them?"]},{"id":"calibrated-conclusion","title":"Calibrated conclusion","description":"States what can and cannot be concluded, specifies the evidence that would settle the matter (controls that sever fungal links only, measured effects on growth or survival, replication across forests), and avoids language that attributes intent to trees.","weight":0.2,"coachingQuestions":["What experiment would separate transfer through fungi from transfer through soil?","Is detecting a transferred isotope the same as showing a benefit to the receiver?"]}],"coachingPrompts":["State the popular claim in one sentence before evaluating it.","Separate 'carbon moved' from 'the tree benefited' and from 'the tree intended it'.","Name at least two alternative pathways for the isotope.","Finish by saying what result would change your mind in either direction."],"modelOutline":[],"sources":[{"id":"karst-2023-cmn-review","title":"Positive citation bias and overinterpreted results lead to misinformation on common mycorrhizal networks in forests (Karst, Jones and Hoeksema, 2023)","publisher":"Nature Ecology & Evolution","url":"https://www.nature.com/articles/s41559-023-01986-1","accessedAt":"2026-11-10T12:00:00Z","usage":"linkOnly","evidenceLocator":"Abstract and main text: evaluation of three common claims about common mycorrhizal networks; alternative explanations; analysis of citation bias"},{"id":"simard-1997-net-transfer","title":"Net transfer of carbon between ectomycorrhizal tree species in the field (Simard et al., 1997)","publisher":"Nature","url":"https://www.nature.com/articles/41557","accessedAt":"2026-11-10T12:00:00Z","usage":"linkOnly","evidenceLocator":"Abstract: reciprocal isotope labeling of paper birch and Douglas-fir seedlings; bidirectional transfer; net gain by Douglas-fir influenced by shading"}],"tags":["mycorrhizae","common-mycorrhizal-networks","evidence-evaluation","essay"],"generatedAt":"2026-11-10T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"editorial-v1","reviewStatus":"verified"},{"id":"botany-v1-c4-rice-essay-022","category":"botany","conceptID":"botany.photosynthesis-pathways","conceptTitle":"C3, C4 and CAM photosynthesis","type":"essay","dimension":"synthesis","difficulty":"advanced","prompt":"For more than fifteen years an international consortium has been trying to engineer the C4 photosynthetic pathway into rice, a C3 crop. Write an assessment for a science-literate funder. Explain why C3 photosynthesis loses efficiency in hot, bright conditions and how C4 plants avoid that loss; state the benefits the project predicts; describe what would have to change in a rice leaf, both anatomically and biochemically; and weigh the case for continuing against the costs and uncertainties, including the conditions under which C4 photosynthesis offers little or no advantage. Keep what has been achieved separate from what is predicted.","choices":[],"explanation":"Coaching should push the learner to explain the mechanism before judging the project: Rubisco's reaction with oxygen, the cost of photorespiration, and the C4 carbon-concentrating pump with its own energy price. A strong answer treats C4 as a trade-off that pays under some conditions, and treats the predicted gains as predictions.","rubric":[{"id":"mechanism","title":"Mechanism of the C3 limitation and the C4 solution","description":"Explains that Rubisco also reacts with oxygen, that the resulting photorespiration wastes fixed carbon and energy and worsens with heat and with closed stomata, and that C4 plants first fix CO2 in mesophyll cells and release it at high concentration around Rubisco in bundle-sheath cells.","weight":0.3,"coachingQuestions":["Why does heat make photorespiration worse?","Where in a C4 leaf does Rubisco work, and what is different about the air around it there?"]},{"id":"engineering","title":"What must be engineered","description":"Describes both workstreams: leaf anatomy (closer veins, enlarged bundle-sheath cells with functional chloroplasts) and biochemistry (a dozen or more enzymes and transporters expressed in the right cell type at the right level), and notes that the genetic control of the anatomy is not fully known.","weight":0.25,"coachingQuestions":["Why is adding the C4 enzymes not enough without changing the leaf's anatomy?","What does the repeated independent evolution of C4 suggest about feasibility?"]},{"id":"trade-offs","title":"Trade-offs and conditions","description":"Weighs predicted gains in yield, water use and nitrogen use against the extra ATP the C4 cycle consumes, the reduced advantage in cool or shaded conditions and as atmospheric CO2 rises, the long and uncertain timeline, and the alternative uses of the same research money.","weight":0.25,"coachingQuestions":["Under what growing conditions would a C4 rice plant do no better than a C3 one?","What else could the same funds improve in rice on a shorter timescale?"]},{"id":"achieved-vs-predicted","title":"Achieved versus predicted","description":"Separates demonstrated steps (individual genes or partial pathways expressed in rice, regulators of leaf anatomy identified) from modeled outcomes, and gives a reasoned recommendation with the uncertainty stated.","weight":0.2,"coachingQuestions":["Which of your statements are measurements and which are model predictions?","What milestone would justify continued funding, and what result would argue for stopping?"]}],"coachingPrompts":["Explain photorespiration in two sentences before mentioning rice.","Describe the C4 pathway as a pump with a running cost.","List the anatomical and the biochemical changes separately.","Label every benefit as measured or predicted."],"modelOutline":[],"sources":[{"id":"c4-rice-project-hypothesis","title":"The Hypothesis","publisher":"C4 Rice Project","url":"https://c4rice.com/the-science/the-basic-science/","accessedAt":"2026-11-10T12:00:00Z","usage":"linkOnly","evidenceLocator":"Page text: C3 photosynthesis limits rice yield; C4 crops show greater water-use and nitrogen-use efficiency; hypothesis that C4 components can be engineered into rice"},{"id":"c4-rice-project-design","title":"Project Design: engineering photosynthesis","publisher":"C4 Rice Project","url":"https://c4rice.com/the-science/engineering-photosynthesis-what-we-are-doing/","accessedAt":"2026-11-10T12:00:00Z","usage":"linkOnly","evidenceLocator":"Page text: anatomy and biochemistry workstreams; at least 12 genes; Kranz anatomy regulation not yet known; C4 evolved from C3 more than 60 times"}],"tags":["c4-photosynthesis","rice","crop-engineering","trade-offs","essay"],"generatedAt":"2026-11-10T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"editorial-v1","reviewStatus":"verified"},{"id":"botany-v1-native-invasive-essay-023","category":"botany","conceptID":"botany.plant-ecology","conceptTitle":"Plant ecology: fire, succession and invasion","type":"essay","dimension":"synthesis","difficulty":"college","prompt":"A neighbor says: 'My Bradford pear is healthy, the bees love it, and the nursery told me it was sterile. Why should it matter whether a plant is native?' Write a reply. Define native, non-native and invasive, and explain why the terms are not interchangeable; use the Callery pear to show how a planting once considered safe became a spreading problem; explain what counts as harm in this context and what evidence would demonstrate it; and give the strongest points on the neighbor's side their due, including the fact that most introduced plants never become invasive. End with practical advice that follows from your reasoning.","choices":[],"explanation":"Coaching should push the learner to use the terms precisely and to explain the mechanism in the case: a self-incompatible clone that set no fruit alone began to fruit once other cultivars and rootstock sprouts supplied compatible pollen, and birds then carried the seed. A strong answer persuades through evidence and fairness, not by treating 'non-native' as a synonym for 'bad'.","rubric":[{"id":"definitions","title":"Precise definitions","description":"Distinguishes native, non-native and invasive, makes clear that invasive means a non-native species whose introduction causes or is likely to cause harm, and gives an example of a harmless or useful non-native plant.","weight":0.25,"coachingQuestions":["What has to be true before a non-native plant is called invasive?","Can you name an introduced plant that no one regards as a problem?"]},{"id":"mechanism","title":"Mechanism in the case","description":"Explains that 'Bradford' trees are one self-incompatible clone, that fruit set began when genetically different cultivars and rootstock shoots provided cross-pollination, that birds disperse the seed, and that wild offspring form dense thorny thickets.","weight":0.3,"coachingQuestions":["Why was 'sterile' true for one tree planted alone and false for a neighborhood of mixed cultivars?","How do the seeds get from a front yard to a roadside or field?"]},{"id":"harm-evidence","title":"Harm and evidence","description":"States what harm means (displacement of other vegetation, costs of control, loss of habitat value) and what observations would establish it, such as spread into unplanted land, records over time, and comparisons of invaded and uninvaded sites.","weight":0.25,"coachingQuestions":["What would you measure to show that the spread causes harm and is not merely visible?","What is the difference between a plant being common and a plant doing damage?"]},{"id":"fairness-advice","title":"Fairness and practical advice","description":"Acknowledges the tree's real appeal and that most introductions are benign, explains why risk is hard to predict in advance and may appear decades later, and offers proportionate advice such as replacing the tree with a regionally native alternative.","weight":0.2,"coachingQuestions":["Which of the neighbor's points are correct?","What should a gardener do differently given that problems can take decades to appear?"]}],"coachingPrompts":["Define the three terms before you use them.","Tell the Callery pear story as cause and effect, step by step.","Concede what the neighbor has right.","Make your advice specific enough to act on."],"modelOutline":[],"sources":[{"id":"usda-nisic-what-are-invasive-species","title":"What are Invasive Species?","publisher":"USDA National Invasive Species Information Center","url":"https://www.invasivespeciesinfo.gov/what-are-invasive-species","accessedAt":"2026-11-10T12:00:00Z","usage":"publicDomain","evidenceLocator":"Definition from Executive Order 13112; non-native and invasive are not interchangeable terms"},{"id":"arnoldia-callery-pear","title":"The Rise and Fall of the Ornamental Callery Pear Tree (Culley, Arnoldia 74(3), 2017)","publisher":"Arnold Arboretum of Harvard University","url":"https://arboretum.harvard.edu/stories/the-rise-and-fall-of-the-ornamental-callery-pear-tree/","accessedAt":"2026-11-10T12:00:00Z","usage":"linkOnly","evidenceLocator":"Sections on self-incompatibility of 'Bradford', cross-pollination among cultivars and rootstock, bird dispersal and spread"}],"tags":["invasive-species","native-plants","callery-pear","gardening","essay"],"generatedAt":"2026-11-10T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"editorial-v1","reviewStatus":"verified"},{"id":"botany-v1-seed-banks-in-situ-essay-024","category":"botany","conceptID":"botany.conservation","conceptTitle":"Plant conservation and seed banks","type":"essay","dimension":"synthesis","difficulty":"college","prompt":"A legislator proposes cutting funds for protecting wild habitat on the grounds that 'the seeds are already safe in a freezer'. Write a response arguing how seed banks and the conservation of plants in their own habitats (in situ conservation) complement each other. Explain how conventional seed banking works and what it does well, using at least one concrete example; explain what it cannot do, including species whose seeds do not survive drying and freezing and the fact that banked seeds stop adapting; explain what in situ conservation provides and where it is vulnerable; and propose how you would divide effort between the two for a threatened wild relative of a crop.","choices":[],"explanation":"Coaching should push the learner to treat the two approaches as insurance against different risks, not as rivals. A strong answer gives seed banks full credit (the Svalbard backup that let a displaced genebank rebuild its collection is a good example), states their biological limits precisely, and ends with a concrete, defensible allocation.","rubric":[{"id":"how-banking-works","title":"How seed banking works and what it does well","description":"Explains drying and cold storage (about -18 to -20 degrees C), the long lifespans this gives desiccation-tolerant seeds, duplication for safety, and a concrete success such as the restoration of a lost collection from backup samples.","weight":0.25,"coachingQuestions":["Why does drying a seed before freezing it matter?","What real event shows a seed bank doing the job it was built for?"]},{"id":"limits","title":"Limits of seed banks","description":"Explains that recalcitrant seeds, including those of many trees and a large share of the most threatened species, die when dried and frozen; that collections sample only part of a species' variation, need periodic testing and regrowing, and are frozen in evolutionary time; and that a seed alone does not preserve pollinators, soil partners or habitat.","weight":0.3,"coachingQuestions":["Which kinds of plants cannot be stored in a conventional seed bank, and what are the alternatives?","What does a population in the wild keep doing that a frozen sample cannot?"]},{"id":"in-situ","title":"What in situ conservation provides and risks","description":"Explains that wild populations continue to evolve with changing climate, pests and partners, and keep whole communities intact, while remaining exposed to land clearing, fire, invasive species and climate shifts that can erase them.","weight":0.25,"coachingQuestions":["Why might a wild population be more useful to a plant breeder in fifty years than seed collected today?","What can destroy a protected population despite its legal protection?"]},{"id":"integrated-plan","title":"Integrated proposal","description":"Offers a reasoned division of effort for a crop wild relative: protect key populations where they grow, bank seed sampled across the range as backup, plan for regeneration and for species that cannot be banked, and tie the argument back to the legislator's claim.","weight":0.2,"coachingQuestions":["If you could fund only one more action for this species, which would it be and why?","How does your plan answer the claim that the freezer is enough?"]}],"coachingPrompts":["Start by granting what seed banks do well.","Name the risk each approach insures against.","Use one concrete example on each side.","End with a specific allocation and the reasoning behind it."],"modelOutline":[],"sources":[{"id":"crop-trust-svalbard-seed-vault","title":"Svalbard Global Seed Vault","publisher":"Crop Trust","url":"https://www.croptrust.org/work/svalbard-global-seed-vault/","accessedAt":"2026-11-10T12:00:00Z","usage":"linkOnly","evidenceLocator":"Page text: backup duplicates of genebank collections stored at -18 degrees C; depositors retain ownership; ICARDA withdrawals to rebuild its collection"},{"id":"kew-new-techniques-conserve-seeds","title":"New techniques needed to conserve seeds of many threatened species","publisher":"Royal Botanic Gardens, Kew","url":"https://www.kew.org/about-us/press-media/new-techniques-needed-to-conserve-seeds","accessedAt":"2026-11-10T12:00:00Z","usage":"linkOnly","evidenceLocator":"Press release on Wyse et al., Nature Plants 2018: about 36 percent of critically endangered species produce recalcitrant seeds that cannot be conventionally banked; cryopreservation as an alternative"}],"tags":["conservation","seed-banks","in-situ","crop-wild-relatives","essay"],"generatedAt":"2026-11-10T12:00:00Z","generatorVersion":"curated-v1","reviewerVersion":"editorial-v1","reviewStatus":"verified"}]}]};
